import * as fs from 'node:fs';
import * as path from 'node:path';

import { app } from 'electron';
import ffmpegStaticPath from 'ffmpeg-static';

import {
  DEFAULT_TARGET_LUFS,
  HEADROOM_DB_TP,
  LOUDNESS_ALGORITHM_VERSION,
  computeAutoGainDb,
  type LoudnessScanError,
  type LoudnessScanResult,
} from '../../src/shared/contracts/loudness.js';
import { normalizeStatNumber } from '../utils/fsHelpers.js';

export {
  DEFAULT_LOUDNESS_TARGET_LUFS,
  DEFAULT_TARGET_LUFS,
  HEADROOM_DB_TP,
  LOUDNESS_ALGORITHM_VERSION,
  MAX_TARGET_LUFS,
  MIN_TARGET_LUFS,
  type LoudnessScanError,
  type LoudnessScanOk,
  type LoudnessScanResult,
} from '../../src/shared/contracts/loudness.js';

const FFMPEG_MIN_TIMEOUT_MS = 2 * 60 * 1000;
const FFMPEG_MAX_TIMEOUT_MS = 10 * 60 * 1000;
const FFMPEG_MS_PER_MB = 15_000;
const FFMPEG_BASE_TIMEOUT_MS = 60_000;

const MIN_INTEGRATED_LUFS = -70;
const MAX_INTEGRATED_LUFS = 10;
const MIN_TRUE_PEAK_DB = -60;
const MAX_TRUE_PEAK_DB = 10;

export type AnalyzeLoudnessOptions = {
  fileMtime?: number;
  fileSizeBytes?: number;
};

export type Ebur128ParseResult = {
  integratedLufs: number;
  lraLowLufs?: number;
  lraLu?: number;
  truePeakDb: number;
};

let scanQueue: Promise<unknown> = Promise.resolve();

function isFiniteInRange(value: number, min: number, max: number): boolean {
  return Number.isFinite(value) && value >= min && value <= max;
}

function isInsideAsarArchive(filePath: string): boolean {
  return /(?:^|[/\\])app\.asar[/\\]/.test(filePath);
}

function parseTpkPeakValues(tpkValues: string): number | null {
  const peaks = tpkValues
    .trim()
    .split(/\s+/)
    .map((value) => Number.parseFloat(value))
    .filter((value) => Number.isFinite(value));
  return peaks.length > 0 ? Math.max(...peaks) : null;
}

function parseTruePeakDb(searchText: string): number | null {
  const peakDbtpMatch = searchText.match(/Peak:\s*([-\d.]+)\s+dBTP/i);
  if (peakDbtpMatch) {
    return Number.parseFloat(peakDbtpMatch[1]);
  }

  const peakDbfsMatch = searchText.match(/Peak:\s*([-\d.]+)\s+dBFS/i);
  if (peakDbfsMatch) {
    return Number.parseFloat(peakDbfsMatch[1]);
  }

  const tpkDbtpMatch = searchText.match(/TPK:\s*(.+?)\s+dBTP/i);
  if (tpkDbtpMatch) {
    return parseTpkPeakValues(tpkDbtpMatch[1]);
  }

  const tpkDbfsMatch = searchText.match(/TPK:\s*(.+?)\s+dBFS/i);
  if (tpkDbfsMatch) {
    return parseTpkPeakValues(tpkDbfsMatch[1]);
  }

  return null;
}

function computeFfmpegTimeoutMs(fileSizeBytes?: number): number {
  if (!fileSizeBytes || fileSizeBytes <= 0) {
    return FFMPEG_MAX_TIMEOUT_MS;
  }

  const sizeMb = fileSizeBytes / (1024 * 1024);
  const scaledTimeout = FFMPEG_BASE_TIMEOUT_MS + sizeMb * FFMPEG_MS_PER_MB;
  return Math.min(
    FFMPEG_MAX_TIMEOUT_MS,
    Math.max(FFMPEG_MIN_TIMEOUT_MS, Math.round(scaledTimeout)),
  );
}

export function parseEbur128Summary(stderr: string): Ebur128ParseResult | null {
  const summaryIndex = stderr.lastIndexOf('Summary:');
  const searchText = summaryIndex >= 0 ? stderr.slice(summaryIndex) : stderr;

  let integratedLufs: number | null = null;

  const summaryIntegratedMatch = searchText.match(
    /Integrated loudness:\s*\r?\n\s*I:\s*([-\d.]+)\s+LUFS/i,
  );
  if (summaryIntegratedMatch) {
    integratedLufs = Number.parseFloat(summaryIntegratedMatch[1]);
  } else {
    const streamingMatches = [...stderr.matchAll(/\bI:\s*([-\d.]+)\s+LUFS/gi)];
    if (streamingMatches.length > 0) {
      integratedLufs = Number.parseFloat(streamingMatches[streamingMatches.length - 1][1]);
    }
  }

  if (
    integratedLufs === null ||
    !isFiniteInRange(integratedLufs, MIN_INTEGRATED_LUFS, MAX_INTEGRATED_LUFS)
  ) {
    return null;
  }

  const truePeakDb = parseTruePeakDb(searchText);

  if (truePeakDb === null || !isFiniteInRange(truePeakDb, MIN_TRUE_PEAK_DB, MAX_TRUE_PEAK_DB)) {
    return null;
  }

  let lraLu: number | undefined;
  const lraMatch = searchText.match(/Loudness range:\s*[\s\S]*?\bLRA:\s*([-\d.]+)\s+LU\b/i);
  if (lraMatch) {
    const parsedLra = Number.parseFloat(lraMatch[1]);
    if (Number.isFinite(parsedLra) && parsedLra >= 0 && parsedLra <= 50) {
      lraLu = parsedLra;
    }
  }

  let lraLowLufs: number | undefined;
  const lraLowMatch = searchText.match(/\bLRA low:\s*([-\d.]+)\s+LUFS\b/i);
  if (lraLowMatch) {
    const parsedLraLow = Number.parseFloat(lraLowMatch[1]);
    if (isFiniteInRange(parsedLraLow, MIN_INTEGRATED_LUFS, MAX_INTEGRATED_LUFS)) {
      lraLowLufs = parsedLraLow;
    }
  }

  return { integratedLufs, lraLowLufs, lraLu, truePeakDb };
}

export function computeTrackGainDb(
  integratedLufs: number,
  truePeakDb: number,
  targetLufs: number,
  headroomDbTp: number = HEADROOM_DB_TP,
): number {
  return computeAutoGainDb(integratedLufs, truePeakDb, targetLufs, headroomDbTp);
}

function getFfmpegCandidatePaths(): string[] {
  const candidates: string[] = [];
  const staticPath =
    typeof ffmpegStaticPath === 'string' && ffmpegStaticPath.length > 0 ? ffmpegStaticPath : null;

  if (app.isPackaged) {
    const executableName = process.platform === 'win32' ? 'ffmpeg.exe' : 'ffmpeg';
    candidates.push(path.join(process.resourcesPath, 'ffmpeg-static', executableName));

    if (staticPath) {
      if (isInsideAsarArchive(staticPath)) {
        candidates.push(staticPath.replace('app.asar', 'app.asar.unpacked'));
      } else {
        candidates.push(staticPath);
      }
    }
  } else if (staticPath) {
    candidates.push(staticPath);
  }

  return [...new Set(candidates)].filter((candidatePath) => !isInsideAsarArchive(candidatePath));
}

export function resolveFfmpegPath(): string | null {
  return getFfmpegCandidatePaths().find((candidatePath) => fs.existsSync(candidatePath)) ?? null;
}

function runFfmpegEbur128(
  ffmpegPath: string,
  filePath: string,
  fileSizeBytes?: number,
): Promise<{ stderr: string; exitCode: number | null }> {
  return new Promise((resolve, reject) => {
    const args = [
      '-hide_banner',
      '-nostats',
      '-i',
      filePath,
      '-af',
      'ebur128=peak=true',
      '-f',
      'null',
      '-',
    ];

    const child = spawn(ffmpegPath, args, {
      windowsHide: true,
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    let stderr = '';
    let settled = false;

    const timeoutMs = computeFfmpegTimeoutMs(fileSizeBytes);
    const timeoutId = setTimeout(() => {
      if (settled) {
        return;
      }
      child.kill();
      settled = true;
      reject(new Error(`FFmpeg loudness scan timed out after ${Math.round(timeoutMs / 1000)}s`));
    }, timeoutMs);

    child.stderr?.on('data', (chunk: Buffer | string) => {
      stderr += chunk.toString();
    });

    child.on('error', (error) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timeoutId);
      reject(error);
    });

    child.on('close', (exitCode) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timeoutId);
      resolve({ stderr, exitCode });
    });
  });
}

function enqueueScan<T>(task: () => Promise<T>): Promise<T> {
  const run = scanQueue.then(() => task());
  scanQueue = run.catch(() => undefined);
  return run;
}

function scanError(message: string): LoudnessScanError {
  return { status: 'error', errorMessage: message };
}

export async function analyzeLoudness(
  filePath: string,
  targetLufs: number = DEFAULT_TARGET_LUFS,
  options?: AnalyzeLoudnessOptions,
): Promise<LoudnessScanResult> {
  return enqueueScan(async () => {
    const ffmpegPath = resolveFfmpegPath();
    if (!ffmpegPath) {
      return scanError('FFmpeg binary not found. Ensure ffmpeg-static is installed and bundled.');
    }

    let fileMtime: number;
    if (options?.fileMtime !== undefined) {
      fileMtime = options.fileMtime;
    } else {
      try {
        const stats = await fs.promises.stat(filePath);
        fileMtime = normalizeStatNumber(stats.mtimeMs);
      } catch (error) {
        return scanError(`Failed to read file metadata: ${(error as Error).message}`);
      }
    }

    try {
      const { stderr, exitCode } = await runFfmpegEbur128(
        ffmpegPath,
        filePath,
        options?.fileSizeBytes,
      );

      if (exitCode !== 0) {
        const trimmed = stderr.trim();
        const tail = trimmed.length > 400 ? trimmed.slice(-400) : trimmed;
        return scanError(
          tail.length > 0
            ? `FFmpeg exited with code ${exitCode}: ${tail}`
            : `FFmpeg exited with code ${exitCode ?? 'unknown'}`,
        );
      }

      const parsed = parseEbur128Summary(stderr);
      if (!parsed) {
        return scanError('Failed to parse ebur128 measurement output from FFmpeg stderr');
      }

      const trackGainDb = computeTrackGainDb(parsed.integratedLufs, parsed.truePeakDb, targetLufs);

      return {
        status: 'ok',
        integratedLufs: parsed.integratedLufs,
        lraLowLufs: parsed.lraLowLufs,
        lraLu: parsed.lraLu,
        truePeakDb: parsed.truePeakDb,
        trackGainDb,
        fileMtime,
        algorithmVersion: LOUDNESS_ALGORITHM_VERSION,
      };
    } catch (error) {
      return scanError(`Loudness scan failed: ${(error as Error).message}`);
    }
  });
}

import { BrowserWindow, ipcMain } from 'electron';

import {
  AimpBridgeState,
  validateAimpLiveStreamPayload,
  validateAimpSourceSelectionPayload,
} from '../../src/shared/contracts/aimp.js';
import { aimpIntegrationService, type AimpLogEntry } from '../aimp/service.js';

const AIMP_STATE_CHANGED_CHANNEL = 'aimp:state-changed';
const AIMP_LOG_CHANNEL = 'aimp:log';

let hasRegisteredAimpHandlers = false;
let unsubscribeAimpBroadcast: (() => void) | null = null;
let unsubscribeAimpLog: (() => void) | null = null;

function broadcastAimpState(state: AimpBridgeState): void {
  for (const window of BrowserWindow.getAllWindows()) {
    if (!window.isDestroyed()) {
      window.webContents.send(AIMP_STATE_CHANGED_CHANNEL, state);
    }
  }
}

function broadcastAimpLog(entry: AimpLogEntry): void {
  for (const window of BrowserWindow.getAllWindows()) {
    if (!window.isDestroyed()) {
      window.webContents.send(AIMP_LOG_CHANNEL, entry);
    }
  }
}

export function registerAimpHandlers(): void {
  if (hasRegisteredAimpHandlers) {
    return;
  }

  hasRegisteredAimpHandlers = true;
  unsubscribeAimpBroadcast = aimpIntegrationService.subscribe((state) => {
    broadcastAimpState(state);
  });
  unsubscribeAimpLog = aimpIntegrationService.subscribeLog((entry) => {
    broadcastAimpLog(entry);
  });

  ipcMain.handle('aimp:getState', async () => {
    return {
      success: true,
      data: aimpIntegrationService.getState(),
    };
  });

  ipcMain.handle('aimp:setSourceSelection', async (_event, payload: unknown) => {
    const validationResult = validateAimpSourceSelectionPayload(payload);
    if (!validationResult.success) {
      return {
        success: false,
        error: validationResult.error.message,
      };
    }

    return {
      success: true,
      data: aimpIntegrationService.setSourceSelection(validationResult.value.sourceSelection),
    };
  });

  ipcMain.handle('aimp:setLiveStreamStarted', async (_event, payload: unknown) => {
    const validationResult = validateAimpLiveStreamPayload(payload);
    if (!validationResult.success) {
      return {
        success: false,
        error: validationResult.error.message,
      };
    }

    try {
      return {
        success: true,
        data: aimpIntegrationService.setLiveStreamStarted(validationResult.value.liveStreamStarted),
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to update AIMP live stream state',
      };
    }
  });
}

export function unregisterAimpHandlers(): void {
  unsubscribeAimpLog?.();
  unsubscribeAimpLog = null;
  unsubscribeAimpBroadcast?.();
  unsubscribeAimpBroadcast = null;
  hasRegisteredAimpHandlers = false;
}

import * as fs from 'fs/promises';
import * as path from 'path';

import { ipcMain } from 'electron';
import * as mm from 'music-metadata';

import {
  analyzeLoudness,
  DEFAULT_TARGET_LUFS,
  MAX_TARGET_LUFS,
  MIN_TARGET_LUFS,
} from '../audio/loudnessScanner.js';
import {
  encodePathToCherryplayAudioUrl,
  MAX_AUDIO_FILE_BYTES,
} from '../protocol/cherryplayAudio.js';
import { isAudioFile, normalizeStatNumber, validatePath } from '../utils/fsHelpers.js';

type AudioPathValidationResult =
  | { ok: true; resolvedPath: string; stats: Awaited<ReturnType<typeof fs.stat>> }
  | { ok: false; error: string };

async function validateAudioFilePath(userPath: string): Promise<AudioPathValidationResult> {
  if (!validatePath(userPath)) {
    return { ok: false, error: 'Invalid path: path traversal detected' };
  }

  const resolvedPath = path.resolve(userPath);

  if (!isAudioFile(resolvedPath)) {
    return { ok: false, error: 'Path is not an audio file' };
  }

  try {
    const stats = await fs.stat(resolvedPath);
    if (!stats.isFile()) {
      return { ok: false, error: 'Path is not a file' };
    }

    if (normalizeStatNumber(stats.size) > MAX_AUDIO_FILE_BYTES) {
      return { ok: false, error: 'Audio file exceeds maximum allowed size' };
    }

    return { ok: true, resolvedPath, stats };
  } catch (error) {
    return { ok: false, error: (error as Error).message };
  }
}

/**
 * Get audio file duration in seconds
 */
async function getAudioDuration(filePath: string): Promise<number> {
  try {
    // Read file metadata
    const metadata = await mm.parseFile(filePath);

    // Get duration in seconds
    if (metadata.format.duration) {
      return Math.floor(metadata.format.duration);
    }

    throw new Error('Duration not found in audio file');
  } catch (error) {
    throw new Error(`Failed to get audio duration: ${(error as Error).message}`);
  }
}

/**
 * Register audio IPC handlers
 */
export function registerAudioHandlers(): void {
  ipcMain.handle('audio:getDuration', async (event, payload: { path: string }) => {
    try {
      const validation = await validateAudioFilePath(payload.path);
      if (!validation.ok) {
        return {
          success: false,
          error: validation.error,
        };
      }

      const { resolvedPath } = validation;

      await fs.access(resolvedPath);

      const duration = await getAudioDuration(resolvedPath);
      return {
        success: true,
        data: duration,
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  ipcMain.handle('audio:getFileUrl', async (event, payload: { path: string }) => {
    try {
      const validation = await validateAudioFilePath(payload.path);
      if (!validation.ok) {
        return {
          success: false,
          error: validation.error,
        };
      }

      return {
        success: true,
        data: {
          url: encodePathToCherryplayAudioUrl(validation.resolvedPath),
        },
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  /**
   * IPC envelope for loudness analysis (subtask 03 relies on this contract):
   * - Path / payload validation failures → `{ success: false, error: string }`
   * - Scan completed (including FFmpeg/parse failures) → `{ success: true, data: LoudnessScanResult }`
   *   where scan failures use `data.status === 'error'` rather than `success: false`.
   * - Unexpected handler exceptions → `{ success: false, error: string }`
   */
  ipcMain.handle(
    'audio:analyzeLoudness',
    async (
      event,
      payload: {
        path: string;
        targetLufs?: number;
      },
    ) => {
      try {
        const validation = await validateAudioFilePath(payload.path);
        if (!validation.ok) {
          return {
            success: false,
            error: validation.error,
          };
        }

        let targetLufs = DEFAULT_TARGET_LUFS;
        if (typeof payload.targetLufs === 'number' && Number.isFinite(payload.targetLufs)) {
          if (payload.targetLufs < MIN_TARGET_LUFS || payload.targetLufs > MAX_TARGET_LUFS) {
            return {
              success: false,
              error: `targetLufs must be between ${MIN_TARGET_LUFS} and ${MAX_TARGET_LUFS}`,
            };
          }
          targetLufs = payload.targetLufs;
        }

        const result = await analyzeLoudness(validation.resolvedPath, targetLufs, {
          fileMtime: normalizeStatNumber(validation.stats.mtimeMs),
          fileSizeBytes: normalizeStatNumber(validation.stats.size),
        });
        return {
          success: true,
          data: result,
        };
      } catch (error) {
        return {
          success: false,
          error: (error as Error).message,
        };
      }
    },
  );

  ipcMain.handle('audio:statAudioFile', async (event, payload: { path: string }) => {
    try {
      const validation = await validateAudioFilePath(payload.path);
      if (!validation.ok) {
        return {
          success: false,
          error: validation.error,
        };
      }

      return {
        success: true,
        data: {
          mtimeMs: normalizeStatNumber(validation.stats.mtimeMs),
          size: normalizeStatNumber(validation.stats.size),
        },
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });
}

import { ipcMain, shell, BrowserWindow } from 'electron';

export type AuthCallbackData = {
  code: string;
  provider?: string;
};

const AUTH_CALLBACK_TIMEOUT_MS = 3 * 60 * 1000;
export const AUTH_CALLBACK_CANCELLED_MESSAGE = 'OAuth callback cancelled';

let authCallbackPromise: {
  resolve: (value: { success: true; data: AuthCallbackData }) => void;
  reject: (error: Error) => void;
} | null = null;

let authCallbackTimeoutId: ReturnType<typeof setTimeout> | null = null;
let pendingCallbackUrl: string | null = null;

function clearAuthCallbackTimeout(): void {
  if (authCallbackTimeoutId !== null) {
    clearTimeout(authCallbackTimeoutId);
    authCallbackTimeoutId = null;
  }
}

function rejectAuthCallback(error: Error): void {
  clearAuthCallbackTimeout();
  if (!authCallbackPromise) {
    return;
  }
  authCallbackPromise.reject(error);
  authCallbackPromise = null;
}

function cancelAuthCallbackWait(): boolean {
  if (!authCallbackPromise) {
    return false;
  }
  rejectAuthCallback(new Error(AUTH_CALLBACK_CANCELLED_MESSAGE));
  return true;
}

function parseAuthCallbackData(url: string): AuthCallbackData {
  const urlObj = new URL(url);
  const code = urlObj.searchParams.get('code');
  const state = urlObj.searchParams.get('state');
  const providerParam = urlObj.searchParams.get('provider');
  const pathProvider = urlObj.pathname.split('/').filter(Boolean)[1];
  const provider = state || providerParam || pathProvider || undefined;

  if (!code) {
    throw new Error('Invalid OAuth callback URL');
  }

  const data: AuthCallbackData = { code };
  if (provider) {
    data.provider = provider;
  }
  return data;
}

function resolveAuthCallback(data: AuthCallbackData, mainWindow: BrowserWindow | null): boolean {
  if (!authCallbackPromise) {
    return false;
  }

  clearAuthCallbackTimeout();
  authCallbackPromise.resolve({
    success: true,
    data,
  });
  authCallbackPromise = null;
  focusMainWindow(mainWindow);
  return true;
}

export function registerAuthHandlers(_mainWindow: BrowserWindow | null): void {
  ipcMain.handle('auth:openExternal', async (_event, { url }: { url: string }) => {
    try {
      await shell.openExternal(url);
      return { success: true };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to open external URL',
      };
    }
  });

  ipcMain.handle('auth:registerCallback', async (event) => {
    return new Promise<{ success: true; data: AuthCallbackData }>((resolve, reject) => {
      cancelAuthCallbackWait();
      authCallbackPromise = { resolve, reject };

      if (pendingCallbackUrl) {
        const url = pendingCallbackUrl;
        pendingCallbackUrl = null;
        try {
          const data = parseAuthCallbackData(url);
          const mainWindow = BrowserWindow.fromWebContents(event.sender);
          if (resolveAuthCallback(data, mainWindow)) {
            return;
          }
        } catch (error) {
          rejectAuthCallback(
            error instanceof Error ? error : new Error('Failed to parse OAuth callback'),
          );
          return;
        }
      }

      authCallbackTimeoutId = setTimeout(() => {
        rejectAuthCallback(new Error('OAuth callback timeout'));
      }, AUTH_CALLBACK_TIMEOUT_MS);
    });
  });

  ipcMain.handle('auth:cancelCallback', async () => {
    cancelAuthCallbackWait();
    return { success: true };
  });

  ipcMain.handle('auth:deliverCallbackUrl', async (_event, { url }: { url: string }) => {
    try {
      handleOAuthCallback(url, null);
      return { success: true };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to deliver auth callback',
      };
    }
  });
}

function focusMainWindow(mainWindow: BrowserWindow | null): void {
  if (!mainWindow) {
    return;
  }
  if (mainWindow.isMinimized()) {
    mainWindow.restore();
  }
  mainWindow.focus();
}

export function handleOAuthCallback(url: string, mainWindow: BrowserWindow | null): void {
  try {
    const data = parseAuthCallbackData(url);
    if (!resolveAuthCallback(data, mainWindow)) {
      pendingCallbackUrl = url;
    }
  } catch (error) {
    console.error('Error parsing OAuth callback URL:', error);
    rejectAuthCallback(
      error instanceof Error ? error : new Error('Failed to parse OAuth callback'),
    );
  }
}

export function resetAuthIpcStateForTests(): void {
  clearAuthCallbackTimeout();
  authCallbackPromise = null;
  pendingCallbackUrl = null;
}

import * as fs from 'fs';
import * as path from 'path';

import { app, ipcMain } from 'electron';

function getDevProjectRoot(): string {
  return fs.realpathSync.native(process.cwd());
}

interface ServerConfig {
  serverUrl: string;
  webBaseUrl?: string;
}

const DEFAULT_WEB_BASE_URL = {
  development: 'http://localhost:3000',
  production: 'https://cherrypashkaparty.ru',
} as const;

function resolveWebBaseUrl(config: ServerConfig | null): string {
  if (config?.webBaseUrl && typeof config.webBaseUrl === 'string' && config.webBaseUrl.trim()) {
    return config.webBaseUrl.trim();
  }
  return app.isPackaged ? DEFAULT_WEB_BASE_URL.production : DEFAULT_WEB_BASE_URL.development;
}

/** Config file name: dev vs packaged app. */
const CONFIG_FILE = {
  development: 'serverConfig.development.json',
  production: 'serverConfig.production.json',
} as const;

function getConfigPath(): string {
  const root = app.isPackaged ? app.getAppPath() : getDevProjectRoot();
  const fileName = app.isPackaged ? CONFIG_FILE.production : CONFIG_FILE.development;
  return path.join(root, fileName);
}

function readConfig(): ServerConfig | null {
  const configPath = getConfigPath();

  try {
    if (fs.existsSync(configPath)) {
      const fileContent = fs.readFileSync(configPath, 'utf-8');
      const config = JSON.parse(fileContent) as ServerConfig;

      if (typeof config.serverUrl !== 'string' || !config.serverUrl) {
        throw new Error('Invalid serverUrl in config');
      }

      return config;
    }
  } catch (error) {
    console.error('[Config] Error reading config file:', error);
    throw error;
  }

  return null;
}

function writeConfig(config: ServerConfig): void {
  const configPath = getConfigPath();

  try {
    const configDir = path.dirname(configPath);
    if (!fs.existsSync(configDir)) {
      fs.mkdirSync(configDir, { recursive: true });
    }

    if (typeof config.serverUrl !== 'string' || !config.serverUrl) {
      throw new Error('Invalid serverUrl in config');
    }

    fs.writeFileSync(configPath, JSON.stringify(config, null, 2), 'utf-8');
  } catch (error) {
    console.error('[Config] Error writing config file:', error);
    throw error;
  }
}

export function registerConfigHandlers(): void {
  ipcMain.handle('config:getConfigPath', async () => {
    try {
      const configPath = getConfigPath();
      return {
        success: true,
        data: configPath,
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  ipcMain.handle('config:getServerUrl', async () => {
    try {
      const config = readConfig();
      if (!config) {
        return {
          success: false,
          error:
            'Server URL is not configured. Add serverUrl to serverConfig.development.json (dev) or serverConfig.production.json (release build).',
        };
      }
      return {
        success: true,
        data: config.serverUrl,
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  ipcMain.handle('config:getWebBaseUrl', async () => {
    try {
      const config = readConfig();
      return {
        success: true,
        data: resolveWebBaseUrl(config),
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  ipcMain.handle('config:setServerUrl', async (event, payload: { serverUrl: string }) => {
    try {
      const currentConfig = readConfig();
      const newConfig: ServerConfig = {
        ...(currentConfig ?? {}),
        serverUrl: payload.serverUrl,
      };
      writeConfig(newConfig);
      return {
        success: true,
        data: newConfig.serverUrl,
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  ipcMain.handle('config:getConfig', async () => {
    try {
      const config = readConfig();
      if (!config) {
        return {
          success: false,
          error:
            'Server URL is not configured. Add serverUrl to serverConfig.development.json or serverConfig.production.json.',
        };
      }
      return {
        success: true,
        data: config,
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });
}

