import * as fs from 'fs/promises';
import * as path from 'path';

import { ipcMain } from 'electron';

import {
  copyFileWithRetry,
  ensureFolder,
  safeFileName,
  getRelativePath,
  validatePath,
} from '../utils/fsHelpers.js';

export interface Track {
  id: string;
  path: string;
  name: string;
  duration?: number;
}

export interface ExportResult {
  successful: string[];
  failed: Array<{ path: string; error: string }>;
}

/**
 * Export playlist with number prefix strategy
 */
async function exportWithNumberPrefix(tracks: Track[], targetPath: string): Promise<ExportResult> {
  const result: ExportResult = {
    successful: [],
    failed: [],
  };

  try {
    await ensureFolder(targetPath);

    for (let i = 0; i < tracks.length; i++) {
      const track = tracks[i];
      const number = (i + 1).toString().padStart(2, '0');
      const ext = path.extname(track.path);
      const originalName = path.basename(track.path, ext);
      const newName = `${number} - ${safeFileName(originalName)}${ext}`;
      const destPath = path.join(targetPath, newName);

      try {
        // Check if source file exists before copying
        await fs.access(track.path);
        await copyFileWithRetry(track.path, destPath);
        result.successful.push(track.path);
      } catch (error) {
        result.failed.push({
          path: track.path,
          error: (error as Error).message,
        });
      }
    }
  } catch (error) {
    throw new Error(`Export failed: ${(error as Error).message}`);
  }

  return result;
}

/**
 * Export playlist to AIMP format (M3U8)
 */
async function exportAIMPPlaylist(
  tracks: Track[],
  targetPath: string,
  playlistName: string,
): Promise<{
  playlistPath: string;
  successful: string[];
  failed: Array<{ path: string; error: string }>;
}> {
  const result: { successful: string[]; failed: Array<{ path: string; error: string }> } = {
    successful: [],
    failed: [],
  };

  try {
    // Create subfolder with playlist name
    const safePlaylistName = safeFileName(playlistName || 'Playlist');
    const playlistFolder = path.join(targetPath, safePlaylistName);
    await ensureFolder(playlistFolder);

    // Copy all tracks with original names
    for (const track of tracks) {
      const fileName = path.basename(track.path);
      const destPath = path.join(playlistFolder, fileName);

      try {
        // Check if source file exists before copying
        await fs.access(track.path);
        await copyFileWithRetry(track.path, destPath);
        result.successful.push(track.path);
      } catch (error) {
        result.failed.push({
          path: track.path,
          error: (error as Error).message,
        });
      }
    }

    // Create M3U8 playlist file
    const playlistFilePath = path.join(playlistFolder, `${safePlaylistName}.m3u8`);
    const playlistContent: string[] = ['#EXTM3U'];

    for (const track of tracks) {
      const fileName = path.basename(track.path);
      // Use relative path from playlist file to track file
      const relativePath = getRelativePath(playlistFilePath, path.join(playlistFolder, fileName));
      playlistContent.push(relativePath);
    }

    // Write playlist file with UTF-8 BOM for compatibility
    const bom = '\uFEFF';
    await fs.writeFile(playlistFilePath, bom + playlistContent.join('\n'), 'utf8');

    return {
      playlistPath: playlistFilePath,
      ...result,
    };
  } catch (error) {
    throw new Error(`AIMP export failed: ${(error as Error).message}`);
  }
}

/**
 * Copy tracks into a new folder (with original filenames)
 */
async function copyTracksToFolder(
  tracks: Track[],
  targetPath: string,
  folderName: string,
): Promise<{
  folderPath: string;
  successful: string[];
  failed: Array<{ path: string; error: string }>;
}> {
  const result: { successful: string[]; failed: Array<{ path: string; error: string }> } = {
    successful: [],
    failed: [],
  };

  try {
    const safeFolderName = safeFileName(folderName || 'Collection');
    const destinationFolder = path.join(targetPath, safeFolderName);
    await ensureFolder(destinationFolder);

    for (const track of tracks) {
      const fileName = path.basename(track.path);
      const destPath = path.join(destinationFolder, fileName);

      try {
        await fs.access(track.path);
        await copyFileWithRetry(track.path, destPath);
        result.successful.push(track.path);
      } catch (error) {
        result.failed.push({
          path: track.path,
          error: (error as Error).message,
        });
      }
    }

    return {
      folderPath: destinationFolder,
      ...result,
    };
  } catch (error) {
    throw new Error(`Copy failed: ${(error as Error).message}`);
  }
}

/**
 * Register export IPC handlers
 */
export function registerExportHandlers(): void {
  ipcMain.handle(
    'export:execute',
    async (
      event,
      payload: {
        tracks: Track[];
        targetPath: string;
        strategy: string;
      },
    ) => {
      try {
        // Validate target path
        if (!validatePath(payload.targetPath)) {
          return {
            success: false,
            error: 'Invalid target path: path traversal detected',
          };
        }

        // Validate all track paths
        for (const track of payload.tracks) {
          if (!validatePath(track.path)) {
            return {
              success: false,
              error: `Invalid track path: ${track.path} - path traversal detected`,
            };
          }
        }

        let result: ExportResult;

        if (payload.strategy === 'copyWithNumberPrefix') {
          result = await exportWithNumberPrefix(payload.tracks, payload.targetPath);
        } else {
          throw new Error(`Unknown export strategy: ${payload.strategy}`);
        }

        return {
          success: true,
          data: result,
        };
      } catch (error) {
        return {
          success: false,
          error: (error as Error).message,
        };
      }
    },
  );

  ipcMain.handle(
    'export:aimp',
    async (
      event,
      payload: {
        tracks: Track[];
        targetPath: string;
        playlistName: string;
      },
    ) => {
      try {
        // Validate target path
        if (!validatePath(payload.targetPath)) {
          return {
            success: false,
            error: 'Invalid target path: path traversal detected',
          };
        }

        // Validate all track paths
        for (const track of payload.tracks) {
          if (!validatePath(track.path)) {
            return {
              success: false,
              error: `Invalid track path: ${track.path} - path traversal detected`,
            };
          }
        }

        const result = await exportAIMPPlaylist(
          payload.tracks,
          payload.targetPath,
          payload.playlistName,
        );

        return {
          success: true,
          data: result,
        };
      } catch (error) {
        return {
          success: false,
          error: (error as Error).message,
        };
      }
    },
  );

  ipcMain.handle(
    'export:copyTracksToFolder',
    async (
      event,
      payload: {
        tracks: Track[];
        targetPath: string;
        folderName: string;
      },
    ) => {
      try {
        if (!validatePath(payload.targetPath)) {
          return {
            success: false,
            error: 'Invalid target path: path traversal detected',
          };
        }

        for (const track of payload.tracks) {
          if (!validatePath(track.path)) {
            return {
              success: false,
              error: `Invalid track path: ${track.path} - path traversal detected`,
            };
          }
        }

        const result = await copyTracksToFolder(
          payload.tracks,
          payload.targetPath,
          payload.folderName,
        );

        return {
          success: true,
          data: result,
        };
      } catch (error) {
        return {
          success: false,
          error: (error as Error).message,
        };
      }
    },
  );
}

import * as fs from 'fs/promises';
import * as path from 'path';

import { ipcMain } from 'electron';

import { isAudioFile, validatePath } from '../utils/fsHelpers.js';
import { logger } from '../utils/logger.js';

export interface DirectoryItem {
  name: string;
  path: string;
  isDirectory: boolean;
  size?: number;
}

/**
 * List directory contents
 */
async function listDirectory(dirPath: string): Promise<DirectoryItem[]> {
  try {
    // Validate path exists and is a directory
    const stats = await fs.stat(dirPath);
    if (!stats.isDirectory()) {
      throw new Error('Path is not a directory');
    }

    // Read directory contents
    const entries = await fs.readdir(dirPath, { withFileTypes: true });

    const items: DirectoryItem[] = [];

    for (const entry of entries) {
      const fullPath = path.join(dirPath, entry.name);

      try {
        const entryStats = await fs.stat(fullPath);
        items.push({
          name: entry.name,
          path: fullPath,
          isDirectory: entryStats.isDirectory(),
          size: entryStats.isFile() ? entryStats.size : undefined,
        });
      } catch (error) {
        // Skip entries that can't be accessed (permissions, etc.)
        logger.warn(`Cannot access ${fullPath}`, error);
      }
    }

    // Sort: directories first, then files, both alphabetically
    items.sort((a, b) => {
      if (a.isDirectory && !b.isDirectory) return -1;
      if (!a.isDirectory && b.isDirectory) return 1;
      return a.name.localeCompare(b.name);
    });

    return items;
  } catch (error) {
    throw new Error(`Failed to list directory: ${(error as Error).message}`);
  }
}

/**
 * Get file/directory stats
 */
async function statFile(filePath: string): Promise<{
  size: number;
  modified: number;
  isDirectory: boolean;
}> {
  try {
    const stats = await fs.stat(filePath);
    return {
      size: stats.size,
      modified: stats.mtimeMs,
      isDirectory: stats.isDirectory(),
    };
  } catch (error) {
    throw new Error(`Failed to stat file: ${(error as Error).message}`);
  }
}

/**
 * Find all audio files recursively in a directory
 */
async function findAudioFilesRecursive(dirPath: string): Promise<string[]> {
  const audioFiles: string[] = [];

  async function traverse(currentPath: string): Promise<void> {
    try {
      const stats = await fs.stat(currentPath);

      if (stats.isDirectory()) {
        const entries = await fs.readdir(currentPath, { withFileTypes: true });

        for (const entry of entries) {
          const fullPath = path.join(currentPath, entry.name);
          await traverse(fullPath);
        }
      } else if (stats.isFile() && isAudioFile(currentPath)) {
        audioFiles.push(currentPath);
      }
    } catch (error) {
      // Skip entries that can't be accessed
      logger.warn(`Cannot access ${currentPath}`, error);
    }
  }

  await traverse(dirPath);
  return audioFiles;
}

/**
 * Register file browser IPC handlers
 */
export function registerFileBrowserHandlers(): void {
  ipcMain.handle('fileBrowser:listDirectory', async (event, payload: { path: string }) => {
    try {
      // Validate path to prevent path traversal attacks
      if (!validatePath(payload.path)) {
        return {
          success: false,
          error: 'Invalid path: path traversal detected',
        };
      }

      const items = await listDirectory(payload.path);
      return {
        success: true,
        data: items,
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  ipcMain.handle('fileBrowser:statFile', async (event, payload: { path: string }) => {
    try {
      // Validate path to prevent path traversal attacks
      if (!validatePath(payload.path)) {
        return {
          success: false,
          error: 'Invalid path: path traversal detected',
        };
      }

      const stats = await statFile(payload.path);
      return {
        success: true,
        data: stats,
      };
    } catch (error) {
      return {
        success: false,
        error: (error as Error).message,
      };
    }
  });

  ipcMain.handle(
    'fileBrowser:findAudioFilesRecursive',
    async (event, payload: { path: string }) => {
      try {
        // Validate path to prevent path traversal attacks
        if (!validatePath(payload.path)) {
          return {
            success: false,
            error: 'Invalid path: path traversal detected',
          };
        }

        const files = await findAudioFilesRecursive(payload.path);
        return {
          success: true,
          data: files,
        };
      } catch (error) {
        return {
          success: false,
          error: (error as Error).message,
        };
      }
    },
  );
}

