let mainWindow: BrowserWindow | null = null;

const isDev = process.env.NODE_ENV === 'development' || !app.isPackaged;

function createWindow(): void {
  mainWindow = new BrowserWindow({
    width: 1200,
    height: 800,
    // App-level floor only; the renderer refines this dynamically via
    // `system:setMinimumWindowSize` using max(appFloor, layout-computed mins).
    minWidth: APP_MIN_WINDOW_WIDTH,
    minHeight: APP_MIN_WINDOW_HEIGHT,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      preload: path.join(__dirname, 'preload.js'),
      webviewTag: false,
      webSecurity: !isDev,
    },
  });

  if (isDev) {
    mainWindow.loadURL('http://localhost:5173');
    mainWindow.webContents.openDevTools();
  } else {
    const indexHtmlPath = path.join(app.getAppPath(), 'dist/index.html');
    mainWindow.loadFile(indexHtmlPath);
  }

  mainWindow.on('closed', () => {
    mainWindow = null;
  });
}

// Регистрация custom URL scheme для OAuth callback
const PROTOCOL = 'cherryplaylist';

// Регистрируем protocol только если приложение не упаковано или в dev режиме
if (process.defaultApp) {
  if (process.argv.length >= 2) {
    app.setAsDefaultProtocolClient(PROTOCOL, process.execPath, [path.resolve(process.argv[1])]);
  }
} else if (!app.isDefaultProtocolClient(PROTOCOL)) {
  app.setAsDefaultProtocolClient(PROTOCOL);
}

registerCherryplayAudioScheme();

app.whenReady().then(() => {
  registerCherryplayAudioProtocolHandler();

  Menu.setApplicationMenu(null);
  session.defaultSession.webRequest.onHeadersReceived((details, callback) => {
    const csp = [
      "default-src 'self' 'unsafe-inline' 'unsafe-eval' data: blob: cherryplay-audio: http://localhost:* ws://localhost:* wss://localhost:* http://*:* https://*:* ws://*:* wss://*:* https://fonts.googleapis.com https://fonts.gstatic.com; " +
        "connect-src 'self' http://localhost:* ws://localhost:* wss://localhost:* http://*:* https://*:* ws://*:* wss://*:* https://fonts.googleapis.com https://fonts.gstatic.com; " +
        "media-src cherryplay-audio: blob: 'self'; " +
        "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; " +
        "font-src 'self' data: https://fonts.gstatic.com;",
    ];
    callback({
      responseHeaders: {
        ...details.responseHeaders,
        'Content-Security-Policy': csp,
      },
    });
  });

  registerFileBrowserHandlers();
  registerAimpHandlers();
  registerAudioHandlers();
  registerDialogHandlers();
  registerSystemHandlers();
  registerConfigHandlers();
  registerExportHandlers();
  registerProjectHandlers();
  registerPlaylistHandlers();
  registerSettingsBundleHandlers();
  registerAuthHandlers(mainWindow);

  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

// Обработка OAuth callback через custom URL scheme
// macOS
app.on('open-url', (event, url) => {
  event.preventDefault();
  handleOAuthCallback(url, mainWindow);
});

// Windows/Linux - обрабатываем аргументы командной строки
const gotTheLock = app.requestSingleInstanceLock();

if (!gotTheLock) {
  app.quit();
} else {
  app.on('second-instance', (_event, commandLine) => {
    // Обрабатываем URL из второго экземпляра
    const url = commandLine.find((arg) => arg.startsWith(`${PROTOCOL}://`));
    if (url) {
      handleOAuthCallback(url, mainWindow);
    }
    // Фокусируемся на главном окне
    if (mainWindow) {
      if (mainWindow.isMinimized()) mainWindow.restore();
      mainWindow.focus();
    }
  });
}

// Обрабатываем URL при запуске приложения (Windows/Linux)
if (process.platform !== 'darwin') {
  const url = process.argv.find((arg) => arg.startsWith(`${PROTOCOL}://`));
  if (url) {
    handleOAuthCallback(url, mainWindow);
  }
}

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('before-quit', () => {
  aimpIntegrationService.dispose();
});

import { contextBridge, ipcRenderer, webUtils } from 'electron';

import {
  isAimpSourceSelection,
  validateAimpBridgeState,
  validateAimpBridgeStateResponse,
  validateAimpLiveStreamPayload,
  validateAimpSourceSelectionPayload,
  type AimpBridgeState,
  type AimpLogEntry,
  type AimpSourceSelection,
} from '../src/shared/contracts/aimp';

function assertBoolean(value: unknown, fieldName: string): asserts value is boolean {
  if (typeof value !== 'boolean') {
    throw new Error(`${fieldName} must be a boolean`);
  }
}

function assertAimpSourceSelection(value: unknown): asserts value is AimpSourceSelection {
  if (!isAimpSourceSelection(value)) {
    throw new Error('sourceSelection must be "cherryPlayPlayer" or "aimp"');
  }
}

const VALID_INVOKE_CHANNELS = [
  'fileBrowser:listDirectory',
  'fileBrowser:statFile',
  'fileBrowser:findAudioFilesRecursive',
  'audio:getDuration',
  'audio:getFileUrl',
  'audio:analyzeLoudness',
  'audio:statAudioFile',
  'export:execute',
  'export:copyFile',
  'export:aimp',
  'export:copyTracksToFolder',
  'project:save',
  'project:savePortableAs',
  'project:load',
  'plugins:list',
  'dialog:showOpenDialog',
  'dialog:showSaveDialog',
  'dialog:showOpenFileDialog',
  'system:getPath',
  'system:openPath',
  'system:openExternal',
  'system:setMinimumWindowSize',
  'config:getConfigPath',
  'config:getServerUrl',
  'config:getWebBaseUrl',
  'config:setServerUrl',
  'config:getConfig',
  'auth:openExternal',
  'auth:registerCallback',
  'auth:cancelCallback',
  'auth:deliverCallbackUrl',
  'settings:saveBundle',
  'settings:loadBundle',
] as const;

const VALID_ON_CHANNELS = ['project:save-progress'] as const;

function assertValidInvokeChannel(channel: string): void {
  if (!(VALID_INVOKE_CHANNELS as readonly string[]).includes(channel)) {
    throw new Error(`Invalid IPC channel: ${channel}`);
  }
}

function assertValidOnChannel(channel: string): void {
  if (!(VALID_ON_CHANNELS as readonly string[]).includes(channel)) {
    throw new Error(`Invalid IPC channel: ${channel}`);
  }
}

async function invokeValidatedAimpChannel(
  channel: 'aimp:getState' | 'aimp:setSourceSelection' | 'aimp:setLiveStreamStarted',
  payload?: unknown,
): Promise<{
  success: boolean;
  data?: AimpBridgeState;
  error?: string;
}> {
  const response = await ipcRenderer.invoke(channel, payload);
  const validationResult = validateAimpBridgeStateResponse(response);
  if (!validationResult.success) {
    throw new Error(validationResult.error.message);
  }

  return validationResult.value;
}

function assertValidAimpState(state: unknown): AimpBridgeState {
  const validationResult = validateAimpBridgeState(state);
  if (!validationResult.success) {
    throw new Error(validationResult.error.message);
  }

  return validationResult.value;
}

contextBridge.exposeInMainWorld('api', {
  getPathForFile: (file: File) => {
    if (!file || typeof file !== 'object') {
      throw new Error('getPathForFile: expected a File object');
    }
    return webUtils.getPathForFile(file);
  },

  invoke: (channel: string, payload?: object) => {
    assertValidInvokeChannel(channel);
    return ipcRenderer.invoke(channel, payload);
  },

  on: (
    channel: string,
    listener: (event: Electron.IpcRendererEvent, ...args: unknown[]) => void,
  ) => {
    assertValidOnChannel(channel);
    ipcRenderer.on(channel, listener);
    return () => ipcRenderer.removeListener(channel, listener);
  },

  aimp: {
    getState: () => invokeValidatedAimpChannel('aimp:getState'),
    setSourceSelection: (sourceSelection: AimpSourceSelection) => {
      assertAimpSourceSelection(sourceSelection);
      const validationResult = validateAimpSourceSelectionPayload({
        sourceSelection,
      });
      if (!validationResult.success) {
        throw new Error(validationResult.error.message);
      }

      return invokeValidatedAimpChannel('aimp:setSourceSelection', validationResult.value);
    },
    setLiveStreamStarted: (liveStreamStarted: boolean) => {
      assertBoolean(liveStreamStarted, 'liveStreamStarted');
      const validationResult = validateAimpLiveStreamPayload({
        liveStreamStarted,
      });
      if (!validationResult.success) {
        throw new Error(validationResult.error.message);
      }

      return invokeValidatedAimpChannel('aimp:setLiveStreamStarted', validationResult.value);
    },
    onStateChanged: (listener: (state: AimpBridgeState) => void) => {
      const wrappedListener = (_event: Electron.IpcRendererEvent, state: unknown) => {
        listener(assertValidAimpState(state));
      };

      ipcRenderer.on('aimp:state-changed', wrappedListener);
      return () => ipcRenderer.removeListener('aimp:state-changed', wrappedListener);
    },
    onLog: (listener: (entry: AimpLogEntry) => void) => {
      const wrappedListener = (_event: Electron.IpcRendererEvent, entry: AimpLogEntry) => {
        listener(entry);
      };
      ipcRenderer.on('aimp:log', wrappedListener);
      return () => ipcRenderer.removeListener('aimp:log', wrappedListener);
    },
  },
});

export {};

declare global {
  interface Window {
    api: {
      getPathForFile: (file: File) => string;
      invoke: (channel: string, payload?: object) => ReturnType<typeof ipcRenderer.invoke>;
      on: (channel: string, listener: (event: unknown, ...args: unknown[]) => void) => () => void;
      aimp: {
        getState: () => Promise<{ success: boolean; data?: AimpBridgeState; error?: string }>;
        setSourceSelection: (
          sourceSelection: AimpSourceSelection,
        ) => Promise<{ success: boolean; data?: AimpBridgeState; error?: string }>;
        setLiveStreamStarted: (
          liveStreamStarted: boolean,
        ) => Promise<{ success: boolean; data?: AimpBridgeState; error?: string }>;
        onStateChanged: (listener: (state: AimpBridgeState) => void) => () => void;
        onLog: (listener: (entry: AimpLogEntry) => void) => () => void;
      };
    };
  }
}

import { createReadStream } from 'fs';
import * as fs from 'fs/promises';
import * as path from 'path';

import { protocol } from 'electron';

import { isAudioFile, validatePath } from '../utils/fsHelpers.js';

export const CHERRYPLAY_AUDIO_SCHEME = 'cherryplay-audio';

/** Fixed authority host so the base64 payload stays in pathname (case-sensitive). */
export const CHERRYPLAY_AUDIO_HOST = 'local';

/** Stat-only guard for absurdly large files; streaming itself is not memory-bound. */
export const MAX_AUDIO_FILE_BYTES = 2 * 1024 * 1024 * 1024;

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
} as const;

function withCorsHeaders(headers: Record<string, string> = {}): Record<string, string> {
  return { ...CORS_HEADERS, ...headers };
}

const AUDIO_MIME_TYPES: Record<string, string> = {
  '.mp3': 'audio/mpeg',
  '.wav': 'audio/wav',
  '.flac': 'audio/flac',
  '.m4a': 'audio/mp4',
  '.ogg': 'audio/ogg',
};

function base64urlEncodeUtf8(text: string): string {
  return Buffer.from(text, 'utf8')
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

function base64urlDecodeUtf8(encoded: string): string {
  const base64 = encoded.replace(/-/g, '+').replace(/_/g, '/');
  const padding = '='.repeat((4 - (base64.length % 4)) % 4);
  return Buffer.from(base64 + padding, 'base64').toString('utf8');
}

export function getAudioMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  return AUDIO_MIME_TYPES[ext] ?? 'application/octet-stream';
}

export interface ParsedByteRange {
  readonly start: number;
  readonly end: number;
}

export function parseByteRange(
  rangeHeader: string | null,
  fileSize: number,
): ParsedByteRange | null | 'unsatisfiable' {
  if (!rangeHeader) {
    return null;
  }

  const match = /^bytes=(\d*)-(\d*)$/i.exec(rangeHeader.trim());
  if (!match) {
    return 'unsatisfiable';
  }

  const [, startPart, endPart] = match;
  let start: number;
  let end: number;

  if (startPart === '' && endPart !== '') {
    const suffixLength = Number.parseInt(endPart, 10);
    if (!Number.isFinite(suffixLength) || suffixLength <= 0) {
      return 'unsatisfiable';
    }
    start = Math.max(0, fileSize - suffixLength);
    end = fileSize - 1;
  } else if (startPart !== '' && endPart === '') {
    start = Number.parseInt(startPart, 10);
    end = fileSize - 1;
  } else if (startPart !== '' && endPart !== '') {
    start = Number.parseInt(startPart, 10);
    end = Number.parseInt(endPart, 10);
  } else {
    return 'unsatisfiable';
  }

  if (!Number.isFinite(start) || !Number.isFinite(end) || start < 0 || start >= fileSize) {
    return 'unsatisfiable';
  }

  if (end >= fileSize) {
    end = fileSize - 1;
  }

  if (start > end) {
    return 'unsatisfiable';
  }

  return { start, end };
}

/**
 * Build a streaming playback URL for a local file path.
 * Format: `cherryplay-audio://local/<base64url(utf8-absolute-path)>`
 *
 * Do not use `cherryplay-audio:///<payload>` — Chromium moves the payload into
 * hostname and lowercases it, corrupting case-sensitive base64url.
 */
export function encodePathToCherryplayAudioUrl(filePath: string): string {
  return `${CHERRYPLAY_AUDIO_SCHEME}://${CHERRYPLAY_AUDIO_HOST}/${base64urlEncodeUtf8(filePath)}`;
}

/**
 * Extract base64url payload from a cherryplay-audio request URL.
 *
 * Canonical form: `cherryplay-audio://local/<payload>` (payload in pathname).
 * Legacy `cherryplay-audio:///<payload>` may appear as `cherryplay-audio://<payload>/`
 * with lowercased hostname — decoding often fails; kept only as best-effort fallback.
 */
export function extractEncodedPathFromCherryplayAudioUrl(requestUrl: string): string | null {
  try {
    const url = new URL(requestUrl);
    if (url.protocol !== `${CHERRYPLAY_AUDIO_SCHEME}:`) {
      return null;
    }

    const pathnamePayload = url.pathname.startsWith('/') ? url.pathname.slice(1) : url.pathname;
    if (pathnamePayload) {
      return pathnamePayload;
    }

    // Legacy browser-normalized triple-slash form (hostname is lowercased — often corrupt).
    if (url.hostname && url.hostname !== CHERRYPLAY_AUDIO_HOST) {
      return url.hostname;
    }

    return null;
  } catch {
    return null;
  }
}

export function decodePathFromCherryplayAudioUrl(requestUrl: string): string | null {
  const encodedPath = extractEncodedPathFromCherryplayAudioUrl(requestUrl);
  if (!encodedPath) {
    return null;
  }

  try {
    return base64urlDecodeUtf8(encodedPath);
  } catch {
    return null;
  }
}

export async function handleCherryplayAudioRequest(request: Request): Promise<Response> {
  const filePath = decodePathFromCherryplayAudioUrl(request.url);
  if (!filePath || !validatePath(filePath)) {
    return new Response('Forbidden', { status: 403, headers: withCorsHeaders() });
  }

  const resolvedPath = path.resolve(filePath);

  if (!isAudioFile(resolvedPath)) {
    return new Response('Forbidden', { status: 403, headers: withCorsHeaders() });
  }

  let fileSize = 0;
  try {
    const stats = await fs.stat(resolvedPath);
    if (!stats.isFile()) {
      return new Response('Forbidden', { status: 403, headers: withCorsHeaders() });
    }
    fileSize = stats.size;
  } catch {
    return new Response('Forbidden', { status: 403, headers: withCorsHeaders() });
  }

  if (fileSize > MAX_AUDIO_FILE_BYTES) {
    return new Response('Payload Too Large', { status: 413, headers: withCorsHeaders() });
  }

  const mimeType = getAudioMimeType(resolvedPath);
  const rangeHeader = request.headers.get('range') ?? request.headers.get('Range');
  const parsedRange = parseByteRange(rangeHeader, fileSize);

  if (parsedRange === 'unsatisfiable') {
    return new Response(null, {
      status: 416,
      headers: withCorsHeaders({
        'Content-Range': `bytes */${fileSize}`,
      }),
    });
  }

  if (parsedRange) {
    const { start, end } = parsedRange;
    const contentLength = end - start + 1;
    const stream = createReadStream(resolvedPath, { start, end });

    return new Response(stream as unknown as ReadableStream<Uint8Array>, {
      status: 206,
      headers: withCorsHeaders({
        'Accept-Ranges': 'bytes',
        'Content-Length': String(contentLength),
        'Content-Range': `bytes ${start}-${end}/${fileSize}`,
        'Content-Type': mimeType,
      }),
    });
  }

  const stream = createReadStream(resolvedPath);
  return new Response(stream as unknown as ReadableStream<Uint8Array>, {
    status: 200,
    headers: withCorsHeaders({
      'Accept-Ranges': 'bytes',
      'Content-Length': String(fileSize),
      'Content-Type': mimeType,
    }),
  });
}

/**
 * Must be called before `app.whenReady()`.
 */
export function registerCherryplayAudioScheme(): void {
  protocol.registerSchemesAsPrivileged([
    {
      scheme: CHERRYPLAY_AUDIO_SCHEME,
      privileges: {
        standard: true,
        secure: true,
        stream: true,
        corsEnabled: true,
      },
    },
  ]);
}

/**
 * Must be called inside `app.whenReady()`.
 */
export function registerCherryplayAudioProtocolHandler(): void {
  protocol.handle(CHERRYPLAY_AUDIO_SCHEME, handleCherryplayAudioRequest);
}

import * as fs from 'fs/promises';
import * as path from 'path';

import { logger } from './logger.js';

// Supported audio file extensions
const AUDIO_EXTENSIONS = ['.mp3', '.wav', '.flac', '.m4a', '.ogg'] as const;

/** Coerce fs.stat numeric fields (Node may type them as number | bigint). */
export function normalizeStatNumber(value: number | bigint): number {
  return typeof value === 'bigint' ? Number(value) : value;
}

/**
 * Check if a file is an audio file based on its extension
 */
export function isAudioFile(filePath: string): boolean {
  const ext = path.extname(filePath).toLowerCase();
  return (AUDIO_EXTENSIONS as readonly string[]).includes(ext);
}

/**
 * Copy file with retry mechanism
 */
export async function copyFileWithRetry(
  src: string,
  dest: string,
  maxRetries: number = 3,
): Promise<void> {
  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      // Ensure destination directory exists
      const destDir = path.dirname(dest);
      await ensureFolder(destDir);

      // Copy file
      await fs.copyFile(src, dest);
      return; // Success
    } catch (error) {
      lastError = error as Error;
      if (attempt < maxRetries) {
        // Wait before retry (exponential backoff)
        await new Promise((resolve) => setTimeout(resolve, 100 * attempt));
      }
    }
  }

  throw lastError || new Error('Copy failed after retries');
}

/**
 * Ensure folder exists, create if it doesn't
 */
export async function ensureFolder(folderPath: string): Promise<void> {
  try {
    await fs.access(folderPath);
  } catch {
    // Folder doesn't exist, create it recursively
    await fs.mkdir(folderPath, { recursive: true });
  }
}

/**
 * Sanitize filename by removing problematic characters
 */
export function safeFileName(fileName: string): string {
  // Remove or replace problematic characters
  // Windows: < > : " | ? * \
  // Also remove control characters
  return (
    fileName
      .replace(/[<>:"|?*\\]/g, '_')
      // eslint-disable-next-line no-control-regex
      .replace(/[\u0000-\u001F\u007F]/g, '') // Remove control characters
      .trim()
  );
}

/** Windows: reserved device / DOS names, case-insensitive (folder segment). */
const WIN32_RESERVED_DIR_NAMES = new Set(
  [
    'CON',
    'PRN',
    'AUX',
    'NUL',
    'COM1',
    'COM2',
    'COM3',
    'COM4',
    'COM5',
    'COM6',
    'COM7',
    'COM8',
    'COM9',
    'LPT1',
    'LPT2',
    'LPT3',
    'LPT4',
    'LPT5',
    'LPT6',
    'LPT7',
    'LPT8',
    'LPT9',
  ].map((s) => s.toUpperCase()),
);

/**
 * For portable project packages the output folder name must match the project name exactly.
 * Rejects names that need sanitization, path separators, or (on Windows) reserved / trailing rules.
 * @throws Error with user-facing RU message when invalid
 */
export function assertExactPortableProjectFolderName(name: string): void {
  const trimmed = name.trim();
  if (trimmed.length === 0) {
    throw new Error('Пустое название проекта — укажите имя, которое подойдёт для папки на диске');
  }
  if (trimmed !== name) {
    throw new Error('Название проекта не должно иметь лишние пробелы по краям');
  }
  if (name.includes('/') || name.includes('\\')) {
    throw new Error(
      'В названии проекта не должно быть символов пути. Измените название и повторите попытку.',
    );
  }
  if (safeFileName(name) !== name) {
    throw new Error(
      'В названии проекта есть символы, нельзя использовать в имени папки (например < > : " | ? * \\). ' +
        'Измените название так, как должна называться папка на диске, и повторите попытку.',
    );
  }
  if (process.platform === 'win32') {
    if (/[. ]$/.test(name)) {
      throw new Error(
        'В Windows имя папки не может заканчиваться точкой или пробелом. Измените название проекта.',
      );
    }
    if (WIN32_RESERVED_DIR_NAMES.has(name.toUpperCase())) {
      throw new Error(
        'Это имя зарезервировано в Windows для устройств. Задайте другое название проекта.',
      );
    }
  }
}

/**
 * Get relative path from one file/folder to another
 * Returns path using forward slashes (M3U standard)
 */
/**
 * True when `absolutePath` resolves to a location under `projectDir` (same
 * drive / root), so it is a normal project-scoped file. Used for strict
 * portable policy: a relative `srcPath` with `..` is allowed only if the
 * resulting path either stays inside the project, or (when outside) the file
 * exists and passes a strict `fs.access` check in the portable copy step.
 */
export function isResolvedPathUnderProjectDir(projectDir: string, absolutePath: string): boolean {
  const resolvedBase = path.resolve(projectDir);
  const resolved = path.resolve(absolutePath);
  const rel = path.relative(resolvedBase, resolved);
  if (rel === '') {
    return true;
  }
  if (rel.startsWith('..') || path.isAbsolute(rel)) {
    return false;
  }
  return true;
}

/**
 * Resolves a track path for portable copy and whether it escapes the project
 * directory (e.g. `../media/a.flac` or an absolute path on another drive).
 */
export function getPortableTrackSourceResolutionMeta(
  projectDir: string,
  srcPath: string,
): { absolute: string; outsideProjectDir: boolean } {
  const absolute = resolveTrackSourceForPortableCopy(projectDir, srcPath);
  return { absolute, outsideProjectDir: !isResolvedPathUnderProjectDir(projectDir, absolute) };
}

/**
 * Resolve a track file path for portable copy: absolute paths stay normalized;
 * relative paths (including `./` and `../` segments) are resolved against the
 * directory of the .cherry file, not the process cwd.
 */
export function resolveTrackSourceForPortableCopy(projectDir: string, srcPath: string): string {
  if (path.isAbsolute(srcPath)) {
    return path.resolve(srcPath);
  }
  return path.resolve(projectDir, srcPath);
}

export function getRelativePath(from: string, to: string): string {
  // Normalize paths
  const fromNormalized = path.resolve(from);
  const toNormalized = path.resolve(to);

  // Get relative path
  const relative = path.relative(path.dirname(fromNormalized), toNormalized);

  // Convert to forward slashes (M3U standard)
  return relative.replace(/\\/g, '/');
}

/**
 * Validate path to prevent path traversal attacks
 * @param userPath - Path provided by user
 * @param basePath - Optional base path to restrict access to
 * @returns true if path is valid, false otherwise
 */
export function validatePath(userPath: string, basePath?: string): boolean {
  if (!userPath || typeof userPath !== 'string') {
    return false;
  }

  try {
    // Block path traversal attempts (.. as path component) if basePath is not specified
    // This prevents path traversal attacks when no base path restriction is provided
    // Note: We allow ~ in filenames (valid on Windows and Unix)
    // Only ~ at the start of a path (like ~/file) is special on Unix, but path.resolve() handles it correctly
    // Check for .. as a path component (not just in filename), e.g., /../, \..\, ../, ..\
    if (!basePath) {
      // Check for .. as a separate path component (both forward and backslashes)
      const hasPathTraversal =
        userPath.includes('/../') ||
        userPath.includes('\\..\\') ||
        userPath.includes('\\../') ||
        userPath.includes('/..\\') ||
        userPath.startsWith('../') ||
        userPath.startsWith('..\\') ||
        userPath.endsWith('/..') ||
        userPath.endsWith('\\..') ||
        userPath === '..';
      if (hasPathTraversal) {
        return false;
      }
    }

    // Resolve and normalize the path
    const resolvedPath = path.resolve(userPath);

    // If basePath is provided, ensure resolved path is within it
    if (basePath) {
      const resolvedBasePath = path.resolve(basePath);

      // Check if resolved path starts with resolved base path
      // Use path.relative to check if path is within base
      const relative = path.relative(resolvedBasePath, resolvedPath);

      // If relative path starts with .. or is absolute, it's outside basePath
      if (relative.startsWith('..') || path.isAbsolute(relative)) {
        return false;
      }
    }

    return true;
  } catch (error) {
    // Log errors for debugging in development mode
    logger.error('Path validation error', error);
    // If path resolution fails, it's invalid
    return false;
  }
}

/**
 * Simple logging utility for Electron main process
 * In production, only warn and error are logged
 * In development, all log levels are visible
 */

class Logger {
  private isDev = process.env.NODE_ENV === 'development' || !process.env.NODE_ENV;

  debug(message: string, ...args: unknown[]): void {
    if (this.isDev) {
      console.debug(`[DEBUG] ${message}`, ...args);
    }
  }

  info(message: string, ...args: unknown[]): void {
    if (this.isDev) {
      console.info(`[INFO] ${message}`, ...args);
    }
  }

  warn(message: string, ...args: unknown[]): void {
    console.warn(`[WARN] ${message}`, ...args);
  }

  error(message: string, error?: Error | unknown, ...args: unknown[]): void {
    if (error instanceof Error) {
      console.error(`[ERROR] ${message}`, error, ...args);
    } else {
      console.error(`[ERROR] ${message}`, error, ...args);
    }
    // In production, could send to error tracking service (e.g., Sentry)
  }
}

export const logger = new Logger();

