import { IconButton } from '@cherryplay/components';
import CloseIcon from '@mui/icons-material/Close';
import React, { useCallback, useEffect, useRef } from 'react';

import { OnlineUnavailablePanel } from '@shared/components';
import { useModalKeyboard } from '@shared/hooks';
import { useClientOutdatedStore, useUIStore } from '@shared/stores';

import { PartySettingsContent } from '../../workspaces/party/components/PartySettingsContent';
import {
  PartyWorkspaceRuntimeEphemeralHost,
  type PartyWorkspaceRuntimeValue,
  useSharedPartyWorkspaceRuntime,
} from '../../workspaces/party/partyWorkspaceRuntimeContext';
import { usePartyWorkspaceStore } from '../../workspaces/party/partyWorkspaceStore';

import './PartySettingsModal.css';

interface PartySettingsModalOpenProps {
  runtime: PartyWorkspaceRuntimeValue | null;
  isClientOutdated: boolean;
  clientRequiredVersion: string | null;
  onClose: () => void;
  onOpenLinkParty: () => void;
}

const PartySettingsModalOpen: React.FC<PartySettingsModalOpenProps> = ({
  runtime,
  isClientOutdated,
  clientRequiredVersion,
  onClose,
  onOpenLinkParty,
}) => {
  const dialogRef = useRef<HTMLDivElement>(null);
  const themeEntitlementModal = usePartyWorkspaceStore((state) => state.themeEntitlementModal);
  const setThemeEntitlementModal = usePartyWorkspaceStore(
    (state) => state.setThemeEntitlementModal,
  );

  useModalKeyboard({
    enabled: true,
    onCancel: onClose,
  });

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) {
      return;
    }
    const previouslyFocused =
      document.activeElement instanceof HTMLElement ? document.activeElement : null;
    dialog.focus();
    return () => {
      previouslyFocused?.focus();
    };
  }, []);

  const handleOverlayClick = useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      if (event.target === event.currentTarget) {
        onClose();
      }
    },
    [onClose],
  );

  return (
    <>
      <PartyWorkspaceRuntimeEphemeralHost />
      <div className="modal-overlay" onClick={handleOverlayClick} role="presentation">
        <div
          ref={dialogRef}
          className="modal-content party-settings-modal-content"
          role="dialog"
          aria-modal="true"
          aria-labelledby="party-settings-modal-title"
          tabIndex={-1}
        >
          <div className="modal-header">
            <h2 className="modal-title" id="party-settings-modal-title">
              Настройки вечеринки
            </h2>
            <IconButton
              type="button"
              className="modal-close"
              onClick={onClose}
              aria-label="Закрыть"
              icon={<CloseIcon />}
              variant="ghost"
              size="md"
            />
          </div>

          <div className="modal-body party-settings-modal-body">
            {isClientOutdated ? (
              <OnlineUnavailablePanel reason="outdated" requiredVersion={clientRequiredVersion} />
            ) : runtime ? (
              <PartySettingsContent runtime={runtime} onOpenLinkParty={onOpenLinkParty} />
            ) : (
              <div className="party-settings-modal-loading">Загрузка настроек вечеринки...</div>
            )}
          </div>
        </div>
      </div>

      {themeEntitlementModal ? (
        <div className="party-editor-locked-theme-modal-overlay" role="dialog" aria-modal="true">
          <div className="party-editor-locked-theme-modal">
            <h4 className="party-editor-locked-theme-title">Тема недоступна</h4>
            <p className="party-editor-locked-theme-text">
              {themeEntitlementModal.message} Можно подключить быстро, если нужно.
            </p>
            {themeEntitlementModal.safeContactUrl ? (
              <a
                href={themeEntitlementModal.safeContactUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="party-editor-locked-theme-cta"
              >
                Напиши в ВК
              </a>
            ) : (
              <p className="party-editor-locked-theme-text">
                Ссылка на ВК сейчас недоступна. Попробуй чуть позже.
              </p>
            )}
            <button
              type="button"
              className="party-editor-button party-editor-button-secondary"
              onClick={() => setThemeEntitlementModal(null)}
            >
              Понятно
            </button>
          </div>
        </div>
      ) : null}
    </>
  );
};

export const PartySettingsModal: React.FC = () => {
  const { modal, closeModal, openModal } = useUIStore();
  const runtime = useSharedPartyWorkspaceRuntime();
  const setThemeEntitlementModal = usePartyWorkspaceStore(
    (state) => state.setThemeEntitlementModal,
  );
  const { isOutdated: isClientOutdated, requiredVersion: clientRequiredVersion } =
    useClientOutdatedStore();

  const isOpen = modal === 'partySettings';

  const handleClose = useCallback(() => {
    setThemeEntitlementModal(null);
    closeModal();
  }, [closeModal, setThemeEntitlementModal]);

  if (!isOpen) {
    return null;
  }

  return (
    <PartySettingsModalOpen
      runtime={runtime}
      isClientOutdated={isClientOutdated}
      clientRequiredVersion={clientRequiredVersion}
      onClose={handleClose}
      onOpenLinkParty={() => openModal('linkParty')}
    />
  );
};

import { Button, Icon, IconButton } from '@cherryplay/components';
import CloseIcon from '@mui/icons-material/Close';
import FolderOpenIcon from '@mui/icons-material/FolderOpen';
import React, { useId, useState, useCallback } from 'react';

import { useModalKeyboard } from '@shared/hooks';

export interface SaveProjectAsModalProps {
  open: boolean;
  isSaving: boolean;
  initialProjectName: string;
  initialDirectory: string;
  onRequestDirectory: (currentDirectory: string) => Promise<string | null>;
  onClose: () => void;
  onConfirm: (payload: {
    portable: boolean;
    projectName: string;
    targetDirectory: string;
  }) => void | Promise<void>;
}

export const SaveProjectAsModal: React.FC<SaveProjectAsModalProps> = ({
  open,
  isSaving,
  initialProjectName,
  initialDirectory,
  onRequestDirectory,
  onClose,
  onConfirm,
}) => {
  const [portable, setPortable] = useState(false);
  const [infoExpanded, setInfoExpanded] = useState(false);
  const [projectName, setProjectName] = useState(initialProjectName);
  const [targetDirectory, setTargetDirectory] = useState(initialDirectory);
  const titleId = useId();
  const infoButtonId = useId();
  const infoPanelId = useId();

  const handleConfirm = useCallback(() => {
    void onConfirm({
      portable,
      projectName: projectName.trim(),
      targetDirectory: targetDirectory.trim(),
    });
  }, [onConfirm, portable, projectName, targetDirectory]);

  const { handleOverlayKeyDown } = useModalKeyboard({
    enabled: open && !isSaving,
    onCancel: onClose,
    onPrimary: handleConfirm,
    primaryDisabled: isSaving,
  });

  if (!open) {
    return null;
  }

  const handleOverlayClick = (event: React.MouseEvent<HTMLDivElement>) => {
    if (event.target === event.currentTarget && !isSaving) {
      onClose();
    }
  };

  const handlePickDirectory = async () => {
    const selected = await onRequestDirectory(targetDirectory);
    if (selected) {
      setTargetDirectory(selected);
    }
  };

  return (
    <div
      className="modal-overlay"
      onClick={handleOverlayClick}
      onKeyDown={handleOverlayKeyDown}
      role="button"
      tabIndex={0}
      aria-label="Закрыть диалог сохранения"
    >
      <div
        className="modal-content save-project-as-modal"
        role="dialog"
        aria-modal
        aria-labelledby={titleId}
      >
        <div className="modal-header">
          <h2 className="modal-title" id={titleId}>
            Сохранить как…
          </h2>
          <IconButton
            className="modal-close"
            type="button"
            onClick={onClose}
            disabled={isSaving}
            aria-label="Закрыть"
            icon={<CloseIcon />}
            variant="ghost"
            size="md"
          />
        </div>

        <div className="modal-body">
          <label className="save-project-as-modal__field">
            <span className="save-project-as-modal__field-label">Имя проекта</span>
            <input
              type="text"
              className="save-project-as-modal__text-input"
              value={projectName}
              onChange={(e) => setProjectName(e.target.value)}
              disabled={isSaving}
              placeholder="Введите имя проекта"
            />
          </label>

          <label className="save-project-as-modal__field">
            <span className="save-project-as-modal__field-label">Папка назначения</span>
            <div className="save-project-as-modal__path-row">
              <input
                type="text"
                className="save-project-as-modal__text-input save-project-as-modal__path-input"
                value={targetDirectory}
                onChange={(e) => setTargetDirectory(e.target.value)}
                disabled={isSaving}
                placeholder="Выберите или введите путь к папке"
              />
              <IconButton
                type="button"
                className="save-project-as-modal__browse"
                onClick={() => {
                  void handlePickDirectory();
                }}
                disabled={isSaving}
                title="Выбрать папку"
                aria-label="Выбрать папку"
                variant="secondary"
                size="sm"
                icon={<FolderOpenIcon style={{ fontSize: 20 }} />}
              />
            </div>
          </label>

          <label className="save-project-as-modal__portable-label">
            <input
              type="checkbox"
              checked={portable}
              onChange={(e) => setPortable(e.target.checked)}
              disabled={isSaving}
            />
            <span>Переносимый проект</span>
            <button
              type="button"
              id={infoButtonId}
              className="save-project-as-modal__info"
              onClick={() => setInfoExpanded((v) => !v)}
              disabled={isSaving}
              aria-expanded={infoExpanded}
              aria-controls={infoPanelId}
              title="Что это значит"
            >
              <Icon size="md" shape="circle" aria-hidden>
                i
              </Icon>
              <span className="visually-hidden">Справка о переносимом проекте</span>
            </button>
          </label>

          {infoExpanded && (
            <div
              className="save-project-as-modal__info-panel"
              id={infoPanelId}
              role="region"
              aria-labelledby={infoButtonId}
            >
              <p className="save-project-as-modal__info-lead">
                Копия всех аудиофайлов рядом с файлом проекта, пути в .cherry становятся
                относительными — можно переносить всю папку.
              </p>
              <ul className="save-project-as-modal__info-list">
                <li>создаётся папка с именем проекта (как в заголовке);</li>
                <li>внутри — файл .cherry и вложенная папка tracks с копиями треков;</li>
                <li>коллекции отражаются в структуре подпапок в tracks;</li>
                <li>при любой ошибке копирования операция прерывается, успех не показывается.</li>
              </ul>
            </div>
          )}
        </div>

        <div className="modal-footer">
          <Button
            className="modal-button"
            type="button"
            onClick={onClose}
            disabled={isSaving}
            variant="secondary"
            size="sm"
          >
            Отмена
          </Button>
          <Button
            className="modal-button"
            type="button"
            loading={isSaving}
            onClick={handleConfirm}
            variant="primary"
            size="sm"
          >
            Сохранить
          </Button>
        </div>
      </div>
    </div>
  );
};

import { Button, IconButton } from '@cherryplay/components';
import CloseIcon from '@mui/icons-material/Close';
import React, { useId } from 'react';

import { useModalKeyboard } from '@shared/hooks';

export interface SettingsImportConfirmDialogProps {
