}

export function resolveHeaderPartyControlCtaLabel(primaryLabel: string): string {
  switch (primaryLabel) {
    case 'Не создана':
      return 'Создать';
    case 'Черновик':
      return 'К настройкам';
    case 'Ждёт начала':
      return 'Играть';
    case 'Идёт':
      return 'Остановить';
    case 'Пауза':
    case 'Конец':
      return 'Играть';
