import type { Layout } from '@core/types/layout';
import type { ProjectSessionMode } from '@core/types/project';
import type { ActiveWorkspace, LayoutPreset } from '@core/types/workspacePreset';
import type { StorePlaybackStatus } from '@shared/contracts/storePlaybackStatus';
import type { PartyLifecycleState } from '@shared/services/partyService';
import { getLayoutPresetFromLayout } from '@shared/utils/layoutPreset';
import { collectWorkspaceTypes } from '@shared/utils/layoutWorkspaceOperations';
import { resolvePartyLifecycleDisplayLabel } from '@workspaces/party/partyLifecycleLabels';

import { HEADER_PARTY_STATUS_UNREACHABLE_LABEL } from './headerPartyStatusVisuals';

export interface HeaderPartyStatusInput {
  linkedParty: { id: string; shortCode: string } | null | undefined;
  partyLifecycleState: PartyLifecycleState | null;
  sessionMode: ProjectSessionMode;
  serverUnreachable: boolean;
  playbackStatus?: StorePlaybackStatus | null;
  programEnded?: boolean;
}

export interface HeaderPartyStatusDisplay {
  primary: string;
  secondary?: string;
}

const ONLINE_PARTY_LAYOUT_PRESETS: ReadonlySet<LayoutPreset> = new Set(['party', 'aimp-party']);

export function isOnlinePartyLayoutPreset(preset: LayoutPreset | null | undefined): boolean {
  return preset != null && ONLINE_PARTY_LAYOUT_PRESETS.has(preset);
}

export function layoutHasOnlinePartyZones(layout: Layout): boolean {
  const types = collectWorkspaceTypes(layout.rootZone);
  return types.has('party-preview');
}

export function isAlreadyOnOnlinePartyLayout(
  activeWorkspace: ActiveWorkspace,
  layout: Layout,
): boolean {
  if (activeWorkspace.kind === 'builtin' && isOnlinePartyLayoutPreset(activeWorkspace.preset)) {
    return true;
  }
  if (isOnlinePartyLayoutPreset(getLayoutPresetFromLayout(layout))) {
    return true;
  }
  return layoutHasOnlinePartyZones(layout);
}

export function resolveHeaderPartyStatus(input: HeaderPartyStatusInput): HeaderPartyStatusDisplay {
  const basePrimary = resolvePartyLifecycleDisplayLabel({
    linkedParty: input.linkedParty ?? null,
    partyLifecycleState: input.partyLifecycleState,
    sessionMode: input.sessionMode,
  });
  const primary = resolveHeaderPartyPlaybackOverlay(
    basePrimary,
    input.playbackStatus,
    input.programEnded === true,
  );

  return withUnreachableOverlay({ primary }, input.serverUnreachable);
}

function resolveHeaderPartyPlaybackOverlay(
  primary: string,
  playbackStatus: StorePlaybackStatus | null | undefined,
  programEnded: boolean,
): string {
  if (primary !== 'Идёт') {
    return primary;
  }
  if (programEnded) {
    return 'Конец';
  }
  if (playbackStatus === 'paused') {
    return 'Пауза';
  }
  return primary;
}

function withUnreachableOverlay(
  display: HeaderPartyStatusDisplay,
  serverUnreachable: boolean,
): HeaderPartyStatusDisplay {
  if (!serverUnreachable) {
    return display;
  }
  return { primary: display.primary, secondary: HEADER_PARTY_STATUS_UNREACHABLE_LABEL };
}

import { getWorkspaceDisplayNameRu } from '@core/constants/workspaceDisplayNames';
import { workspaceRegistry } from '@core/registry';
import { Layout } from '@core/types/layout';
import {
  collectWorkspaceTypes,
  isSingletonWorkspaceType,
} from '@shared/utils/layoutWorkspaceOperations';

export interface WorkspacePickerOption {
  type: string;
  name: string;
}

export const AIR_DISABLED_HINT = 'Недостаточно места — увеличьте окно или измените пропорции';

export const LAYOUT_EDIT_DISABLED_TITLE = 'Недоступно в режиме редактирования окон';

function isWorkspaceTypeUsedInLayout(type: string, usedTypes: Set<string>): boolean {
  if (type === 'player' || type === 'aimp') {
    return usedTypes.has('player') || usedTypes.has('aimp');
  }

  return usedTypes.has(type);
}

function isTestWorkspaceType(type: string): boolean {
  return /^test\d$/.test(type);
}

export function getWorkspacePickerOptions(layout?: Layout): WorkspacePickerOption[] {
  const usedTypes = layout ? collectWorkspaceTypes(layout.rootZone) : new Set<string>();

  const options = workspaceRegistry
    .getAllModulesByType()
    .filter((module) => module.type !== 'aimp' && !isTestWorkspaceType(module.type))
    .map((module) => ({
      type: module.type,
      name: getWorkspaceDisplayNameRu(module.type, module.name),
    }));

  return options
    .filter(
      (option) =>
        !isSingletonWorkspaceType(option.type) ||
        !isWorkspaceTypeUsedInLayout(option.type, usedTypes),
    )
    .sort((left, right) => left.name.localeCompare(right.name, 'ru'));
}

import type {
  DemoPlayerFloatingPosition,
  DemoPlayerFloatingSize,
} from '@shared/stores/settingsStore';

export const PANEL_BOUNDS_PADDING_PX = 8;
export const DEFAULT_EDGE_OFFSET_PX = 16;
export const FALLBACK_PANEL_WIDTH_PX = 420;
/** Fixed floating panel height: header + track title row + single controls row. */
export const FLOATING_PANEL_FIXED_HEIGHT_PX = 120;
export const FALLBACK_PANEL_HEIGHT_PX = FLOATING_PANEL_FIXED_HEIGHT_PX;
export const FLOATING_PANEL_MIN_WIDTH_PX = 400;
export const FLOATING_PANEL_MIN_HEIGHT_PX = FLOATING_PANEL_FIXED_HEIGHT_PX;
export const FLOATING_PANEL_MAX_HEIGHT_PX = FLOATING_PANEL_FIXED_HEIGHT_PX;
export const KEYBOARD_DRAG_STEP_PX = 12;
export const KEYBOARD_DRAG_STEP_FAST_PX = 36;

export interface FloatingMetrics {
  panelWidth: number;
  panelHeight: number;
  containerWidth: number;
  containerHeight: number;
}

export function clampFloatingSize(
  width: number,
  _height: number,
  containerWidth: number,
  _containerHeight: number,
): DemoPlayerFloatingSize {
  const minWidth = FLOATING_PANEL_MIN_WIDTH_PX;
  const maxWidth = Math.max(minWidth, containerWidth - PANEL_BOUNDS_PADDING_PX * 2);

  return {
    width: Math.max(minWidth, Math.min(maxWidth, width)),
    height: FLOATING_PANEL_FIXED_HEIGHT_PX,
  };
}

export function clampFloatingPosition(
  x: number,
  y: number,
  metrics: FloatingMetrics,
  panelSize?: DemoPlayerFloatingSize,
): DemoPlayerFloatingPosition {
  const effectivePanelWidth = panelSize?.width ?? metrics.panelWidth;
  const effectivePanelHeight = FLOATING_PANEL_FIXED_HEIGHT_PX;
  const minX = PANEL_BOUNDS_PADDING_PX;
  const minY = PANEL_BOUNDS_PADDING_PX;
  const maxX = Math.max(
    minX,
    metrics.containerWidth - effectivePanelWidth - PANEL_BOUNDS_PADDING_PX,
  );
  const maxY = Math.max(
    minY,
    metrics.containerHeight - effectivePanelHeight - PANEL_BOUNDS_PADDING_PX,
  );

  return {
    x: Math.max(minX, Math.min(maxX, x)),
    y: Math.max(minY, Math.min(maxY, y)),
  };
}

