import { useEffect, type RefObject } from 'react';

import type { Layout } from '@core/types/layout';
import { APP_MIN_WINDOW_WIDTH, APP_MIN_WINDOW_HEIGHT } from '@shared/contracts/windowMins';
import { getAppMode } from '@shared/platform';
import { ipcService } from '@shared/services/ipcService';
import { useLayoutStore } from '@shared/stores';
import { computeMinWindowSize, type WindowChromeInsets } from '@shared/utils';
import {
  registerLayoutViewportGetter,
  type LayoutViewportSize,
} from '@shared/utils/layoutViewportBridge';
import { logger } from '@shared/utils/logger';

/**
 * Absolute lower bound for the window minimum, used as `max(appFloor, computed)`
 * so empty/small layouts still keep a usable window size.
 *
 * Sourced from the shared window-min contract (`@shared/contracts/windowMins`),
 * the same module the Electron main-process floor is built from, so the renderer
 * and main can never drift apart.
 */
const APP_WINDOW_MIN_FLOOR: LayoutViewportSize = {
  width: APP_MIN_WINDOW_WIDTH,
  height: APP_MIN_WINDOW_HEIGHT,
};

const RESIZE_DEBOUNCE_MS = 120;

function measureLayoutViewport(host: HTMLElement | null): LayoutViewportSize | null {
  if (!host) {
    return null;
  }

  const rect = host.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) {
    return null;
  }

  return { width: rect.width, height: rect.height };
}

function measureChromeInsets(host: HTMLElement | null): WindowChromeInsets {
  const viewport = measureLayoutViewport(host);
  if (!viewport) {
    return { top: 0, bottom: 0, left: 0, right: 0 };
  }

  return {
    top: Math.max(0, window.innerHeight - viewport.height),
    bottom: 0,
    left: Math.max(0, window.innerWidth - viewport.width),
    right: 0,
  };
}

/**
 * Computes the minimum window client size from the current layout mins plus
 * measured chrome insets and reports it to the Electron shell. Also registers a
 * live layout-viewport getter used by add-adjacent feasibility checks.
 *
 * Recomputes on layout change, layout-edit toggle, window resize, and host
 * resize (which captures chrome-affecting toggles such as the in-app player
 * header or the demo banner). No-op outside Electron.
 */
export function useWindowMinSize(hostRef: RefObject<HTMLElement | null>): void {
  const layout = useLayoutStore((state) => state.layout);
  const isLayoutEditMode = useLayoutStore((state) => state.isLayoutEditMode);

  useEffect(() => {
    const host = hostRef.current;

    registerLayoutViewportGetter(() => measureLayoutViewport(hostRef.current));

    if (getAppMode() !== 'electron') {
      return () => registerLayoutViewportGetter(() => null);
    }

    const currentLayout: Layout = layout;

    const sendMinWindowSize = (): void => {
      const chrome = measureChromeInsets(hostRef.current);
      const computed = computeMinWindowSize(currentLayout, chrome);

      const minWidth = Math.ceil(Math.max(APP_WINDOW_MIN_FLOOR.width, computed.minWidth));
      const minHeight = Math.ceil(Math.max(APP_WINDOW_MIN_FLOOR.height, computed.minHeight));

      void ipcService.setMinimumWindowSize(minWidth, minHeight).catch((error: unknown) => {
        logger.warn('[useWindowMinSize] Failed to set minimum window size', error);
      });
    };

    let debounceTimer: ReturnType<typeof setTimeout> | null = null;
    const scheduleUpdate = (): void => {
      if (debounceTimer !== null) {
        clearTimeout(debounceTimer);
      }
      debounceTimer = setTimeout(sendMinWindowSize, RESIZE_DEBOUNCE_MS);
    };

    sendMinWindowSize();

    window.addEventListener('resize', scheduleUpdate);

    let resizeObserver: ResizeObserver | null = null;
    if (host && typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(scheduleUpdate);
      resizeObserver.observe(host);
    }

    return () => {
      if (debounceTimer !== null) {
        clearTimeout(debounceTimer);
      }
      window.removeEventListener('resize', scheduleUpdate);
      resizeObserver?.disconnect();
      registerLayoutViewportGetter(() => null);
    };
    // `isLayoutEditMode` is a dependency because toggling layout-edit mode shows/hides
    // edit chrome (air bars, controls), which changes measured chrome insets and thus
    // the reported minimum window size; recompute when it changes.
  }, [hostRef, layout, isLayoutEditMode]);
}

import { requestActivateWorkspace } from './useWorkspaceDirtyGuard';

export type { RequestActivateWorkspaceOptions } from './useWorkspaceDirtyGuard';

/**
 * Workspace activation entry point for header UI.
 * Silently auto-commits dirty layout via `requestActivateWorkspace` before switching.
 */
export function useWorkspaceActivation() {
  return { requestActivateWorkspace };
}

import type { WorkspaceRef } from '@core/types/workspacePreset';
import { useLayoutStore } from '@shared/stores';

export interface RequestActivateWorkspaceOptions {
  bypassDirtyGuard?: boolean;
}

function isSameWorkspace(
  active: ReturnType<typeof useLayoutStore.getState>['activeWorkspace'],
  ref: WorkspaceRef,
): boolean {
  if (ref.kind === 'builtin') {
    return active.kind === 'builtin' && active.preset === ref.preset;
  }
  return active.kind === 'user' && active.id === ref.id;
}

export function requestActivateWorkspace(
  ref: WorkspaceRef,
  options?: RequestActivateWorkspaceOptions,
): boolean {
  const state = useLayoutStore.getState();
  if (state.isLayoutEditMode) {
    return false;
  }

  if (isSameWorkspace(state.activeWorkspace, ref)) {
    return true;
  }

  if (!options?.bypassDirtyGuard && state.isWorkspaceDirty()) {
    state.autoCommitWorkspaceChanges();
  }

  return useLayoutStore.getState().activateWorkspace(ref);
}

export function requestCreateScratchWorkspace(): boolean {
  const state = useLayoutStore.getState();
  if (state.isLayoutEditMode) {
    return false;
  }

  if (state.activeWorkspace.kind === 'scratch' && !state.isWorkspaceDirty()) {
    return true;
  }

  if (state.isWorkspaceDirty()) {
    state.autoCommitWorkspaceChanges();
  }

  return useLayoutStore.getState().createScratchWorkspace();
}

export function requestExitEditMode(): void {
  const state = useLayoutStore.getState();
  if (!state.isLayoutEditMode) {
    return;
  }

  state.autoCommitWorkspaceChanges();
  state.setLayoutEditMode(false);
}

export function requestToggleLayoutEditMode(): void {
  const state = useLayoutStore.getState();
  if (!state.isLayoutEditMode) {
    state.setLayoutEditMode(true);
    return;
  }
  requestExitEditMode();
}

import { resetDemoPersistStorage } from '@shared/demo/demoResetStorage';
import {
  CapacitorPlatform,
  ElectronPlatform,
  setPlatform,
  WebDemoPlatform,
} from '@shared/platform';

const ELECTRON_API_WAIT_MS = 5000;

const BOOTSTRAP_ERROR =
  '[CherryPlayList] Platform bootstrap failed: no supported runtime detected. ' +
  'Use `npm run dev` for Electron, `npm run dev:web` for web demo, or `npm run dev:capacitor` for Capacitor stub.';

const PRELOAD_MISSING_ERROR =
  '[CherryPlayList] Electron preload (window.api) не загрузился. ' +
  'Выполните `npm run compile:electron` и перезапустите `npm run dev`.';

function isElectronUserAgent(): boolean {
  return typeof navigator !== 'undefined' && /Electron/i.test(navigator.userAgent);
}

async function waitForElectronApi(timeoutMs: number): Promise<boolean> {
  if (typeof window !== 'undefined' && typeof window.api !== 'undefined') {
    return true;
  }

  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, 50));
    if (typeof window !== 'undefined' && typeof window.api !== 'undefined') {
      return true;
    }
  }

  return false;
}

export function isDevAuthCallbackDocumentPath(): boolean {
  return (
    import.meta.env.DEV &&
    typeof window !== 'undefined' &&
    (window.location.pathname === '/auth/callback' ||
      window.location.pathname === '/auth-callback.html')
  );
}

export function redirectDevAuthCallbackToStaticPage(): boolean {
  if (!isDevAuthCallbackDocumentPath()) {
    return false;
  }

  if (window.location.pathname === '/auth-callback.html') {
    return false;
  }

  window.location.replace(`/auth-callback.html${window.location.search}`);
  return true;
}

export async function bootstrapApp(): Promise<void> {
  if (redirectDevAuthCallbackToStaticPage()) {
    await new Promise<void>(() => {});
    return;
  }

  const isDemoMode = import.meta.env.VITE_APP_MODE === 'demo';
  const isCapacitorMode = import.meta.env.VITE_APP_MODE === 'capacitor';

  if (isDemoMode) {
    await resetDemoPersistStorage();
    setPlatform(new WebDemoPlatform(), 'demo');
    return;
  }

  if (isCapacitorMode) {
    setPlatform(new CapacitorPlatform(), 'capacitor');
    return;
  }

  if (await waitForElectronApi(ELECTRON_API_WAIT_MS)) {
    setPlatform(new ElectronPlatform(), 'electron');
    return;
  }

  if (isElectronUserAgent()) {
    throw new Error(PRELOAD_MISSING_ERROR);
  }

  throw new Error(BOOTSTRAP_ERROR);
}

