import { isProjectGroup } from '@core/types/project';

import { DisplayItem } from '../../shared/utils/playerItemsUtils';

import { HierarchyPosition, InsertPosition } from './types';

export function collectFlatIndicesForItem(
  itemId: string,
  displayItems: DisplayItem[],
): Set<number> {
  const indices = new Set<number>();

  const itemIndex = displayItems.findIndex((di) => di.item.id === itemId);
  if (itemIndex === -1) {
    return indices;
  }

  const item = displayItems[itemIndex];
  indices.add(item.flatIndex);

  if (isProjectGroup(item.item)) {
    const groupLevel = item.level;
    for (let i = itemIndex + 1; i < displayItems.length; i++) {
      const di = displayItems[i];
      if (di.level <= groupLevel) {
        break;
      }
      indices.add(di.flatIndex);
    }
  }

  return indices;
}

export function collectAllFlatIndices(rootIds: string[], displayItems: DisplayItem[]): Set<number> {
  const allIndices = new Set<number>();

  for (const id of rootIds) {
    const indices = collectFlatIndicesForItem(id, displayItems);
    indices.forEach((idx) => allIndices.add(idx));
  }

  return allIndices;
}

export function getRootIdsForDrag(
  itemId: string,
  selectedIds: Set<string>,
  displayItems: DisplayItem[],
): string[] {
  const idsToProcess =
    selectedIds.has(itemId) && selectedIds.size > 1 ? selectedIds : new Set([itemId]);

  const allIndicesMap = new Map<string, Set<number>>();
  for (const id of idsToProcess) {
    allIndicesMap.set(id, collectFlatIndicesForItem(id, displayItems));
  }

  const rootIds: string[] = [];
  for (const id of idsToProcess) {
    const itemDi = displayItems.find((di) => di.item.id === id);
    if (!itemDi) continue;

    let isNested = false;
    for (const [otherId, otherIndices] of allIndicesMap) {
      if (otherId === id) continue;
      if (otherIndices.has(itemDi.flatIndex)) {
        isNested = true;
        break;
      }
    }

    if (!isNested) {
      rootIds.push(id);
    }
  }

  return rootIds.sort((a, b) => {
    const aIdx = displayItems.find((di) => di.item.id === a)?.flatIndex ?? 0;
    const bIdx = displayItems.find((di) => di.item.id === b)?.flatIndex ?? 0;
    return aIdx - bIdx;
  });
}

export function isDropInsideDragged(targetFlatIndex: number, allFlatIndices: Set<number>): boolean {
  return allFlatIndices.has(targetFlatIndex);
}

export function calculateDropPosition(
  targetFlatIndex: number,
  position: InsertPosition,
  displayItems: DisplayItem[],
): HierarchyPosition {
  const targetItem = displayItems[targetFlatIndex];
  if (!targetItem) {
    const rootCount = displayItems.filter((di) => di.parentGroupId === null).length;
    return { parentId: null, localIndex: rootCount };
  }

  if (position === 'top') {
    const parentId = targetItem.parentGroupId;
    const siblings = displayItems.filter((di) => di.parentGroupId === parentId);
    const localIndex = siblings.findIndex((di) => di.flatIndex === targetFlatIndex);
    return {
      parentId,
      localIndex: localIndex === -1 ? 0 : localIndex,
    };
  }

  if (isProjectGroup(targetItem.item)) {
    return { parentId: targetItem.item.id, localIndex: 0 };
  }

  const nextFlatIndex = targetFlatIndex + 1;
  const nextItem = displayItems[nextFlatIndex];

  if (!nextItem) {
    if (targetItem.parentGroupId !== null) {
      const siblings = displayItems.filter((di) => di.parentGroupId === targetItem.parentGroupId);
      return { parentId: targetItem.parentGroupId, localIndex: siblings.length };
    }
    const rootCount = displayItems.filter((di) => di.parentGroupId === null).length;
    return { parentId: null, localIndex: rootCount };
  }

  if (targetItem.parentGroupId !== null && nextItem.level <= targetItem.level) {
    const siblings = displayItems.filter((di) => di.parentGroupId === targetItem.parentGroupId);
    const targetSiblingIndex = siblings.findIndex((di) => di.flatIndex === targetFlatIndex);
    return { parentId: targetItem.parentGroupId, localIndex: targetSiblingIndex + 1 };
  }

  const parentId = nextItem.parentGroupId;
  const siblings = displayItems.filter((di) => di.parentGroupId === parentId);
  const localIndex = siblings.findIndex((di) => di.flatIndex === nextFlatIndex);

  return {
    parentId,
    localIndex: localIndex === -1 ? 0 : localIndex,
  };
}

export function filterDisplayItems(
  displayItems: DisplayItem[],
  indicesToRemove: Set<number>,
): DisplayItem[] {
  const filtered: DisplayItem[] = [];
  let newFlatIndex = 0;

  for (const di of displayItems) {
    if (!indicesToRemove.has(di.flatIndex)) {
      filtered.push({
        ...di,
        flatIndex: newFlatIndex++,
      });
    }
  }

  return filtered;
}

import type { Track, TrackLoudness } from '@core/types/track';

import { computeAutoGainDb, type LoudnessSettings } from '../contracts/loudness';

import { TRACK_GAIN_LINEAR_MAX, TRACK_GAIN_LINEAR_MIN } from './playback/effects';

export { computeAutoGainDb } from '../contracts/loudness';

/** Auto gain from scan metadata and the current target LUFS (ignores persisted trackGainDb). */
export function resolveAutoGainDb(
  loudness: TrackLoudness | undefined,
  targetLufs: number,
): number | undefined {
  if (!loudness || loudness.status !== 'ok') {
    return undefined;
  }

  if (loudness.integratedLufs === undefined || loudness.truePeakDb === undefined) {
    return undefined;
  }

  return computeAutoGainDb(loudness.integratedLufs, loudness.truePeakDb, targetLufs);
}

export function getEffectiveGainDb(track: Track, settings: LoudnessSettings): number | undefined {
  const loudness = track.loudness;
  if (!loudness) {
    return undefined;
  }

  if (loudness.manualGainDb !== undefined) {
    return loudness.manualGainDb;
  }

  if (loudness.status === 'ok') {
    return resolveAutoGainDb(loudness, settings.loudnessTargetLufs);
  }

  return undefined;
}

export function resolveLinearGain(track: Track, settings: LoudnessSettings): number {
  if (!settings.loudnessNormalizationEnabled) {
    return 1;
  }

  const gainDb = getEffectiveGainDb(track, settings);
  if (gainDb === undefined) {
    return 1;
  }

  const linear = 10 ** (gainDb / 20);
  return Math.min(TRACK_GAIN_LINEAR_MAX, Math.max(TRACK_GAIN_LINEAR_MIN, linear));
}

import { logger } from '../../utils/logger';

import { clampPlaybackValue } from './clampPlaybackValue';
import {
  AUTO_GAIN_NORMALIZATION,
  DEFAULT_EQUALIZER_BANDS,
  DEFAULT_TRACK_GAIN,
  TRACK_GAIN_LINEAR_MAX,
  TRACK_GAIN_LINEAR_MIN,
  type EqualizerBands,
  type PlaybackEffects,
} from './effects';
import type {
  PlaybackEngineEventName,
  PlaybackEngineListener,
  PlaybackEngineSubscription,
} from './events';
import { MediaElementTransport } from './mediaElementTransport';
import type { PlatformAudioAdapter } from './PlatformAudioAdapter';
import type { PlaybackEngine } from './PlaybackEngine';
import type { PlaybackSnapshot, PlaybackSource } from './types';

export interface WebAudioPlaybackEngineOptions {
  readonly id: string;
  readonly initialVolume?: number;
  readonly adapter: PlatformAudioAdapter;
}

/**
 * {@link PlaybackEngine} using Web Audio API (EBU order): MediaElementSource → EQ → compressor →
 * track gain (R128 linear normalize) → master gain → destination.
 *
 * Transport lifecycle (load/play/seek/events) is delegated to {@link MediaElementTransport}.
 */
export class WebAudioPlaybackEngine implements PlaybackEngine, PlaybackEffects {
  private readonly adapter: PlatformAudioAdapter;
  private readonly transport: MediaElementTransport;
  private audioContext: AudioContext | null = null;
  private sourceNode: MediaElementAudioSourceNode | null = null;
  private trackGainNode: GainNode | null = null;
  private eqLowNode: BiquadFilterNode | null = null;
  private eqMidNode: BiquadFilterNode | null = null;
  private eqHighNode: BiquadFilterNode | null = null;
  private compressorNode: DynamicsCompressorNode | null = null;
  private masterGainNode: GainNode | null = null;
  private trackGain = DEFAULT_TRACK_GAIN;
  private equalizerBands: EqualizerBands = DEFAULT_EQUALIZER_BANDS;
  private autoGainEnabled = false;
  private compressionStrength = 0;

  constructor(options: WebAudioPlaybackEngineOptions) {
    this.adapter = options.adapter;
    this.transport = new MediaElementTransport({
      id: options.id,
      adapter: options.adapter,
      initialVolume: options.initialVolume,
      hooks: {
        applyVolume: (volume) => this.applyMasterVolume(volume),
        applyOutputDevice: (deviceId) => this.applyOutputDevice(deviceId),
        beforePlay: () => this.ensureAudioContextRunning(),
        onDispose: () => {
          this.disconnectGraph();
          void this.audioContext?.close();
          this.audioContext = null;
        },
      },
    });
  }

  get id(): string {
    return this.transport.id;
  }

  load(source: PlaybackSource): Promise<void> {
    return this.transport.load(source);
  }

  play(): Promise<void> {
    return this.transport.play();
  }

  pause(): void {
    this.transport.pause();
  }

  stop(): void {
    this.transport.stop();
  }

  seek(seconds: number): void {
    this.transport.seek(seconds);
  }

  setVolume(value: number): void {
    this.transport.setVolume(value);
  }

  setTrackGain(gain: number): void {
    if (this.transport.isDisposed()) {
      return;
    }

    this.trackGain = clampPlaybackValue(gain, TRACK_GAIN_LINEAR_MIN, TRACK_GAIN_LINEAR_MAX);
    this.applyTrackGain();
  }

  setEqualizerBands(bands: EqualizerBands): void {
    if (this.transport.isDisposed()) {
      return;
    }

    this.equalizerBands = bands;
    this.applyEqualizerBands();
  }

  setAutoGainEnabled(enabled: boolean): void {
    if (this.transport.isDisposed()) {
      return;
    }

    this.autoGainEnabled = enabled;
    this.applyTrackGain();
  }

  setCompressionStrength(strength: number): void {
    if (this.transport.isDisposed()) {
      return;
    }

    this.compressionStrength = clampPlaybackValue(strength, 0, 1);
    this.applyCompressionParams();
    this.applyCompressionRouting();
  }

  setOutputDevice(deviceId: string | null): Promise<void> {
    return this.transport.setOutputDevice(deviceId);
  }

  getSnapshot(): PlaybackSnapshot {
    return this.transport.getSnapshot();
  }

  subscribe<K extends PlaybackEngineEventName>(
    event: K,
    listener: PlaybackEngineListener<K>,
  ): PlaybackEngineSubscription {
    return this.transport.subscribe(event, listener);
  }

  dispose(): void {
    this.transport.dispose();
  }

  private async ensureAudioContextRunning(): Promise<void> {
    this.ensureGraph();
    if (this.audioContext?.state === 'suspended') {
      await this.audioContext.resume();
    }
  }

  private ensureGraph(): void {
    if (this.audioContext && this.sourceNode) {
      return;
    }

    const audio = this.transport.getAudioElement();
    const context = new AudioContext();
    const sourceNode = context.createMediaElementSource(audio);
    const trackGainNode = context.createGain();
    const eqLowNode = context.createBiquadFilter();
    eqLowNode.type = 'lowshelf';
    eqLowNode.frequency.value = 320;

    const eqMidNode = context.createBiquadFilter();
    eqMidNode.type = 'peaking';
    eqMidNode.frequency.value = 1000;
    eqMidNode.Q.value = 1;

    const eqHighNode = context.createBiquadFilter();
    eqHighNode.type = 'highshelf';
    eqHighNode.frequency.value = 3200;

    const compressorNode = context.createDynamicsCompressor();
    compressorNode.attack.value = 0.015;
    compressorNode.release.value = 1;

    const masterGainNode = context.createGain();

    sourceNode.connect(eqLowNode);
    eqLowNode.connect(eqMidNode);
    eqMidNode.connect(eqHighNode);

    this.audioContext = context;
    this.sourceNode = sourceNode;
    this.trackGainNode = trackGainNode;
    this.eqLowNode = eqLowNode;
    this.eqMidNode = eqMidNode;
    this.eqHighNode = eqHighNode;
    this.compressorNode = compressorNode;
    this.masterGainNode = masterGainNode;

    this.applyCompressionParams();
    this.applyCompressionRouting();
    masterGainNode.connect(context.destination);

    this.applyTrackGain();
    this.applyEqualizerBands();
    this.applyMasterVolume(this.transport.getSnapshot().volume);

    if ('setSinkId' in context && typeof context.setSinkId === 'function') {
      const outputDeviceId = this.transport.getSnapshot().outputDeviceId;
      void context.setSinkId(outputDeviceId ?? 'default').catch((error: unknown) => {
        logger.warn(
          'WebAudioPlaybackEngine: failed to set AudioContext sink on graph init',
          error instanceof Error ? error : undefined,
        );
      });
    }
  }

  /**
   * Routes output to the selected device. After {@link createMediaElementSource},
   * Chromium/Electron reject {@link HTMLAudioElement.setSinkId} (AbortError) — use
   * {@link AudioContext.setSinkId} for the Web Audio graph instead.
   */
  private async applyOutputDevice(deviceId: string | null): Promise<void> {
    const sinkId = deviceId ?? 'default';

    if (this.sourceNode !== null || this.audioContext !== null) {
      this.ensureGraph();
      if (
        this.audioContext &&
        'setSinkId' in this.audioContext &&
        typeof this.audioContext.setSinkId === 'function'
      ) {
        await this.audioContext.setSinkId(sinkId);
        return;
      }
    }

    await this.adapter.setSinkId(this.transport.getAudioElement(), deviceId);
  }

  private applyMasterVolume(volume: number): void {
    if (this.masterGainNode) {
      this.masterGainNode.gain.value = volume;
      return;
    }

    if (!this.transport.isDisposed()) {
      this.transport.getAudioElement().volume = volume;
    }
  }

  private applyTrackGain(): void {
    if (!this.trackGainNode) {
      return;
    }

    const autoMultiplier = this.autoGainEnabled ? AUTO_GAIN_NORMALIZATION : 1;
    this.trackGainNode.gain.value = this.trackGain * autoMultiplier;
  }

  private applyEqualizerBands(): void {
    if (this.eqLowNode) {
      this.eqLowNode.gain.value = this.equalizerBands.lowDb;
    }
    if (this.eqMidNode) {
      this.eqMidNode.gain.value = this.equalizerBands.midDb;
    }
    if (this.eqHighNode) {
      this.eqHighNode.gain.value = this.equalizerBands.highDb;
    }
  }

  private applyCompressionParams(): void {
    if (!this.compressorNode) {
      return;
    }

    const strength = this.compressionStrength;
    if (strength <= 0) {
      return;
    }

    // EBU Tech 3343 gentle LRA block: low threshold, moderate ratio, long release.
    this.compressorNode.threshold.value = -45 + strength * 10;
    this.compressorNode.ratio.value = 1.2 + strength * 0.8;
    this.compressorNode.knee.value = 30 - strength * 15;
  }

  private applyCompressionRouting(): void {
    if (!this.eqHighNode || !this.trackGainNode || !this.masterGainNode) {
      return;
    }

    this.eqHighNode.disconnect();
    this.compressorNode?.disconnect();
    this.trackGainNode.disconnect();

    if (this.compressionStrength > 0 && this.compressorNode) {
      this.eqHighNode.connect(this.compressorNode);
      this.compressorNode.connect(this.trackGainNode);
    } else {
      this.eqHighNode.connect(this.trackGainNode);
    }

    this.trackGainNode.connect(this.masterGainNode);
  }

  private disconnectGraph(): void {
    this.sourceNode?.disconnect();
    this.trackGainNode?.disconnect();
    this.eqLowNode?.disconnect();
    this.eqMidNode?.disconnect();
    this.eqHighNode?.disconnect();
    this.compressorNode?.disconnect();
    this.masterGainNode?.disconnect();
    this.sourceNode = null;
    this.trackGainNode = null;
    this.eqLowNode = null;
    this.eqMidNode = null;
    this.eqHighNode = null;
    this.compressorNode = null;
    this.masterGainNode = null;
  }
}

import type { Track } from '@core/types/track';

import {
  DEFAULT_LOUDNESS_QUIET_GAP_RANGE_LU,
  DEFAULT_LOUDNESS_TARGET_LUFS,
  type LoudnessSettings,
} from '../../contracts/loudness';
import { resolveLinearGain } from '../loudnessGain';

import { getEffectiveCompressionStrength } from './compressionStrength';
import { DEFAULT_EQUALIZER_BANDS, DEFAULT_TRACK_GAIN, isPlaybackEffects } from './effects';
import type { PlaybackEngine } from './PlaybackEngine';

/** Applies per-track loudness gain and compression; does not reset EQ bands. */
export function applyLoudnessPlaybackEffects(
  engine: PlaybackEngine,
  track: Track,
  settings: LoudnessSettings,
): void {
  if (!isPlaybackEffects(engine)) {
    return;
  }

  if (settings.loudnessNormalizationEnabled) {
    engine.setTrackGain(resolveLinearGain(track, settings));
    engine.setAutoGainEnabled(false);
    engine.setCompressionStrength(getEffectiveCompressionStrength(track, settings));
  } else {
    engine.setTrackGain(DEFAULT_TRACK_GAIN);
    engine.setAutoGainEnabled(false);
    engine.setCompressionStrength(0);
  }
}

/** Track-load preset: loudness effects plus default EQ bands and disabled autogain. */
export function applyPlaybackEffects(
  engine: PlaybackEngine,
  track: Track,
  settings: LoudnessSettings,
): void {
  applyLoudnessPlaybackEffects(engine, track, settings);

  if (isPlaybackEffects(engine)) {
    engine.setEqualizerBands(DEFAULT_EQUALIZER_BANDS);
  }
}

/** Legacy helper — applies unity gain with loudness normalization disabled. */
export function applyDefaultPlaybackEffects(engine: PlaybackEngine): void {
  applyPlaybackEffects(
    engine,
    { id: '', path: '', name: '' },
    {
      loudnessNormalizationEnabled: false,
      loudnessTargetLufs: DEFAULT_LOUDNESS_TARGET_LUFS,
      loudnessCompressionEnabled: false,
      loudnessQuietGapRangeLu: DEFAULT_LOUDNESS_QUIET_GAP_RANGE_LU,
    },
  );
}

import { getDefaultDeviceId } from '../../utils/audioDevices';
import { logger } from '../../utils/logger';

import type { PlaybackEngine } from './PlaybackEngine';

function isDeviceNotFoundError(error: unknown): boolean {
  if (error instanceof DOMException) {
    return error.name === 'NotFoundError' || error.message.includes('not found');
  }
  if (error instanceof Error) {
    return error.message.includes('not found') || error.message.includes('NotFoundError');
  }
  return false;
}

export interface OutputDeviceFallbackOptions {
  readonly deviceId: string | null;
  readonly onDeviceNotFound: () => void;
  readonly logContext: string;
}

/**
 * Applies output device to a {@link PlaybackEngine} with fallback to system default
 * when the selected device is unavailable (mirrors store behavior pre-migration).
 */
export async function applyPlaybackOutputDeviceWithFallback(
  engine: PlaybackEngine,
  options: OutputDeviceFallbackOptions,
): Promise<void> {
  const { deviceId, onDeviceNotFound, logContext } = options;

  try {
    await engine.setOutputDevice(deviceId);
  } catch (error) {
    logger.error(`Failed to set audio device (${logContext})`, error);

    if (isDeviceNotFoundError(error) && deviceId !== null) {
      onDeviceNotFound();
      try {
        await engine.setOutputDevice(getDefaultDeviceId());
      } catch (fallbackError) {
        logger.error(`Failed to set default audio device (${logContext})`, fallbackError);
        throw error;
      }
      return;
    }

    throw error;
  }
}

import type { StorePlaybackStatus } from '../../contracts/storePlaybackStatus';

import type { PlaybackEngine } from './PlaybackEngine';
import type { PlaybackEngineStatus } from './types';

export type { StorePlaybackStatus };

export function mapEngineStatusToStoreStatus(status: PlaybackEngineStatus): StorePlaybackStatus {
  switch (status) {
    case 'playing':
      return 'playing';
    case 'paused':
      return 'paused';
    case 'loading':
      return 'loading';
    case 'buffering':
      return 'buffering';
    case 'ended':
      return 'ended';
    case 'error':
      return 'error';
    case 'idle':
    default:
      return 'idle';
  }
}

export interface PlaybackEngineStoreBindings {
  readonly onStatusChanged: (status: StorePlaybackStatus) => void;
  readonly onPositionChanged: (positionSeconds: number) => void;
  readonly onDurationChanged: (durationSeconds: number) => void;
  readonly onEnded: () => void;
  readonly onError: (message: string) => void;
}

/**
 * Subscribes store callbacks to engine events (hybrid state model).
 * @returns Disposer — call on store teardown.
 */
export function bindPlaybackEngineToStore(
  engine: PlaybackEngine,
  bindings: PlaybackEngineStoreBindings,
): () => void {
  const subscriptions = [
    engine.subscribe('statusChanged', (status) => {
      bindings.onStatusChanged(mapEngineStatusToStoreStatus(status));
    }),
    engine.subscribe('positionChanged', (position) => {
      bindings.onPositionChanged(position);
    }),
    engine.subscribe('durationChanged', (duration) => {
      bindings.onDurationChanged(duration);
    }),
    engine.subscribe('ended', () => {
      bindings.onEnded();
    }),
    engine.subscribe('error', (message) => {
      bindings.onError(message);
    }),
  ];

  return () => {
    for (const unsubscribe of subscriptions) {
      unsubscribe();
    }
  };
}

import type { Track, TrackLoudness } from '@core/types/track';

import {
  clampLoudnessQuietGapRangeLu,
  COMPRESSION_QUIET_GAP_RANGE_LU,
  DEFAULT_LOUDNESS_QUIET_GAP_RANGE_LU,
  type LoudnessSettings,
} from '../../contracts/loudness';
import { getEffectiveGainDb } from '../loudnessGain';

/** Fallback quiet-passage offset when only integrated LUFS is available. */
export const COMPRESSION_INTEGRATED_ONLY_QUIET_OFFSET_LU = 6;
export { COMPRESSION_QUIET_GAP_RANGE_LU };
/** Estimate quiet-passage loudness from LRA when {@link TrackLoudness.lraLowLufs} is missing. */
export const COMPRESSION_LRA_QUIET_ESTIMATE_FACTOR = 0.55;
/** LRA below this LU is treated as already compressed (dense pop / brickwall). */
export const COMPRESSION_LRA_MIN_LU = 8;
/** Full {@link resolveDynamicNeed} when LRA span reaches MIN + this many LU. */
export const COMPRESSION_LRA_RANGE_LU = 10;
/** Positive gain above this dB adds extra strength (boost exaggerates internal contrast). */
export const COMPRESSION_BOOST_GATE_DB = 3;
/** Full boost multiplier span above {@link COMPRESSION_BOOST_GATE_DB}. */
export const COMPRESSION_BOOST_RANGE_DB = 12;

function clamp01(value: number): number {
  return Math.min(1, Math.max(0, value));
}

/** Quiet-gap span for full quietNeed from global settings (5…30 LU). */
export function resolveQuietGapRangeLu(settings: LoudnessSettings): number {
  return clampLoudnessQuietGapRangeLu(
    settings.loudnessQuietGapRangeLu ?? DEFAULT_LOUDNESS_QUIET_GAP_RANGE_LU,
  );
}

/**
 * Estimates loudness of quiet passages for compression strength.
 * Prefers ebur128 LRA low (10th percentile); falls back to integrated − 0.55×LRA.
 */
export function resolveQuietPassageLufs(loudness: TrackLoudness): number | undefined {
  if (loudness.lraLowLufs !== undefined) {
    return loudness.lraLowLufs;
  }

  if (loudness.lraLu !== undefined && loudness.integratedLufs !== undefined) {
    return loudness.integratedLufs - loudness.lraLu * COMPRESSION_LRA_QUIET_ESTIMATE_FACTOR;
  }

  if (loudness.integratedLufs !== undefined) {
    return loudness.integratedLufs - COMPRESSION_INTEGRATED_ONLY_QUIET_OFFSET_LU;
  }

  return undefined;
}

/**
 * How wide the programme dynamics are (0…1). Uses LRA when available, else integrated − LRA low.
 */
export function resolveDynamicNeed(loudness: TrackLoudness): number {
  if (loudness.lraLu !== undefined) {
    return clamp01((loudness.lraLu - COMPRESSION_LRA_MIN_LU) / COMPRESSION_LRA_RANGE_LU);
  }

  if (loudness.integratedLufs !== undefined && loudness.lraLowLufs !== undefined) {
    const spreadLu = loudness.integratedLufs - loudness.lraLowLufs;
    return clamp01((spreadLu - COMPRESSION_LRA_MIN_LU) / COMPRESSION_LRA_RANGE_LU);
  }

  return 1;
}

/**
 * Auto-calculated compression strength in 0…1 from quiet-passage gap and LRA (EBU LRA block).
 * Compression runs before linear gain in playback; strength does not use |gainDb| as a driver.
 * Ignores {@link TrackLoudness.manualCompressionStrength}.
 */
export function resolveAutoCompressionStrength(track: Track, settings: LoudnessSettings): number {
  if (!settings.loudnessNormalizationEnabled || !settings.loudnessCompressionEnabled) {
    return 0;
  }

  const loudness = track.loudness;
  if (!loudness || loudness.status !== 'ok') {
    return 0;
  }

  const quietPassageLufs = resolveQuietPassageLufs(loudness);
  if (quietPassageLufs === undefined) {
    return 0;
  }

  const quietGapLu = settings.loudnessTargetLufs - quietPassageLufs;
  if (quietGapLu <= 0) {
    return 0;
  }

  const quietNeed = clamp01(quietGapLu / resolveQuietGapRangeLu(settings));
  const dynamicNeed = resolveDynamicNeed(loudness);
  let strength = quietNeed * dynamicNeed;

  const gainDb = getEffectiveGainDb(track, settings);
  if (gainDb !== undefined && gainDb > COMPRESSION_BOOST_GATE_DB) {
    const boostFactor =
      1 + clamp01((gainDb - COMPRESSION_BOOST_GATE_DB) / COMPRESSION_BOOST_RANGE_DB);
    strength = Math.min(1, strength * boostFactor);
  }

  return strength;
}

/**
 * Effective per-track compression strength for playback and UI (0…1).
 * Uses manual override when set; otherwise {@link resolveAutoCompressionStrength}.
 */
export function getEffectiveCompressionStrength(track: Track, settings: LoudnessSettings): number {
  if (!settings.loudnessNormalizationEnabled || !settings.loudnessCompressionEnabled) {
    return 0;
  }

  const loudness = track.loudness;
  if (!loudness || loudness.status !== 'ok') {
    return 0;
  }

  if (loudness.manualCompressionStrength !== undefined) {
    return clamp01(loudness.manualCompressionStrength);
  }

  return resolveAutoCompressionStrength(track, settings);
}

/** @deprecated Prefer {@link getEffectiveCompressionStrength} — kept for existing imports. */
export const resolveCompressionStrength = getEffectiveCompressionStrength;

import { ipcService } from '../../services/ipcService';
import { setAudioSinkId } from '../../utils/audioDevices';

import type { PlatformAudioAdapter, ResolvedPlaybackUrl } from './PlatformAudioAdapter';
import type { PlaybackSource } from './types';

/**
 * Default Electron/browser {@link PlatformAudioAdapter} delegating to IPC and audio device helpers.
 *
 * Resolves `filePath` via `audio:getFileUrl` → `cherryplay-audio://` streaming protocol URL.
 * Protocol URLs work under the renderer CSP without base64/Blob indirection.
 */
export function createDefaultPlatformAudioAdapter(): PlatformAudioAdapter {
  return {
    async resolveSource(source: PlaybackSource): Promise<ResolvedPlaybackUrl> {
      switch (source.kind) {
        case 'filePath': {
          const { url } = await ipcService.getAudioFileUrl(source.path, false);
          return { url };
        }
        case 'url':
          return { url: source.url };
        case 'blobUrl':
          return { url: source.blobUrl };
        default: {
          const exhaustiveCheck: never = source;
          throw new Error(
            `Unknown playback source kind: ${(exhaustiveCheck as PlaybackSource).kind}`,
          );
        }
      }
    },

    async getDuration(filePath: string): Promise<number | null> {
      try {
        const duration = await ipcService.getAudioDuration(filePath, false);
        return Number.isFinite(duration) ? duration : null;
      } catch {
        return null;
      }
    },

    async analyzeLoudness(filePath: string, targetLufs: number) {
      try {
        return await ipcService.analyzeLoudness(filePath, targetLufs, false);
      } catch {
        return null;
      }
    },

    async statAudioFile(filePath: string) {
      try {
        return await ipcService.statAudioFile(filePath, false);
      } catch {
        return null;
      }
    },

    async setSinkId(
      target: HTMLAudioElement | AudioContext,
      deviceId: string | null,
    ): Promise<void> {
      if (target instanceof HTMLAudioElement) {
        await setAudioSinkId(target, deviceId);
        return;
      }

      if ('setSinkId' in target && typeof target.setSinkId === 'function') {
        const sinkId = deviceId ?? 'default';
        await target.setSinkId(sinkId);
      }
    },
  };
}

import { createDefaultPlatformAudioAdapter } from './createDefaultPlatformAudioAdapter';
import type { PlaybackEngine } from './PlaybackEngine';
import type { PlaybackEngineOptions, PlaybackEnginePair } from './types';
import { DEFAULT_PLAYBACK_VOLUME, DEMO_PLAYBACK_ENGINE_ID, MAIN_PLAYBACK_ENGINE_ID } from './types';
import { WebAudioPlaybackEngine } from './WebAudioPlaybackEngine';

/**
 * Creates a **new** {@link PlaybackEngine} instance. Each call is independent.
 *
 * The desktop app imports shared main/demo instances from `playbackEngines.ts` instead
 * of calling this factory per store. Use this for tests or custom one-off engines.
 *
 * @param options - Instance id, volume, and optional adapter.
 */
export function createPlaybackEngine(options: PlaybackEngineOptions): PlaybackEngine {
  const adapter = options.adapter ?? createDefaultPlatformAudioAdapter();

  return new WebAudioPlaybackEngine({
    id: options.id,
    initialVolume: options.initialVolume ?? DEFAULT_PLAYBACK_VOLUME,
    adapter,
  });
}

/**
 * Creates the standard **main + demo** engine pair with distinct instance ids.
 *
 * Follows the two-instance pattern: independent engines for `playerAudioStore` and
 * `demoPlayerStore` after migration. Device conflict policy remains in stores.
 *
 * @param overrides - Optional shared options (adapter, volume); ids are fixed to main/demo.
 */
export function createPlaybackEnginePair(
  overrides: Omit<PlaybackEngineOptions, 'id'> = {},
): PlaybackEnginePair {
  const shared: Omit<PlaybackEngineOptions, 'id'> = {
    initialVolume: overrides.initialVolume ?? DEFAULT_PLAYBACK_VOLUME,
    adapter: overrides.adapter,
  };

  return {
    main: createPlaybackEngine({ ...shared, id: MAIN_PLAYBACK_ENGINE_ID }),
    demo: createPlaybackEngine({ ...shared, id: DEMO_PLAYBACK_ENGINE_ID }),
  };
}

/**
 * Per-band equalizer settings in decibels.
 * Applied by {@link WebAudioPlaybackEngine} via BiquadFilter nodes.
 */
export interface EqualizerBands {
  readonly lowDb: number;
  readonly midDb: number;
  readonly highDb: number;
}

export const DEFAULT_EQUALIZER_BANDS: EqualizerBands = {
  lowDb: 0,
  midDb: 0,
  highDb: 0,
};

/** Linear track gain multiplier (1 = unity). Combined with auto-gain when enabled. */
export const DEFAULT_TRACK_GAIN = 1;

/** Manual / playback track gain limits (dB), aligned with loudness UI slider. */
export const MIN_TRACK_GAIN_DB = -30;
export const MAX_TRACK_GAIN_DB = 30;

export const TRACK_GAIN_LINEAR_MIN = 0;
export const TRACK_GAIN_LINEAR_MAX = 10 ** (MAX_TRACK_GAIN_DB / 20);

/** Placeholder auto-gain normalization factor when enabled (full analysis deferred). */
export const AUTO_GAIN_NORMALIZATION = 0.9;

/**
 * Optional effects capability for engines with a Web Audio gain/EQ chain.
 *
 * Playlist and session logic stay in stores; effects are playback-layer only.
 */
export interface PlaybackEffects {
  /** Per-track linear gain (0…{@link TRACK_GAIN_LINEAR_MAX}, 1 = unity). */
  setTrackGain(gain: number): void;

  /** Three-band EQ (low shelf, peaking mid, high shelf). */
  setEqualizerBands(bands: EqualizerBands): void;

  /**
   * Enables placeholder loudness normalization (fixed multiplier until real analysis).
   * @param enabled - When true, applies {@link AUTO_GAIN_NORMALIZATION} on top of track gain.
   */
  setAutoGainEnabled(enabled: boolean): void;

  /**
   * Adaptive dynamics compression after EQ (loudness normalization feature).
   * @param strength - 0 = bypass; 0…1 maps to light…heavy compressor settings.
   */
  setCompressionStrength(strength: number): void;
}

export function isPlaybackEffects(engine: unknown): engine is PlaybackEffects {
  return (
    typeof engine === 'object' &&
    engine !== null &&
    'setTrackGain' in engine &&
    typeof (engine as PlaybackEffects).setTrackGain === 'function' &&
    'setCompressionStrength' in engine &&
    typeof (engine as PlaybackEffects).setCompressionStrength === 'function'
  );
}

import { isProjectTrack } from '@core/types/project';
import type { Track, TrackLoudness } from '@core/types/track';

import { useDemoPlayerStore } from '../../stores/demoPlayerStore';
import { usePlayerAudioStore } from '../../stores/playerAudioStore';
import { useProjectStore } from '../../stores/projectStore';
import { useSettingsStore } from '../../stores/settingsStore';

import { applyLoudnessPlaybackEffects } from './applyPlaybackEffects';
import type { PlaybackEngine } from './PlaybackEngine';
import { demoPlaybackEngine, mainPlaybackEngine } from './playbackEngines';

function syncPlaybackEngineIfTrackMatches(
  trackId: string,
  options: {
    currentTrack: Track | null | undefined;
    isPlayerDisabled?: boolean;
    engine: PlaybackEngine;
    onTrackUpdated: (track: Track) => void;
  },
): void {
  if (options.isPlayerDisabled || !options.currentTrack || options.currentTrack.id !== trackId) {
    return;
  }

  const item = useProjectStore.getState().findItemById(trackId);
  if (!item || !isProjectTrack(item)) {
    return;
  }

  applyLoudnessPlaybackEffects(options.engine, item, useSettingsStore.getState());
  options.onTrackUpdated({ ...item });
}

function syncMainPlayerIfTrackMatches(trackId: string): void {
  const { currentTrack } = usePlayerAudioStore.getState();
  syncPlaybackEngineIfTrackMatches(trackId, {
    currentTrack,
    engine: mainPlaybackEngine,
    onTrackUpdated: (track) => usePlayerAudioStore.setState({ currentTrack: track }),
  });
}

function syncDemoPlayerIfTrackMatches(trackId: string): void {
  const { currentTrack, isDisabled } = useDemoPlayerStore.getState();
  syncPlaybackEngineIfTrackMatches(trackId, {
    currentTrack,
    isPlayerDisabled: isDisabled,
    engine: demoPlaybackEngine,
    onTrackUpdated: (track) => useDemoPlayerStore.setState({ currentTrack: track }),
  });
}

/** Re-apply loudness gain on active engines when a track's loudness metadata changes. */
export function applyLoudnessChangeToActivePlayback(trackId: string): void {
  syncMainPlayerIfTrackMatches(trackId);
  syncDemoPlayerIfTrackMatches(trackId);
}

function hasLoudnessPlaybackFieldsChanged(
  prev: TrackLoudness | undefined,
  next: TrackLoudness | undefined,
): boolean {
  if (prev === next) {
    return false;
  }
  if (!prev || !next) {
    return prev !== next;
  }

  return (
    prev.status !== next.status ||
    prev.trackGainDb !== next.trackGainDb ||
    prev.manualGainDb !== next.manualGainDb ||
    prev.manualCompressionStrength !== next.manualCompressionStrength ||
    prev.integratedLufs !== next.integratedLufs ||
    prev.lraLowLufs !== next.lraLowLufs ||
    prev.lraLu !== next.lraLu
  );
}

function handleProjectLoudnessChange(
  state: ReturnType<typeof useProjectStore.getState>,
  prevState: ReturnType<typeof useProjectStore.getState>,
): void {
  const mainTrackId = usePlayerAudioStore.getState().currentTrack?.id;
  const demoTrackId = useDemoPlayerStore.getState().currentTrack?.id;
  const trackIds = new Set([mainTrackId, demoTrackId].filter(Boolean) as string[]);

  for (const trackId of trackIds) {
    const prevItem = prevState.findItemById(trackId);
    const nextItem = state.findItemById(trackId);
    if (!prevItem || !nextItem || !isProjectTrack(prevItem) || !isProjectTrack(nextItem)) {
      continue;
    }
    if (hasLoudnessPlaybackFieldsChanged(prevItem.loudness, nextItem.loudness)) {
      applyLoudnessChangeToActivePlayback(trackId);
    }
  }
}

/** Subscribe to project/settings updates so gain changes apply during playback. */
export function wireLoudnessPlaybackSync(): void {
  useProjectStore.subscribe((state, prevState) => {
    handleProjectLoudnessChange(state, prevState);
  });

  useSettingsStore.subscribe((state, prevState) => {
    if (
      state.loudnessNormalizationEnabled === prevState.loudnessNormalizationEnabled &&
      state.loudnessTargetLufs === prevState.loudnessTargetLufs &&
      state.loudnessCompressionEnabled === prevState.loudnessCompressionEnabled &&
      state.loudnessQuietGapRangeLu === prevState.loudnessQuietGapRangeLu
    ) {
      return;
    }

    const mainTrackId = usePlayerAudioStore.getState().currentTrack?.id;
    const demoTrackId = useDemoPlayerStore.getState().currentTrack?.id;
    if (mainTrackId) {
      syncMainPlayerIfTrackMatches(mainTrackId);
    }
    if (demoTrackId) {
      syncDemoPlayerIfTrackMatches(demoTrackId);
    }
  });
}

export type BrowserLoginFlowState = {
  status: 'idle' | 'waiting' | 'failed';
  error: string | null;
};

let state: BrowserLoginFlowState = { status: 'idle', error: null };
const listeners = new Set<() => void>();

function setState(next: BrowserLoginFlowState): void {
  state = next;
  listeners.forEach((listener) => listener());
}

export function getBrowserLoginFlowState(): BrowserLoginFlowState {
  return state;
}

export function subscribeBrowserLoginFlow(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function beginBrowserLoginFlow(): void {
  setState({ status: 'waiting', error: null });
}

export function completeBrowserLoginFlow(): void {
  setState({ status: 'idle', error: null });
}

export function failBrowserLoginFlow(message: string): void {
  setState({ status: 'failed', error: message });
}

export function resetBrowserLoginFlow(): void {
  setState({ status: 'idle', error: null });
}

import { ProjectItem } from '@core/types/project';

import { insertItemAtPath } from '../stores/projectStoreCore';
import { cloneItem, cloneItems } from '../utils/historyCore';

import { CommandResult, HistoryCommand, ItemPosition, ItemsState } from './index';

export class AddItemsCommand implements HistoryCommand {
  readonly type = 'addItems';

  constructor(
    private readonly items: ProjectItem[],
    private readonly atIndex?: number,
  ) {}

  execute(state: ItemsState): CommandResult {
    const newItems = [...state.items];
    const insertIndex = this.atIndex ?? newItems.length;
    newItems.splice(insertIndex, 0, ...cloneItems(this.items));
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const itemIds = new Set(this.items.map((i) => i.id));
    const newItems = state.items.filter((item) => !itemIds.has(item.id));
    return { success: true, newState: { items: newItems } };
  }
}

export class AddItemsAtPositionsCommand implements HistoryCommand {
  readonly type = 'addItemsAtPositions';

  constructor(private readonly positions: ItemPosition[]) {}

  execute(state: ItemsState): CommandResult {
    let newItems = [...state.items];
    const sortedPositions = [...this.positions].sort((a, b) => a.index - b.index);
    for (const pos of sortedPositions) {
      newItems = insertItemAtPath(newItems, cloneItem(pos.item), pos.parentPath, pos.index);
    }
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const itemIds = new Set(this.positions.map((p) => p.item.id));
    const removeRecursive = (items: ProjectItem[]): ProjectItem[] => {
      return items
        .filter((item) => !itemIds.has(item.id))
        .map((item) => {
          if ('items' in item) {
            return { ...item, items: removeRecursive(item.items) };
          }
          return item;
        });
    };
    return { success: true, newState: { items: removeRecursive(state.items) } };
  }
}

import { isProjectGroup, ProjectGroup, ProjectItem } from '@core/types/project';

import { updateGroupInItems } from '../stores/projectStoreCore';
import { cloneItems } from '../utils/historyCore';

import { CommandResult, HistoryCommand, ItemsState } from './index';

export class CreateGroupCommand implements HistoryCommand {
  readonly type = 'createGroup';

  constructor(
    private readonly groupId: string,
    private readonly groupName: string,
    _itemIds: string[],
    private readonly insertIndex: number,
    private readonly originalItems: ProjectItem[],
    private readonly originalIndices: number[],
  ) {}

  execute(state: ItemsState): CommandResult {
    const newItems = [...state.items];
    const sortedIndices = [...this.originalIndices].sort((a, b) => b - a);
    sortedIndices.forEach((index) => {
      if (index < newItems.length) {
        newItems.splice(index, 1);
      }
    });
    const group: ProjectGroup = {
      id: this.groupId,
      name: this.groupName,
      items: cloneItems(this.originalItems),
    };
    newItems.splice(this.insertIndex, 0, group);
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const newItems = state.items.flatMap((item) => {
      if (isProjectGroup(item) && item.id === this.groupId) {
        return item.items;
      }
      return [item];
    });
    return { success: true, newState: { items: newItems } };
  }
}

export class UngroupCommand implements HistoryCommand {
  readonly type = 'ungroup';

  constructor(
    private readonly groupId: string,
    private readonly group: ProjectGroup,
    private readonly groupIndex: number,
  ) {}

  execute(state: ItemsState): CommandResult {
    const newItems = state.items.flatMap((item) => {
      if (isProjectGroup(item) && item.id === this.groupId) {
        return item.items;
      }
      return [item];
    });
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const itemIds = new Set(this.group.items.map((i) => i.id));
    const filtered = state.items.filter((item) => !itemIds.has(item.id));
    const newItems = [
      ...filtered.slice(0, this.groupIndex),
      {
        id: this.group.id,
        name: this.group.name,
        items: cloneItems(this.group.items),
      },
      ...filtered.slice(this.groupIndex),
    ];
    return { success: true, newState: { items: newItems } };
  }
}

export class RenameGroupCommand implements HistoryCommand {
  readonly type = 'renameGroup';

  constructor(
    private readonly groupId: string,
    private readonly oldName: string,
    private readonly newName: string,
  ) {}

  execute(state: ItemsState): CommandResult {
    const newItems = updateGroupInItems(state.items, this.groupId, (grp) => ({
      ...grp,
      name: this.newName,
    }));
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const newItems = updateGroupInItems(state.items, this.groupId, (grp) => ({
      ...grp,
      name: this.oldName,
    }));
    return { success: true, newState: { items: newItems } };
  }
}

import { ProjectItem } from '@core/types/project';

import { cloneItems } from '../utils/historyCore';

import { CommandResult, HistoryCommand, ItemsState } from './index';

export class MoveItemCommand implements HistoryCommand {
  readonly type = 'moveItem';

  constructor(
    private readonly fromIndex: number,
    private readonly toIndex: number,
  ) {}

  execute(state: ItemsState): CommandResult {
    const newItems = [...state.items];
    if (this.fromIndex < 0 || this.fromIndex >= newItems.length) {
      return { success: false };
    }
    const [moved] = newItems.splice(this.fromIndex, 1);
    if (!moved) {
      return { success: false };
    }
    const targetIndex = Math.min(this.toIndex, newItems.length);
    newItems.splice(targetIndex, 0, moved);
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const newItems = [...state.items];
    const effectiveToIndex = Math.min(this.toIndex, state.items.length - 1);
    if (effectiveToIndex < 0 || effectiveToIndex >= newItems.length) {
      return { success: false };
    }
    const [moved] = newItems.splice(effectiveToIndex, 1);
    if (!moved) {
      return { success: false };
    }
    newItems.splice(this.fromIndex, 0, moved);
    return { success: true, newState: { items: newItems } };
  }
}

export class MoveItemsCommand implements HistoryCommand {
  readonly type = 'moveItems';

  constructor(
    private readonly items: ProjectItem[],
    private readonly fromIndices: number[],
    private readonly toIndex: number,
  ) {}

  execute(state: ItemsState): CommandResult {
    const newItems = [...state.items];
    const sortedFromIndices = [...this.fromIndices].sort((a, b) => b - a);
    sortedFromIndices.forEach((index) => {
      newItems.splice(index, 1);
    });
    const insertIndex = Math.min(this.toIndex, newItems.length);
    newItems.splice(insertIndex, 0, ...cloneItems(this.items));
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const newItems = [...state.items];
    const itemIds = new Set(this.items.map((i) => i.id));
    const filtered = newItems.filter((item) => !itemIds.has(item.id));
    const sortedFromIndices = [...this.fromIndices].sort((a, b) => a - b);
    let result = filtered;
    this.items.forEach((item, i) => {
      const insertAt = sortedFromIndices[i];
      result = [...result.slice(0, insertAt), item, ...result.slice(insertAt)];
    });
    return { success: true, newState: { items: result } };
  }
}

import { CommandResult, HistoryCommand, ItemsState } from './index';

export class SetNameCommand implements HistoryCommand {
  readonly type = 'setName';

  constructor(
    private readonly oldName: string,
    private readonly newName: string,
  ) {}

  execute(_state: ItemsState): CommandResult {
    return { success: true, newState: { name: this.newName } };
  }

  undo(_state: ItemsState): CommandResult {
    return { success: true, newState: { name: this.oldName } };
  }
}

import { ProjectItem } from '@core/types/project';

import { insertItemAtPath, removeItemFromItems } from '../stores/projectStoreCore';
import { cloneItem } from '../utils/historyCore';

import { CommandResult, HistoryCommand, ItemPosition, ItemsState } from './index';

export class RemoveItemsCommand implements HistoryCommand {
  readonly type = 'removeItems';

  constructor(
    private readonly items: ProjectItem[],
    private readonly indices: number[],
  ) {}

  execute(state: ItemsState): CommandResult {
    let newItems = [...state.items];
    for (const item of this.items) {
      newItems = removeItemFromItems(newItems, item.id);
    }
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    let newItems = [...state.items];
    const sortedEntries = this.items
      .map((item, i) => ({ item, index: this.indices[i] }))
      .sort((a, b) => a.index - b.index);

    for (const entry of sortedEntries) {
      newItems = insertItemAtPath(newItems, cloneItem(entry.item), [], entry.index);
    }
    return { success: true, newState: { items: newItems } };
  }
}

export class RemoveNestedItemCommand implements HistoryCommand {
  readonly type = 'removeNestedItem';

  constructor(
    private readonly item: ProjectItem,
    private readonly parentPath: string[],
    private readonly indexInParent: number,
  ) {}

  execute(state: ItemsState): CommandResult {
    const newItems = removeItemFromItems(state.items, this.item.id);
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    const newItems = insertItemAtPath(
      state.items,
      cloneItem(this.item),
      this.parentPath,
      this.indexInParent,
    );
    return { success: true, newState: { items: newItems } };
  }
}

export class RemoveItemsAtPositionsCommand implements HistoryCommand {
  readonly type = 'removeItemsAtPositions';

  constructor(private readonly positions: ItemPosition[]) {}

  execute(state: ItemsState): CommandResult {
    let newItems = [...state.items];
    for (const pos of this.positions) {
      newItems = removeItemFromItems(newItems, pos.item.id);
    }
    return { success: true, newState: { items: newItems } };
  }

  undo(state: ItemsState): CommandResult {
    let newItems = [...state.items];
    const sortedPositions = [...this.positions].sort((a, b) => a.index - b.index);
    for (const pos of sortedPositions) {
      newItems = insertItemAtPath(newItems, cloneItem(pos.item), pos.parentPath, pos.index);
    }
    return { success: true, newState: { items: newItems } };
  }
}

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { WorkspaceId } from '@core/types/workspace';

import { useDragDropStore } from '../../stores/dragDropStore';

import { ItemListContextValue, ItemListProvider } from './ItemListContext';

export interface ItemListProps {
  children: React.ReactNode;
  baseClassName?: string;
  className?: string;
  style?: React.CSSProperties;
  workspaceId?: WorkspaceId;
  /** Container drag over handler - receives event and insert index (where item would be inserted) */
  onDragOver?: (e: React.DragEvent, insertIndex: number) => void;
  /** Container drop handler - receives event and insert index */
  onDrop?: (e: React.DragEvent, insertIndex: number) => void;
  onDragLeave?: (e: React.DragEvent) => void;
  onDragEnd?: (e: React.DragEvent) => void;
  showEmptyState?: boolean;
  emptyState?: React.ReactNode;
}

/**
 * ItemList - Container component with drop logic on the container level
 *
 * Handles drag and drop at the container level, solving the "dead zone" bug
 * where drops between items don't work. The drop position is calculated
 * based on cursor position relative to all items.
 *
 * @example
 * ```tsx
 * <ItemList
 *   onDragOver={handleDragOverContainer}
 *   onDrop={handleDropOnContainer}
 *   onDragLeave={handleDragLeave}
 * >
 *   {items.map((item, index) => (
 *     <ListRow key={item.id} id={item.id}>
 *       ...
 *     </ListRow>
 *   ))}
 * </ItemList>
 * ```
 */
export const ItemList: React.FC<ItemListProps> = ({
  children,
  baseClassName = 'item-list',
  className,
  style,
  workspaceId,
  onDragOver,
  onDrop,
  onDragLeave,
  onDragEnd,
  showEmptyState = true,
  emptyState,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const lastInsertIndexRef = useRef<number>(0);
  const [dropIndex, setDropIndex] = useState<number | null>(null);
  const [isDragging, setIsDragging] = useState(false);

  const hoverWorkspaceId = useDragDropStore((state) => state.hoverWorkspaceId);
  const globalDragging = useDragDropStore((state) => state.dragging);

  useEffect(() => {
    if (!globalDragging) {
      // Reset state when dragging stops - using setTimeout to avoid synchronous setState in effect
      setTimeout(() => {
        setDropIndex(null);
        setIsDragging(false);
      }, 0);
      return;
    }
    if (workspaceId && hoverWorkspaceId !== null && hoverWorkspaceId !== workspaceId) {
      setTimeout(() => {
        setDropIndex(null);
        setIsDragging(false);
      }, 0);
    }
  }, [hoverWorkspaceId, workspaceId, globalDragging]);

  /**
   * Calculate the insert index based on cursor position
   * This is the key logic that solves the "dead zone" bug
   */
  const calculateInsertIndex = useCallback((e: React.DragEvent): number => {
    const container = containerRef.current;
    if (!container) return 0;

    const items = container.querySelectorAll('[data-item-id]');
    if (items.length === 0) return 0;

    // Default to end of list
    let insertIndex = items.length;

    for (let i = 0; i < items.length; i++) {
      const rect = items[i].getBoundingClientRect();
      const midY = rect.top + rect.height / 2;

      if (e.clientY < midY) {
        insertIndex = i;
        break;
      }
    }

    return insertIndex;
  }, []);

  const handleDragOver = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();

      setIsDragging(true);
      const insertIndex = calculateInsertIndex(e);
      lastInsertIndexRef.current = insertIndex;
      setDropIndex(insertIndex);

      onDragOver?.(e, insertIndex);
    },
    [calculateInsertIndex, onDragOver],
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();

      const insertIndex = lastInsertIndexRef.current;
      onDrop?.(e, insertIndex);

      setDropIndex(null);
      setIsDragging(false);
    },
    [onDrop],
  );

  const handleDragLeave = useCallback(
    (e: React.DragEvent) => {
      // Only clear state if we're actually leaving the container
      const rect = containerRef.current?.getBoundingClientRect();
      if (!rect) return;

      const { clientX, clientY } = e;
      const relatedTarget = e.relatedTarget as HTMLElement | null;
      const currentTarget = e.currentTarget as HTMLElement;

      // Check if we're leaving the container bounds
      const isOutside =
        clientX < rect.left || clientX > rect.right || clientY < rect.top || clientY > rect.bottom;

      // Check if the related target is still within our container
      const isStillInside = relatedTarget && currentTarget.contains(relatedTarget);

      if (isOutside && !isStillInside) {
        setDropIndex(null);
        setIsDragging(false);
        onDragLeave?.(e);
      }
    },
    [onDragLeave],
  );

  const handleDragEnd = useCallback(
    (e: React.DragEvent) => {
      setDropIndex(null);
      setIsDragging(false);
      onDragEnd?.(e);
    },
    [onDragEnd],
  );

  // Callback for child components to update drop index
  const updateDropIndex = useCallback((index: number | null) => {
    setDropIndex(index);
    if (index !== null) {
      setIsDragging(true);
    }
  }, []);

  // Memoize context value
  const contextValue: ItemListContextValue = useMemo(
    () => ({
      dropIndex,
      isDragging,
      baseClassName,
      updateDropIndex,
    }),
    [dropIndex, isDragging, baseClassName, updateDropIndex],
  );

  // Check if children is empty
  const childArray = React.Children.toArray(children);
  const isEmpty = childArray.length === 0;

  const computedClassName = [baseClassName, className].filter(Boolean).join(' ');

  return (
    <ItemListProvider value={contextValue}>
      <div
        ref={containerRef}
        className={computedClassName}
        style={style}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        onDragLeave={handleDragLeave}
        onDragEnd={handleDragEnd}
      >
        {isEmpty && showEmptyState
          ? emptyState || (
              <div className={`${baseClassName}-empty`}>
                <p>No items</p>
              </div>
            )
          : children}
      </div>
    </ItemListProvider>
  );
};

ItemList.displayName = 'ItemList';

import React, { createContext, useContext } from 'react';

/**
 * Context value for ItemList component
 * Provides drop state information to all child components
 */
export interface ItemListContextValue {
  /** Current drop index (where the item will be inserted) */
  dropIndex: number | null;
  /** Whether a drag operation is in progress */
  isDragging: boolean;
  /** Base CSS class name for styling */
  baseClassName: string;
  /** Update drop index from child components (e.g., when dragging over items) */
  updateDropIndex: (index: number | null) => void;
}

const defaultContextValue: ItemListContextValue = {
  dropIndex: null,
  isDragging: false,
  baseClassName: 'item-list',
  updateDropIndex: () => {},
};

export const ItemListContext = createContext<ItemListContextValue>(defaultContextValue);

/**
 * Hook to access ItemList context
 * Must be used within an ItemList component
 */
export function useItemListContext(): ItemListContextValue {
  const context = useContext(ItemListContext);
  if (!context) {
    throw new Error('useItemListContext must be used within an ItemList component');
  }
  return context;
}

/**
 * Props for ItemListContext.Provider wrapper
 */
export interface ItemListProviderProps {
  value: ItemListContextValue;
  children: React.ReactNode;
}

/**
 * Provider component for ItemList context
 */
export const ItemListProvider: React.FC<ItemListProviderProps> = ({ value, children }) => {
  return <ItemListContext.Provider value={value}>{children}</ItemListContext.Provider>;
};

import { useCallback } from 'react';

import { useItemListContext } from './ItemListContext';

export interface UseItemDragOverOptions {
  /** Index of the item in the list */
  index: number;
  /** Whether the item can be dropped on */
  disabled?: boolean;
}

/**
 * Hook for handling drag over on individual list items
 * Updates the drop index in ItemList context based on cursor position
 *
 * @example
 * ```tsx
 * const { handleDragOver } = useItemDragOver({ index: 3 });
 *
 * return (
 *   <div onDragOver={handleDragOver}>
 *     ...
 *   </div>
 * );
 * ```
 */
export function useItemDragOver({ index, disabled = false }: UseItemDragOverOptions) {
  const { updateDropIndex } = useItemListContext();

  const handleDragOver = useCallback(
    (e: React.DragEvent) => {
      if (disabled) return;

      // Calculate insert position based on cursor position
      const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
      const y = e.clientY - rect.top;
      const isTopHalf = y < rect.height / 2;

      // If cursor is in top half, insert before this item (index)
      // If cursor is in bottom half, insert after this item (index + 1)
      const insertIndex = isTopHalf ? index : index + 1;

      updateDropIndex(insertIndex);
    },
    [index, disabled, updateDropIndex],
  );

  return { handleDragOver };
}

import React, { createContext, useContext } from 'react';

/**
 * Context value for ListRow component
 * Provides state information to all child components
 */
export interface ListRowContextValue {
  /** Unique identifier for the row */
  id: string;
  /** Whether the row is currently selected */
  isSelected: boolean;
  /** Whether the row is being dragged */
  isDragging: boolean;
  /** Whether the row is active (e.g., currently playing track) */
  isActive: boolean;
  /** Whether the row is playing (for audio items) */
  isPlaying: boolean;
  /** Whether the row is disabled */
  isDisabled: boolean;
  /** Whether the row has been played (for session mode) */
  isPlayed: boolean;
  /** Whether this is the current item (e.g., current track in player) */
  isCurrent: boolean;
  /** Whether the row is locked (cannot be dragged/deleted) */
  isLocked: boolean;
  /** Nesting level for hierarchical items (groups) */
  level: number;
  /** Base CSS class name for styling */
  baseClassName: string;
}

const defaultContextValue: ListRowContextValue = {
  id: '',
  isSelected: false,
  isDragging: false,
  isActive: false,
  isPlaying: false,
  isDisabled: false,
  isPlayed: false,
  isCurrent: false,
  isLocked: false,
  level: 0,
  baseClassName: 'list-row',
};

export const ListRowContext = createContext<ListRowContextValue>(defaultContextValue);

/**
 * Hook to access ListRow context
 * Must be used within a ListRow component
 */
export function useListRowContext(): ListRowContextValue {
  const context = useContext(ListRowContext);
  if (!context) {
    throw new Error('useListRowContext must be used within a ListRow component');
  }
  return context;
}

/**
 * Props for ListRowContext.Provider wrapper
 */
export interface ListRowProviderProps {
  value: ListRowContextValue;
  children: React.ReactNode;
}

/**
 * Provider component for ListRow context
 */
export const ListRowProvider: React.FC<ListRowProviderProps> = ({ value, children }) => {
  return <ListRowContext.Provider value={value}>{children}</ListRowContext.Provider>;
};

