import FolderIcon from '@mui/icons-material/Folder';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import React, { useState, useRef, useEffect, useCallback } from 'react';

import { ProjectItem, isProjectGroup } from '@core/types/project';
import { Track } from '@core/types/track';

import { formatTrackDuration } from '../../utils/durationUtils';
import { getGroupItemCount, getGroupTotalDuration } from '../../utils/playerItemsUtils';
import { useItemDragOver } from '../ItemList';
import { ListRowCompound } from '../ListRow';

function pluralize(count: number, one: string, few: string, many: string): string {
  const mod10 = count % 10;
  const mod100 = count % 100;

  if (mod100 >= 11 && mod100 <= 19) {
    return many;
  }
  if (mod10 === 1) {
    return one;
  }
  if (mod10 >= 2 && mod10 <= 4) {
    return few;
  }
  return many;
}

export type ProjectItemRowMode = 'playlist' | 'player-preparation' | 'player-session';

export interface ProjectItemRowProps {
  item: ProjectItem;
  index: number;
  listIndex: number;
  level?: number;
  mode: ProjectItemRowMode;

  isSelected: boolean;
  isDragging: boolean;
  isDragOver?: boolean;
  insertPosition?: 'top' | 'bottom' | null;

  isActive?: boolean;
  isPlaying?: boolean;

  isPlayed?: boolean;
  isDisabled?: boolean;
  isCurrent?: boolean;
  isLocked?: boolean;

  groupDuration?: number;
  isDuplicatePath?: boolean;
  isNotOnServer?: boolean;

  onToggleSelect: (id: string, e?: React.MouseEvent) => void;
  onRemove: (id: string) => void;
  onDragStart: (e: React.DragEvent, id: string) => void;
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent, id: string) => void;
  onDragEnd: (e: React.DragEvent) => void;
  onPlay?: (track: Track) => Promise<void> | void;
  onPause?: () => void;
  onToggleDisabled?: (itemId: string) => void;
  onRenameGroup?: (groupId: string, newName: string) => void;
  onUngroupGroup?: (groupId: string) => void;
  onOpenSettings?: (itemId: string) => void;
  onTrackActions?: (itemId: string, anchorRect: DOMRect) => void;
  trackActionsDisabled?: boolean;

  settingsButton?: React.ReactNode;
  loudnessControls?: React.ReactNode;
}

export const ProjectItemRow: React.FC<ProjectItemRowProps> = ({
  item,
  index,
  listIndex,
  level = 0,
  mode,
  isSelected,
  isDragging,
  isDragOver = false,
  insertPosition = null,
  isActive = false,
  isPlaying = false,
  isPlayed = false,
  isDisabled = false,
  isCurrent = false,
  isLocked = false,
  groupDuration,
  isDuplicatePath = false,
  isNotOnServer = false,
  onToggleSelect,
  onRemove,
  onDragStart,
  onDragOver,
  onDrop,
  onDragEnd,
  onPlay,
  onPause,
  onToggleDisabled,
  onRenameGroup,
  onUngroupGroup,
  onOpenSettings,
  onTrackActions,
  trackActionsDisabled = false,
  settingsButton,
  loudnessControls,
}) => {
  const isGroup = isProjectGroup(item);
  const track = isGroup ? null : item;

  const [isEditingName, setIsEditingName] = useState(false);
  const [editingName, setEditingName] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const showPlayButton = !isGroup;
  const showDisableButton = mode === 'player-session';
  const showSettingsButton = mode !== 'playlist';

  const handlePlay = () => {
    if (!track || !onPlay) return;
    const maybePromise = onPlay(track);
    if (maybePromise && typeof (maybePromise as Promise<void>).catch === 'function') {
      (maybePromise as Promise<void>).catch(() => undefined);
    }
  };

  const handlePause = () => {
    onPause?.();
  };

  const handleToggleDisabled = () => {
    onToggleDisabled?.(item.id);
  };

  const handleStartEdit = (e: React.MouseEvent) => {
    if (!isGroup || !onRenameGroup || isLocked) return;
    e.stopPropagation();
    setIsEditingName(true);
    setEditingName(item.name);
  };

  const handleSaveName = () => {
    if (!isGroup || !onRenameGroup) return;
    const trimmedName = editingName.trim();
    if (trimmedName && trimmedName !== item.name) {
      onRenameGroup(item.id, trimmedName);
    }
    setIsEditingName(false);
  };

  const handleRowClick = (e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    if (target.closest('.track-loudness-popover, .track-loudness-button')) {
      return;
    }
    onToggleSelect(item.id, e);
  };

  const handleCancelEdit = () => {
    setIsEditingName(false);
    setEditingName('');
  };

  const handleNameKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSaveName();
    } else if (e.key === 'Escape') {
      e.preventDefault();
      handleCancelEdit();
    }
  };

  useEffect(() => {
    if (isEditingName && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [isEditingName]);

  const itemCount = isGroup ? getGroupItemCount(item) : 0;
  const groupDisplayName = isGroup
    ? `${item.name} (${itemCount} ${pluralize(itemCount, 'элемент', 'элемента', 'элементов')})`
    : '';
  const trackDisplayName = track?.name || '';

  const displayDuration = isGroup
    ? groupDuration !== undefined && groupDuration > 0
      ? formatTrackDuration(groupDuration)
      : (() => {
          const baseDuration = getGroupTotalDuration(item);
          return baseDuration > 0 ? formatTrackDuration(baseDuration) : undefined;
        })()
    : track?.duration && track.duration > 0
      ? formatTrackDuration(track.duration)
      : undefined;

  const handleDragStart = (e: React.DragEvent) => {
    if (isEditingName) {
      e.preventDefault();
      return;
    }
    onDragStart(e, item.id);
  };

  const handleDrop = (e: React.DragEvent) => {
    if (isEditingName) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    onDrop(e, item.id);
  };

  const { handleDragOver: updateContextDropIndex } = useItemDragOver({
    index: listIndex,
    disabled: isLocked || isEditingName,
  });

  const handleDragOver = useCallback(
    (e: React.DragEvent) => {
      if (isEditingName) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      updateContextDropIndex(e);
      onDragOver(e);
    },
    [isEditingName, updateContextDropIndex, onDragOver],
  );

  const renderGroupNameContent = () => {
    if (isEditingName) {
      return (
        <>
          <input
            ref={inputRef}
            type="text"
            value={editingName}
            onChange={(e) => setEditingName(e.target.value)}
            onBlur={handleSaveName}
            onKeyDown={handleNameKeyDown}
            onClick={(e) => e.stopPropagation()}
            onMouseDown={(e) => e.stopPropagation()}
            className="playlist-item-group-name-input"
            style={{
              background: 'var(--bg-tertiary)',
              border: '1px solid var(--accent-primary)',
              borderRadius: '4px',
              padding: '2px 6px',
              fontSize: 'var(--font-size-body)',
              color: 'var(--text-primary)',
              outline: 'none',
              flex: 1,
              minWidth: 0,
            }}
          />
          <span style={{ marginLeft: '4px' }}>
            ({itemCount} {pluralize(itemCount, 'элемент', 'элемента', 'элементов')})
          </span>
        </>
      );
    }

    return groupDisplayName;
  };

  return (
    <ListRowCompound
      id={item.id}
      isSelected={isSelected}
      isDragging={isDragging}
      isDragOver={isDragOver}
      insertPosition={insertPosition}
      isActive={isActive}
      isPlaying={isPlaying}
      isPlayed={isPlayed}
      isDisabled={isDisabled}
      isCurrent={isCurrent}
      isLocked={isLocked}
      level={level}
      draggable={!isLocked && !isEditingName}
      onClick={handleRowClick}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDrop={handleDrop}
      onDragEnd={onDragEnd}
      className={isGroup ? 'playlist-item--group' : ''}
      data-item-id={item.id}
    >
      {showPlayButton && track && onPlay && (
        <ListRowCompound.PlayButton onPlay={handlePlay} onPause={handlePause} />
      )}

      {isGroup && (
        <div className="playlist-item-group-icon">
          <FolderIcon style={{ fontSize: '20px', color: 'var(--text-secondary)' }} />
        </div>
      )}

      <ListRowCompound.DragHandle />

      <ListRowCompound.Checkbox onToggle={(e) => onToggleSelect(item.id, e)} />

      {isGroup && onUngroupGroup ? (
        <ListRowCompound.UngroupButton onUngroup={() => onUngroupGroup(item.id)} />
      ) : (
        <ListRowCompound.Index value={index} />
      )}

      <ListRowCompound.Content
        editable={isGroup && !!onRenameGroup && !isLocked}
        onDoubleClick={isGroup ? handleStartEdit : undefined}
        title={
          isGroup && onRenameGroup && !isLocked ? 'Двойной клик для переименования' : undefined
        }
      >
        {isGroup ? renderGroupNameContent() : trackDisplayName}
      </ListRowCompound.Content>

      {!isGroup && track && track.isMissing && (
        <span
          className="playlist-item-missing-dot"
          title={`Файл не найден: ${track.path}`}
          aria-label="Файл не найден"
          style={{ color: 'var(--warning, #ff9800)', fontSize: '14px', marginRight: '4px' }}
        >
          ⚠
        </span>
      )}

      {!isGroup && track && loudnessControls}

      {displayDuration && (
        <ListRowCompound.Secondary>
          {isNotOnServer && (
            <span
              className="playlist-item-not-on-server-dot"
              title="Трека нет в плейлисте на сервере"
              aria-label="Трека нет на сервере"
            />
          )}
          {isDuplicatePath && (
            <span
              className="playlist-item-duplicate-dot"
              title="Дубликат: такой трек уже есть в списке (по пути или имени файла)"
              aria-label="Дубликат"
            />
          )}
          {displayDuration}
        </ListRowCompound.Secondary>
      )}

      <ListRowCompound.Actions>
        {showSettingsButton &&
          (settingsButton ||
            (onOpenSettings && (
              <ListRowCompound.SettingsButton onClick={() => onOpenSettings(item.id)} />
            )))}

        {showDisableButton && onToggleDisabled && (
          <ListRowCompound.DisableButton onToggle={handleToggleDisabled} />
        )}

        {!isGroup && mode !== 'playlist' && (
          <ListRowCompound.ActionButton
            className="playlist-item-more"
            aria-label="Действия с треком"
            title={
              trackActionsDisabled || !onTrackActions
                ? undefined
                : 'Действия: перейти к треку, удалить и др.'
            }
            disabled={trackActionsDisabled || !onTrackActions}
            onClick={(e) => {
              if (!trackActionsDisabled && onTrackActions) {
                onTrackActions(item.id, (e.currentTarget as HTMLElement).getBoundingClientRect());
              }
            }}
            icon={<MoreVertIcon style={{ fontSize: '18px' }} />}
            variant="ghost"
            size="sm"
          />
        )}

        <ListRowCompound.DeleteButton onClick={() => onRemove(item.id)} />
      </ListRowCompound.Actions>
    </ListRowCompound>
  );
};

ProjectItemRow.displayName = 'ProjectItemRow';

import { getServerUrl, getServerUrlSync } from './serverConfig';

let cachedApiConfig: {
  serverUrl: string;
  signalRUrl: string;
  apiUrl: string;
} | null = null;

/** Убирает завершающий слэш у base URL, чтобы не получать двойной слэш в путях */
function normalizeBaseUrl(url: string): string {
  return url.replace(/\/+$/, '');
}

function buildSignalRUrl(serverUrl: string): string {
  return `${normalizeBaseUrl(serverUrl)}/partyHub`;
}

function buildApiUrl(serverUrl: string): string {
  return `${normalizeBaseUrl(serverUrl)}/api`;
}

async function getApiConfigAsync(): Promise<{
  serverUrl: string;
  signalRUrl: string;
  apiUrl: string;
}> {
  const raw = await getServerUrl();
  const serverUrl = normalizeBaseUrl(raw);
  return {
    serverUrl,
    signalRUrl: buildSignalRUrl(raw),
    apiUrl: buildApiUrl(raw),
  };
}

function getApiConfigSync(): {
  serverUrl: string;
  signalRUrl: string;
  apiUrl: string;
} {
  if (cachedApiConfig) {
    return cachedApiConfig;
  }

  const raw = getServerUrlSync();
  const serverUrl = normalizeBaseUrl(raw);
  cachedApiConfig = {
    serverUrl,
    signalRUrl: buildSignalRUrl(raw),
    apiUrl: buildApiUrl(raw),
  };

  return cachedApiConfig;
}

export const apiConfig = {
  get serverUrl(): string {
    try {
      return getApiConfigSync().serverUrl;
    } catch (error) {
      throw new Error(
        `Failed to get server URL: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  },

  get signalRUrl(): string {
    try {
      return getApiConfigSync().signalRUrl;
    } catch (error) {
      throw new Error(
        `Failed to get SignalR URL: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  },

  get apiUrl(): string {
    try {
      return getApiConfigSync().apiUrl;
    } catch (error) {
      throw new Error(
        `Failed to get API URL: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
  },
};

export async function getApiConfig(): Promise<{
  serverUrl: string;
  signalRUrl: string;
  apiUrl: string;
}> {
  const config = await getApiConfigAsync();
  cachedApiConfig = config;
  return config;
}

export function clearApiConfigCache(): void {
  cachedApiConfig = null;
}

/**
 * App version from package.json (injected at build time via Vite define).
 * Single source of truth for display: package.json "version".
 */
export const APP_VERSION = typeof __APP_VERSION__ !== 'undefined' ? __APP_VERSION__ : '0.0.0';

import { APP_VERSION } from './appVersion';

/**
 * Версия desktop-клиента из package.json (инжектируется при сборке через Vite define).
 */
export const CLIENT_VERSION = APP_VERSION;

export const CLIENT_VERSION_HEADER = 'X-Client-Version';
export const CLIENT_APP_HEADER = 'X-Client-App';
export const CLIENT_APP_ID = 'desktop';

export function getClientVersionHeaders(): Record<string, string> {
  return {
    [CLIENT_VERSION_HEADER]: CLIENT_VERSION,
    [CLIENT_APP_HEADER]: CLIENT_APP_ID,
  };
}

import { getPlatform, isPlatformInitialized } from '../platform';

let cachedServerUrl: string | null = null;
let cachedWebBaseUrl: string | null = null;
let warnedEmptyElectronServerUrl = false;

function isConfiguredServerUrl(value: string | null | undefined): value is string {
  return value !== undefined && value !== null;
}

function warnEmptyElectronServerUrlOnce(): void {
  if (warnedEmptyElectronServerUrl) {
    return;
  }
  warnedEmptyElectronServerUrl = true;
  console.warn(
    '[serverConfig] Empty serverUrl from Electron config is only intended for web demo same-origin proxy. ' +
      'Electron should set serverUrl in serverConfig.development.json or serverConfig.production.json.',
  );
}

function cacheElectronServerUrl(data: string): string {
  if (data === '') {
    warnEmptyElectronServerUrlOnce();
  }
  cachedServerUrl = data;
  return data;
}

function getEnvServerUrl(): string | undefined {
  const value = import.meta.env.VITE_API_URL;
  return isConfiguredServerUrl(value) ? value : undefined;
}

async function invokeConfig<T>(channel: string, payload?: object): Promise<T | null> {
  if (!isPlatformInitialized()) {
    return null;
  }

  const result = (await getPlatform().invoke(channel, payload)) as
    | { success: true; data: T }
    | { success: false; error: string };

  if (result.success && result.data !== undefined) {
    return result.data;
  }

  if (result.success === false) {
    throw new Error(result.error);
  }

  return null;
}

export async function getWebBaseUrl(): Promise<string> {
  if (cachedWebBaseUrl !== null) {
    return cachedWebBaseUrl;
  }

  if (isPlatformInitialized()) {
    try {
      const data = await invokeConfig<string>('config:getWebBaseUrl');
      if (isConfiguredServerUrl(data)) {
        cachedWebBaseUrl = data;
        return data;
      }
    } catch (error) {
      if (error instanceof Error) {
        throw error;
      }
      throw new Error('Failed to get web base URL from config file.');
    }
  }

  throw new Error(
    'Web base URL is not configured. Set webBaseUrl in serverConfig.development.json / serverConfig.production.json.',
  );
}

export function getWebBaseUrlSync(): string {
  if (cachedWebBaseUrl !== null) {
    return cachedWebBaseUrl;
  }

  throw new Error(
    'Web base URL is not configured. Load webBaseUrl from server config and restart the application.',
  );
}

export async function getServerUrl(): Promise<string> {
  const envServerUrl = getEnvServerUrl();
  if (envServerUrl !== undefined) {
    return envServerUrl;
  }

  if (isPlatformInitialized()) {
    try {
      const data = await invokeConfig<string>('config:getServerUrl');
      if (isConfiguredServerUrl(data)) {
        return cacheElectronServerUrl(data);
      }

      cachedServerUrl = null;
      throw new Error(
        'Server URL is not configured. Set serverUrl in serverConfig.development.json (dev) or serverConfig.production.json (release).',
      );
    } catch (error) {
      cachedServerUrl = null;
      if (error instanceof Error) {
        throw error;
      }
      throw new Error(
        'Failed to get server URL from config file. Configure serverUrl in serverConfig.development.json or serverConfig.production.json.',
      );
    }
  }

  throw new Error(
    'Server URL is not configured. Set VITE_API_URL or serverUrl in serverConfig.development.json / serverConfig.production.json.',
  );
}

export function getServerUrlSync(): string {
  const envServerUrl = getEnvServerUrl();
  if (envServerUrl !== undefined) {
    return envServerUrl;
  }

  if (cachedServerUrl !== null) {
    return cachedServerUrl;
  }

  throw new Error(
    'Server URL is not configured. Set VITE_API_URL or serverUrl in server config and restart the application.',
  );
}

export async function setServerUrl(serverUrl: string): Promise<boolean> {
  if (!isPlatformInitialized()) {
    return false;
  }

  try {
    const data = await invokeConfig<string>('config:setServerUrl', { serverUrl });
    if (isConfiguredServerUrl(data)) {
      cachedServerUrl = serverUrl;
      return true;
    }
    return false;
  } catch {
    return false;
  }
}

export function clearServerUrlCache(): void {
  cachedServerUrl = null;
  cachedWebBaseUrl = null;
}

export async function getConfigFilePath(): Promise<string | null> {
  if (!isPlatformInitialized()) {
    return null;
  }

  try {
    return await invokeConfig<string>('config:getConfigPath');
  } catch {
    return null;
  }
}

export async function initializeServerConfig(): Promise<void> {
  if (!isPlatformInitialized()) {
    return;
  }

  try {
    const serverUrlData = await invokeConfig<string>('config:getServerUrl');
    if (isConfiguredServerUrl(serverUrlData)) {
      cacheElectronServerUrl(serverUrlData);
      const { clearApiConfigCache } = await import('./apiConfig');
      clearApiConfigCache();
    } else {
      cachedServerUrl = null;
    }

    const webBaseUrlData = await invokeConfig<string>('config:getWebBaseUrl');
    if (isConfiguredServerUrl(webBaseUrlData)) {
      cachedWebBaseUrl = webBaseUrlData;
    } else {
      cachedWebBaseUrl = null;
    }
  } catch {
    cachedServerUrl = null;
    cachedWebBaseUrl = null;
  }
}

export const AIMP_PROTOCOL_VERSION = '1.0.0';
export const AIMP_PROTOCOL_PIPE_NAME = '\\\\.\\pipe\\cherryplay-aimp-v1';
// The named-pipe transport is newline-delimited JSON (one UTF-8 JSON message per line).
export const AIMP_PROTOCOL_MESSAGE_DELIMITER = '\n';
export const AIMP_HEARTBEAT_INTERVAL_MS = 5000;
export const AIMP_HEARTBEAT_STALE_TIMEOUT_MS = 15000;
export const AIMP_MAX_MESSAGE_BYTES = 2 * 1024 * 1024;

export const AIMP_SUPPORTED_PROTOCOL_VERSIONS = [AIMP_PROTOCOL_VERSION] as const;

export type AimpSourceSelection = 'cherryPlayPlayer' | 'aimp';
export type AimpConnectionPhase = 'disconnected' | 'listening' | 'connected' | 'stale';
export type AimpPlaybackStatus = 'playing' | 'paused' | 'stopped';
export type AimpProtocolMessageType =
  | 'hello'
  | 'playlistSnapshot'
  | 'playbackSnapshot'
  | 'heartbeat'
  | 'goodbye';
export type AimpProtocolServerMessageType = 'helloAck';
export type AimpTrackIdentityStrategy = 'nativeTrackId' | 'filePath' | 'titleDuration';
export type AimpHelloAckErrorCode = 'unsupportedProtocolVersion' | 'rejected';
export type AimpDisconnectReasonCode =
  | 'transportClosed'
  | 'transportError'
  | 'clientGoodbye'
  | 'heartbeatTimeout'
  | 'handshakeRequired'
  | 'protocolVersionMismatch'
  | 'malformedPayload'
  | 'sourceDisabled'
  | 'connectionReplaced'
  | 'listenFailed'
  | 'unknown';
export type AimpGatingReasonCode =
  | 'sourceNotAimp'
  | 'unsupportedPlatform'
  | 'unsupportedArchitecture'
  | 'pluginManifestMissing'
  | 'pluginManifestInvalid'
  | 'pipeListenFailed';
export type AimpProtocolErrorCode =
  | 'invalidEnvelope'
  | 'invalidType'
  | 'unsupportedProtocolVersion'
  | 'invalidPayload'
  | 'missingHandshake'
  | 'payloadTooLarge'
  | 'invalidJson';

/** Log entry for AIMP plugin interaction (main → renderer console). */
export interface AimpLogEntry {
  timestamp: string;
  level: 'debug' | 'info' | 'warn';
  event: string;
  message: string;
  data?: unknown;
}

export interface AimpProtocolEnvelopeBase<TType extends string, TPayload> {
  type: TType;
  protocolVersion: string;
  sequence: number;
  messageId: string;
  sentAt: string;
  payload: TPayload;
}

export interface AimpHelloPayload {
  pluginName: string;
  pluginVersion: string;
  aimpVersion: string;
  architecture: 'x64';
  platform: 'win32';
  instanceId: string;
}

export interface AimpHelloAckPayload {
  accepted: boolean;
  serverProtocolVersion: string;
  errorCode?: AimpHelloAckErrorCode;
  detail?: string;
}

export interface AimpPlaylistTrackPayload {
  /** Optional canonical key from plugin; when present and non-empty, used as track identity */
  trackKey?: string;
  nativeTrackId?: string;
  filePath?: string;
  title: string;
  artist?: string;
  album?: string;
  durationMs?: number;
  positionInQueue: number;
  isActive?: boolean;
}

export interface AimpTrackReferencePayload {
  nativeTrackId?: string;
  filePath?: string;
  title?: string;
