import { notifyDemoUnavailable } from './notifyDemoUnavailable';

/** True when native FS / save dialogs must not run (browser web demo, capacitor stub, etc.). */
export function isNativeFileOperationBlocked(): boolean {
  return !getPlatformCapabilities().supportsNativeFileSystem;
}

/**
 * Blocks the operation in demo with a standard toast.
 * @returns true if the caller may proceed with Electron/native FS work.
 */
export function guardNativeFileOperation(): boolean {
  if (isNativeFileOperationBlocked()) {
    notifyDemoUnavailable();
    return false;
  }
  return true;
}

import { getPlatformCapabilities } from '../platform/platformCapabilities';

import { notifyDemoUnavailable } from './notifyDemoUnavailable';

/** True when local file playback must not run (web demo, capacitor stub, etc.). */
export function isLocalFilePlaybackBlocked(): boolean {
  return !getPlatformCapabilities().supportsLocalFilePlayback;
}

/**
 * Blocks playback when local file playback is unsupported.
 * @returns true if the caller may proceed with playback.
 */
export function guardPlaybackUnavailable(): boolean {
  if (isLocalFilePlaybackBlocked()) {
    notifyDemoUnavailable();
    return false;
  }
  return true;
}

import { projectService } from '../services/projectService';
import { useProjectStore } from '../stores/projectStore';
import { useSettingsStore } from '../stores/settingsStore';
import { useUIStore } from '../stores/uiStore';
export const DEMO_SAMPLE_PROJECT_URL = '/demo/sample.cherry';

function demoLoadErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
export const DEMO_SAMPLE_PROJECT_PATH = '/demo/sample.cherry';

export async function loadDemoProject(): Promise<void> {
  const response = await fetch(DEMO_SAMPLE_PROJECT_URL);
  if (!response.ok) {
    throw new Error(`Failed to fetch demo project (${response.status})`);
  }

  const rawData: unknown = await response.json();
  const projectData = await projectService.loadProjectFromData(rawData, DEMO_SAMPLE_PROJECT_PATH);

  useProjectStore.getState().loadProject({
    ...projectData,
    filePath: DEMO_SAMPLE_PROJECT_PATH,
    linkedParty: projectData.linkedParty ?? null,
  });

  useSettingsStore.getState().setLastOpenedPlaylist(DEMO_SAMPLE_PROJECT_PATH);
}

export async function loadDemoProjectSafe(): Promise<boolean> {
  try {
    await loadDemoProject();
    return true;
  } catch (error) {
    useUIStore.getState().addNotification({
      type: 'error',
      message: `Ошибка загрузки демо-проекта: ${demoLoadErrorMessage(error)}`,
    });
    return false;
  }
}

export function shouldAutoLoadDemoProject(): boolean {
  return import.meta.env.VITE_LOAD_DEMO_PROJECT === '1';
}

import { getPlatformUnavailableMessage } from '../platform/demoUnavailable';
import { useUIStore } from '../stores/uiStore';

export function notifyDemoUnavailable(): void {
  useUIStore.getState().addNotification({
    type: 'warning',
    message: getPlatformUnavailableMessage(),
  });
}

import { useCallback, useEffect, useSyncExternalStore } from 'react';

import {
  beginBrowserLoginFlow,
  completeBrowserLoginFlow,
  failBrowserLoginFlow,
  getBrowserLoginFlowState,
  resetBrowserLoginFlow,
  subscribeBrowserLoginFlow,
} from '../auth/browserLoginFlow';
import { getAppMode, getPlatform, isPlatformInitialized } from '../platform';
import { authService } from '../services/authService';
import { useAuthStore } from '../stores/authStore';

function cancelPendingAuthCallback(): void {
  if (!isPlatformInitialized() || getAppMode() !== 'electron') {
    return;
  }
  void getPlatform().invoke('auth:cancelCallback');
}

export function useBrowserLogin() {
  const flowState = useSyncExternalStore(
    subscribeBrowserLoginFlow,
    getBrowserLoginFlowState,
    getBrowserLoginFlowState,
  );
  const authenticated = useAuthStore((store) => store.isAuthenticated());

  useEffect(() => {
    if (authenticated && flowState.status === 'waiting') {
      completeBrowserLoginFlow();
    }
  }, [authenticated, flowState.status]);

  const startLogin = useCallback(async () => {
    cancelPendingAuthCallback();
    beginBrowserLoginFlow();
    try {
      await authService.startBrowserLogin();
    } catch (error) {
      const message =
        error instanceof Error && error.message.trim()
          ? error.message
          : 'Не удалось открыть браузер';
      failBrowserLoginFlow(message);
    }
  }, []);

  const retryLogin = useCallback(() => {
    resetBrowserLoginFlow();
    void startLogin();
  }, [startLogin]);

  const cancelWaiting = useCallback(() => {
    cancelPendingAuthCallback();
    resetBrowserLoginFlow();
  }, []);

  return {
    isWaiting: flowState.status === 'waiting',
    error: flowState.error,
    startLogin,
    retryLogin,
    cancelWaiting,
  };
}

