import { useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';

import { isProjectGroup, ProjectItem } from '@core/types/project';

import { DragDropCommand } from '../../modules/dragDrop/types';
import {
  AddItemsAtPositionsCommand,
  ItemPosition,
  RemoveItemsAtPositionsCommand,
} from '../commands';
import {
  useGlobalHistoryStore,
  createMoveDescription,
  createCopyDescription,
} from '../stores/globalHistoryStore';
import {
  findItemRecursive,
  findItemWithParent,
  removeItemsById,
  insertIntoGroup,
} from '../stores/projectStoreCore';
import { getProjectStore } from '../stores/projectStoreFactory';
import { cloneItems } from '../utils/historyCore';
import { logger } from '../utils/logger';

function cloneItemWithNewIds(item: ProjectItem): ProjectItem {
  if (isProjectGroup(item)) {
    return {
      ...item,
      id: uuidv4(),
      items: item.items.map(cloneItemWithNewIds),
    };
  }
  return { ...item, id: uuidv4() };
}

function insertItemsAtPosition(
  items: ProjectItem[],
  itemsToInsert: ProjectItem[],
  parentId: string | null,
  localIndex: number,
): ProjectItem[] {
  if (parentId === null) {
    const newItems = [...items];
    const safeIndex = Math.min(Math.max(0, localIndex), newItems.length);
    newItems.splice(safeIndex, 0, ...itemsToInsert);
    return newItems;
  } else {
    return insertIntoGroup(items, parentId, localIndex, itemsToInsert);
  }
}

export function useDragDropExecutor() {
  const executeMove = useCallback((command: DragDropCommand): boolean => {
    if (command.type !== 'move') {
      logger.error('executeMove: invalid command type', { type: command.type });
      return false;
    }

    try {
      const { itemIds, sourceWorkspaceId, targetWorkspaceId, targetParentId, targetIndex } =
        command;
      const isSameWorkspace = sourceWorkspaceId === targetWorkspaceId;

      const sourceStore = getProjectStore(sourceWorkspaceId);
      const targetStore = getProjectStore(targetWorkspaceId);

      if (!sourceStore || !targetStore) {
        logger.error('executeMove: stores not found', {
          sourceWorkspaceId,
          targetWorkspaceId,
        });
        return false;
      }

      const sourceState = sourceStore.getState();

      // Collect items and their positions for history
      const itemsToMove: ProjectItem[] = [];
      const sourcePositions: ItemPosition[] = [];
      for (const id of itemIds) {
        const positionInfo = findItemWithParent(sourceState.items, id);
        if (positionInfo) {
          itemsToMove.push(positionInfo.item);
          sourcePositions.push({
            item: positionInfo.item,
            parentPath: positionInfo.parentPath,
            index: positionInfo.indexInParent,
          });
        }
      }

      if (itemsToMove.length === 0) {
        logger.warn('executeMove: no items found to move', { itemIds });
        return false;
      }

      // For same-workspace: keep original IDs; for cross-workspace: generate new IDs
      const newItems: ProjectItem[] = isSameWorkspace
        ? cloneItems(itemsToMove)
        : itemsToMove.map(cloneItemWithNewIds);

      const sourceItemsBefore = [...sourceState.items];
      // For same-workspace, source and target state are the same
      const targetItemsBefore = isSameWorkspace
        ? sourceItemsBefore
        : [...targetStore.getState().items];

      try {
        sourceStore.setState({ _skipHistory: true });
        if (!isSameWorkspace) {
          targetStore.setState({ _skipHistory: true });
        }

        // Step 1: Remove from source
        const sourceNewItems = removeItemsById(sourceState.items, itemIds);
        sourceStore.setState({ items: sourceNewItems });

        // Step 2: Insert into target (for same-workspace, use the updated state)
        const currentTargetItems = isSameWorkspace
          ? sourceStore.getState().items
          : targetStore.getState().items;

        const targetNewItems = insertItemsAtPosition(
          currentTargetItems,
          newItems,
          targetParentId,
          targetIndex,
        );

        if (isSameWorkspace) {
          sourceStore.setState({ items: targetNewItems, _skipHistory: false });
        } else {
          targetStore.setState({ items: targetNewItems, _skipHistory: false });
        }

        // Build target positions for history command
        const targetParentPath = targetParentId ? [targetParentId] : [];
        const targetPositions: ItemPosition[] = newItems.map((item, i) => ({
          item,
          parentPath: targetParentPath,
          index: targetIndex + i,
        }));

        // Push composite command for undo/redo
        useGlobalHistoryStore.getState().pushCompositeCommand(
          [
            {
              workspaceId: sourceWorkspaceId,
              command: new RemoveItemsAtPositionsCommand(
                sourcePositions.map((p) => ({
                  item: cloneItems([p.item])[0],
                  parentPath: p.parentPath,
                  index: p.index,
                })),
              ),
            },
            {
              workspaceId: targetWorkspaceId,
              command: new AddItemsAtPositionsCommand(
                targetPositions.map((p) => ({
                  item: cloneItems([p.item])[0],
                  parentPath: p.parentPath,
                  index: p.index,
                })),
              ),
            },
          ],
          createMoveDescription(sourceWorkspaceId, targetWorkspaceId, itemsToMove.length),
        );

        sourceStore.getState().markAsDirty();
        if (!isSameWorkspace) {
          targetStore.getState().markAsDirty();
        }

        return true;
      } catch (error) {
        logger.error('executeMove: error during transaction, rolling back', error);
        try {
          sourceStore.setState({ items: sourceItemsBefore, _skipHistory: false });
          if (!isSameWorkspace) {
            targetStore.setState({ items: targetItemsBefore, _skipHistory: false });
          }
        } catch (rollbackError) {
          logger.error('executeMove: rollback failed', rollbackError);
        }
        return false;
      }
    } catch (error) {
      logger.error('executeMove: unexpected error', error);
      return false;
    }
  }, []);

  const executeCopy = useCallback((command: DragDropCommand): boolean => {
    if (command.type !== 'copy') {
      logger.error('executeCopy: invalid command type', { type: command.type });
      return false;
    }

    try {
      const { itemIds, sourceWorkspaceId, targetWorkspaceId, targetParentId, targetIndex } =
        command;

      const sourceStore = getProjectStore(sourceWorkspaceId);
      const targetStore = getProjectStore(targetWorkspaceId);

      if (!sourceStore || !targetStore) {
        logger.error('executeCopy: stores not found', {
          sourceWorkspaceId,
          targetWorkspaceId,
        });
        return false;
      }

      const sourceState = sourceStore.getState();

      const itemsToCopy: ProjectItem[] = [];
      for (const id of itemIds) {
        const item = findItemRecursive(sourceState.items, id);
        if (item) {
          itemsToCopy.push(item);
        }
      }

      if (itemsToCopy.length === 0) {
        logger.warn('executeCopy: no items found to copy', { itemIds });
        return false;
      }

      // Copy always generates new IDs
      const newItems: ProjectItem[] = itemsToCopy.map(cloneItemWithNewIds);

      const targetState = targetStore.getState();

      targetStore.setState({ _skipHistory: true });

      const targetNewItems = insertItemsAtPosition(
        targetState.items,
        newItems,
        targetParentId,
        targetIndex,
      );
      targetStore.setState({ items: targetNewItems, _skipHistory: false });

      // Build target positions for history command
      const targetParentPath = targetParentId ? [targetParentId] : [];
      const targetPositions: ItemPosition[] = newItems.map((item, i) => ({
        item,
        parentPath: targetParentPath,
        index: targetIndex + i,
      }));

      useGlobalHistoryStore.getState().pushCommand(
        targetWorkspaceId,
        new AddItemsAtPositionsCommand(
          targetPositions.map((p) => ({
            item: cloneItems([p.item])[0],
            parentPath: p.parentPath,
            index: p.index,
          })),
        ),
        createCopyDescription(sourceWorkspaceId, targetWorkspaceId, itemsToCopy.length),
      );

      targetStore.getState().markAsDirty();

      return true;
    } catch (error) {
      logger.error('executeCopy: unexpected error', error);
      return false;
    }
  }, []);

  return { executeMove, executeCopy };
}

import { useCallback, useRef } from 'react';

/**
 * Options for useItemSelection hook
 */
export interface UseItemSelectionOptions<T extends { id: string }> {
  /** Array of items that can be selected */
  items: T[];
  /** Currently selected item IDs */
  selectedIds: Set<string>;
  /** Callback when selection changes */
  onSelectionChange: (ids: Set<string>) => void;
}

/**
 * Return type for useItemSelection hook
 */
export interface UseItemSelectionReturn {
  /** Handle click on an item with modifier key support */
  handleClick: (id: string, event?: React.MouseEvent) => void;
  /** Select all items */
  selectAll: () => void;
  /** Deselect all items */
  deselectAll: () => void;
  /** Select a range of items between two IDs */
  selectRange: (fromId: string, toId: string) => void;
  /** Toggle selection of a single item */
  toggleSelection: (id: string) => void;
  /** Check if an item is selected */
  isSelected: (id: string) => boolean;
}

/**
 * useItemSelection - Unified selection logic for list items
 *
 * Provides consistent selection behavior across all list views:
 * - Single click: Toggle selection (or replace selection without modifiers)
 * - Ctrl/Cmd + click: Add/remove from selection
 * - Shift + click: Select range from last selected item
 *
 * @example
 * ```tsx
 * const { handleClick, selectAll, deselectAll } = useItemSelection({
 *   items: tracks,
 *   selectedIds: selectedTrackIds,
 *   onSelectionChange: setSelectedTrackIds,
 * });
 *
 * // In component
 * <ListRow onClick={(e) => handleClick(track.id, e)} />
 * ```
 */
export function useItemSelection<T extends { id: string }>({
  items,
  selectedIds,
  onSelectionChange,
}: UseItemSelectionOptions<T>): UseItemSelectionReturn {
  // Track the last selected item for range selection
  const lastSelectedRef = useRef<string | null>(null);

  /**
   * Toggle selection of a single item
   */
  const toggleSelection = useCallback(
    (id: string) => {
      const newSelection = new Set(selectedIds);
      if (newSelection.has(id)) {
        newSelection.delete(id);
      } else {
        newSelection.add(id);
      }
      lastSelectedRef.current = id;
      onSelectionChange(newSelection);
    },
    [selectedIds, onSelectionChange],
  );

  /**
   * Select a range of items between two IDs
   */
  const selectRange = useCallback(
    (fromId: string, toId: string) => {
      const fromIndex = items.findIndex((item) => item.id === fromId);
      const toIndex = items.findIndex((item) => item.id === toId);

      if (fromIndex === -1 || toIndex === -1) {
        // If either item not found, just toggle the target
        toggleSelection(toId);
        return;
      }

      const startIndex = Math.min(fromIndex, toIndex);
      const endIndex = Math.max(fromIndex, toIndex);

      const newSelection = new Set(selectedIds);
      for (let i = startIndex; i <= endIndex; i++) {
        newSelection.add(items[i].id);
      }

      lastSelectedRef.current = toId;
      onSelectionChange(newSelection);
    },
    [items, selectedIds, onSelectionChange, toggleSelection],
  );

  /**
   * Handle click with modifier key support
   */
  const handleClick = useCallback(
    (id: string, event?: React.MouseEvent) => {
      const isCtrlOrCmd = event?.ctrlKey || event?.metaKey;
      const isShift = event?.shiftKey;

      if (isCtrlOrCmd) {
        // Ctrl/Cmd + click: Add/remove from selection
        toggleSelection(id);
      } else if (isShift && lastSelectedRef.current && selectedIds.size > 0) {
        // Shift + click: Select range from last selected
        selectRange(lastSelectedRef.current, id);
      } else {
        // Regular click: Toggle selection
        toggleSelection(id);
      }
    },
    [selectedIds, selectRange, toggleSelection],
  );

  /**
   * Select all items
   */
  const selectAll = useCallback(() => {
    const allIds = new Set(items.map((item) => item.id));
    if (items.length > 0) {
      lastSelectedRef.current = items[items.length - 1].id;
    }
    onSelectionChange(allIds);
  }, [items, onSelectionChange]);

  /**
   * Deselect all items
   */
  const deselectAll = useCallback(() => {
    lastSelectedRef.current = null;
    onSelectionChange(new Set());
  }, [onSelectionChange]);

  /**
   * Check if an item is selected
   */
  const isSelected = useCallback(
    (id: string) => {
      return selectedIds.has(id);
    },
    [selectedIds],
  );

  return {
    handleClick,
    selectAll,
    deselectAll,
    selectRange,
    toggleSelection,
    isSelected,
  };
}

import { useCallback, useEffect, useRef } from 'react';

import { isOverlayKeyboardTarget, shouldIgnoreEnterForPrimary } from '@shared/utils/modalKeyboard';

export interface UseModalKeyboardOptions {
  enabled: boolean;
  onCancel: () => void;
  onPrimary?: () => void;
  primaryDisabled?: boolean;
}

const modalKeyboardStack: symbol[] = [];

function isModalOverlayElement(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) {
    return false;
  }

  return target.classList.contains('modal-overlay');
}

export function useModalKeyboard({
  enabled,
  onCancel,
  onPrimary,
  primaryDisabled = false,
}: UseModalKeyboardOptions) {
  const modalIdRef = useRef<symbol>(Symbol('modalKeyboard'));
  const onCancelRef = useRef(onCancel);
  const onPrimaryRef = useRef(onPrimary);

  useEffect(() => {
    onCancelRef.current = onCancel;
  }, [onCancel]);

  useEffect(() => {
    onPrimaryRef.current = onPrimary;
  }, [onPrimary]);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    const handleDocumentKeyDown = (event: KeyboardEvent) => {
      const currentTop = modalKeyboardStack[modalKeyboardStack.length - 1];
      if (currentTop !== modalIdRef.current) {
        return;
      }

      if (event.key === 'Escape') {
        if (event.defaultPrevented) {
          return;
        }

        event.preventDefault();
        onCancelRef.current();
        return;
      }

      if (
        event.key !== 'Enter' ||
        event.shiftKey ||
        event.ctrlKey ||
        event.metaKey ||
        event.altKey
      ) {
        return;
      }

      const primary = onPrimaryRef.current;
      if (!primary || primaryDisabled) {
        return;
      }

      if (event.defaultPrevented) {
        return;
      }

      if (isModalOverlayElement(event.target) || shouldIgnoreEnterForPrimary(event.target)) {
        return;
      }

      event.preventDefault();
      primary();
    };

    document.addEventListener('keydown', handleDocumentKeyDown);
    return () => {
      document.removeEventListener('keydown', handleDocumentKeyDown);
    };
  }, [enabled, primaryDisabled]);

  useEffect(() => {
    if (!enabled) {
      return;
    }

    const modalId = modalIdRef.current;
    modalKeyboardStack.push(modalId);

    return () => {
      const index = modalKeyboardStack.lastIndexOf(modalId);
      if (index !== -1) {
        modalKeyboardStack.splice(index, 1);
      }
    };
  }, [enabled]);

  const handleOverlayKeyDown = useCallback((event: React.KeyboardEvent<HTMLElement>) => {
    if (!isOverlayKeyboardTarget(event)) {
      return;
    }

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
    }
  }, []);

  return { handleOverlayKeyDown };
}

import { useMemo } from 'react';

import {
  getPlatformCapabilities,
  type PlatformCapabilities,
} from '../platform/platformCapabilities';

/** Stable snapshot of platform capabilities for React components (mode does not change at runtime). */
export function usePlatformCapabilities(): PlatformCapabilities {
  return useMemo(() => getPlatformCapabilities(), []);
}

