import { useCallback, useMemo } from 'react';

import { Track } from '@core/types/track';
import { WorkspaceId } from '@core/types/workspace';

import { isLocalFilePlaybackBlocked } from '../demo/guardPlayback';
import { DEMO_UNAVAILABLE_MESSAGE } from '../platform/demoUnavailable';
import { useLayoutStore, useSettingsStore } from '../stores';
import { useDemoPlayerStore, PlayerStatus } from '../stores/demoPlayerStore';
import { collectWorkspaceTypes } from '../utils/layoutWorkspaceOperations';
import { logger } from '../utils/logger';

export interface UsePlaybackPreviewOptions {
  workspaceId: WorkspaceId;
}

export interface UsePlaybackPreviewReturn {
  activeTrackId: string | undefined;
  playerStatus: PlayerStatus;
  startPlayback: (track: Track) => Promise<void>;
  pausePlayback: () => void;
  isActive: (trackId: string) => boolean;
  isPlaying: (trackId: string) => boolean;
}

export function usePlaybackPreview({
  workspaceId,
}: UsePlaybackPreviewOptions): UsePlaybackPreviewReturn {
  const {
    currentTrack,
    status: playerStatus,
    loadTrack,
    setActiveTrack,
    play,
    pause,
  } = useDemoPlayerStore();
  const layout = useLayoutStore((state) => state.layout);
  const setDemoPlayerFloatingOpen = useSettingsStore((state) => state.setDemoPlayerFloatingOpen);
  const hasDemoPlayerWorkspace = useMemo(
    () => collectWorkspaceTypes(layout.rootZone).has('demo-player'),
    [layout],
  );

  const activeTrackId = currentTrack?.id;

  const startPlayback = useCallback(
    async (track: Track) => {
      const shouldOpenFloatingOnAttempt = !hasDemoPlayerWorkspace;
      try {
        if (shouldOpenFloatingOnAttempt) {
          setDemoPlayerFloatingOpen(true);
        }

        if (isLocalFilePlaybackBlocked()) {
          setActiveTrack(track, workspaceId);
          useDemoPlayerStore.setState({
            error: DEMO_UNAVAILABLE_MESSAGE,
            status: 'error',
          });
          return;
        }

        const isSameTrack = activeTrackId === track.id;
        if (!isSameTrack || playerStatus === 'ended') {
          await loadTrack(track, workspaceId);
        }

        const { isDisabled } = useDemoPlayerStore.getState();
        if (isDisabled) {
          useDemoPlayerStore.setState({
            error: 'Воспроизведение невозможно: используется то же устройство, что и плеер',
            status: 'error',
          });
          return;
        }

        await play();
      } catch (error) {
        if (shouldOpenFloatingOnAttempt) {
          const { currentTrack: latestTrack, status: latestStatus } = useDemoPlayerStore.getState();
          const hasActiveDemoSession =
            latestTrack !== null || latestStatus === 'playing' || latestStatus === 'loading';

          if (!hasActiveDemoSession) {
            setDemoPlayerFloatingOpen(false);
          }
        }
        logger.error('Failed to start track playback', error);
      }
    },
    [
      activeTrackId,
      playerStatus,
      loadTrack,
      play,
      setActiveTrack,
      setDemoPlayerFloatingOpen,
      hasDemoPlayerWorkspace,
      workspaceId,
    ],
  );

  const pausePlayback = useCallback(() => {
    pause();
  }, [pause]);

  const isActive = useCallback(
    (trackId: string): boolean => {
      return activeTrackId === trackId;
    },
    [activeTrackId],
  );

  const isPlaying = useCallback(
    (trackId: string): boolean => {
      return activeTrackId === trackId && playerStatus === 'playing';
    },
    [activeTrackId, playerStatus],
  );

  return {
    activeTrackId,
    playerStatus,
    startPlayback,
    pausePlayback,
    isActive,
    isPlaying,
  };
}

import { useCallback, useState } from 'react';

export interface UsePlaybackTimelineOptions {
  readonly position: number;
  readonly duration: number;
  readonly disabled: boolean;
  readonly seek: (positionSeconds: number) => void;
  /** Called after the user commits a seek (e.g. resume when ended). */
  readonly onSeekCommitted?: (positionSeconds: number) => void;
}

/**
 * Controlled range input for playback timelines.
 * Keeps a local scrub value while dragging/clicking so frequent engine
 * position updates do not reset the thumb before seek commits.
 */
export function usePlaybackTimeline(options: UsePlaybackTimelineOptions) {
  const { position, duration, disabled, seek, onSeekCommitted } = options;
  const [isScrubbing, setIsScrubbing] = useState(false);
  const [scrubValue, setScrubValue] = useState(0);

  const safePosition = Number.isFinite(position) ? Math.max(0, position) : 0;
  const resolvedDuration = Number.isFinite(duration) && duration > 0 ? duration : 1;
  const displayPosition = isScrubbing ? scrubValue : safePosition;

  const beginScrub = useCallback(() => {
    if (disabled) {
      return;
    }
    setIsScrubbing(true);
    setScrubValue(safePosition);
  }, [disabled, safePosition]);

  const handleInput = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled) {
        return;
      }
      const value = parseFloat(event.target.value);
      if (!Number.isFinite(value)) {
        return;
      }
      setScrubValue(value);
      seek(value);
    },
    [disabled, seek],
  );

  const handleChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled) {
        setIsScrubbing(false);
        return;
      }
      const value = parseFloat(event.target.value);
      if (Number.isFinite(value)) {
        seek(value);
        onSeekCommitted?.(value);
      }
      setIsScrubbing(false);
    },
    [disabled, onSeekCommitted, seek],
  );

  return {
    displayPosition,
    resolvedDuration,
    beginScrub,
    handleInput,
    handleChange,
  };
}

import { useCallback, useRef } from 'react';

/**
 * Options for useSelectionWithModifiers hook
 */
export interface UseSelectionWithModifiersOptions {
  /** Toggle selection of a single item */
  toggleSelection: (id: string) => void;
  /** Select a range of items between two IDs */
  selectRange: (fromId: string, toId: string) => void;
}

/**
 * Return type for useSelectionWithModifiers hook
 */
export interface UseSelectionWithModifiersReturn {
  /** Handle click/select with modifier key support (Ctrl, Shift) */
  handleToggleSelect: (id: string, event?: React.MouseEvent) => void;
  /** Reference to the last selected item ID (for range selection) */
  lastSelectedIdRef: React.MutableRefObject<string | null>;
}

/**
 * useSelectionWithModifiers - Unified selection handler with modifier key support
 *
 * Provides consistent selection behavior with modifier keys across all list views:
 * - Regular click: Toggle selection
 * - Ctrl/Cmd + click: Toggle selection (same as regular)
 * - Shift + click: Select range from last selected item
 *
 * This hook complements useItemSelection by providing a ready-to-use handler
 * that tracks the last selected item for range selection.
 *
 * @example
 * ```tsx
 * const { handleToggleSelect } = useSelectionWithModifiers({
 *   toggleSelection: toggleItemSelection,
 *   selectRange: selectRange,
 * });
 *
 * // In component
 * <ProjectItemRow
 *   onToggleSelect={handleToggleSelect}
 *   ...
 * />
 * ```
 */
export function useSelectionWithModifiers({
  toggleSelection,
  selectRange,
}: UseSelectionWithModifiersOptions): UseSelectionWithModifiersReturn {
  // Track the last selected item for Shift+click range selection
  const lastSelectedIdRef = useRef<string | null>(null);

  /**
   * Handle selection with modifier key support
   */
  const handleToggleSelect = useCallback(
    (id: string, event?: React.MouseEvent) => {
      if (event?.ctrlKey || event?.metaKey) {
        // Ctrl/Cmd + click: Toggle selection
        toggleSelection(id);
      } else if (event?.shiftKey && lastSelectedIdRef.current) {
        // Shift + click: Select range from last selected
        selectRange(lastSelectedIdRef.current, id);
      } else {
        // Regular click: Toggle selection
        toggleSelection(id);
      }
      // Always update last selected
      lastSelectedIdRef.current = id;
    },
    [toggleSelection, selectRange],
  );

  return {
    handleToggleSelect,
    lastSelectedIdRef,
  };
}

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef } from 'react';

import { Track } from '../../core/types/track';
import { logger } from '../utils/logger';

const DEFAULT_BATCH_SIZE = 5;

export interface UseAudioPathDurationsOptions {
  paths: string[];
  requestDuration: (path: string) => Promise<number>;
  onResolved: (path: string, duration: number) => void;
  onError?: (path: string, error: Error) => void;
  enabled?: boolean;
  shouldApply?: (path: string) => boolean;
  batchSize?: number;
}

export function useAudioPathDurations({
  paths,
  requestDuration,
  onResolved,
  onError,
  enabled = true,
  shouldApply,
  batchSize = DEFAULT_BATCH_SIZE,
}: UseAudioPathDurationsOptions) {
  const abortControllerRef = useRef<AbortController | null>(null);
  const pathsSnapshotRef = useRef(paths);

  useLayoutEffect(() => {
    pathsSnapshotRef.current = paths;
  });

  const loadPaths = useCallback(
    async (pathList: string[], externalSignal?: AbortSignal) => {
      const unique = [...new Set(pathList)];
      for (let i = 0; i < unique.length; i += batchSize) {
        const batch = unique.slice(i, i + batchSize);
        await Promise.all(
          batch.map(async (path) => {
            try {
              const duration = await requestDuration(path);
              if (externalSignal?.aborted) return;
              if (shouldApply && !shouldApply(path)) return;
              onResolved(path, duration);
            } catch (error) {
              if (!externalSignal?.aborted) {
                const err = error instanceof Error ? error : new Error(String(error));
                logger.error(`Failed to load duration for ${path}`, err);
                onError?.(path, err);
              }
            }
          }),
        );
        if (externalSignal?.aborted) {
          break;
        }
      }
    },
    [batchSize, onError, onResolved, requestDuration, shouldApply],
  );

  const pathsKey = paths.join('\0');

  useEffect(() => {
    if (!enabled) {
      return;
    }
    const list = pathsSnapshotRef.current;
    if (list.length === 0) {
      return;
    }
    const controller = new AbortController();
    abortControllerRef.current?.abort();
    abortControllerRef.current = controller;
    void loadPaths(list, controller.signal);
    return () => {
      controller.abort();
    };
  }, [enabled, loadPaths, pathsKey]);

  useEffect(() => {
    return () => {
      abortControllerRef.current?.abort();
    };
  }, []);

  return { loadPaths };
}

interface UseTrackDurationOptions {
  tracks: Track[];
  isAudioFile: (path: string) => boolean;
  requestDuration: (path: string) => Promise<number>;
  resolveTrackById?: (id: string) => Track | undefined;
  onDurationResolved: (trackId: string, duration: number) => void;
  onError?: (path: string, error: Error) => void;
  batchSize?: number;
  /** When false, skips IPC duration requests (e.g. web demo). */
  enabled?: boolean;
}

export function useTrackDuration({
  tracks,
  isAudioFile,
  requestDuration,
  resolveTrackById,
  onDurationResolved,
  onError,
  batchSize = DEFAULT_BATCH_SIZE,
  enabled = true,
}: UseTrackDurationOptions) {
  const tracksRef = useRef(tracks);
  const resolveRef = useRef(resolveTrackById);

  useLayoutEffect(() => {
    tracksRef.current = tracks;
    resolveRef.current = resolveTrackById;
  });

  const paths = useMemo(() => {
    const seen = new Set<string>();
    const out: string[] = [];
    for (const t of tracks) {
      if (t.duration != null || !isAudioFile(t.path)) continue;
      if (seen.has(t.path)) continue;
      seen.add(t.path);
      out.push(t.path);
    }
    return out;
  }, [tracks, isAudioFile]);

  const shouldApply = useCallback((path: string) => {
    return tracksRef.current.some((t) => {
      if (t.path !== path || t.duration != null) return false;
      if (resolveRef.current) {
        const cur = resolveRef.current(t.id);
        return !!cur && cur.duration == null;
      }
      return true;
    });
  }, []);

  const onResolved = useCallback(
    (path: string, duration: number) => {
      for (const t of tracksRef.current) {
        if (t.path !== path || t.duration != null) continue;
        if (resolveRef.current) {
          const cur = resolveRef.current(t.id);
          if (!cur || cur.duration != null) continue;
        }
        onDurationResolved(t.id, duration);
      }
    },
    [onDurationResolved],
  );

  const { loadPaths } = useAudioPathDurations({
    paths,
    requestDuration,
    onResolved,
    onError,
    shouldApply,
    batchSize,
    enabled,
  });

  const loadDurationsForTracks = useCallback(
    (targets: Array<{ id: string; path: string }>, externalSignal?: AbortSignal) => {
      const pathList = targets.map((t) => t.path);
      void loadPaths(pathList, externalSignal);
    },
    [loadPaths],
  );

  return {
    loadDurationsForTracks,
  };
}

import { useEffect } from 'react';

import { useSettingsStore } from '../stores/settingsStore';
import { isTrackItemSizePreset, type TrackItemSizePreset } from '../types/trackItemSize';

const DEFAULT_PRESET: TrackItemSizePreset = 'medium';

const SIZE_PRESETS: Record<TrackItemSizePreset, { padding: number; margin: number }> = {
  tiny: { padding: 1, margin: 0 },
  small: { padding: 5, margin: 1 },
  medium: { padding: 8, margin: 2 },
  large: { padding: 12, margin: 4 },
};

/**
 * Hook to initialize and update CSS variables for track item sizes
 * based on the selected preset from settings
 */
export function useTrackItemSize(): void {
  const trackItemSizePreset = useSettingsStore((state) => state.trackItemSizePreset);

  useEffect(() => {
    const resolvedPreset = isTrackItemSizePreset(trackItemSizePreset)
      ? trackItemSizePreset
      : DEFAULT_PRESET;
    const preset = SIZE_PRESETS[resolvedPreset];
    document.documentElement.style.setProperty('--track-item-padding', `${preset.padding}px`);
    document.documentElement.style.setProperty('--track-item-margin', `${preset.margin}px`);
    document.documentElement.setAttribute('data-track-item-size', resolvedPreset);
  }, [trackItemSizePreset]);
}

