import type {
  AuthService as IAuthService,
  ConsentInput,
  OrganizerDto,
  AuthExchangeRequest,
  AuthExchangeResponse,
  ForgotPasswordResponse,
} from '@cherryplay/components';
import { AuthHttpError, FORGOT_PASSWORD_GENERIC_SUCCESS } from '@cherryplay/components';

import { getServerUrl, getWebBaseUrl } from '../config/serverConfig';
import {
  applyDemoAuthSession,
  DEMO_ACCESS_TOKEN,
  getDemoOrganizerDto,
} from '../demo/demoAuthFixture';
import { isDemoAuthMode } from '../demo/guardDemoAuth';
import { notifyDemoUnavailable } from '../demo/notifyDemoUnavailable';
import { getPlatform, isPlatformInitialized } from '../platform';
import { useAuthStore } from '../stores/authStore';
import { apiFetch } from '../utils/apiFetch';
import { handleAuthError, SESSION_EXPIRED_USER_MESSAGE } from '../utils/authErrorHandler';
import { isSessionAuthError } from '../utils/apiErrorHandler';
import { clearAuthSession, setAuthSessionToken } from '../utils/authSession';
import { isTokenExpired } from '../utils/tokenUtils';

export type { OrganizerDto, AuthExchangeRequest, AuthExchangeResponse };

async function readResponseErrorMessage(response: Response): Promise<string> {
  try {
    const text = await response.text();
    if (!text) {
      return '';
    }
    try {
      const json = JSON.parse(text) as {
        message?: unknown;
        detail?: unknown;
        title?: unknown;
      };
      if (typeof json.message === 'string' && json.message.trim()) {
        return json.message;
      }
      if (typeof json.detail === 'string' && json.detail.trim()) {
        return json.detail;
      }
      if (typeof json.title === 'string' && json.title.trim()) {
        return json.title;
      }
    } catch {
      return text;
    }
    return text;
  } catch {
    return '';
  }
}

async function throwAuthHttpError(response: Response): Promise<never> {
  const message = await readResponseErrorMessage(response);
  throw new AuthHttpError(response.status, message);
}

export function buildDesktopAuthReturnTo(
  isDev: boolean,
  origin: string | undefined,
): string {
  if (isDev && origin) {
    return `${origin}/auth/callback`;
  }
  return 'cherryplaylist://auth';
}

class AuthService implements IAuthService {
  private async getBaseUrl(): Promise<string> {
    return getServerUrl();
  }

  async startBrowserLogin(): Promise<void> {
    if (isDemoAuthMode()) {
      applyDemoAuthSession();
      console.info('[AuthService] Demo: browser login skipped, using demo organizer');
      return;
    }

    const webBaseUrl = await getWebBaseUrl();
    const returnTo = buildDesktopAuthReturnTo(
      import.meta.env.DEV,
      typeof window !== 'undefined' ? window.location.origin : undefined,
    );
    const loginUrl = `${webBaseUrl.replace(/\/$/, '')}/login?client=desktop&return_to=${encodeURIComponent(returnTo)}`;

    console.log('[AuthService] Starting browser login:', { webBaseUrl, loginUrl });

    if (isPlatformInitialized()) {
      const result = (await getPlatform().invoke('auth:openExternal', { url: loginUrl })) as
        | { success: true }
        | { success: false; error: string };

      if (!result.success) {
        console.error('[AuthService] Failed to open browser:', result.error);
        throw new Error(result.error || 'Failed to open browser');
      }

      console.log('[AuthService] Browser opened successfully, waiting for auth callback...');
      console.log(
        '[AuthService] Expected callback:',
        import.meta.env.DEV
          ? 'cherryplaylist://auth?code=... or http://localhost:5173/auth/callback?code=...'
          : 'cherryplaylist://auth?code=...',
      );
      return;
    }

    console.warn('[AuthService] Platform not available, using window.open fallback');
    window.open(loginUrl, '_blank');
  }

  async exchangeDesktopCode(code: string): Promise<string> {
    if (isDemoAuthMode()) {
      applyDemoAuthSession();
      return DEMO_ACCESS_TOKEN;
    }
    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/auth/desktop/exchange`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        code,
      }),
      cache: 'no-cache',
    });

    if (!response.ok) {
      await throwAuthHttpError(response);
    }

    const data = (await response.json()) as AuthExchangeResponse;
    return data.accessToken;
  }

  async startOAuthFlow(provider: 'telegram' | 'vk' | 'mailru'): Promise<void> {
    if (isDemoAuthMode()) {
      applyDemoAuthSession();
      console.info('[AuthService] Demo: OAuth skipped, using demo organizer', { provider });
      return;
    }
    const baseUrl = await this.getBaseUrl();

    const isDev = import.meta.env.DEV;
    const redirectUriParam = isDev
      ? `?redirectUri=${encodeURIComponent(`${baseUrl}/auth/${provider}/callback`)}`
      : '';

    const authUrl = `${baseUrl}/auth/${provider}/start${redirectUriParam}`;

    console.log('[AuthService] Starting OAuth flow:', {
      provider,
      baseUrl,
      authUrl,
      isDev,
    });

    if (isPlatformInitialized()) {
      const result = (await getPlatform().invoke('auth:openExternal', { url: authUrl })) as
        | { success: true }
        | { success: false; error: string };

      if (!result.success) {
        console.error('[AuthService] Failed to open browser:', result.error);
        throw new Error(result.error || 'Failed to open browser');
      }

      console.log('[AuthService] Browser opened successfully, waiting for OAuth callback...');
      console.log('[AuthService] Expected callback URL: cherryplaylist://auth');
      return;
    }

    console.warn('[AuthService] Platform not available, using window.open fallback');
    window.open(authUrl, '_blank');
  }

  async exchangeCode(code: string, provider: string, deviceId?: string): Promise<string> {
    if (isDemoAuthMode()) {
      applyDemoAuthSession();
      return DEMO_ACCESS_TOKEN;
    }
    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/auth/exchange`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        code,
        provider,
        deviceId,
      } as AuthExchangeRequest),
      cache: 'no-cache',
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Failed to exchange code: ${errorText}`);
    }

    const data = (await response.json()) as AuthExchangeResponse;
    return data.accessToken;
  }

  async getCurrentOrganizer(): Promise<OrganizerDto> {
    if (isDemoAuthMode()) {
      return getDemoOrganizerDto();
    }
    const baseUrl = await this.getBaseUrl();
    const token = useAuthStore.getState().accessToken;

    if (!token) {
      throw new Error('No access token available');
    }

    if (isTokenExpired(token)) {
      handleAuthError('Authentication token has expired');
      throw new Error(SESSION_EXPIRED_USER_MESSAGE);
    }

    try {
      const sessionCheckResponse = await apiFetch(`${baseUrl}/api/organizer/session/check`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        cache: 'no-cache',
      });

      if (!sessionCheckResponse.ok) {
        if (isSessionAuthError(sessionCheckResponse.status)) {
          handleAuthError(`Session check HTTP ${sessionCheckResponse.status}`);
          throw new Error(SESSION_EXPIRED_USER_MESSAGE);
        }
        throw new Error('Session check failed');
      }
    } catch (error) {
      if (error instanceof Error && error.message === SESSION_EXPIRED_USER_MESSAGE) {
        throw error;
      }
      throw new Error('Session check failed');
    }

    const response = await apiFetch(`${baseUrl}/api/organizer/me`, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      cache: 'no-cache',
    });

    if (!response.ok) {
      if (isSessionAuthError(response.status)) {
        handleAuthError(`Organizer me HTTP ${response.status}`);
        throw new Error(SESSION_EXPIRED_USER_MESSAGE);
      }
      const errorText = await response.text();
      throw new Error(`Failed to get organizer: ${errorText}`);
    }

    return response.json();
  }

  async login(email: string, password: string): Promise<string> {
    if (isDemoAuthMode()) {
      applyDemoAuthSession();
      return DEMO_ACCESS_TOKEN;
    }
    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/auth/login`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email,
        password,
      }),
      cache: 'no-cache',
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Failed to login: ${errorText}`);
    }

    const data = (await response.json()) as AuthExchangeResponse;
    const token = data.accessToken;

    setAuthSessionToken(token);

    try {
      const organizer = await this.getCurrentOrganizer();
      useAuthStore.getState().setOrganizer({ id: organizer.id, name: organizer.name });
    } catch (err) {
      console.warn('Failed to load organizer info after login:', err);
    }

    return token;
  }

  async register(
    email: string,
    password: string,
    name: string,
    _consents: ConsentInput[],
  ): Promise<string> {
    if (isDemoAuthMode()) {
      applyDemoAuthSession();
      useAuthStore
        .getState()
        .setOrganizer({ id: getDemoOrganizerDto().id, name: name.trim() || 'Demo Organizer' });
      return DEMO_ACCESS_TOKEN;
    }
    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/auth/register`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        email,
        password,
        name,
      }),
      cache: 'no-cache',
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Failed to register: ${errorText}`);
    }

    const data = (await response.json()) as AuthExchangeResponse;
    const token = data.accessToken;

    setAuthSessionToken(token);

    try {
      const organizer = await this.getCurrentOrganizer();
      useAuthStore.getState().setOrganizer({ id: organizer.id, name: organizer.name });
    } catch (err) {
      console.warn('Failed to load organizer info after register:', err);
    }

    return token;
  }

  async forgotPassword(email: string): Promise<ForgotPasswordResponse> {
    if (isDemoAuthMode()) {
      return { message: FORGOT_PASSWORD_GENERIC_SUCCESS };
    }

    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/auth/forgot-password`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email }),
      cache: 'no-cache',
    });

    if (!response.ok) {
      await throwAuthHttpError(response);
    }

    if (response.status === 204) {
      return { message: FORGOT_PASSWORD_GENERIC_SUCCESS };
    }

    try {
      const data = (await response.json()) as ForgotPasswordResponse;
      return {
        message:
          typeof data.message === 'string' && data.message.trim()
            ? data.message
            : FORGOT_PASSWORD_GENERIC_SUCCESS,
      };
    } catch {
      return { message: FORGOT_PASSWORD_GENERIC_SUCCESS };
    }
  }

  async changePassword(oldPassword: string, newPassword: string): Promise<void> {
    if (isDemoAuthMode()) {
      notifyDemoUnavailable();
      throw new AuthHttpError(503, 'Смена пароля недоступна в демо-режиме');
    }

    const baseUrl = await this.getBaseUrl();
    const token = useAuthStore.getState().accessToken;

    if (!token) {
      throw new AuthHttpError(401, 'Требуется авторизация');
    }

    const response = await apiFetch(`${baseUrl}/auth/change-password`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        oldPassword,
        newPassword,
      }),
      cache: 'no-cache',
    });

    if (!response.ok) {
      await throwAuthHttpError(response);
    }
  }

  async logout(): Promise<void> {
    if (isDemoAuthMode()) {
      notifyDemoUnavailable();
      applyDemoAuthSession();
      return;
    }

    const baseUrl = await this.getBaseUrl();
    const token = useAuthStore.getState().accessToken;

    if (token) {
      try {
        await apiFetch(`${baseUrl}/auth/logout`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
          },
          cache: 'no-cache',
        });
      } catch (error) {
        console.error('Error during logout:', error);
      }
    }

    clearAuthSession();
  }
}

export const authService = new AuthService();

import { Track } from '@core/types/track';

import { guardNativeFileOperation } from '../demo/guardNativeFileOperation';

import { exportService } from './exportService';
import { ipcService } from './ipcService';
import { playlistService, type PlaylistData } from './playlistService';

export interface ExportCollectionJsonParams {
  name: string;
  tracks: Track[];
}

export interface CopyCollectionTracksParams {
  tracks: Track[];
  folderName: string;
}

/**
 * Saves collection as JSON via native save dialog + IPC.
 * In web demo: shows «Не доступно в демо» and returns false.
 */
export async function exportCollectionAsJson(params: ExportCollectionJsonParams): Promise<boolean> {
  if (!guardNativeFileOperation()) {
    return false;
  }

  const { name, tracks } = params;
  const path = await ipcService.showSaveDialog({
    title: 'Экспортировать коллекцию',
    defaultPath: `${name}.json`,
    filters: [{ name: 'JSON файлы', extensions: ['json'] }],
  });

  if (!path) {
    return false;
  }

  const playlistData: PlaylistData = {
    name,
    tracks: tracks.map((track) => ({
      path: track.path,
      name: track.name,
      duration: track.duration,
    })),
  };

  await playlistService.savePlaylist(path, playlistData);
  return true;
}

/**
 * Copies collection tracks into a user-selected folder.
 * In web demo: shows «Не доступно в демо» and returns null.
 */
export async function copyCollectionTracksToFolder(params: CopyCollectionTracksParams): Promise<{
  folderPath: string;
  successful: string[];
  failed: Array<{ path: string; error: string }>;
} | null> {
  if (!guardNativeFileOperation()) {
    return null;
  }

  const targetPath = await ipcService.showFolderDialog({
    title: 'Выберите папку для копирования треков',
  });

  if (!targetPath) {
    return null;
  }

  return exportService.copyTracksToFolder(params.tracks, targetPath, params.folderName);
}

/**
 * Loads collection JSON from disk via open dialog + IPC.
 * In web demo: shows «Не доступно в демо» and returns null.
 */
export async function importCollectionFromJson(): Promise<PlaylistData | null> {
  if (!guardNativeFileOperation()) {
    return null;
  }

  const path = await ipcService.showOpenFileDialog({
    title: 'Импортировать коллекцию',
    filters: [{ name: 'JSON файлы', extensions: ['json'] }],
  });

  if (!path) {
    return null;
  }

  return playlistService.loadPlaylist(path);
}

import { ipcService, DirectoryItem } from './ipcService';

/**
 * Supported audio file extensions
 */
const AUDIO_EXTENSIONS = ['.mp3', '.wav', '.flac', '.m4a', '.ogg'] as const;

/**
 * Get file extension from path (browser-safe)
 */
function getFileExtension(filePath: string): string {
  const lastDot = filePath.lastIndexOf('.');
  const lastSlash = Math.max(filePath.lastIndexOf('/'), filePath.lastIndexOf('\\'));
  if (lastDot > lastSlash && lastDot !== -1) {
    return filePath.substring(lastDot).toLowerCase();
  }
  return '';
}

/**
 * Get parent directory path (browser-safe)
 */
function getParentPath(filePath: string): string | null {
  // Normalize path separators
  const normalized = filePath.replace(/\\/g, '/');
  const lastSlash = normalized.lastIndexOf('/');

  if (lastSlash === -1) {
    return null; // No parent (root)
  }

  if (lastSlash === 0) {
    // Root path like "/folder"
    return '/';
  }

  const parent = normalized.substring(0, lastSlash);

  // If parent is the same as current, we're at root
  if (parent === filePath) {
    return null;
  }

  return parent;
}

class FileService {
  /**
   * List folder contents
   */
  async listFolder(folderPath: string): Promise<DirectoryItem[]> {
    // ipcService.invoke уже обрабатывает ошибки и показывает уведомления
    return await ipcService.listDirectory(folderPath);
  }

  /**
   * Check if file is a valid audio file
   */
  isValidAudioFile(filePath: string): boolean {
    const ext = getFileExtension(filePath);
    return (AUDIO_EXTENSIONS as readonly string[]).includes(ext);
  }

  /**
   * Read file metadata (optional, for future use)
   */
  async readFileMeta(filePath: string): Promise<{
    size: number;
    modified: number;
    isDirectory: boolean;
  } | null> {
    try {
      // ipcService.invoke уже обрабатывает ошибки и показывает уведомления
      return await ipcService.statFile(filePath);
    } catch {
      // Возвращаем null при ошибке, так как это не критичная операция
      return null;
    }
  }

  /**
   * Get parent path
   */
  getParentPath(filePath: string): string | null {
    return getParentPath(filePath);
  }

  /**
   * Get path segments for breadcrumbs (cross-platform)
   * Handles both Windows (C:\Users\...) and Unix (/home/...) paths
   */
  getPathSegments(filePath: string): Array<{ name: string; path: string }> {
    if (!filePath) return [];

    const crumbs: Array<{ name: string; path: string }> = [];

    // Normalize path separators to forward slashes for processing
    const normalized = filePath.replace(/\\/g, '/');

    // Handle Windows absolute paths (C:/Users/...)
    // eslint-disable-next-line security/detect-unsafe-regex
    const windowsDriveMatch = normalized.match(/^([A-Za-z]:)(\/.*)?$/);
    if (windowsDriveMatch) {
      const drive = windowsDriveMatch[1];
      const rest = windowsDriveMatch[2] || '';

      // Add drive as first segment
      crumbs.push({ name: drive, path: drive + '/' });

      // Process rest of the path
      const parts = rest.split('/').filter((p) => p);
      let currentPath = drive + '/';

      for (const part of parts) {
        currentPath =
          currentPath === drive + '/' ? `${currentPath}${part}` : `${currentPath}/${part}`;
        crumbs.push({ name: part, path: currentPath });
      }

      return crumbs;
    }

    // Handle Unix absolute paths (/home/...)
    if (normalized.startsWith('/')) {
      const parts = normalized.split('/').filter((p) => p);
      let currentPath = '/';

      // Add root
      crumbs.push({ name: '/', path: '/' });

      for (const part of parts) {
        currentPath = currentPath === '/' ? `/${part}` : `${currentPath}/${part}`;
        crumbs.push({ name: part, path: currentPath });
      }

      return crumbs;
    }

    // Handle relative paths
    const parts = normalized.split('/').filter((p) => p);
    let currentPath = '';

    for (const part of parts) {
      currentPath = currentPath ? `${currentPath}/${part}` : part;
      crumbs.push({ name: part, path: currentPath });
    }

    return crumbs;
  }
}

