export class ThemeNotEntitledError extends Error {
  readonly code: 'theme_not_entitled';
  readonly themeId?: string;
  readonly requiredPackageCodes: string[];

  constructor(message: string, themeId?: string, requiredPackageCodes: string[] = []) {
    super(message);
    this.name = 'ThemeNotEntitledError';
    this.code = 'theme_not_entitled';
    this.themeId = themeId;
    this.requiredPackageCodes = requiredPackageCodes;
  }
}

export class InvalidPartyLifecycleTransitionError extends Error {
  readonly code = 'invalid_lifecycle_transition' as const;
  readonly currentState: PartyLifecycleState;
  readonly requestedState: PartyLifecycleState;

  constructor(
    message: string,
    currentState: PartyLifecycleState,
    requestedState: PartyLifecycleState,
  ) {
    super(message);
    this.name = 'InvalidPartyLifecycleTransitionError';
    this.currentState = currentState;
    this.requestedState = requestedState;
  }
}

class PartyService {
  private themeAccessCache: ThemeAccessDto | null = null;
  private themeAccessCacheToken: string | null = null;
  private themeAccessInFlight: Promise<ThemeAccessDto> | null = null;
  private static readonly guidRegex =
    /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/;

  private async getBaseUrl(): Promise<string> {
    const config = await getApiConfig();
    return config.apiUrl;
  }

  private getAuthHeaders(): Record<string, string> {
    const token = useAuthStore.getState().accessToken;
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }
    return headers;
  }

  invalidateThemeAccessCache(): void {
    this.themeAccessCache = null;
    this.themeAccessCacheToken = null;
    this.themeAccessInFlight = null;
  }

  async createParty(data: CreatePartyDto): Promise<PartyDto> {
    if (isDemoAuthMode()) {
      return demoCreateParty(data);
    }
    const token = useAuthStore.getState().accessToken;
    if (!token) {
      throw new Error('Для создания вечеринки необходимо войти в аккаунт');
    }
    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/parties`, {
      method: 'POST',
      headers: this.getAuthHeaders(),
      body: JSON.stringify(data),
      cache: 'no-cache',
    });

    await this.throwIfThemeNotEntitled(response);
    return handleApiResponse<PartyDto>(response, 'Failed to create party');
  }

  async getParties(): Promise<PartyDto[]> {
    if (isDemoAuthMode()) {
      return [getDemoPartySnapshot()];
    }
    const token = useAuthStore.getState().accessToken;
    if (!token) {
      throw new Error('Для просмотра списка вечеринок необходимо войти в аккаунт');
    }
    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/parties`, {
      method: 'GET',
      headers: this.getAuthHeaders(),
      cache: 'no-cache',
    });
    return handleApiResponse<PartyDto[]>(response, 'Failed to load parties');
  }

  async getParty(partyId: string): Promise<PartyDto> {
    if (isDemoAuthMode()) {
      if (partyId === DEMO_PARTY_ID || partyId.toLowerCase() === DEMO_PARTY_ID) {
        return getDemoPartySnapshot();
      }
      return getDemoPartySnapshot();
    }
    const token = useAuthStore.getState().accessToken;
    if (!token) {
      throw new Error('Для получения данных вечеринки необходимо войти в аккаунт');
    }
    const baseUrl = await this.getBaseUrl();
    const normalizedPartyId = this.normalizePartyId(partyId);
    const response = await apiFetch(`${baseUrl}/parties/${normalizedPartyId}`, {
      method: 'GET',
      headers: this.getAuthHeaders(),
      cache: 'no-cache',
    });

    return handleApiResponse<PartyDto>(response, 'Failed to get party');
  }

  async checkPartyExists(partyId: string): Promise<boolean> {
    if (isDemoAuthMode()) {
      return true;
    }
    const token = useAuthStore.getState().accessToken;
    if (!token) {
      throw new Error('Для получения данных вечеринки необходимо войти в аккаунт');
    }
    const baseUrl = await this.getBaseUrl();
    const normalizedPartyId = this.normalizePartyId(partyId);
    const response = await apiFetch(`${baseUrl}/parties/${normalizedPartyId}`, {
      method: 'GET',
      headers: this.getAuthHeaders(),
      cache: 'no-cache',
    });

    if (response.status === 404) {
      return false;
    }

    if (!response.ok) {
      await handleApiResponse<never>(response, 'Failed to check party existence');
    }

    return true;
  }

  async checkServerReachable(): Promise<boolean> {
    if (isDemoAuthMode()) {
      return true;
    }
    try {
      const config = await getApiConfig();
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5000);
      try {
        const response = await fetch(`${config.serverUrl}/api/health`, {
          method: 'GET',
          signal: controller.signal,
          cache: 'no-cache',
        });
        return response.ok;
      } finally {
        clearTimeout(timeoutId);
      }
    } catch {
      return false;
    }
  }

  async updateParty(partyId: string, data: UpdatePartyDto): Promise<void> {
    if (isDemoAuthMode()) {
      demoUpdateParty(partyId, data);
      return;
    }
    const baseUrl = await this.getBaseUrl();
    const normalizedPartyId = this.normalizePartyId(partyId);
    const response = await apiFetch(`${baseUrl}/parties/${normalizedPartyId}`, {
      method: 'PUT',
      headers: this.getAuthHeaders(),
      body: JSON.stringify(data),
      cache: 'no-cache',
    });

    await this.throwIfThemeNotEntitled(response);
    await handleApiResponse<void>(response, 'Failed to update party');
  }

  async updatePartyPlaylist(
    partyId: string,
    playlist: { items: PlayerItemForApi[]; totalTracks: number; totalDuration: number },
  ): Promise<void> {
    if (isDemoAuthMode()) {
      void partyId;
      void playlist;
      return;
    }
    const baseUrl = await this.getBaseUrl();
    const normalizedPartyId = this.normalizePartyId(partyId);
    const response = await apiFetch(`${baseUrl}/parties/${normalizedPartyId}/playlist`, {
      method: 'PUT',
      headers: this.getAuthHeaders(),
      body: JSON.stringify(playlist),
      cache: 'no-cache',
    });

    if (!response.ok) {
      await handleApiResponse<never>(response, 'Failed to update party playlist');
    }
  }

  async deleteParty(partyId: string): Promise<void> {
    if (isDemoAuthMode()) {
      void partyId;
      return;
    }
    const baseUrl = await this.getBaseUrl();
    const normalizedPartyId = this.normalizePartyId(partyId);
    const response = await apiFetch(`${baseUrl}/parties/${normalizedPartyId}`, {
      method: 'DELETE',
      headers: this.getAuthHeaders(),
      cache: 'no-cache',
    });
    await handleApiResponse<void>(response, 'Failed to delete party');
  }

  async transitionPartyLifecycle(
    partyId: string,
    targetState: PartyLifecycleState,
  ): Promise<PartyDto> {
    if (isDemoAuthMode()) {
      void partyId;
      return demoTransitionPartyLifecycle(targetState);
    }
    const baseUrl = await this.getBaseUrl();
    const normalizedPartyId = this.normalizePartyId(partyId);
    const body: TransitionPartyLifecycleDto = { partyLifecycleState: targetState };
    const response = await apiFetch(`${baseUrl}/parties/${normalizedPartyId}/lifecycle`, {
      method: 'POST',
      headers: this.getAuthHeaders(),
      body: JSON.stringify(body),
      cache: 'no-cache',
    });

    await this.throwIfInvalidLifecycleTransition(response);
    return handleApiResponse<PartyDto>(response, 'Failed to transition party lifecycle');
  }

  async getPartyState(shortCode: string): Promise<PartyStateDto | null> {
    if (isDemoAuthMode()) {
      void shortCode;
      return getDemoPartyState();
    }
    const baseUrl = await this.getBaseUrl();
    const response = await apiFetch(`${baseUrl}/parties/public/${shortCode}/state`, {
      method: 'GET',
      headers: { 'Content-Type': 'application/json' },
      cache: 'no-cache',
    });
    if (!response.ok) {
      if (response.status === 404) return null;
      await handleApiResponse<never>(response, 'Failed to get party state');
    }
    return response.json() as Promise<PartyStateDto>;
  }

  async getPartyUrl(shortCode: string): Promise<string> {
    if (isDemoAuthMode()) {
      return getDemoPartyPublicUrl(shortCode);
    }
    const config = await getApiConfig();
    const serverUrl = config.serverUrl;
    if (!serverUrl.trim()) {
      return `http://localhost:3000/party/${shortCode}`;
    }

    try {
      const url = new URL(serverUrl);
      const protocol = url.protocol;
      const hostname = url.hostname;

      const apiPort = url.port;

      let webPort: string | null = null;
      if (apiPort && apiPort !== '80' && apiPort !== '443') {
        if (apiPort === '5000') {
          webPort = '3000';
        } else {
          webPort = url.protocol === 'https:' ? '443' : '80';
        }
      }

      if (webPort) {
        return `${protocol}//${hostname}:${webPort}/party/${shortCode}`;
      }

      return `${protocol}//${hostname}/party/${shortCode}`;
    } catch {
      const cleanUrl = serverUrl.replace(/^https?:\/\//, '').split('/')[0];
      const protocol = serverUrl.startsWith('https') ? 'https' : 'http';
      const defaultWebPort = serverUrl.includes(':5000') ? '3000' : null;
      if (defaultWebPort) {
        return `${protocol}://${cleanUrl}:${defaultWebPort}/party/${shortCode}`;
      }
      return `${protocol}://${cleanUrl}/party/${shortCode}`;
    }
  }

  async getThemeAccess(forceRefresh = false): Promise<ThemeAccessDto> {
    if (isDemoAuthMode()) {
      void forceRefresh;
      return DEMO_THEME_ACCESS;
    }
    const token = useAuthStore.getState().accessToken;
    if (!token) {
      this.invalidateThemeAccessCache();
      throw new Error('Для получения доступа к темам необходимо войти в аккаунт');
    }

    if (
      this.themeAccessCacheToken === null ||
      !constantTimeStringEqual(this.themeAccessCacheToken, token)
    ) {
      this.invalidateThemeAccessCache();
      this.themeAccessCacheToken = token;
    }

    if (!forceRefresh && this.themeAccessCache) {
      return this.themeAccessCache;
    }

    if (!forceRefresh && this.themeAccessInFlight) {
      return this.themeAccessInFlight;
    }

    this.themeAccessInFlight = (async () => {
      const baseUrl = await this.getBaseUrl();
      const response = await apiFetch(`${baseUrl}/organizer/me/theme-access`, {
        method: 'GET',
        headers: this.getAuthHeaders(),
        cache: 'no-cache',
      });

      if (response.status === 401 || response.status === 403) {
        this.invalidateThemeAccessCache();
      }
      const data = await handleApiResponse<ThemeAccessDto>(response, 'Failed to load theme access');
      this.themeAccessCache = data;
      return data;
    })();

    try {
      return await this.themeAccessInFlight;
    } finally {
      this.themeAccessInFlight = null;
    }
  }

  private async throwIfThemeNotEntitled(response: Response): Promise<void> {
    if (response.status !== 403) {
      return;
    }

    let payload: unknown;
    try {
      payload = await response.clone().json();
    } catch {
      return;
    }

    if (!payload || typeof payload !== 'object') {
      return;
    }

    const body = payload as {
      code?: unknown;
      message?: unknown;
      detail?: unknown;
      themeId?: unknown;
      requiredPackageCodes?: unknown;
    };

    if (body.code !== 'theme_not_entitled') {
      return;
    }

    const message =
      (typeof body.message === 'string' && body.message) ||
      (typeof body.detail === 'string' && body.detail) ||
      'У вас нет доступа к выбранной теме.';

    const themeId = typeof body.themeId === 'string' ? body.themeId : undefined;
    const requiredPackageCodes = Array.isArray(body.requiredPackageCodes)
      ? body.requiredPackageCodes.filter((code): code is string => typeof code === 'string')
      : [];

    throw new ThemeNotEntitledError(message, themeId, requiredPackageCodes);
  }

  private async throwIfInvalidLifecycleTransition(response: Response): Promise<void> {
    if (response.status !== 409) {
      return;
    }

    let payload: unknown;
    try {
      payload = await response.clone().json();
    } catch {
      return;
    }

    if (!payload || typeof payload !== 'object') {
      return;
    }

    const body = payload as {
      code?: unknown;
      message?: unknown;
      detail?: unknown;
      currentState?: unknown;
      requestedState?: unknown;
    };

    if (body.code !== 'invalid_lifecycle_transition') {
      return;
    }

    const message =
      (typeof body.message === 'string' && body.message) ||
      (typeof body.detail === 'string' && body.detail) ||
      'Недопустимый переход состояния вечеринки.';

    const currentState = isPartyLifecycleState(body.currentState) ? body.currentState : 'draft';
    const requestedState = isPartyLifecycleState(body.requestedState)
      ? body.requestedState
      : 'draft';

    throw new InvalidPartyLifecycleTransitionError(message, currentState, requestedState);
  }

  private normalizePartyId(partyId: string): string {
    const normalized = partyId.trim().replace(/^\{|\}$/g, '');
    if (!PartyService.guidRegex.test(normalized)) {
      throw new Error('Некорректный идентификатор вечеринки');
    }
    return normalized.toLowerCase();
  }
}

export const partyService = new PartyService();

import {
  DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
  isProjectGroup,
  isProjectTrack,
  LinkedParty,
  PartyTrackDisplaySettings,
  ProjectFile,
  ProjectGroup,
  ProjectGroupSettings,
  ProjectItem,
  ProjectSessionState,
  ProjectSettings,
  ProjectTrackSettings,
  SavedProjectGroup,
  SavedProjectItem,
  SavedProjectTrack,
} from '@core/types/project';
import { Track } from '@core/types/track';
import { validateProjectFile, validateProjectIntegrity } from '@shared/utils/projectValidation';

import { ipcService } from './ipcService';
import { normalizeLoadedLoudness } from './loudnessService';

/**
 * Returns the directory portion of a file path (cross-platform, handles both / and \).
 */
function pathDirname(filePath: string): string {
  const lastSep = Math.max(filePath.lastIndexOf('/'), filePath.lastIndexOf('\\'));
  return lastSep >= 0 ? filePath.slice(0, lastSep) : '.';
}

/**
 * Resolves a relative path against a base directory.
 * Handles `./` and `../` segments without requiring Node.js `path` module.
 */
function resolveRelativePath(baseDir: string, relativePath: string): string {
  // Normalize separators to forward slash for processing
  const normalizedBase = baseDir.replace(/\\/g, '/');
  const normalizedRel = relativePath.replace(/\\/g, '/');

  const parts = normalizedBase.split('/');

  // Remove trailing empty segment if base ends with /
  if (parts[parts.length - 1] === '') {
    parts.pop();
  }

  const relParts = normalizedRel.split('/');
  for (const segment of relParts) {
    if (segment === '.' || segment === '') {
      continue;
    } else if (segment === '..') {
      if (parts.length > 0) {
        parts.pop();
      }
    } else {
      parts.push(segment);
    }
  }

  const resolved = parts.join('/');

  // Restore Windows drive letter separator if present (e.g. "C:/..." → "C:/...")
  // and convert back to backslashes on Windows paths
  if (/^[A-Za-z]:/.test(resolved)) {
    return resolved.replace(/\//g, '\\');
  }

  return resolved;
}

/**
 * Returns true if the given path is relative (starts with ./ or ../).
 */
function isRelativePath(filePath: string): boolean {
  return (
    filePath.startsWith('./') ||
    filePath.startsWith('../') ||
    filePath.startsWith('.\\') ||
    filePath.startsWith('..\\')
  );
}

/**
 * Checks whether a file is accessible on disk.
 * Returns false instead of throwing if the file does not exist.
 */
async function checkFileExists(filePath: string): Promise<boolean> {
  try {
    await ipcService.statFile(filePath);
    return true;
  } catch {
    return false;
  }
}

/**
 * Resolves relative track paths to absolute and marks missing tracks.
 * Mutates tracks in-place; operates on all tracks recursively.
 */
async function resolveAndCheckTracks(items: ProjectItem[], cherryFilePath: string): Promise<void> {
  const baseDir = pathDirname(cherryFilePath);

  const processItems = async (projectItems: ProjectItem[]): Promise<void> => {
    for (const item of projectItems) {
      if (isProjectTrack(item)) {
        if (isRelativePath(item.path)) {
          item.path = resolveRelativePath(baseDir, item.path);
        }

        const exists = await checkFileExists(item.path);
        item.isMissing = !exists;
      } else if (isProjectGroup(item)) {
        await processItems(item.items);
      }
    }
  };

  await processItems(items);
}

/**
 * Состояние проекта для сериализации/десериализации
 */
export interface ProjectStateData {
  name: string;
  items: ProjectItem[];
  settings: ProjectSettings;
  trackSettings: Map<string, ProjectTrackSettings>;
  groupSettings: Map<string, ProjectGroupSettings>;
  sessionState?: ProjectSessionState;
  linkedParty?: LinkedParty | null;
  partyTrackDisplay?: PartyTrackDisplaySettings;
  partyThemeId?: string;
  partyCustomizationSettings?: Record<string, unknown>;
}

class ProjectService {
  /**
   * Сохранить проект в файл .cherry
   */
  async saveProject(
    path: string,
    projectFile: ProjectFile,
    options?: { portableMode?: boolean; strictSourceFiles?: boolean; notifyOnIpcError?: boolean },
  ): Promise<void> {
    const notify = options?.notifyOnIpcError !== false;
    await ipcService.invoke<void>(
      'project:save',
      {
        path,
        projectFile,
        portableMode: options?.portableMode,
        strictSourceFiles: options?.strictSourceFiles,
      },
      notify,
    );
  }

  /**
   * Переносимый «пакет»: вложенная папка с именем проекта, .cherry и копия треков (строгий режим в main).
   */
  async savePortableAs(
    parentPath: string,
    projectFile: ProjectFile,
    options?: { notifyOnIpcError?: boolean },
  ): Promise<{ cherryPath: string; folderPath: string }> {
    const notify = options?.notifyOnIpcError !== false;
    return ipcService.invoke<{ cherryPath: string; folderPath: string }>(
      'project:savePortableAs',
      {
        parentPath,
        projectFile,
      },
      notify,
    );
  }

  /**
   * Загрузить проект из файла .cherry
   * Валидирует данные и выводит предупреждения в консоль
   */
  async loadProject(filePath: string): Promise<ProjectStateData> {
    const rawData = await ipcService.invoke<unknown>('project:load', { path: filePath });
    return this.loadProjectFromData(rawData, filePath);
  }

  /**
   * Parse and validate project JSON (e.g. fetched demo asset) without IPC.
   */
  async loadProjectFromData(rawData: unknown, filePath: string): Promise<ProjectStateData> {
    const validationResult = validateProjectFile(rawData);

    if (!validationResult.isValid || !validationResult.data) {
      const errorMessage = validationResult.errors.join('; ');
      throw new Error(`Invalid project file: ${errorMessage}`);
    }

    if (validationResult.warnings.length > 0) {
      console.warn('Project file warnings:', validationResult.warnings);
    }

    const integrityWarnings = validateProjectIntegrity(validationResult.data);
    if (integrityWarnings.length > 0) {
      console.warn('Project integrity warnings:', integrityWarnings);
    }

    const projectData = this.deserializeProject(validationResult.data);

    if (filePath) {
      await resolveAndCheckTracks(projectData.items, filePath);
    }

    return projectData;
  }

  /**
   * Сериализация состояния проекта в формат файла .cherry
   */
  serializeProject(state: ProjectStateData): ProjectFile {
    const savedItems: SavedProjectItem[] = [];
    const rootItemIds: string[] = [];

    // Рекурсивно собираем все элементы
    const processItems = (items: ProjectItem[]): void => {
      items.forEach((item) => {
        if (isProjectTrack(item)) {
          const savedTrack: SavedProjectTrack = {
            type: 'track',
            id: item.id,
            path: item.path,
            name: item.name,
            duration: item.duration,
            ...(item.loudness !== undefined ? { loudness: item.loudness } : {}),
          };
          savedItems.push(savedTrack);
        } else if (isProjectGroup(item)) {
          // Сначала обрабатываем вложенные элементы
          processItems(item.items);

          const savedGroup: SavedProjectGroup = {
            type: 'group',
            id: item.id,
            name: item.name,
            items: item.items.map((child) => child.id),
          };
          savedItems.push(savedGroup);
        }
      });
    };

    // Обрабатываем все элементы
    processItems(state.items);

    // Собираем ID корневых элементов
    state.items.forEach((item) => {
      rootItemIds.push(item.id);
    });

    // Конвертируем Map в Record
    const trackSettingsRecord: Record<string, ProjectTrackSettings> = {};
    state.trackSettings.forEach((value, key) => {
      trackSettingsRecord[key] = value;
    });

    const groupSettingsRecord: Record<string, ProjectGroupSettings> = {};
    state.groupSettings.forEach((value, key) => {
      groupSettingsRecord[key] = value;
    });

    return {
      version: '2.0',
      name: state.name,
      items: savedItems,
      rootItems: rootItemIds,
      settings: state.settings,
      trackSettings: trackSettingsRecord,
      groupSettings: groupSettingsRecord,
      sessionState: state.sessionState,
      ...(state.linkedParty && { linkedParty: state.linkedParty }),
      partyTrackDisplay: state.partyTrackDisplay ?? DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
      ...(state.partyThemeId !== undefined ? { partyThemeId: state.partyThemeId } : {}),
      ...(state.partyCustomizationSettings !== undefined
        ? { partyCustomizationSettings: state.partyCustomizationSettings }
        : {}),
    };
  }

  /**
   * Десериализация файла .cherry в состояние проекта
   */
  deserializeProject(file: ProjectFile): ProjectStateData {
    // Создаем Map для быстрого доступа к элементам по ID
    const itemsById = new Map<string, SavedProjectItem>();
    file.items.forEach((item) => {
      itemsById.set(item.id, item);
    });

    // Рекурсивная функция для восстановления элемента
    const restoreItem = (itemId: string, visited: Set<string>): ProjectItem | null => {
      if (visited.has(itemId)) {
        console.warn(`Circular reference detected for item ${itemId}`);
        return null;
      }
      visited.add(itemId);

      const savedItem = itemsById.get(itemId);
      if (!savedItem) {
        console.warn(`Item ${itemId} not found`);
        return null;
      }

      if (savedItem.type === 'track') {
        const normalizedLoudness =
          savedItem.loudness !== undefined
            ? normalizeLoadedLoudness(savedItem.loudness)
            : undefined;
        const track: Track = {
          id: savedItem.id,
          path: savedItem.path,
          name: savedItem.name,
          duration: savedItem.duration,
          ...(normalizedLoudness !== undefined ? { loudness: normalizedLoudness } : {}),
        };
        return track;
      } else if (savedItem.type === 'group') {
        const children: ProjectItem[] = [];
        savedItem.items.forEach((childId) => {
          const child = restoreItem(childId, new Set(visited));
          if (child) {
            children.push(child);
          }
        });

        const group: ProjectGroup = {
          id: savedItem.id,
          name: savedItem.name,
          items: children,
        };
        return group;
      }

      return null;
    };

    // Восстанавливаем корневые элементы
    const items: ProjectItem[] = [];
    file.rootItems.forEach((itemId) => {
      const item = restoreItem(itemId, new Set());
      if (item) {
        items.push(item);
      }
    });

    // Конвертируем Record в Map
    const trackSettings = new Map<string, ProjectTrackSettings>();
    if (file.trackSettings) {
      Object.entries(file.trackSettings).forEach(([key, value]) => {
        trackSettings.set(key, value);
      });
    }

    const groupSettings = new Map<string, ProjectGroupSettings>();
    if (file.groupSettings) {
      Object.entries(file.groupSettings).forEach(([key, value]) => {
        groupSettings.set(key, value);
      });
    }

    return {
      name: file.name,
      items,
      settings: file.settings,
      trackSettings,
      groupSettings,
      sessionState: file.sessionState,
      linkedParty: file.linkedParty ?? null,
      partyTrackDisplay: file.partyTrackDisplay ?? DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
      partyThemeId: file.partyThemeId,
      partyCustomizationSettings: file.partyCustomizationSettings,
    };
  }
}

export const projectService = new ProjectService();

import { DEFAULT_FILEBROWSER_WORKSPACE_ID } from '@core/constants/workspace';
import type { Layout } from '@core/types/layout';
import type { WorkspaceId } from '@core/types/workspace';
import type {
  ActiveWorkspace,
  BuiltinLayoutOverrides,
  UserWorkspace,
} from '@core/types/workspacePreset';
import { APP_VERSION } from '@shared/config/appVersion';
import { getPlatformCapabilities } from '@shared/platform/platformCapabilities';

import type { AimpSourceSelection } from '../contracts/aimp';
import {
  clampLoudnessQuietGapRangeLu,
  clampLoudnessTargetLufs,
  DEFAULT_LOUDNESS_QUIET_GAP_RANGE_LU,
  DEFAULT_LOUDNESS_TARGET_LUFS,
} from '../contracts/loudness';
import type { CustomKeyBindings } from '../shortcuts/shortcutTypes';
import { normalizeBuiltinLayoutOverrides, useLayoutStore } from '../stores/layoutStore';
import { migrateFileBrowserPathsOnRehydrate, useSettingsStore } from '../stores/settingsStore';
import { isTrackItemSizePreset, type TrackItemSizePreset } from '../types/trackItemSize';

import { ipcService } from './ipcService';

export const SETTINGS_EXPORT_SCHEMA_VERSION = 1 as const;
export const SETTINGS_EXPORT_BUNDLE_FILENAME = 'cherryplaylist-settings-bundle.json';

const JSON_FILE_FILTERS = [{ name: 'JSON файлы', extensions: ['json'] }];

function cloneLayout(layout: Layout): Layout {
  return JSON.parse(JSON.stringify(layout)) as Layout;
}

const AUTH_FIELD_KEYS = ['accessToken', 'organizer', 'refreshToken'] as const;

export interface SettingsExportPersistedState {
  exportPath: string;
  exportStrategy: 'copyWithNumberPrefix' | 'aimpPlaylist';
  lastOpenedPlaylist: string;
  fileBrowserPath: string;
  fileBrowserPathsByWorkspaceId?: Record<WorkspaceId, string>;
  trackItemSizePreset: TrackItemSizePreset;
  hourDividerInterval: number;
  showHourDividers: boolean;
  playerAudioDeviceId: string | null;
  demoPlayerAudioDeviceId: string | null;
  keyBindings: CustomKeyBindings;
  enableStreaming: boolean;
  streamingSource: AimpSourceSelection;
  loudnessNormalizationEnabled?: boolean;
  loudnessTargetLufs?: number;
  loudnessCompressionEnabled?: boolean;
  loudnessQuietGapRangeLu?: number;
}

export interface SettingsExportBundle {
  schemaVersion: typeof SETTINGS_EXPORT_SCHEMA_VERSION;
  appVersion: string;
  exportedAt: string;
  settings: SettingsExportPersistedState;
  workspaces: {
    userWorkspaces: UserWorkspace[];
    activeWorkspace?: ActiveWorkspace;
    builtinLayoutOverrides?: BuiltinLayoutOverrides;
  };
}

export interface SettingsImportResult {
  settingsFieldCount: number;
  workspacesImported: number;
  workspacesUpdated: number;
}

function coerceFileBrowserPathsByWorkspaceId(
  value: unknown,
): Record<WorkspaceId, string> | undefined {
  if (!value || typeof value !== 'object') {
    return undefined;
  }

  const result: Record<WorkspaceId, string> = {};
  for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
    if (typeof key === 'string' && typeof entry === 'string') {
      result[key] = entry;
    }
  }

  return result;
}

export function pickSettingsExportFields(
  state: ReturnType<typeof useSettingsStore.getState>,
): SettingsExportPersistedState {
  const defaultFileBrowserPath = state.getFileBrowserPathForWorkspace(
    DEFAULT_FILEBROWSER_WORKSPACE_ID,
  );

  return {
    exportPath: state.exportPath,
    exportStrategy: state.exportStrategy,
    lastOpenedPlaylist: state.lastOpenedPlaylist,
    fileBrowserPath: defaultFileBrowserPath,
    fileBrowserPathsByWorkspaceId: { ...state.fileBrowserPathsByWorkspaceId },
    trackItemSizePreset: state.trackItemSizePreset,
    hourDividerInterval: state.hourDividerInterval,
    showHourDividers: state.showHourDividers,
    playerAudioDeviceId: state.playerAudioDeviceId,
    demoPlayerAudioDeviceId: state.demoPlayerAudioDeviceId,
    keyBindings: state.keyBindings,
    enableStreaming: state.enableStreaming,
    streamingSource: state.streamingSource,
    loudnessNormalizationEnabled: state.loudnessNormalizationEnabled,
    loudnessTargetLufs: state.loudnessTargetLufs,
    loudnessCompressionEnabled: state.loudnessCompressionEnabled,
    loudnessQuietGapRangeLu: state.loudnessQuietGapRangeLu,
  };
}

export function buildSettingsExportBundle(): SettingsExportBundle {
  const settingsState = useSettingsStore.getState();
  const layoutState = useLayoutStore.getState();

  const activeWorkspace =
    layoutState.activeWorkspace.kind === 'scratch' ? undefined : layoutState.activeWorkspace;

  return {
    schemaVersion: SETTINGS_EXPORT_SCHEMA_VERSION,
    appVersion: APP_VERSION,
    exportedAt: new Date().toISOString(),
    settings: pickSettingsExportFields(settingsState),
    workspaces: {
      userWorkspaces: layoutState.userWorkspaces.map((workspace) => ({
        ...workspace,
        layout: cloneLayout(workspace.layout),
      })),
      builtinLayoutOverrides: normalizeBuiltinLayoutOverrides(layoutState.builtinLayoutOverrides),
      ...(activeWorkspace ? { activeWorkspace } : {}),
    },
  };
}

function hasAuthFields(value: unknown): boolean {
  if (!value || typeof value !== 'object') {
    return false;
  }
  return AUTH_FIELD_KEYS.some((key) => key in (value as Record<string, unknown>));
}

function isUserWorkspace(value: unknown): value is UserWorkspace {
  if (!value || typeof value !== 'object') {
    return false;
  }
  const workspace = value as Record<string, unknown>;
  return (
    typeof workspace.id === 'string' &&
    typeof workspace.name === 'string' &&
    workspace.layout !== null &&
    typeof workspace.layout === 'object'
  );
}

function isActiveWorkspace(value: unknown): value is ActiveWorkspace {
  if (!value || typeof value !== 'object') {
    return false;
  }
  const active = value as Record<string, unknown>;
  if (active.kind === 'builtin') {
    return typeof active.preset === 'string';
  }
  if (active.kind === 'user') {
    return typeof active.id === 'string';
  }
  if (active.kind === 'scratch') {
    return true;
  }
  return false;
}

function isSettingsExportPersistedState(value: unknown): value is SettingsExportPersistedState {
  if (!value || typeof value !== 'object' || hasAuthFields(value)) {
    return false;
  }
  const settings = value as Record<string, unknown>;
  return (
    typeof settings.exportPath === 'string' &&
    (settings.exportStrategy === 'copyWithNumberPrefix' ||
      settings.exportStrategy === 'aimpPlaylist') &&
    typeof settings.lastOpenedPlaylist === 'string' &&
    typeof settings.fileBrowserPath === 'string' &&
    isTrackItemSizePreset(settings.trackItemSizePreset) &&
    typeof settings.hourDividerInterval === 'number' &&
    typeof settings.showHourDividers === 'boolean' &&
    (settings.playerAudioDeviceId === null || typeof settings.playerAudioDeviceId === 'string') &&
    (settings.demoPlayerAudioDeviceId === null ||
      typeof settings.demoPlayerAudioDeviceId === 'string') &&
    typeof settings.keyBindings === 'object' &&
    settings.keyBindings !== null &&
    typeof settings.enableStreaming === 'boolean' &&
    (settings.streamingSource === 'cherryPlayPlayer' || settings.streamingSource === 'aimp') &&
    (settings.loudnessNormalizationEnabled === undefined ||
      typeof settings.loudnessNormalizationEnabled === 'boolean') &&
    (settings.loudnessTargetLufs === undefined ||
      typeof settings.loudnessTargetLufs === 'number') &&
    (settings.loudnessCompressionEnabled === undefined ||
      typeof settings.loudnessCompressionEnabled === 'boolean') &&
    (settings.loudnessQuietGapRangeLu === undefined ||
      typeof settings.loudnessQuietGapRangeLu === 'number') &&
    (settings.fileBrowserPathsByWorkspaceId === undefined ||
      coerceFileBrowserPathsByWorkspaceId(settings.fileBrowserPathsByWorkspaceId) !== undefined)
  );
}

export function validateSettingsExportBundle(data: unknown): data is SettingsExportBundle {
  if (!data || typeof data !== 'object') {
    return false;
  }

  const bundle = data as Record<string, unknown>;
  if (bundle.schemaVersion !== SETTINGS_EXPORT_SCHEMA_VERSION) {
    return false;
  }
  if (typeof bundle.appVersion !== 'string' || typeof bundle.exportedAt !== 'string') {
    return false;
  }
  if (!isSettingsExportPersistedState(bundle.settings)) {
    return false;
  }

  const workspaces = bundle.workspaces;
  if (!workspaces || typeof workspaces !== 'object') {
    return false;
  }

  const workspacesRecord = workspaces as Record<string, unknown>;
  if (!Array.isArray(workspacesRecord.userWorkspaces)) {
    return false;
  }
  if (!workspacesRecord.userWorkspaces.every(isUserWorkspace)) {
    return false;
  }

  if (
    workspacesRecord.activeWorkspace !== undefined &&
    !isActiveWorkspace(workspacesRecord.activeWorkspace)
  ) {
    return false;
  }

  if (workspacesRecord.builtinLayoutOverrides !== undefined) {
    const overrides = workspacesRecord.builtinLayoutOverrides;
    if (!overrides || typeof overrides !== 'object' || Array.isArray(overrides)) {
      return false;
    }
    for (const layout of Object.values(overrides as Record<string, unknown>)) {
      if (!layout || typeof layout !== 'object') {
        return false;
      }
    }
  }

  return !hasAuthFields(bundle);
}

export function parseSettingsBundleJson(text: string): SettingsExportBundle {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    throw new Error('Некорректный JSON');
  }

  if (!validateSettingsExportBundle(parsed)) {
    throw new Error('Неподдерживаемый формат файла настроек');
  }

  return parsed;
}

function resolveUniqueWorkspaceName(name: string, usedNames: Set<string>): string {
  if (!usedNames.has(name)) {
    return name;
  }

  let suffix = 2;
  while (usedNames.has(`${name} (${suffix})`)) {
    suffix += 1;
  }
  return `${name} (${suffix})`;
}

export function mergeUserWorkspacesOnImport(
  existing: UserWorkspace[],
  incoming: UserWorkspace[],
): { merged: UserWorkspace[]; importedCount: number; updatedCount: number } {
  const mergedById = new Map(existing.map((workspace) => [workspace.id, workspace]));
  const usedNames = new Set(existing.map((workspace) => workspace.name));
  let importedCount = 0;
  let updatedCount = 0;

  for (const workspace of incoming) {
    const exists = mergedById.has(workspace.id);
    const previous = exists ? mergedById.get(workspace.id) : undefined;

    if (previous) {
      usedNames.delete(previous.name);
    }

    const uniqueName = resolveUniqueWorkspaceName(workspace.name, usedNames);
    usedNames.add(uniqueName);

    const nextWorkspace: UserWorkspace = {
      ...workspace,
      name: uniqueName,
      layout: cloneLayout(workspace.layout),
    };

    mergedById.set(workspace.id, nextWorkspace);

    if (exists) {
      updatedCount += 1;
    } else {
      importedCount += 1;
    }
  }

  return {
    merged: Array.from(mergedById.values()),
    importedCount,
    updatedCount,
  };
}

function isImportableActiveWorkspace(
  activeWorkspace: ActiveWorkspace,
  mergedWorkspaces: UserWorkspace[],
): boolean {
  if (activeWorkspace.kind === 'scratch') {
    return false;
  }
  if (activeWorkspace.kind === 'user') {
    return mergedWorkspaces.some((workspace) => workspace.id === activeWorkspace.id);
  }
  return true;
}

function prepareLayoutStateForSettingsImport(): void {
  const state = useLayoutStore.getState();
  state.autoCommitWorkspaceChanges();
  state.setLayoutEditMode(false);
}

function normalizeImportedSettings(
  settings: SettingsExportPersistedState,
): SettingsExportPersistedState & {
  fileBrowserPathsByWorkspaceId: Record<WorkspaceId, string>;
} {
  const coercedMap = coerceFileBrowserPathsByWorkspaceId(settings.fileBrowserPathsByWorkspaceId);
  const migrated = migrateFileBrowserPathsOnRehydrate({
    fileBrowserPath: settings.fileBrowserPath,
    fileBrowserPathsByWorkspaceId: coercedMap ?? {},
  });

  return {
    ...settings,
    fileBrowserPath: migrated.fileBrowserPath,
    fileBrowserPathsByWorkspaceId: migrated.fileBrowserPathsByWorkspaceId,
    loudnessNormalizationEnabled:
      typeof settings.loudnessNormalizationEnabled === 'boolean'
        ? settings.loudnessNormalizationEnabled
        : true,
    loudnessCompressionEnabled:
      typeof settings.loudnessCompressionEnabled === 'boolean'
        ? settings.loudnessCompressionEnabled
        : false,
    loudnessTargetLufs:
      typeof settings.loudnessTargetLufs === 'number'
        ? clampLoudnessTargetLufs(settings.loudnessTargetLufs)
        : DEFAULT_LOUDNESS_TARGET_LUFS,
    loudnessQuietGapRangeLu:
      typeof settings.loudnessQuietGapRangeLu === 'number'
        ? clampLoudnessQuietGapRangeLu(settings.loudnessQuietGapRangeLu)
        : DEFAULT_LOUDNESS_QUIET_GAP_RANGE_LU,
  };
}

export function applySettingsImport(bundle: SettingsExportBundle): SettingsImportResult {
  const normalizedSettings = normalizeImportedSettings(bundle.settings);
  const settingsFieldCount = Object.keys(normalizedSettings).length;

  prepareLayoutStateForSettingsImport();

  const layoutState = useLayoutStore.getState();
  const { merged, importedCount, updatedCount } = mergeUserWorkspacesOnImport(
    layoutState.userWorkspaces,
    bundle.workspaces.userWorkspaces,
  );

  const incomingOverrides = normalizeBuiltinLayoutOverrides(
    bundle.workspaces.builtinLayoutOverrides,
  );
  const mergedOverrides: BuiltinLayoutOverrides = {
    ...normalizeBuiltinLayoutOverrides(layoutState.builtinLayoutOverrides),
    ...incomingOverrides,
  };

  useLayoutStore.setState({
    userWorkspaces: merged,
    builtinLayoutOverrides: mergedOverrides,
  });

  const activeWorkspace = bundle.workspaces.activeWorkspace;
  if (activeWorkspace && isImportableActiveWorkspace(activeWorkspace, merged)) {
    if (activeWorkspace.kind === 'builtin') {
      useLayoutStore.getState().activateWorkspace({
        kind: 'builtin',
        preset: activeWorkspace.preset,
      });
    } else if (activeWorkspace.kind === 'user') {
      useLayoutStore.getState().activateWorkspace({
        kind: 'user',
        id: activeWorkspace.id,
      });
    }
  } else {
    const current = useLayoutStore.getState().activeWorkspace;
    if (current.kind === 'builtin') {
      useLayoutStore.getState().activateWorkspace({
        kind: 'builtin',
        preset: current.preset,
      });
    }
  }

  useSettingsStore.setState(normalizedSettings);

  return {
    settingsFieldCount,
    workspacesImported: importedCount,
    workspacesUpdated: updatedCount,
  };
}

export function downloadSettingsBundleInBrowser(): void {
  const bundle = buildSettingsExportBundle();
  const json = JSON.stringify(bundle, null, 2);
  const blob = new Blob([json], { type: 'application/json;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = SETTINGS_EXPORT_BUNDLE_FILENAME;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

async function exportSettingsBundleViaNativeDialog(): Promise<boolean> {
  const bundle = buildSettingsExportBundle();
  const path = await ipcService.showSaveDialog({
    title: 'Экспорт настроек',
    defaultPath: SETTINGS_EXPORT_BUNDLE_FILENAME,
    filters: JSON_FILE_FILTERS,
  });

  if (!path) {
    return false;
  }

  await ipcService.invoke('settings:saveBundle', { path, bundle }, false);
  return true;
}

export async function loadSettingsBundleViaNativeDialog(): Promise<SettingsExportBundle | null> {
  const path = await ipcService.showOpenFileDialog({
    title: 'Импорт настроек',
    filters: JSON_FILE_FILTERS,
  });

  if (!path) {
    return null;
  }

  const data = await ipcService.invoke<unknown>('settings:loadBundle', { path }, false);
  if (!validateSettingsExportBundle(data)) {
    throw new Error('Неподдерживаемый формат файла настроек');
  }

  return data;
}

export type SettingsExportOutcome = 'exported' | 'cancelled';

export async function exportSettingsBundle(): Promise<SettingsExportOutcome> {
  if (getPlatformCapabilities().supportsNativeFileSystem) {
    const exported = await exportSettingsBundleViaNativeDialog();
    return exported ? 'exported' : 'cancelled';
  }

  downloadSettingsBundleInBrowser();
  return 'exported';
}

import * as signalR from '@microsoft/signalr';

import { clearApiConfigCache, getApiConfig } from '../config/apiConfig';
import { type PlaybackStateDto } from '../contracts/playbackState';
import { useAuthStore } from '../stores';
import {
  handleAuthError,
  isAuthError,
  SESSION_EXPIRED_USER_MESSAGE,
} from '../utils/authErrorHandler';
import { isTokenExpired } from '../utils/tokenUtils';

export type { PlaybackStateDto, PlaybackWireStatus } from '../contracts/playbackState';

const SignalREvents = {
  OnSessionStarted: 'OnSessionStarted',
  OnSessionEnded: 'OnSessionEnded',
  OnFullStateUpdated: 'OnFullStateUpdated',
  OnPlaybackPositionUpdated: 'OnPlaybackPositionUpdated',
  OnStateChanged: 'OnStateChanged',
  OnPlaylistChanged: 'OnPlaylistChanged',
  Error: 'Error',
} as const;

export type SessionStartedHandler = (partyId: string) => void;
export type SessionEndedHandler = (partyId: string) => void;
export type FullStateUpdatedHandler = (partyId: string, state: PlaybackStateDto) => void;
export type PlaybackPositionUpdatedHandler = (
  partyId: string,
  trackId: string,
  position: number,
) => void;
export type StateChangedHandler = (partyId: string) => void;
export type PlaylistChangedHandler = (partyId: string) => void;
export type ErrorHandler = (error: Error) => void;

interface ReconnectConfig {
  maxAttempts: number;
  delayMs: number;
}

class SignalRService {
  private connection: signalR.HubConnection | null = null;
  private isConnecting = false;
  private reconnectConfig: ReconnectConfig = {
    maxAttempts: 5,
    delayMs: 3000,
  };


  private eventHandlers: {
    onSessionStarted?: SessionStartedHandler;
    onSessionEnded?: SessionEndedHandler;
    onFullStateUpdated?: FullStateUpdatedHandler;
    onPlaybackPositionUpdated?: PlaybackPositionUpdatedHandler;
    onStateChanged?: StateChangedHandler;
    onPlaylistChanged?: PlaylistChangedHandler;
    onError?: ErrorHandler;
    onReconnectionFailed?: () => void;
  } = {};


  private currentPartyId: string | null = null;
  private currentToken: string | undefined = undefined;
  private partyReconnectHandler: ((partyId: string) => Promise<void>) | null = null;


  setPartyReconnectHandler(handler: ((partyId: string) => Promise<void>) | null): void {
    this.partyReconnectHandler = handler;
  }


  isServiceConnected(): boolean {
    return (
      this.connection !== null && this.connection.state === signalR.HubConnectionState.Connected
    );
  }


  getConnectionState(): signalR.HubConnectionState | null {
    return this.connection?.state ?? null;
  }


  getConnectionErrorReason(): string | null {
    if (!this.currentPartyId) {
      return 'Нет вечеринки';
    }

    const state = this.getConnectionState();
    if (state === null) {
      return 'Нет вечеринки';
    }

    if (state === signalR.HubConnectionState.Disconnected) {
      return 'Ошибка соединения';
    }

    if (
      state === signalR.HubConnectionState.Disconnecting ||
      state === signalR.HubConnectionState.Reconnecting
    ) {
      return 'Ошибка соединения';
    }

    return null; 
  }


  async connect(token?: string): Promise<void> {

    const authToken = token || useAuthStore.getState().accessToken;


    if (authToken && isTokenExpired(authToken)) {
      console.warn('[SignalR] Token expired, clearing auth');
      handleAuthError('Authentication token has expired');
      throw new Error(SESSION_EXPIRED_USER_MESSAGE);
    }


    if (authToken) {
      this.currentToken = authToken;
    }

    if (this.isConnecting) {

      while (this.isConnecting) {
        await new Promise((resolve) => setTimeout(resolve, 100));
      }
      if (this.isServiceConnected()) {
        return;
      }
    }

    if (this.isServiceConnected()) {
      return;
    }

    this.isConnecting = true;

    try {

      if (this.connection) {
        await this.cleanupConnection();
      }


      clearApiConfigCache();
      const config = await getApiConfig();

      console.log('[SignalR] Starting connection to:', config.signalRUrl);




      const connectionOptions: signalR.IHttpConnectionOptions = {};
      if (authToken) {


        connectionOptions.accessTokenFactory = () => {
          const currentToken = useAuthStore.getState().accessToken || authToken;
          return Promise.resolve(currentToken || '');
        };
      }

      this.connection = new signalR.HubConnectionBuilder()
        .withUrl(config.signalRUrl, connectionOptions)
        .withAutomaticReconnect({
          nextRetryDelayInMilliseconds: (retryContext) => {
            if (retryContext.previousRetryCount < this.reconnectConfig.maxAttempts) {
              console.log(
                `[SignalR] Reconnecting attempt ${retryContext.previousRetryCount + 1}/${this.reconnectConfig.maxAttempts}`,
              );
              return this.reconnectConfig.delayMs;
            }
            console.error('[SignalR] Max reconnection attempts reached');
            if (this.eventHandlers.onReconnectionFailed) {
              this.eventHandlers.onReconnectionFailed();
            }
            return null; 
          },
        })
        .build();


      this.setupConnectionHandlers();


      this.setupHubEventHandlers();

      await this.connection.start();
      console.log('[SignalR] Successfully connected');
    } catch (error) {
      console.error('[SignalR] Failed to connect:', error);
      await this.cleanupConnection();
      throw error;
    } finally {
      this.isConnecting = false;
    }
  }


  private setupConnectionHandlers(): void {
    if (!this.connection) return;

    this.connection.onclose((error) => {
      console.log('[SignalR] Connection closed', error ? `with error: ${error.message}` : '');
      if (error && this.eventHandlers.onError) {
        this.eventHandlers.onError(new Error(error.message || 'Connection closed'));
      }
    });

    this.connection.onreconnecting((error) => {
      console.log('[SignalR] Reconnecting...', error ? `Error: ${error.message}` : '');
    });

    this.connection.onreconnected(async (connectionId) => {
      console.log('[SignalR] Reconnected with connection ID:', connectionId);


      const currentToken = useAuthStore.getState().accessToken || this.currentToken;
      if (currentToken && isTokenExpired(currentToken)) {
        console.warn('[SignalR] Token expired during reconnect, clearing auth');
        handleAuthError('Authentication token has expired');
        await this.disconnect();
        return;
      }


      if (currentToken) {
        this.currentToken = currentToken;
      }


      this.setupHubEventHandlers();


      if (this.currentPartyId) {
        try {
          console.log('[SignalR] Restoring party connection after reconnect:', this.currentPartyId);


          if (this.connection && this.isServiceConnected() && this.currentToken) {
            await this.invokeWithLogging(
              'JoinPartyAsOrganizer',
              this.currentPartyId,
              this.currentToken,
            );
          }

          if (this.partyReconnectHandler) {
            await this.partyReconnectHandler(this.currentPartyId);
          }

          console.log('[SignalR] Party connection restored after reconnect');
        } catch (error) {
          console.error('[SignalR] Failed to restore party connection after reconnect:', error);
        }
      }
    });
  }


  private setupHubEventHandlers(): void {
    if (!this.connection) return;


    Object.values(SignalREvents).forEach((eventName) => {
      this.connection!.off(eventName);
    });

    if (this.eventHandlers.onSessionStarted) {
      this.connection.on(SignalREvents.OnSessionStarted, (partyId: string) => {
        console.log('[SignalR] ← Received OnSessionStarted:', {
          partyId,
          timestamp: new Date().toISOString(),
        });
        this.eventHandlers.onSessionStarted!(partyId);
      });
    }

    if (this.eventHandlers.onSessionEnded) {
      this.connection.on(SignalREvents.OnSessionEnded, (partyId: string) => {
        console.log('[SignalR] ← Received OnSessionEnded:', {
          partyId,
          timestamp: new Date().toISOString(),
        });
        this.eventHandlers.onSessionEnded!(partyId);
      });
    }

    if (this.eventHandlers.onFullStateUpdated) {
      this.connection.on(
        SignalREvents.OnFullStateUpdated,
        (partyId: string, state: PlaybackStateDto) => {
          console.log('[SignalR] ← Received OnFullStateUpdated:', {
            partyId,
            state: {
              currentTrackId: state.currentTrackId,
              status: state.status,
              position: state.position,
              duration: state.duration,
              volume: state.volume,
              mode: state.mode,
              playedTrackIds: state.playedTrackIds?.length || 0,
              disabledTrackIds: state.disabledTrackIds?.length || 0,
              disabledGroupIds: state.disabledGroupIds?.length || 0,
              lastUpdatedAt: state.lastUpdatedAt,
            },
            timestamp: new Date().toISOString(),
          });
          this.eventHandlers.onFullStateUpdated!(partyId, state);
        },
      );
    }

    if (this.eventHandlers.onPlaybackPositionUpdated) {
      this.connection.on(
        SignalREvents.OnPlaybackPositionUpdated,
        (partyId: string, trackId: string, position: number) => {
          console.log('[SignalR] ← Received OnPlaybackPositionUpdated:', {
            partyId,
            trackId,
            position,
            timestamp: new Date().toISOString(),
          });
          this.eventHandlers.onPlaybackPositionUpdated!(partyId, trackId, position);
        },
      );
    }

    if (this.eventHandlers.onStateChanged) {
      this.connection.on(SignalREvents.OnStateChanged, (partyId: string) => {
        console.log('[SignalR] ← Received OnStateChanged:', {
          partyId,
          timestamp: new Date().toISOString(),
        });
        this.eventHandlers.onStateChanged!(partyId);
      });
    }

    if (this.eventHandlers.onPlaylistChanged) {
      this.connection.on(SignalREvents.OnPlaylistChanged, (partyId: string) => {
        console.log('[SignalR] ← Received OnPlaylistChanged:', {
          partyId,
          timestamp: new Date().toISOString(),
        });
        this.eventHandlers.onPlaylistChanged!(partyId);
      });
    }

    if (this.eventHandlers.onError) {
      this.connection.on(SignalREvents.Error, (message: string) => {
        console.log('[SignalR] ← Received Error:', {
          message,
          timestamp: new Date().toISOString(),
        });
        this.eventHandlers.onError!(new Error(message));
      });
    }
  }


  private async cleanupConnection(): Promise<void> {
    if (this.connection) {

      this.removeAllEventHandlers();

      try {
        await this.connection.stop();
      } catch (error) {
        console.error('[SignalR] Error stopping connection:', error);
      }

      this.connection = null;
    }
  }


  private removeAllEventHandlers(): void {
    if (!this.connection) return;

    Object.values(SignalREvents).forEach((eventName) => {
      this.connection!.off(eventName);
    });
  }


  async disconnect(): Promise<void> {
    await this.cleanupConnection();
    this.currentPartyId = null;
    this.currentToken = undefined;

    console.log('[SignalR] Disconnected');
  }


  private async invokeWithLogging<T>(methodName: string, ...args: unknown[]): Promise<T> {
    if (!this.connection) {
      throw new Error('SignalR connection is null');
    }

    const logData = {
      method: methodName,
      args: args.length > 0 ? args : undefined,
      timestamp: new Date().toISOString(),
    };

    console.log(`[SignalR] → Invoking ${methodName}:`, logData);

    try {
      const result = await this.connection.invoke<T>(methodName, ...args);
      console.log(`[SignalR] ✓ ${methodName} succeeded`, {
        method: methodName,
        timestamp: new Date().toISOString(),
      });
      return result;
    } catch (error) {
      console.error(`[SignalR] ✗ ${methodName} failed:`, {
        method: methodName,
        error: error instanceof Error ? error.message : String(error),
        timestamp: new Date().toISOString(),
      });
      throw error;
    }
  }


  async joinPartyAsOrganizer(partyId: string, token?: string): Promise<void> {

    const authToken = token || useAuthStore.getState().accessToken;

    if (!authToken) {
      throw new Error('Authentication token is required to join as organizer');
    }

    if (!this.isServiceConnected()) {
      console.log('[SignalR] Connection not established, connecting...');
      await this.connect(authToken);
    }

    if (!this.connection || !this.isServiceConnected()) {
      throw new Error('SignalR connection not established');
    }

    console.log('[SignalR] Joining party as organizer:', {
      partyId,
      hasToken: !!authToken,
    });

    try {
      await this.invokeWithLogging('JoinPartyAsOrganizer', partyId, authToken);
      this.currentPartyId = partyId;
      console.log('[SignalR] Successfully joined party as organizer');
    } catch (error) {
      console.error('[SignalR] Failed to join party as organizer:', error);

      if (isAuthError(error)) {
        handleAuthError(error instanceof Error ? error : String(error));
      }
      throw error;
    }
  }


  async startSession(partyId: string): Promise<void> {
    if (!this.isServiceConnected()) {
      throw new Error('SignalR connection not established');
    }

    if (!this.connection) {
      throw new Error('SignalR connection is null');
    }


    const token = useAuthStore.getState().accessToken || this.currentToken;
    if (!token) {
      const error = new Error('Authentication token is required to start session');
      handleAuthError(error);
      throw error;
    }

    if (isTokenExpired(token)) {
      handleAuthError('Authentication token has expired');
      throw new Error(SESSION_EXPIRED_USER_MESSAGE);
    }

    console.log('[SignalR] Starting session:', { partyId });

    try {
      await this.invokeWithLogging('StartSession', partyId);
      console.log('[SignalR] Session started successfully');
    } catch (error) {
      console.error('[SignalR] Failed to start session:', error);
      if (isAuthError(error)) {
        handleAuthError(error instanceof Error ? error : String(error));
      }
      throw error;
    }
  }


  async endSession(partyId: string): Promise<void> {
    if (!this.isServiceConnected() || !this.connection) {
      return; 
    }

    try {
      await this.invokeWithLogging('EndSession', partyId);
      console.log('[SignalR] Session ended');
    } catch (error) {
      console.error('[SignalR] Failed to end session:', error);
    }
  }


  async resetPlaybackState(partyId: string): Promise<void> {
    if (!this.isServiceConnected() || !this.connection) {
      throw new Error('Нет подключения к серверу');
    }

    await this.invokeWithLogging('ResetPlaybackState', partyId);
    console.log('[SignalR] Playback state reset');
  }


  async updatePlaybackPosition(partyId: string, trackId: string, position: number): Promise<void> {
    if (!this.isServiceConnected() || !this.connection) {
      return; 
    }

    try {
      await this.invokeWithLogging('UpdatePlaybackPosition', partyId, trackId, position);
    } catch (error) {
      console.error('[SignalR] Failed to update playback position:', error);
    }
  }


  async notifyStateChanged(partyId: string): Promise<void> {
    try {
      await this.notifyStateChangedOrThrow(partyId);
    } catch (error) {
      console.error('[SignalR] Failed to notify state changed:', error);
    }
  }

  async notifyStateChangedOrThrow(partyId: string): Promise<void> {
    if (!this.isServiceConnected() || !this.connection) {
      throw new Error('SignalR connection not established');
    }

    await this.invokeWithLogging('NotifyStateChanged', partyId);
  }


  async updateFullState(partyId: string, state: PlaybackStateDto): Promise<void> {
    try {
      await this.updateFullStateOrThrow(partyId, state);
    } catch (error) {
      console.error('[SignalR] Failed to update full state:', error);
    }
  }

  async updateFullStateOrThrow(partyId: string, state: PlaybackStateDto): Promise<void> {
    if (!this.isServiceConnected() || !this.connection) {
      throw new Error('SignalR connection not established');
    }

    await this.invokeWithLogging('UpdateFullState', partyId, state);
  }


  onSessionStarted(handler: SessionStartedHandler): void {
    this.eventHandlers.onSessionStarted = handler;
    if (this.connection && this.isServiceConnected()) {
      this.connection.on(SignalREvents.OnSessionStarted, handler);
    }
  }


  onSessionEnded(handler: SessionEndedHandler): void {
    this.eventHandlers.onSessionEnded = handler;
    if (this.connection && this.isServiceConnected()) {
      this.connection.on(SignalREvents.OnSessionEnded, handler);
    }
  }


  onFullStateUpdated(handler: FullStateUpdatedHandler): void {
    this.eventHandlers.onFullStateUpdated = handler;
    if (this.connection && this.isServiceConnected()) {
      this.connection.on(SignalREvents.OnFullStateUpdated, handler);
    }
  }


  onPlaybackPositionUpdated(handler: PlaybackPositionUpdatedHandler): void {
    this.eventHandlers.onPlaybackPositionUpdated = handler;
    if (this.connection && this.isServiceConnected()) {
      this.connection.on(SignalREvents.OnPlaybackPositionUpdated, handler);
    }
  }


  onStateChanged(handler: StateChangedHandler): void {
    this.eventHandlers.onStateChanged = handler;
    if (this.connection && this.isServiceConnected()) {
      this.connection.on(SignalREvents.OnStateChanged, handler);
    }
  }


  onPlaylistChanged(handler: PlaylistChangedHandler): void {
    this.eventHandlers.onPlaylistChanged = handler;
    if (this.connection && this.isServiceConnected()) {
      this.connection.on(SignalREvents.OnPlaylistChanged, handler);
    }
  }


  onError(handler: ErrorHandler): void {
    this.eventHandlers.onError = handler;
  }


  onReconnectionFailed(handler: (() => void) | null | undefined): void {
    this.eventHandlers.onReconnectionFailed = handler ?? undefined;
  }


  removeAllHandlers(): void {
    this.removeAllEventHandlers();
    this.eventHandlers = {};
  }
}

