].join(', ');

const PLAYER_SPACE_DIALOG_SELECTOR = '.modal-overlay, [role="dialog"], [aria-modal="true"]';

export function matchKeyBinding(event: KeyboardEvent, binding: KeyBinding): boolean {
  if (event.code !== binding.code) {
    return false;
  }

  const eventHasCtrlOrCmd = event.ctrlKey || event.metaKey;
  const bindingRequiresCtrl = binding.ctrlKey === true;

  if (bindingRequiresCtrl !== eventHasCtrlOrCmd) {
    return false;
  }

  const bindingRequiresShift = binding.shiftKey === true;
  if (bindingRequiresShift !== event.shiftKey) {
    return false;
  }

  const bindingRequiresAlt = binding.altKey === true;
  if (bindingRequiresAlt !== event.altKey) {
    return false;
  }

  return true;
}

export function isInputField(event: KeyboardEvent): boolean {
  const target = event.target as HTMLElement | null;
  if (!target) {
    return false;
  }
  return target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable;
}

export function isInteractiveElement(event: KeyboardEvent): boolean {
  const target = event.target;
  if (!(target instanceof Element)) {
    return false;
  }
  return target.closest(INTERACTIVE_SELECTOR) !== null;
}

export function shouldBlockPlayerSpaceShortcut(event: KeyboardEvent): boolean {
  const target = event.target;
  if (!(target instanceof Element)) {
    return false;
  }
  if (isInputField(event)) {
    return true;
  }
  if (target.closest(PLAYER_SPACE_DIALOG_SELECTOR)) {
    return true;
  }
  if (target.closest(PLAYER_SPACE_NATIVE_CONTROL_SELECTOR)) {
    return true;
  }
  const roleButton = target.closest('[role="button"]');
  if (roleButton && !roleButton.hasAttribute('data-list-row')) {
    return true;
  }
  return false;
}

export function bindingHasModifier(binding: KeyBinding): boolean {
  return (
    binding.ctrlKey === true ||
    binding.metaKey === true ||
    binding.altKey === true ||
    binding.shiftKey === true
  );
}

export function isActivationKeyBinding(binding: KeyBinding): boolean {
  return (binding.code === 'Space' || binding.code === 'Enter') && !bindingHasModifier(binding);
}

export function isMac(): boolean {
  return navigator.platform.toUpperCase().indexOf('MAC') >= 0;
}

export function formatKeyBinding(binding: KeyBinding): string {
  const parts: string[] = [];

  if (binding.ctrlKey) {
    parts.push(isMac() ? 'Cmd' : 'Ctrl');
  }

  if (binding.altKey) {
    parts.push(isMac() ? 'Option' : 'Alt');
  }

  if (binding.shiftKey) {
    parts.push('Shift');
  }

  parts.push(codeToKeyName(binding.code));

  return parts.join('+');
}

function codeToKeyName(code: string): string {
  if (code.startsWith('Key')) {
    return code.slice(3);
  }

  if (code.startsWith('Digit')) {
    return code.slice(5);
  }

  const specialKeys: Record<string, string> = {
    Escape: 'Esc',
    Delete: 'Del',
    Backspace: 'Backspace',
    Enter: 'Enter',
    Space: 'Space',
    ArrowUp: '↑',
    ArrowDown: '↓',
    ArrowLeft: '←',
    ArrowRight: '→',
    Tab: 'Tab',
  };

  return specialKeys[code] || code;
}

export function parseShortcutString(shortcutString: string): KeyBinding | null {
  const parts = shortcutString.split('+').map((p) => p.trim().toLowerCase());

  if (parts.length === 0) {
    return null;
  }

  const binding: KeyBinding = {
    code: '',
    ctrlKey: false,
    shiftKey: false,
    altKey: false,
  };

  for (const part of parts) {
    switch (part) {
      case 'ctrl':
      case 'cmd':
      case 'command':
        binding.ctrlKey = true;
        break;
      case 'shift':
        binding.shiftKey = true;
        break;
      case 'alt':
      case 'option':
        binding.altKey = true;
        break;
      default:
        binding.code = keyNameToCode(part);
        break;
    }
  }

  if (!binding.code) {
    return null;
  }

  return binding;
}

function keyNameToCode(keyName: string): string {
  const normalized = keyName.toUpperCase();

  if (normalized.length === 1 && normalized >= 'A' && normalized <= 'Z') {
    return `Key${normalized}`;
  }

  if (normalized.length === 1 && normalized >= '0' && normalized <= '9') {
    return `Digit${normalized}`;
  }

  const specialCodes: Record<string, string> = {
    ESC: 'Escape',
    ESCAPE: 'Escape',
    DEL: 'Delete',
    DELETE: 'Delete',
    BACKSPACE: 'Backspace',
    ENTER: 'Enter',
    RETURN: 'Enter',
    SPACE: 'Space',
    TAB: 'Tab',
  };

  return specialCodes[normalized] || normalized;
}

import { useEffect, useMemo, useRef } from 'react';

import { toggleSessionPlayPause } from '@shared/utils/togglePlayPause';

import { shortcutManager } from './ShortcutManager';
import type { ShortcutHandlers, ShortcutId, UseShortcutsOptions } from './shortcutTypes';

export function useShortcuts(handlers: ShortcutHandlers, options: UseShortcutsOptions = {}): void {
  const { enabled = true } = options;

  const registeredIds = useRef<Set<ShortcutId>>(new Set());

  useEffect(() => {
    if (!enabled) {
      for (const id of registeredIds.current) {
        shortcutManager.unregisterHandler(id);
      }
      registeredIds.current.clear();
      return;
    }

    const handlerEntries = Object.entries(handlers) as [ShortcutId, (() => void) | undefined][];

    const currentIds = new Set<ShortcutId>();

    for (const [id, handler] of handlerEntries) {
      if (handler) {
        shortcutManager.registerHandler(id, handler);
        currentIds.add(id);
      }
    }

    for (const id of registeredIds.current) {
      if (!currentIds.has(id)) {
        shortcutManager.unregisterHandler(id);
      }
    }

    registeredIds.current = currentIds;

    return () => {
      for (const id of registeredIds.current) {
        shortcutManager.unregisterHandler(id);
      }
      registeredIds.current.clear();
    };
  }, [handlers, enabled]);
}

export function useGlobalShortcuts(
  handlers: Pick<ShortcutHandlers, 'global.save' | 'global.saveAs' | 'global.open' | 'global.new'>,
  options: UseShortcutsOptions = {},
): void {
  useShortcuts(handlers, options);
}

export function useListShortcuts(
  handlers: Pick<
    ShortcutHandlers,
    'list.undo' | 'list.redo' | 'list.delete' | 'list.selectAll' | 'list.escape'
  >,
  options: UseShortcutsOptions = {},
): void {
  useShortcuts(handlers, options);
}

export function usePlayerShortcuts(options: UseShortcutsOptions = {}): void {
  const handlers = useMemo(
    () => ({
      'player.togglePlay': toggleSessionPlayPause,
    }),
    [],
  );

  useShortcuts(handlers, options);
}

import { createWithEqualityFn } from 'zustand/traditional';

import {
  createInitialAimpBridgeState,
  type AimpBridgeState,
  type AimpSourceSelection,
} from '../contracts/aimp';
import { getPlatformCapabilities } from '../platform/platformCapabilities';
import { isPlatformInitialized } from '../platform/platformContext';
import { aimpService } from '../services/aimpService';
import {
  createAimpPublishingPathState,
  type AimpPublishingPathState,
  type AimpPublishingPathStatus,
} from '../utils';
import { logger } from '../utils/logger';

let unsubscribeAimpBridge: (() => void) | null = null;
let unsubscribeAimpLog: (() => void) | null = null;
let initializePromise: Promise<void> | null = null;

function canUseRendererAimpBridge(): boolean {
  return isPlatformInitialized() && getPlatformCapabilities().supportsAimpWorkspace;
}

interface AimpStoreState {
  bridgeState: AimpBridgeState;
  isInitialized: boolean;
  isInitializing: boolean;
  lastError: string | null;
  publishingBridgeReady: boolean;
  publishingPath: AimpPublishingPathState;
  setBridgeState: (bridgeState: AimpBridgeState) => void;
  setPublishingBridgeReady: (publishingBridgeReady: boolean) => void;
  setPublishingPathState: (status: AimpPublishingPathStatus, error?: string | null) => void;
  initialize: () => Promise<void>;
  syncSourceSelection: (sourceSelection: AimpSourceSelection) => Promise<AimpBridgeState>;
  setLiveStreamStarted: (liveStreamStarted: boolean) => Promise<AimpBridgeState>;
  resetBridgeState: () => void;
}

export const useAimpStore = createWithEqualityFn<AimpStoreState>()((set, get) => ({
  bridgeState: createInitialAimpBridgeState(),
  isInitialized: false,
  isInitializing: false,
  lastError: null,
  publishingBridgeReady: false,
  publishingPath: createAimpPublishingPathState('idle'),

  setBridgeState: (bridgeState) =>
    set({
      bridgeState,
      lastError: null,
    }),

  setPublishingBridgeReady: (publishingBridgeReady) =>
    set({
      publishingBridgeReady,
      publishingPath: createAimpPublishingPathState(publishingBridgeReady ? 'ready' : 'idle'),
    }),

  setPublishingPathState: (status, error = null) =>
    set({
      publishingBridgeReady: status === 'ready',
      publishingPath: createAimpPublishingPathState(status, error),
    }),

  initialize: async () => {
    if (get().isInitialized || !canUseRendererAimpBridge()) {
      set({ isInitialized: true });
      return;
    }

    if (initializePromise) {
      await initializePromise;
      return;
    }

    set({
      isInitializing: true,
      lastError: null,
    });

    initializePromise = (async () => {
      try {
        const bridgeState = await aimpService.getState();
        set({
          bridgeState,
          isInitialized: true,
          lastError: null,
        });

        if (!unsubscribeAimpBridge) {
          unsubscribeAimpBridge = aimpService.subscribe((nextBridgeState) => {
            useAimpStore.getState().setBridgeState(nextBridgeState);
          });
        }
        if (!unsubscribeAimpLog) {
          unsubscribeAimpLog = aimpService.subscribeToLog((entry) => {
            const prefix = `[AIMP ${entry.level}] ${entry.event}: ${entry.message}`;
            if (
              entry.data !== undefined &&
              entry.data !== null &&
              Object.keys(entry.data as object).length > 0
            ) {
              console.log(prefix, entry.data);
            } else {
              console.log(prefix);
            }
          });
        }
      } catch (error) {
        const message =
          error instanceof Error ? error.message : 'Failed to initialize AIMP renderer state';
        logger.error('[AIMP] Failed to initialize renderer store', error);
        set({
          lastError: message,
        });
        throw error;
      } finally {
        set({
          isInitializing: false,
        });
        initializePromise = null;
      }
    })();

    await initializePromise;
  },

  syncSourceSelection: async (sourceSelection) => {
    if (!canUseRendererAimpBridge()) {
      const bridgeState = {
        ...get().bridgeState,
        sourceSelection,
      };
      set({ bridgeState, isInitialized: true });
      return bridgeState;
    }

    await get().initialize();
    const bridgeState = await aimpService.setSourceSelection(sourceSelection);
    set({
      bridgeState,
      lastError: null,
    });
    return bridgeState;
  },

  setLiveStreamStarted: async (liveStreamStarted) => {
    if (!canUseRendererAimpBridge()) {
      const bridgeState = {
        ...get().bridgeState,
        liveStreamStarted,
      };
      set({ bridgeState, isInitialized: true });
      return bridgeState;
    }

    await get().initialize();
    const bridgeState = await aimpService.setLiveStreamStarted(liveStreamStarted);
    set({
      bridgeState,
      lastError: null,
    });
    return bridgeState;
  },

  resetBridgeState: () =>
    set({
      bridgeState: createInitialAimpBridgeState(),
      publishingBridgeReady: false,
      publishingPath: createAimpPublishingPathState('idle'),
      lastError: null,
      isInitialized: canUseRendererAimpBridge() ? get().isInitialized : true,
      isInitializing: false,
    }),
}));

import { create } from 'zustand';

interface ClientOutdatedState {
  isOutdated: boolean;
  requiredVersion: string | null;
  markOutdated: (requiredVersion?: string) => void;
  resetOutdated: () => void;
}

export const useClientOutdatedStore = create<ClientOutdatedState>((set) => ({
  isOutdated: false,
  requiredVersion: null,
  markOutdated: (requiredVersion) =>
    set((state) => {
      const version =
        typeof requiredVersion === 'string' && requiredVersion.trim() !== ''
          ? requiredVersion.trim()
          : state.requiredVersion;

      if (state.isOutdated) {
        return { requiredVersion: version };
      }

      return { isOutdated: true, requiredVersion: version };
    }),
  resetOutdated: () => set({ isOutdated: false, requiredVersion: null }),
}));

export function notifyClientOutdated(requiredVersion?: string): void {
  useClientOutdatedStore.getState().markOutdated(requiredVersion);
}

export function isClientOutdated(): boolean {
  return useClientOutdatedStore.getState().isOutdated;
}

export function resetClientOutdatedState(): void {
  useClientOutdatedStore.getState().resetOutdated();
}

