import type { PartyTrackDisplaySettings, ProjectItem } from '@core/types/project';
import type { AimpPlaylistSnapshotDto } from '@shared/contracts/aimp';
import { convertAimpPlaylistForApi, convertPlaylistForApi } from '@shared/utils';

import type { PlaylistForApiPayload } from './PlaybackBroadcastSource';

export type PartyPlaylistSource = 'aimp' | 'project';

export function resolvePlaylistSource(params: {
  streamingSource: string;
  aimpPlaylistSnapshot: AimpPlaylistSnapshotDto | null;
}): PartyPlaylistSource {
  if (
    params.streamingSource === 'aimp' &&
    params.aimpPlaylistSnapshot != null &&
    params.aimpPlaylistSnapshot.tracks.length > 0
  ) {
    return 'aimp';
  }
  return 'project';
}

export function buildPlaylistForApiPayload(params: {
  streamingSource: string;
  aimpPlaylistSnapshot: AimpPlaylistSnapshotDto | null;
  items: ProjectItem[];
  partyTrackDisplay: PartyTrackDisplaySettings;
}): PlaylistForApiPayload {
  const { streamingSource, aimpPlaylistSnapshot, items, partyTrackDisplay } = params;
  if (
    resolvePlaylistSource({ streamingSource, aimpPlaylistSnapshot }) === 'aimp' &&
    aimpPlaylistSnapshot
  ) {
    return convertAimpPlaylistForApi(aimpPlaylistSnapshot, partyTrackDisplay);
  }
  return convertPlaylistForApi(items, partyTrackDisplay);
}

export type CherryPlayPublishOperation = 'playlistPublish' | 'fullStatePublish';

export const CHERRYPLAY_RECONNECTION_FAILED_MESSAGE =
  'Не удалось автоматически переподключиться к серверу трансляции.';

export const CHERRYPLAY_RECONNECT_ACTION_LABEL = 'Переподключить';

const TOAST_COALESCE_MS = 8_000;

function errorDetail(error: unknown): string {
  if (error instanceof Error && error.message.trim()) {
    return error.message;
  }
  if (typeof error === 'string' && error.trim()) {
    return error;
  }
  return '';
}

export function mapCherryPlayStreamingErrorPhrase(error: unknown): string {
  const detail = errorDetail(error).toLowerCase();
  if (!detail) {
    return 'неизвестная ошибка';
  }
  if (
    detail.includes('failed to fetch') ||
    detail.includes('networkerror') ||
    detail.includes('network request failed') ||
    detail.includes('err_network') ||
    detail.includes('offline')
  ) {
    return 'нет сети';
  }
  if (detail.includes('timeout') || detail.includes('timed out')) {
    return 'таймаут';
  }
  if (detail.includes('401') || detail.includes('unauthorized')) {
    return 'нет авторизации';
  }
  if (detail.includes('403') || detail.includes('forbidden')) {
    return 'доступ запрещён';
  }
  if (detail.includes('404') || detail.includes('not found')) {
    return 'не найдено';
  }
  if (
    detail.includes('500') ||
    detail.includes('502') ||
    detail.includes('503') ||
    detail.includes('internal server')
  ) {
    return 'ошибка сервера';
  }
  if (detail.includes('websocket') || detail.includes('connection') || detail.includes('connect')) {
    return 'нет соединения';
  }
  return 'неизвестная ошибка';
}

export function formatCherryPlayConnectError(error: unknown): string {
  return `Не удалось подключиться к трансляции: ${mapCherryPlayStreamingErrorPhrase(error)}`;
}

export function formatCherryPlayPublishError(
  operation: CherryPlayPublishOperation,
  error: unknown,
): string {
  const phrase = mapCherryPlayStreamingErrorPhrase(error);
  if (operation === 'playlistPublish') {
    return `Не удалось синхронизировать плейлист на сервер: ${phrase}`;
  }
  return `Не удалось опубликовать состояние трансляции: ${phrase}`;
}

export type CherryPlayStreamingNotify = (notification: {
  type: 'error' | 'warning';
  message: string;
  duration: number;
  action?: { label: string; onAction: () => void };
}) => void;

export interface CherryPlayStreamingErrorHandlerOptions {
  onReconnect?: () => void;
}

export function createCherryPlayStreamingErrorHandlers(
  notify: CherryPlayStreamingNotify,
  options?: CherryPlayStreamingErrorHandlerOptions,
) {
  const lastNotifiedAt = new Map<string, number>();

  const shouldNotify = (key: string): boolean => {
    const now = Date.now();
    const previous = lastNotifiedAt.get(key) ?? 0;
    if (now - previous < TOAST_COALESCE_MS) {
      return false;
    }
    lastNotifiedAt.set(key, now);
    return true;
  };

  return {
    onConnectError: (error: unknown) => {
      if (!shouldNotify('connect')) {
        return;
      }
      notify({
        type: 'error',
        message: formatCherryPlayConnectError(error),
        duration: 6000,
      });
    },
    onPublishError: (operation: CherryPlayPublishOperation, error: unknown) => {
      if (!shouldNotify(`publish:${operation}`)) {
        return;
      }
      notify({
        type: 'error',
        message: formatCherryPlayPublishError(operation, error),
        duration: 6000,
      });
    },
    onReconnectionFailed: () => {
      if (!shouldNotify('reconnectionFailed')) {
        return;
      }
      notify({
        type: 'warning',
        message: CHERRYPLAY_RECONNECTION_FAILED_MESSAGE,
        duration: 8000,
        action: options?.onReconnect
          ? { label: CHERRYPLAY_RECONNECT_ACTION_LABEL, onAction: options.onReconnect }
          : undefined,
      });
    },
  };
}

import { getPlatformCapabilities } from '../platform/platformCapabilities';
import { isPlatformInitialized } from '../platform/platformContext';

export interface StreamingNetworkPolicySettings {
  readonly enableStreaming: boolean;
}

export interface OnlineNetworkPolicy {
  readonly networkEnabled: boolean;
  readonly partyDiscoverabilityEnabled: boolean;
}

export function isStreamingNetworkEnabled(
  settings: Pick<StreamingNetworkPolicySettings, 'enableStreaming'>,
): boolean {
  return settings.enableStreaming;
}

export function isStreamingHubAllowed(
  settings: Pick<StreamingNetworkPolicySettings, 'enableStreaming'>,
): boolean {
  if (!isStreamingNetworkEnabled(settings)) {
    return false;
  }
  if (!isPlatformInitialized()) {
    return false;
  }
  return getPlatformCapabilities().supportsRealAuth;
}

export function isPartyDiscoverabilityEnabled(
  _settings?: Pick<StreamingNetworkPolicySettings, 'enableStreaming'>,
): boolean {
  return true;
}

export function getOnlineNetworkPolicy(
  settings: StreamingNetworkPolicySettings,
): OnlineNetworkPolicy {
  return {
    networkEnabled: isStreamingNetworkEnabled(settings),
    partyDiscoverabilityEnabled: isPartyDiscoverabilityEnabled(settings),
  };
}

import { partyService } from '../services/partyService';
import { useAimpStore } from '../stores/aimpStore';
import { useProjectStore } from '../stores/projectStore';
import { getAimpPlaylistPublishKey } from '../utils/aimpStreamingAdapter';

import type { PlaylistForApiPayload } from './PlaybackBroadcastSource';

export async function syncPartyPlaylist(
  partyId: string,
  payload: PlaylistForApiPayload,
  onSynced?: (payload: PlaylistForApiPayload) => void,
): Promise<void> {
  console.log('[PartyPlaylistSync] → Sending PUT request to update playlist:', {
    partyId,
    itemsCount: payload.items.length,
    timestamp: new Date().toISOString(),
  });

  await partyService.updatePartyPlaylist(partyId, payload);
  onSynced?.(payload);

  console.log('[PartyPlaylistSync] ✓ Playlist updated successfully');
}

export function subscribePartyPlaylistSync(
  partyId: string,
  getPayload: () => PlaylistForApiPayload,
  onAfterSync: () => void,
  onSyncError?: (error: unknown) => void,
  onSynced?: (payload: PlaylistForApiPayload) => void,
): () => void {
  let isInitialCall = true;

  return useProjectStore.subscribe(() => {
    if (isInitialCall) {
      isInitialCall = false;
      return;
    }

    const projectState = useProjectStore.getState();
    console.log('[PartyPlaylistSync] Playlist changed:', {
      itemsCount: projectState.items.length,
      timestamp: new Date().toISOString(),
    });

    const payload = getPayload();
    void syncPartyPlaylist(partyId, payload, onSynced)
      .then(() => {
        onAfterSync();
      })
      .catch((error) => {
        console.error('[PartyPlaylistSync] ✗ Failed to update playlist:', error);
        onSyncError?.(error);
      });
  });
}

export function subscribeAimpPartyPlaylistSync(
  partyId: string,
  getPayload: () => PlaylistForApiPayload,
  onAfterSync: () => void,
  onSyncError?: (error: unknown) => void,
  onSynced?: (payload: PlaylistForApiPayload) => void,
): () => void {
  let lastPublishedKey: string | null = null;

  return useAimpStore.subscribe(() => {
    const bridgeState = useAimpStore.getState().bridgeState;
    if (!bridgeState.liveStreamStarted) {
      lastPublishedKey = null;
      return;
    }

    const publishKey = getAimpPlaylistPublishKey(bridgeState.playlistSnapshot);
    if (publishKey === null || publishKey === lastPublishedKey) {
      return;
    }

    const payload = getPayload();
    syncPartyPlaylist(partyId, payload, onSynced)
      .then(() => {
        lastPublishedKey = publishKey;
        onAfterSync();
      })
      .catch((error) => {
        console.error('[PartyPlaylistSync] ✗ Failed to update AIMP playlist:', error);
        onSyncError?.(error);
      });
  });
}

import * as signalR from '@microsoft/signalr';

import { isDefinitivePartyExistenceError } from '../services/partyExistenceErrors';
import { partyService } from '../services/partyService';
import { signalRService } from '../services/signalRService';
import { logger } from '../utils';

import { AimpBroadcastSource } from './AimpBroadcastSource';
import { isStreamingHubAllowed } from './onlineNetworkPolicy';
import type { StreamingNetworkPolicySettings } from './onlineNetworkPolicy';
import { subscribeAimpPartyPlaylistSync, subscribePartyPlaylistSync } from './partyPlaylistSync';
import type { PlaybackBroadcastSource, PlaylistForApiPayload } from './PlaybackBroadcastSource';

export interface StreamingOrchestratorConfig {
  partyId: string;
  broadcastSource: PlaybackBroadcastSource;
  streamingSource: 'cherryPlayPlayer' | 'aimp';
  networkSettings: Pick<StreamingNetworkPolicySettings, 'enableStreaming'>;
  onConnectionStateChange?: (state: signalR.HubConnectionState | null) => void;
  onPartyNotFound?: () => void;
  onConnectError?: (error: unknown) => void;
  onPublishError?: (operation: 'playlistPublish' | 'fullStatePublish', error: unknown) => void;
  onPublishSuccess?: () => void;
  onPlaylistSynced?: (payload: PlaylistForApiPayload) => void;
  onReconnectionFailed?: () => void;
}

const RECONNECT_DELAY_MS = 10_000;
const POSITION_TICK_MS = 1_000;
const FULL_STATE_COALESCE_MS = 50;

export class StreamingOrchestrator {
  private config: StreamingOrchestratorConfig | null = null;
  private running = false;
  private connectInFlight: Promise<void> | null = null;
  private connectGeneration = 0;
  private sourceUnsubscribe: (() => void) | null = null;
  private playlistUnsubscribe: (() => void) | null = null;
  private positionInterval: NodeJS.Timeout | null = null;
  private reconnectTimeout: NodeJS.Timeout | null = null;
  private fullStateCoalesceTimer: NodeJS.Timeout | null = null;
  private liveSessionActive = false;
  private frozenStatePublishKey: string | null = null;
  private lifecycleTail: Promise<void> = Promise.resolve();

  start(config: StreamingOrchestratorConfig): void {
    void this.enqueueLifecycle(() => this.applyStart(config));
  }

  stop(): void {
    void this.enqueueLifecycle(async () => {
      this.stopInternal(true);
    });
  }

  async teardown(): Promise<void> {
    return this.enqueueLifecycle(() => this.applyTeardown());
  }

  async switchSource(config: StreamingOrchestratorConfig): Promise<void> {
    return this.enqueueLifecycle(() => this.applyStart(config));
  }

  private enqueueLifecycle<T>(operation: () => Promise<T>): Promise<T> {
    const next = this.lifecycleTail.then(operation, operation);
    this.lifecycleTail = next.then(
      () => undefined,
      () => undefined,
    );
    return next;
  }

  private async applyStart(config: StreamingOrchestratorConfig): Promise<void> {
    if (!isStreamingHubAllowed(config.networkSettings)) {
      await this.applyTeardown();
      return;
    }

    const previousConfig = this.config;
    const sameConfig =
      this.running &&
      previousConfig?.partyId === config.partyId &&
      previousConfig.broadcastSource.sourceId === config.broadcastSource.sourceId &&
      previousConfig.streamingSource === config.streamingSource;

    if (sameConfig) {
      this.config = config;
      return;
    }

    const switchingSource =
      previousConfig !== null &&
      (previousConfig.streamingSource !== config.streamingSource ||
        previousConfig.broadcastSource.sourceId !== config.broadcastSource.sourceId);

    this.config = config;

    if (switchingSource) {
      await this.applyTeardown(false);
    } else if (this.running) {
      this.stopInternal(false);
    }

    this.running = true;
    signalRService.setPartyReconnectHandler((partyId) => this.restoreAfterReconnect(partyId));
    signalRService.onReconnectionFailed(() => {
      this.handleHubReconnectionExhausted();
    });
    await this.connectAndSubscribe();
  }

  private async applyTeardown(clearConfig = true): Promise<void> {
    const partyId = this.config?.partyId;
    const source = this.config?.broadcastSource;

    this.stopInternal(true);

    if (partyId && source?.isLiveSessionActive()) {
      await signalRService.endSession(partyId);
    }

    if (partyId && signalRService.isServiceConnected()) {
      await signalRService.resetPlaybackState(partyId);
    }

    await signalRService.disconnect();

    if (clearConfig) {
      this.config = null;
    }
  }

  reconnect(): void {
    if (!this.config || !this.running) {
      return;
    }
    void this.connectAndSubscribe();
  }

  syncAimpFrozenState(enableStreaming: boolean): void {
    const config = this.config;
    const partyId = config?.partyId;

    if (!partyId || !this.running || config.streamingSource !== 'aimp') {
      this.frozenStatePublishKey = null;
      return;
    }

    const source = config.broadcastSource;
    if (!(source instanceof AimpBroadcastSource)) {
      this.frozenStatePublishKey = null;
      return;
    }

    const snapshot = source.getFrozenStateSnapshot(enableStreaming);
    if (!snapshot) {
      this.frozenStatePublishKey = null;
      return;
    }

    if (this.frozenStatePublishKey === snapshot.key) {
      return;
    }

    this.frozenStatePublishKey = snapshot.key;

    if (!signalRService.isServiceConnected()) {
      return;
    }

    void signalRService
      .notifyStateChangedOrThrow(partyId)
      .then(() => signalRService.updateFullStateOrThrow(partyId, snapshot.dto))
      .then(() => {
        config.onPublishSuccess?.();
      })
      .catch((error) => {
        logger.error('[StreamingOrchestrator] Failed to publish frozen AIMP state', error);
        config.onPublishError?.('fullStatePublish', error);
      });
  }

  syncLiveSession(isLive: boolean): void {
    const partyId = this.config?.partyId;
    if (!partyId || !this.running || !signalRService.isServiceConnected()) {
      return;
    }

    if (isLive) {
      if (!this.liveSessionActive) {
        this.startPositionTicks(partyId);
        signalRService
          .startSession(partyId)
          .catch((err) => logger.error('[StreamingOrchestrator] Failed to start session', err));
        this.liveSessionActive = true;
      } else if (!this.positionInterval) {
        this.startPositionTicks(partyId);
      }
      return;
    }

    if (this.liveSessionActive) {
      if (this.config?.streamingSource === 'aimp') {
        signalRService.endSession(partyId).catch((err) => {
          logger.error('[StreamingOrchestrator] Failed to end AIMP session', err);
        });
        signalRService.resetPlaybackState(partyId).catch((err) => {
          logger.error('[StreamingOrchestrator] Failed to reset AIMP playback state', err);
        });
      }
      this.liveSessionActive = false;
    }

    this.stopPositionTicks();
  }

  async resetServerPlaybackState(): Promise<void> {
    const partyId = this.config?.partyId;
    if (!partyId) {
      return;
    }

    this.stopPositionTicks();
    await signalRService.resetPlaybackState(partyId);
  }

  publishFullState(): void {
    const partyId = this.config?.partyId;
    if (!partyId || !signalRService.isServiceConnected()) {
      return;
    }
    this.publishFullStateNow(partyId);
  }

  get isRunning(): boolean {
    return this.running;
  }

  get activeConfig(): StreamingOrchestratorConfig | null {
    return this.config;
  }

  private stopInternal(clearReconnectHandler: boolean): void {
    this.connectGeneration += 1;
    this.connectInFlight = null;
    this.running = false;
    this.liveSessionActive = false;
    this.frozenStatePublishKey = null;

    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }

    if (this.fullStateCoalesceTimer) {
      clearTimeout(this.fullStateCoalesceTimer);
      this.fullStateCoalesceTimer = null;
    }

    this.stopSourceSubscriptions();
    this.stopPositionTicks();

    if (clearReconnectHandler) {
      signalRService.setPartyReconnectHandler(null);
      signalRService.onReconnectionFailed(undefined);
    }
  }

  private scheduleReconnect(generation: number): void {
    if (!this.running || generation !== this.connectGeneration) {
      return;
    }

    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
    }

    this.reconnectTimeout = setTimeout(() => {
      this.reconnectTimeout = null;
      if (this.running && generation === this.connectGeneration) {
        void this.connectAndSubscribe();
      }
    }, RECONNECT_DELAY_MS);
  }

  private handleHubReconnectionExhausted(): void {
    if (!this.running || !this.config) {
      return;
    }

    this.config.onReconnectionFailed?.();
    this.config.onConnectionStateChange?.(signalR.HubConnectionState.Disconnected);
    this.scheduleReconnect(this.connectGeneration);
  }

  private async connectAndSubscribe(): Promise<void> {
    const config = this.config;
    if (!config || !this.running) {
      return;
    }

    if (this.connectInFlight) {
      return this.connectInFlight;
    }

    const generation = this.connectGeneration;
    this.connectInFlight = this.doConnectAndSubscribe(config, generation).finally(() => {
      if (this.connectGeneration === generation) {
        this.connectInFlight = null;
      }
    });

    return this.connectInFlight;
  }

  private async doConnectAndSubscribe(
    config: StreamingOrchestratorConfig,
    generation: number,
  ): Promise<void> {
    const { partyId, onConnectionStateChange, onPartyNotFound } = config;

    if (this.reconnectTimeout) {
      clearTimeout(this.reconnectTimeout);
      this.reconnectTimeout = null;
    }

    try {
      const exists = await partyService.checkPartyExists(partyId);
      if (generation !== this.connectGeneration || !this.running) {
        return;
      }

      if (!exists) {
        logger.warn(
          '[StreamingOrchestrator] Party does not exist on server, skipping SignalR connection',
        );
        onConnectionStateChange?.(signalR.HubConnectionState.Disconnected);
        onPartyNotFound?.();
        return;
      }
    } catch (error) {
      logger.error('[StreamingOrchestrator] Failed to check party existence:', error);
      onConnectionStateChange?.(signalR.HubConnectionState.Disconnected);
      if (isDefinitivePartyExistenceError(error)) {
        config.onConnectError?.(error);
        return;
      }
      this.scheduleReconnect(generation);
      return;
    }

    if (signalRService.isServiceConnected()) {
      onConnectionStateChange?.(signalR.HubConnectionState.Connected);
      this.startSourceSubscriptions(partyId);
      this.syncLiveSession(config.broadcastSource.isLiveSessionActive());
      return;
    }

    try {
      logger.info('[StreamingOrchestrator] Connecting to SignalR for party', partyId);
      onConnectionStateChange?.(signalR.HubConnectionState.Connecting);

      await signalRService.connect();
      if (generation !== this.connectGeneration || !this.running) {
        return;
      }

      await signalRService.joinPartyAsOrganizer(partyId);
      if (generation !== this.connectGeneration || !this.running) {
        return;
      }

      this.startSourceSubscriptions(partyId);
      this.publishFullStateNow(partyId);
      this.syncLiveSession(config.broadcastSource.isLiveSessionActive());
      onConnectionStateChange?.(signalR.HubConnectionState.Connected);
    } catch (error) {
      logger.error('[StreamingOrchestrator] Failed to connect to SignalR:', error);
      config.onConnectError?.(error);
      onConnectionStateChange?.(signalR.HubConnectionState.Disconnected);
      this.scheduleReconnect(generation);
    }
  }

  private async restoreAfterReconnect(partyId: string): Promise<void> {
    if (!this.running || this.config?.partyId !== partyId) {
      return;
    }

    try {
      logger.info('[StreamingOrchestrator] Restoring party connection after reconnect:', partyId);
      this.startSourceSubscriptions(partyId);
      this.syncLiveSession(this.config.broadcastSource.isLiveSessionActive());
      this.publishFullStateNow(partyId);
      this.config.onConnectionStateChange?.(signalR.HubConnectionState.Connected);
    } catch (error) {
      logger.error('[StreamingOrchestrator] Failed to restore after reconnect:', error);
    }
  }

  private startSourceSubscriptions(partyId: string): void {
    const config = this.config;
    if (!config) {
      return;
    }

    this.stopSourceSubscriptions();

    this.sourceUnsubscribe = config.broadcastSource.subscribe(() => {
      this.scheduleFullStatePublish(partyId);
    });

    if (config.broadcastSource.sourceId === 'aimp') {
      this.playlistUnsubscribe = subscribeAimpPartyPlaylistSync(
        partyId,
        () => config.broadcastSource.getPlaylistForApi(),
        () => {
          this.scheduleFullStatePublish(partyId);
        },
        (error) => {
          config.onPublishError?.('playlistPublish', error);
        },
        (payload) => {
          config.onPlaylistSynced?.(payload);
        },
      );
      return;
    }

    this.playlistUnsubscribe = subscribePartyPlaylistSync(
      partyId,
      () => config.broadcastSource.getPlaylistForApi(),
      () => {
        this.scheduleFullStatePublish(partyId);
      },
      (error) => {
        config.onPublishError?.('playlistPublish', error);
      },
      (payload) => {
        config.onPlaylistSynced?.(payload);
      },
    );
  }

  private stopSourceSubscriptions(): void {
    if (this.sourceUnsubscribe) {
      this.sourceUnsubscribe();
      this.sourceUnsubscribe = null;
    }

    if (this.playlistUnsubscribe) {
      this.playlistUnsubscribe();
      this.playlistUnsubscribe = null;
    }
  }

  private scheduleFullStatePublish(partyId: string): void {
    if (this.fullStateCoalesceTimer) {
      return;
    }

    this.fullStateCoalesceTimer = setTimeout(() => {
      this.fullStateCoalesceTimer = null;
      this.publishFullStateNow(partyId);
    }, FULL_STATE_COALESCE_MS);
  }

  private publishFullStateNow(partyId: string): void {
    if (!signalRService.isServiceConnected()) {
      return;
    }

    const source = this.config?.broadcastSource;
    if (!source) {
      return;
    }

    if (source.sourceId === 'aimp' && !source.isLiveSessionActive()) {
      return;
    }

    const playbackState = source.getPlaybackStateDto();
    void signalRService
      .notifyStateChangedOrThrow(partyId)
      .then(() => signalRService.updateFullStateOrThrow(partyId, playbackState))
      .then(() => {
        this.config?.onPublishSuccess?.();
      })
      .catch((error) => {
        logger.error('[StreamingOrchestrator] Failed to publish full state', error);
        this.config?.onPublishError?.('fullStatePublish', error);
      });
  }

  private startPositionTicks(partyId: string): void {
    this.stopPositionTicks();

    this.positionInterval = setInterval(() => {
      if (!signalRService.isServiceConnected() || !this.config) {
        return;
      }

      const source = this.config.broadcastSource;
      if (!source.shouldSendPositionTicks()) {
        return;
      }

      const trackId = source.getCurrentTrackId();
      if (!trackId) {
        return;
      }

      const position = source.getPosition();
      signalRService.updatePlaybackPosition(partyId, trackId, position);
    }, POSITION_TICK_MS);
  }

  private stopPositionTicks(): void {
    if (this.positionInterval) {
      clearInterval(this.positionInterval);
      this.positionInterval = null;
    }
  }
}

export const streamingOrchestrator = new StreamingOrchestrator();

import * as signalR from '@microsoft/signalr';
import { useEffect, useRef } from 'react';

import { useSettingsStore } from '../stores';
import { useAimpStore } from '../stores/aimpStore';
import {
  formatAimpPublishingPathError,
  shouldApplyAimpDisconnectedPublishingError,
} from '../utils/aimpPublishingPath';

import { AimpBroadcastSource } from './AimpBroadcastSource';
import { isStreamingHubAllowed } from './onlineNetworkPolicy';
import type { PlaylistForApiPayload } from './PlaybackBroadcastSource';
import { streamingOrchestrator } from './streamingOrchestrator';

export interface UseAimpStreamingOrchestratorOptions {
  partyId: string | null;
  hasHydrated: boolean;
  onPartyNotFound?: () => void;
  onPlaylistSynced?: (payload: PlaylistForApiPayload) => void;
}

export function useAimpStreamingOrchestrator(options: UseAimpStreamingOrchestratorOptions): void {
  const { partyId, hasHydrated, onPartyNotFound, onPlaylistSynced } = options;
  const enableStreaming = useSettingsStore((state) => state.enableStreaming);
  const streamingSource = useSettingsStore((state) => state.streamingSource);
  const bridgeState = useAimpStore((state) => state.bridgeState);
  const liveStreamStarted = bridgeState.liveStreamStarted;
  const publishingBridgeReady = useAimpStore((state) => state.publishingBridgeReady);
  const connectionPhase = bridgeState.connection.phase;
  const playbackStatus = bridgeState.playbackSnapshot?.status;
  const setPublishingPathState = useAimpStore((state) => state.setPublishingPathState);

  const broadcastSourceRef = useRef(new AimpBroadcastSource());
  const onPartyNotFoundRef = useRef(onPartyNotFound);
  const onPlaylistSyncedRef = useRef(onPlaylistSynced);

  useEffect(() => {
    onPartyNotFoundRef.current = onPartyNotFound;
  }, [onPartyNotFound]);

  useEffect(() => {
    onPlaylistSyncedRef.current = onPlaylistSynced;
  }, [onPlaylistSynced]);

  const hubAllowed = isStreamingHubAllowed({ enableStreaming });
  const orchestratorActive =
    hasHydrated && hubAllowed && streamingSource === 'aimp' && partyId !== null;

  useEffect(() => {
    if (!orchestratorActive || !partyId) {
      setPublishingPathState('idle');
      return;
    }

    setPublishingPathState('connecting');
    streamingOrchestrator.start({
      partyId,
      broadcastSource: broadcastSourceRef.current,
      streamingSource: 'aimp',
      networkSettings: { enableStreaming },
      onConnectionStateChange: (state) => {
        if (state === signalR.HubConnectionState.Connecting) {
          setPublishingPathState('connecting');
        } else if (state === signalR.HubConnectionState.Connected) {
          setPublishingPathState('ready');
        } else if (state === signalR.HubConnectionState.Disconnected) {
          const currentStatus = useAimpStore.getState().publishingPath.status;
          if (!shouldApplyAimpDisconnectedPublishingError(currentStatus)) {
            return;
          }
          setPublishingPathState(
            'error',
            formatAimpPublishingPathError('verifyPartyExists', new Error('disconnected')),
          );
        }
      },
      onPartyNotFound: () => {
        setPublishingPathState('error', formatAimpPublishingPathError('checkPartyExists'));
        onPartyNotFoundRef.current?.();
      },
      onConnectError: (error) => {
        setPublishingPathState('error', formatAimpPublishingPathError('connect', error));
      },
      onPublishError: (operation, error) => {
        setPublishingPathState('error', formatAimpPublishingPathError(operation, error));
      },
      onPublishSuccess: () => {
        setPublishingPathState('ready');
      },
      onPlaylistSynced: (payload) => onPlaylistSyncedRef.current?.(payload),
    });

    return () => {
      if (streamingOrchestrator.activeConfig?.streamingSource === 'aimp') {
        void streamingOrchestrator.teardown();
      }
    };
  }, [orchestratorActive, partyId, enableStreaming, setPublishingPathState, streamingSource]);

  useEffect(() => {
    if (!orchestratorActive || !partyId) {
      return;
    }

    streamingOrchestrator.syncLiveSession(broadcastSourceRef.current.isLiveSessionActive());
  }, [
    orchestratorActive,
    partyId,
    liveStreamStarted,
    publishingBridgeReady,
    connectionPhase,
    playbackStatus,
  ]);

  useEffect(() => {
    if (!orchestratorActive || !partyId) {
      return;
    }

    streamingOrchestrator.syncAimpFrozenState(enableStreaming);
  }, [bridgeState, enableStreaming, orchestratorActive, partyId, publishingBridgeReady]);
}

import { useMemo } from 'react';

import { useSettingsStore } from '@shared/stores';

import { getOnlineNetworkPolicy, type OnlineNetworkPolicy } from './onlineNetworkPolicy';

