import * as signalR from '@microsoft/signalr';
import { useCallback, useEffect, useRef, useState } from 'react';

import { signalRService } from '../services/signalRService';
import { useSettingsStore } from '../stores';

import { CherryPlayPlayerBroadcastSource } from './CherryPlayPlayerBroadcastSource';
import { isStreamingHubAllowed, isStreamingNetworkEnabled } from './onlineNetworkPolicy';
import type { PlaylistForApiPayload } from './PlaybackBroadcastSource';
import { streamingOrchestrator } from './streamingOrchestrator';

export interface UseStreamingOrchestratorOptions {
  partyId: string | null;
  sessionMode: 'preparation' | 'session';
  onPartyNotFound?: () => void;
  onPlaylistSynced?: (payload: PlaylistForApiPayload) => void;
  onConnectError?: (error: unknown) => void;
  onPublishError?: (operation: 'playlistPublish' | 'fullStatePublish', error: unknown) => void;
  onPublishSuccess?: () => void;
  onReconnectionFailed?: () => void;
}

export interface UseStreamingOrchestratorResult {
  connectionState: signalR.HubConnectionState | null;
  reconnect: () => void;
}

export function useStreamingOrchestrator(
  options: UseStreamingOrchestratorOptions,
): UseStreamingOrchestratorResult {
  const {
    partyId,
    sessionMode,
    onPartyNotFound,
    onPlaylistSynced,
    onConnectError,
    onPublishError,
    onPublishSuccess,
    onReconnectionFailed,
  } = options;
  const enableStreaming = useSettingsStore((state) => state.enableStreaming);
  const streamingSource = useSettingsStore((state) => state.streamingSource);

  const [hubConnectionState, setHubConnectionState] = useState<signalR.HubConnectionState | null>(
    null,
  );
  const broadcastSourceRef = useRef(new CherryPlayPlayerBroadcastSource());
  const onPartyNotFoundRef = useRef(onPartyNotFound);
  const onPlaylistSyncedRef = useRef(onPlaylistSynced);
  const onConnectErrorRef = useRef(onConnectError);
  const onPublishErrorRef = useRef(onPublishError);
  const onPublishSuccessRef = useRef(onPublishSuccess);
  const onReconnectionFailedRef = useRef(onReconnectionFailed);

  useEffect(() => {
    onPartyNotFoundRef.current = onPartyNotFound;
  }, [onPartyNotFound]);

  useEffect(() => {
    onPlaylistSyncedRef.current = onPlaylistSynced;
  }, [onPlaylistSynced]);

  useEffect(() => {
    onConnectErrorRef.current = onConnectError;
  }, [onConnectError]);

  useEffect(() => {
    onPublishErrorRef.current = onPublishError;
  }, [onPublishError]);

  useEffect(() => {
    onPublishSuccessRef.current = onPublishSuccess;
  }, [onPublishSuccess]);

  useEffect(() => {
    onReconnectionFailedRef.current = onReconnectionFailed;
  }, [onReconnectionFailed]);

  const networkEnabled = isStreamingNetworkEnabled({ enableStreaming });
  const hubAllowed = isStreamingHubAllowed({ enableStreaming });
  const orchestratorActive =
    hubAllowed && streamingSource === 'cherryPlayPlayer' && partyId !== null;

  const connectionState = networkEnabled && orchestratorActive ? hubConnectionState : null;

  useEffect(() => {
    if (!orchestratorActive || !partyId) {
      if (streamingOrchestrator.activeConfig?.streamingSource === 'cherryPlayPlayer') {
        void streamingOrchestrator.teardown();
      }

      return;
    }

    streamingOrchestrator.start({
      partyId,
      broadcastSource: broadcastSourceRef.current,
      streamingSource: 'cherryPlayPlayer',
      networkSettings: { enableStreaming },
      onConnectionStateChange: setHubConnectionState,
      onPartyNotFound: () => onPartyNotFoundRef.current?.(),
      onPlaylistSynced: (payload) => onPlaylistSyncedRef.current?.(payload),
      onConnectError: (error) => onConnectErrorRef.current?.(error),
      onPublishError: (operation, error) => onPublishErrorRef.current?.(operation, error),
      onPublishSuccess: () => onPublishSuccessRef.current?.(),
      onReconnectionFailed: () => onReconnectionFailedRef.current?.(),
    });

    return () => {
      if (streamingOrchestrator.activeConfig?.streamingSource === 'cherryPlayPlayer') {
        void streamingOrchestrator.teardown();
      }
    };
  }, [orchestratorActive, partyId, enableStreaming, hubAllowed, streamingSource]);

  useEffect(() => {
    if (!orchestratorActive || !partyId) {
      return;
    }

    streamingOrchestrator.syncLiveSession(sessionMode === 'session');
  }, [orchestratorActive, partyId, sessionMode]);

  useEffect(() => {
    if (!orchestratorActive) {
      return;
    }

    const interval = setInterval(() => {
      setHubConnectionState(signalRService.getConnectionState());
    }, 1000);

    return () => clearInterval(interval);
  }, [orchestratorActive]);

  const reconnect = useCallback(() => {
    streamingOrchestrator.reconnect();
  }, []);

  return { connectionState, reconnect };
}

export const TRACK_ITEM_SIZE_PRESETS = ['tiny', 'small', 'medium', 'large'] as const;

export type TrackItemSizePreset = (typeof TRACK_ITEM_SIZE_PRESETS)[number];

export function isTrackItemSizePreset(value: unknown): value is TrackItemSizePreset {
  return (
    typeof value === 'string' && (TRACK_ITEM_SIZE_PRESETS as readonly string[]).includes(value)
  );
}

import type { AimpBridgeState } from '../contracts/aimp';

import { canStartAimpLiveStream } from './aimpStreamingAdapter';
import { logger } from './logger';

export interface AimpOrganizerSessionActions {
  startSession: () => Promise<void>;
  setLiveStreamStarted: (liveStreamStarted: boolean) => Promise<void>;
  endSession: () => Promise<void>;
  resetPlaybackState: () => Promise<void>;
  disconnect?: () => Promise<void>;
}

interface StartAimpOrganizerSessionOptions {
  bridgeState: Pick<
    AimpBridgeState,
    | 'sourceSelection'
    | 'environment'
    | 'connection'
    | 'pluginMetadata'
    | 'playlistSnapshot'
    | 'playbackSnapshot'
  >;
  publishingBridgeReady: boolean;
  actions: AimpOrganizerSessionActions;
}

interface TeardownAimpOrganizerSessionOptions {
  actions: AimpOrganizerSessionActions;
  shouldEndSession: boolean;
  shouldResetPlaybackState: boolean;
  shouldDisconnect: boolean;
}

export async function startAimpOrganizerSession({
  bridgeState,
  publishingBridgeReady,
  actions,
}: StartAimpOrganizerSessionOptions): Promise<void> {
  if (!publishingBridgeReady) {
    throw new Error('AIMP publishing path is not ready yet.');
  }

  if (!canStartAimpLiveStream(bridgeState)) {
    throw new Error('AIMP snapshots and plugin connection are not ready for live streaming yet.');
  }

  await actions.startSession();

  try {
    await actions.setLiveStreamStarted(true);
  } catch (error) {
    await teardownAimpOrganizerSession({
      actions,
      shouldEndSession: true,
      shouldResetPlaybackState: true,
      shouldDisconnect: false,
    });
    throw error;
  }
}

export async function teardownAimpOrganizerSession({
  actions,
  shouldEndSession,
  shouldResetPlaybackState,
  shouldDisconnect,
}: TeardownAimpOrganizerSessionOptions): Promise<void> {
  if (shouldEndSession) {
    try {
      await actions.endSession();
    } catch (error) {
      logger.error('[AIMP] Failed to end organizer session during teardown', error);
    }
  }

  if (shouldResetPlaybackState) {
    try {
      await actions.resetPlaybackState();
    } catch (error) {
      logger.error('[AIMP] Failed to reset organizer playback state during teardown', error);
    }
  }

  if (shouldDisconnect && actions.disconnect) {
    try {
      await actions.disconnect();
    } catch (error) {
      logger.error('[AIMP] Failed to disconnect SignalR during teardown', error);
    }
  }
}

import type {
  AimpEnvironmentEligibility,
  AimpGatingReason,
  AimpSourceSelection,
} from '../contracts/aimp';
import type { LayoutPreset } from '../stores/layoutStore';

export interface AimpPartyPresetState {
  visible: boolean;
  fallbackPreset: Extract<LayoutPreset, 'party' | 'player'>;
  blockingReasons: AimpGatingReason[];
}

/** Single enforce point for built-in `party` layout preset discoverability. */
export function isPartyLayoutPresetDiscoverable(partyDiscoverabilityEnabled: boolean): boolean {
  return partyDiscoverabilityEnabled;
}

export function getAimpPartyPresetState(options: {
  sourceSelection: AimpSourceSelection;
  environment: AimpEnvironmentEligibility;
  partyDiscoverabilityEnabled?: boolean;
  /** @deprecated Use `partyDiscoverabilityEnabled` from `useOnlineNetworkPolicy`. */
  enableStreaming?: boolean;
}): AimpPartyPresetState {
  const fallbackPreset: AimpPartyPresetState['fallbackPreset'] = 'party';
  const partyDiscoverabilityEnabled = options.partyDiscoverabilityEnabled ?? true;

  if (!partyDiscoverabilityEnabled) {
    return {
      visible: false,
      fallbackPreset,
      blockingReasons: [],
    };
  }

  if (options.sourceSelection !== 'aimp') {
    return {
      visible: false,
      fallbackPreset,
      blockingReasons: [
        {
          code: 'sourceNotAimp',
          message: 'AIMP + Party preset is available only while AIMP is selected as the source.',
        },
      ],
    };
  }

  if (!options.environment.eligible) {
    return {
      visible: false,
      fallbackPreset,
      blockingReasons: options.environment.gatingReasons,
    };
  }

  return {
    visible: true,
    fallbackPreset,
    blockingReasons: [],
  };
}

export type AimpPublishingPathStatus = 'idle' | 'connecting' | 'ready' | 'error';

export interface AimpPublishingPathState {
  status: AimpPublishingPathStatus;
  error: string | null;
}

export interface AimpPublishingBridgeServices {
  checkPartyExists: (partyId: string) => Promise<boolean>;
  connect: () => Promise<void>;
  joinPartyAsOrganizer: (partyId: string) => Promise<void>;
}

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : 'Unknown error';
}

export function createAimpPublishingPathState(
  status: AimpPublishingPathStatus,
  error: string | null = null,
): AimpPublishingPathState {
  return {
    status,
    error,
  };
}

export function formatAimpPublishingPathError(
  operation:
    | 'checkPartyExists'
    | 'verifyPartyExists'
    | 'connect'
    | 'joinPartyAsOrganizer'
    | 'playlistPublish'
    | 'fullStatePublish',
  error?: unknown,
): string {
  switch (operation) {
    case 'checkPartyExists':
      return 'Linked Party was not found on the server, so the AIMP publish path cannot start.';
    case 'verifyPartyExists':
      return `Failed to verify the linked Party on the server: ${getErrorMessage(error)}`;
    case 'connect':
      return `Failed to connect the AIMP publish path to SignalR: ${getErrorMessage(error)}`;
    case 'joinPartyAsOrganizer':
      return `Failed to join the linked Party as organizer for AIMP publishing: ${getErrorMessage(
        error,
      )}`;
    case 'playlistPublish':
      return `Failed to publish the latest AIMP playlist to the linked Party: ${getErrorMessage(
        error,
      )}`;
    case 'fullStatePublish':
      return `Failed to publish the latest AIMP playback state to the linked Party: ${getErrorMessage(
        error,
      )}`;
    default:
      return `AIMP publishing failed: ${getErrorMessage(error)}`;
  }
}

/** Keep a more specific connect / not-found error instead of a generic Disconnected overwrite. */
export function shouldApplyAimpDisconnectedPublishingError(
  currentStatus: AimpPublishingPathStatus,
): boolean {
  return currentStatus !== 'error';
}

export async function startAimpPublishingBridge(
  partyId: string,
  services: AimpPublishingBridgeServices,
): Promise<AimpPublishingPathState> {
  let exists: boolean;
  try {
    exists = await services.checkPartyExists(partyId);
  } catch (error) {
    return createAimpPublishingPathState(
      'error',
      formatAimpPublishingPathError('verifyPartyExists', error),
    );
  }

  if (!exists) {
    return createAimpPublishingPathState(
      'error',
      formatAimpPublishingPathError('checkPartyExists'),
    );
  }

  try {
    await services.connect();
  } catch (error) {
    return createAimpPublishingPathState('error', formatAimpPublishingPathError('connect', error));
  }

  try {
    await services.joinPartyAsOrganizer(partyId);
  } catch (error) {
    return createAimpPublishingPathState(
      'error',
      formatAimpPublishingPathError('joinPartyAsOrganizer', error),
    );
  }

  return createAimpPublishingPathState('ready');
}

import {
  DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
  type PartyTrackDisplaySettings,
} from '@core/types/project';

import {
  hasUsableAimpLiveStreamSnapshots,
  normalizeTrackKeyForComparison,
  type AimpBridgeState,
  type AimpConnectionPhase,
  type AimpGatingReason,
  type AimpPlaybackStatus,
  type AimpPlaylistSnapshotDto,
  type AimpPlaylistTrackDto,
} from '../contracts/aimp';
import {
  mapAimpPlaybackStatusToWireStatus,
  type PlaybackStateDto,
} from '../contracts/playbackState';

import { applyPartyTrackDisplayToTrackName, type PlayerItemForApi } from './partyUtils';

export interface AimpAvailability {
  available: boolean;
  gatingReasons: AimpGatingReason[];
}

function convertDurationMsToSeconds(durationMs?: number): number {
  if (typeof durationMs !== 'number' || durationMs <= 0) {
    return 0;
  }

  return Math.max(0, Math.round(durationMs / 1000));
}

export function getAimpAvailability(state: Pick<AimpBridgeState, 'environment'>): AimpAvailability {
  const gatingReasons = state.environment.gatingReasons.filter(
    (reason) => reason.code !== 'sourceNotAimp',
  );

  return {
    available: gatingReasons.length === 0,
    gatingReasons,
  };
}

export function isAimpDegraded(state: Pick<AimpBridgeState, 'connection'>): boolean {
  return (
    state.connection.phase === 'stale' ||
    state.connection.protocolError !== null ||
    state.connection.disconnectReason !== null
  );
}

export function getAimpCurrentTrack(
  state: Pick<AimpBridgeState, 'playlistSnapshot' | 'playbackSnapshot'>,
): AimpPlaylistTrackDto | null {
  const trackKey =
    state.playbackSnapshot?.currentTrackKey ?? state.playlistSnapshot?.activeTrackKey ?? null;

  if (!trackKey || state.playlistSnapshot === null) {
    return null;
  }

  const normalizedKey = normalizeTrackKeyForComparison(trackKey);
  return (
    state.playlistSnapshot.tracks.find(
      (track) => normalizeTrackKeyForComparison(track.trackKey) === normalizedKey,
    ) ?? null
  );
}

export function getAimpEffectiveProgressMs(
  state: Pick<AimpBridgeState, 'connection' | 'playbackSnapshot'>,
  nowMs: number = Date.now(),
): number {
  const playbackSnapshot = state.playbackSnapshot;
  if (playbackSnapshot === null) {
    return 0;
  }

  let progressMs = playbackSnapshot.positionMs;
  if (playbackSnapshot.status === 'playing' && state.connection.phase === 'connected') {
    const receivedAtMs = Date.parse(playbackSnapshot.receivedAt);
    if (!Number.isNaN(receivedAtMs)) {
      progressMs += Math.max(0, nowMs - receivedAtMs);
    }
  }

  if (typeof playbackSnapshot.durationMs === 'number') {
    progressMs = Math.min(progressMs, playbackSnapshot.durationMs);
  }

  return Math.max(0, progressMs);
}

export function createAimpPlaybackStateDto(
  state: Pick<
    AimpBridgeState,
    'connection' | 'playlistSnapshot' | 'playbackSnapshot' | 'liveStreamStarted'
  >,
  nowMs: number = Date.now(),
): PlaybackStateDto {
  const currentTrack = getAimpCurrentTrack(state);
  const currentTrackKey =
    state.playbackSnapshot?.currentTrackKey ?? state.playlistSnapshot?.activeTrackKey ?? null;
  const currentTrackOrder = currentTrack?.order ?? null;

  return {
    currentTrackId: currentTrackKey,
    status: mapAimpPlaybackStatusToWireStatus(state.playbackSnapshot?.status),
    position: getAimpEffectiveProgressMs(state, nowMs) / 1000,
    duration: convertDurationMsToSeconds(
      state.playbackSnapshot?.durationMs ?? currentTrack?.durationMs,
    ),
    volume:
      typeof state.playbackSnapshot?.volumePercent === 'number'
        ? state.playbackSnapshot.volumePercent / 100
        : 0.8,
    mode: state.liveStreamStarted ? 'session' : 'preparation',
    playedTrackIds:
      currentTrackOrder === null || state.playlistSnapshot === null
        ? []
        : state.playlistSnapshot.tracks
            .filter((track) => track.order < currentTrackOrder)
            .map((track) => track.trackKey),
    disabledTrackIds: [],
    disabledGroupIds: [],
    lastUpdatedAt: new Date(nowMs).toISOString(),
  };
}

function getAimpTrackDisplayName(track: AimpPlaylistTrackDto): string {
  if (track.artist && track.artist.trim().length > 0) {
    return `${track.artist} - ${track.title}`;
  }

  return track.title;
}

export function convertAimpPlaylistForApi(
  playlistSnapshot: Pick<AimpPlaylistSnapshotDto, 'tracks'> | null,
  trackDisplay: PartyTrackDisplaySettings = DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
): {
  items: PlayerItemForApi[];
  totalTracks: number;
  totalDuration: number;
} {
  const tracks = playlistSnapshot?.tracks ?? [];

  return {
    items: tracks.map((track) => {
      const rawName = getAimpTrackDisplayName(track);
      const name = applyPartyTrackDisplayToTrackName(rawName, trackDisplay);
      return {
        id: track.trackKey,
        type: 'track',
        name,
        duration: convertDurationMsToSeconds(track.durationMs),
        displayOrder: track.order,
        level: 0,
      };
    }),
    totalTracks: tracks.length,
    totalDuration: tracks.reduce(
      (sum, track) => sum + convertDurationMsToSeconds(track.durationMs),
      0,
    ),
  };
}

export function canUseAimpLiveSnapshots(
  state: Pick<AimpBridgeState, 'playlistSnapshot' | 'playbackSnapshot'>,
): boolean {
  return hasUsableAimpLiveStreamSnapshots(state.playlistSnapshot, state.playbackSnapshot);
}

export function canStartAimpLiveStream(
  state: Pick<
    AimpBridgeState,
    | 'sourceSelection'
    | 'environment'
    | 'connection'
    | 'pluginMetadata'
    | 'playlistSnapshot'
    | 'playbackSnapshot'
  >,
): boolean {
  return (
    state.sourceSelection === 'aimp' &&
    state.environment.eligible &&
    state.connection.phase === 'connected' &&
    state.connection.pluginConnected &&
    state.pluginMetadata !== null &&
    canUseAimpLiveSnapshots(state)
  );
}

export function getAimpPlaylistPublishKey(
  playlistSnapshot: Pick<AimpPlaylistSnapshotDto, 'playlistId' | 'revision'> | null,
): string | null {
  if (playlistSnapshot === null) {
    return null;
  }

  return `${playlistSnapshot.playlistId}:${playlistSnapshot.revision}`;
}

/**
 * Key for "did we already publish this playback state" — excludes position/revision
 * so we only call UpdateFullState when track/status/playlist changes, not on every
 * position update. Position is sent via UpdatePlaybackPosition every 1s to avoid
 * out-of-order and high-frequency full state updates.
 */
export function getAimpPlaybackPublishKey(
  state: Pick<
    AimpBridgeState,
    'connection' | 'playlistSnapshot' | 'playbackSnapshot' | 'liveStreamStarted'
  >,
): string {
  return JSON.stringify({
    connectionPhase: state.connection.phase,
    playlistRevision: state.playlistSnapshot?.revision ?? null,
    playbackStatus: state.playbackSnapshot?.status ?? null,
    currentTrackKey: state.playbackSnapshot?.currentTrackKey ?? null,
    liveStreamStarted: state.liveStreamStarted,
  });
}

export function canAdvanceAimpPlayback(
  connectionPhase: AimpConnectionPhase,
  playbackStatus: AimpPlaybackStatus | null | undefined,
): boolean {
  return connectionPhase === 'connected' && playbackStatus === 'playing';
}

import type React from 'react';

/** Gap between a track-row anchor control and its anchored panel. */
export const ANCHOR_PANEL_GAP_PX = 4;

/** Shared z-index for track-row anchored panels (dropdowns, popovers). */
export const ANCHOR_PANEL_Z_INDEX = 1001;

export function resolveAnchorPanelLeft(
  anchorRect: DOMRect,
  panelWidth: number,
  gap = ANCHOR_PANEL_GAP_PX,
): number {
  const rightSideLeft = anchorRect.right + gap;
  if (rightSideLeft + panelWidth <= window.innerWidth) {
    return rightSideLeft;
  }
  return anchorRect.left - panelWidth - gap;
}

export function resolveAnchorPanelCenterY(anchorRect: DOMRect): number {
  return anchorRect.top + anchorRect.height / 2;
}

type BuildAnchorPanelStyleOptions = {
  anchorRect: DOMRect;
  panelWidth: number;
  gap?: number;
};

/** Fixed-width panel anchored to a track-row control, vertically centered on the anchor. */
export function buildAnchorPanelStyle({
  anchorRect,
  panelWidth,
  gap = ANCHOR_PANEL_GAP_PX,
}: BuildAnchorPanelStyleOptions): React.CSSProperties {
  return {
    position: 'fixed',
    left: resolveAnchorPanelLeft(anchorRect, panelWidth, gap),
    top: resolveAnchorPanelCenterY(anchorRect),
    transform: 'translateY(-50%)',
    zIndex: ANCHOR_PANEL_Z_INDEX,
    width: panelWidth,
    boxSizing: 'border-box',
  };
}

import { handleAuthError, SESSION_EXPIRED_USER_MESSAGE } from './authErrorHandler';

export interface ApiError {
  message: string;
  status: number;
  statusText: string;
  code?: string;
}

const NON_SESSION_FORBIDDEN_CODES = new Set([
  'consent_required',
  'theme_not_entitled',
  'theme_not_visible',
  'admin_only',
]);

export async function handleApiResponse<T>(response: Response, defaultMessage: string): Promise<T> {
  if (!response.ok) {
    const error = await createApiError(response, defaultMessage);

    if (isSessionAuthError(response.status, error.code)) {
      handleAuthError(error.message);
      throw new Error(SESSION_EXPIRED_USER_MESSAGE);
    }

    throw new Error(error.message);
  }

  if (response.status === 204) {
    return undefined as T;
  }

  const contentLength = response.headers.get('content-length');
  const contentType = response.headers.get('content-type');

  if (contentLength === '0' || (contentType && !contentType.includes('application/json'))) {
    return undefined as T;
  }

  const text = await response.text();

  if (!text || text.trim().length === 0) {
    return undefined as T;
  }

  try {
    return JSON.parse(text) as T;
  } catch (e) {
    throw new Error(`Failed to parse JSON response: ${e instanceof Error ? e.message : String(e)}`);
  }
}

export async function createApiError(
  response: Response,
  defaultMessage: string,
): Promise<ApiError> {
  let errorMessage = defaultMessage;
  let code: string | undefined;

  try {
    const text = await response.text();
    if (text) {
      try {
        const json = JSON.parse(text) as {
          detail?: unknown;
          message?: unknown;
          error?: unknown;
          code?: unknown;
        };
        const detail = typeof json.detail === 'string' ? json.detail : undefined;
        const message = typeof json.message === 'string' ? json.message : undefined;
        const error = typeof json.error === 'string' ? json.error : undefined;
        code = typeof json.code === 'string' ? json.code : undefined;
        errorMessage = detail || message || error || text;
        if (code && !errorMessage.includes(code)) {
          errorMessage = `${errorMessage} (${code})`;
        }
      } catch {
        errorMessage = text;
      }
    } else {
      errorMessage = response.statusText || defaultMessage;
    }
  } catch {
    errorMessage = response.statusText || defaultMessage;
  }

  return {
    message: errorMessage,
    status: response.status,
    statusText: response.statusText,
    code,
  };
}

export async function parseApiErrorPayload<T>(response: Response): Promise<T | null> {
  try {
    const text = await response.text();
    if (!text) return null;
    return JSON.parse(text) as T;
  } catch {
    return null;
  }
}

export function isSessionAuthError(status: number, code?: string): boolean {
  if (status === 401) {
    return true;
  }
  if (status !== 403) {
    return false;
  }
  if (code && NON_SESSION_FORBIDDEN_CODES.has(code)) {
    return false;
  }
  return true;
}

export function isAuthError(status: number, code?: string): boolean {
  return isSessionAuthError(status, code);
}

import { getClientVersionHeaders } from '../config/clientVersion';
import { notifyClientOutdated } from '../stores/clientOutdatedStore';

import { parseApiErrorPayload } from './apiErrorHandler';

export const CLIENT_OUTDATED_STATUS = 426;
export const CLIENT_OUTDATED_CODE = 'client_outdated';

interface ClientOutdatedPayload {
  code?: string;
  requiredVersion?: string;
}

function hasHeaderKey(headers: Record<string, string>, name: string): boolean {
  const lower = name.toLowerCase();
  return Object.keys(headers).some((key) => key.toLowerCase() === lower);
}

function mergeClientVersionHeaders(init?: RequestInit): Record<string, string> {
  const merged: Record<string, string> = {};

  const source = init?.headers;
  if (source instanceof Headers) {
    source.forEach((value, key) => {
      merged[key] = value;
    });
  } else if (Array.isArray(source)) {
    for (const [key, value] of source) {
      merged[key] = value;
    }
  } else if (source) {
    Object.assign(merged, source);
  }

  for (const [key, value] of Object.entries(getClientVersionHeaders())) {
    if (!hasHeaderKey(merged, key)) {
      merged[key] = value;
    }
  }

  return merged;
}

async function handleClientOutdatedResponse(response: Response): Promise<void> {
  if (response.status !== CLIENT_OUTDATED_STATUS) {
    return;
  }

  const payload = await parseApiErrorPayload<ClientOutdatedPayload>(response.clone());
  if (payload?.code === CLIENT_OUTDATED_CODE) {
    notifyClientOutdated(payload.requiredVersion);
  }
}

/**
 * Обёртка над fetch: добавляет заголовки версии клиента и обрабатывает 426 client_outdated.
 */
export async function apiFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
  const response = await fetch(input, {
    ...init,
    headers: mergeClientVersionHeaders(init),
  });

  await handleClientOutdatedResponse(response);

  return response;
}

/**
 * Утилиты для работы с аудиоустройствами через Web Audio API
 */

export interface AudioDevice {
  deviceId: string;
  label: string;
  kind: MediaDeviceKind;
}

/**
 * Проверяет, поддерживается ли setSinkId в текущем браузере
 */
export function isSinkIdSupported(): boolean {
  return typeof HTMLAudioElement !== 'undefined' && 'setSinkId' in HTMLAudioElement.prototype;
}

/**
 * Получает список всех аудиоустройств вывода
 * @returns Promise с массивом устройств
 */
export async function getAudioOutputDevices(): Promise<AudioDevice[]> {
  if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
    return [];
  }

  try {
    // Для получения полных меток устройств может потребоваться разрешение
    // Попробуем получить разрешение на доступ к микрофону (это разблокирует метки)
    try {
      await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch {
      // Игнорируем ошибку - метки могут быть недоступны, но устройства все равно можно получить
    }

    const devices = await navigator.mediaDevices.enumerateDevices();
    const audioOutputDevices = devices
      .filter((device) => device.kind === 'audiooutput')
      .map((device) => ({
        deviceId: device.deviceId,
        label: device.label || `Устройство ${device.deviceId.substring(0, 8)}`,
        kind: device.kind,
      }));

    return audioOutputDevices;
  } catch (error) {
    console.error('Failed to enumerate audio devices', error);
    return [];
  }
}

/**
 * Получает ID устройства по умолчанию
 * @returns 'default' - стандартное значение для устройства по умолчанию
 */
export function getDefaultDeviceId(): string {
  return 'default';
}

/**
 * Проверяет, является ли ошибка ошибкой "устройство не найдено"
 */
function isDeviceNotFoundError(error: unknown): boolean {
  if (error instanceof DOMException) {
    return error.name === 'NotFoundError' || error.message.includes('not found');
  }
  if (error instanceof Error) {
    return error.message.includes('not found') || error.message.includes('NotFoundError');
  }
  return false;
}

/**
 * Применяет выбранное аудиоустройство к HTMLAudioElement
 * @param audioElement - элемент аудио
 * @param deviceId - ID устройства или 'default' для устройства по умолчанию
 * @returns Promise, который разрешается при успешной установке устройства
 * @throws Ошибку только если не удалось установить даже устройство по умолчанию
 */
export async function setAudioSinkId(
  audioElement: HTMLAudioElement,
  deviceId: string | null,
): Promise<void> {
  if (!isSinkIdSupported()) {
    // Если setSinkId не поддерживается, используем устройство по умолчанию
    // В Electron это должно работать, но на всякий случай проверяем
    return;
  }

  const targetDeviceId = deviceId || getDefaultDeviceId();

  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (audioElement as any).setSinkId(targetDeviceId);
  } catch (error) {
    // Если это ошибка "устройство не найдено" и мы пытались установить не устройство по умолчанию,
    // пробуем установить устройство по умолчанию
    if (isDeviceNotFoundError(error) && targetDeviceId !== getDefaultDeviceId()) {
      try {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await (audioElement as any).setSinkId(getDefaultDeviceId());
        // Успешно переключились на устройство по умолчанию - не пробрасываем ошибку
        // Вызывающий код должен обновить настройки
        return;
      } catch (fallbackError) {
        // Если даже устройство по умолчанию не удалось установить, логируем и пробрасываем исходную ошибку
        console.error('Failed to set default audio sink ID after device not found', fallbackError);
        throw error;
      }
    }

    // Для других ошибок или если уже пытались установить устройство по умолчанию, логируем и пробрасываем ошибку
    console.error('Failed to set audio sink ID', error);
    throw error;
  }
}

import { useUIStore } from '../stores/uiStore';

import { clearAuthSession } from './authSession';

export const SESSION_EXPIRED_USER_MESSAGE = 'Сессия устарела. Войдите ещё раз.';

export function handleAuthError(error?: Error | string): void {
  const technicalMessage =
    typeof error === 'string'
      ? error
      : error instanceof Error
        ? error.message
        : SESSION_EXPIRED_USER_MESSAGE;

  clearAuthSession();

  const uiStore = useUIStore.getState();
  uiStore.closeModal();

  uiStore.addNotification({
    type: 'error',
    message: SESSION_EXPIRED_USER_MESSAGE,
    duration: 8000,
  });

  console.warn('[AuthErrorHandler] Authentication error:', technicalMessage);
}

export function isSessionExpiredError(error: unknown): boolean {
  if (typeof error === 'string') {
    return error.includes(SESSION_EXPIRED_USER_MESSAGE);
  }
  if (error instanceof Error) {
    return error.message.includes(SESSION_EXPIRED_USER_MESSAGE);
  }
  return false;
}

export function isAuthErrorMessage(error: unknown): boolean {
  if (isSessionExpiredError(error)) {
    return true;
  }
  if (error instanceof Error) {
    const message = error.message;
    return (
      message.includes('401') ||
      message.includes('Authentication') ||
      message.includes('Unauthorized') ||
      message.includes('token expired') ||
      message.includes('token invalid') ||
      message.includes('Session check failed')
    );
  }
  return false;
}

export { isAuthErrorMessage as isAuthError };

import { partyService } from '@shared/services/partyService';
import { useAuthStore } from '@shared/stores/authStore';

export function setAuthSessionToken(token: string | null): void {
  useAuthStore.getState().setToken(token);
  partyService.invalidateThemeAccessCache();
}

export function clearAuthSession(): void {
  useAuthStore.getState().clearAuth();
  partyService.invalidateThemeAccessCache();
}

export async function copyTextToClipboard(text: string): Promise<void> {
  const clipboardApi = typeof navigator !== 'undefined' ? navigator.clipboard : undefined;
  if (clipboardApi?.writeText) {
    const wrote = await clipboardApi.writeText(text).then(
      () => true,
      () => false,
    );
    if (wrote) {
      return;
    }
  }

  if (typeof document === 'undefined') {
    throw new Error('Clipboard is unavailable');
  }

  const textarea = document.createElement('textarea');
  textarea.value = text;
  textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed';
  textarea.style.top = '0';
  textarea.style.left = '0';
  textarea.style.opacity = '0';
  document.body.appendChild(textarea);
  textarea.focus();
  textarea.select();
  textarea.setSelectionRange(0, text.length);

  let copied = false;
  try {
    copied = document.execCommand('copy');
  } finally {
    document.body.removeChild(textarea);
  }

  if (!copied) {
    throw new Error('Clipboard is unavailable');
  }
}

import { useEffect, useState } from 'react';

/**
 * Debounce utility function
 * @param func - Function to debounce
 * @param wait - Wait time in milliseconds
 * @returns Debounced function
 */
export function debounce<T extends (...args: unknown[]) => unknown>(
  func: T,
  wait: number,
): (...args: Parameters<T>) => void {
  let timeoutId: NodeJS.Timeout | null = null;

  return function debounced(...args: Parameters<T>) {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
    }
    timeoutId = setTimeout(() => {
      func(...args);
    }, wait);
  };
}

/**
 * React hook for debounced values
 * @param value - Value to debounce
 * @param delay - Delay in milliseconds
 * @returns Debounced value
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

import { Track } from '@core/types/track';

/**
 * Интерфейс для контекста расчета отсечек
 */
export interface DividerCalculationContext {
  tracks: Track[];
  activeTrackId: string | null;
  currentTrackPosition: number | undefined;
  mode: 'preparation' | 'session';
  hourDividerInterval: number; // в секундах
  isTrackDisabled: (trackId: string) => boolean;
  isTrackPlayed: (trackId: string) => boolean;
  calculateTrackDurationWithPause: (track: Track) => number;
}

/**
 * Результат расчета начальной позиции для отсчета
 */
export interface StartPosition {
  startFromIndex: number;
  currentTimeOffset: number; // в секундах
  currentRealTime: number | null; // timestamp или null
}

/**
 * Находит начальный индекс для расчета отсечек
 */
export function findStartIndex(
  tracks: Track[],
  activeTrackId: string | null,
  isTrackDisabled: (trackId: string) => boolean,
  isTrackPlayed: (trackId: string) => boolean,
): number {
  if (activeTrackId) {
    const currentTrackIndex = tracks.findIndex((t) => t.id === activeTrackId);
    if (currentTrackIndex !== -1) {
      return currentTrackIndex;
    }
  }

  // Если текущего трека нет, начинаем с первого активного
  for (let i = 0; i < tracks.length; i++) {
    const track = tracks[i];
    if (!isTrackDisabled(track.id) && !isTrackPlayed(track.id)) {
      return i;
    }
  }

  return 0;
}

/**
 * Вычисляет начальную позицию и текущее время для расчета отсечек
 */
export function calculateStartPosition(context: DividerCalculationContext): StartPosition {
  const { tracks, activeTrackId, mode, isTrackDisabled, isTrackPlayed } = context;

  const startFromIndex = findStartIndex(tracks, activeTrackId, isTrackDisabled, isTrackPlayed);

  let currentTimeOffset = 0;
  let currentRealTime: number | null = null;

  if (mode === 'session') {
    // База — «сейчас» в wall-clock. Границы трека на таймлайне и остаток очереди
    // сдвигаются на −currentTrackPosition в calculateDividerMarkers / plannedEnd
    // и в calculateAccumulatedDuration, чтобы тайм не дрейфовал каждую секунду.
    currentRealTime = Date.now();
    currentTimeOffset = 0; // смещение внутри трека учитывается при расчёте отрезков, не здесь
  }

  return {
    startFromIndex,
    currentTimeOffset,
    currentRealTime,
  };
}

/**
 * Вычисляет следующее ровное время после указанного времени
 */
export function calculateNextEvenTime(currentTime: number, hourDividerInterval: number): number {
  const currentDate = new Date(currentTime);
  const currentMinutes = currentDate.getHours() * 60 + currentDate.getMinutes();
  const intervalMinutes = hourDividerInterval / 60;

  // Вычисляем следующее ровное время после текущего момента (округление вверх)
  const nextEvenMinutes =
    Math.floor(currentMinutes / intervalMinutes) * intervalMinutes + intervalMinutes;
  const nextEvenDate = new Date(currentDate);
  nextEvenDate.setHours(Math.floor(nextEvenMinutes / 60));
  nextEvenDate.setMinutes(nextEvenMinutes % 60);
  nextEvenDate.setSeconds(0);
  nextEvenDate.setMilliseconds(0);

  return nextEvenDate.getTime();
}

/**
 * Секунды до конца трека и далее по очереди: в сессии на активном треке
 * — остаток (duration − currentTrackPosition), иначе полная длительность.
 */
function getSessionOrFullTrackDurationSeconds(
  context: DividerCalculationContext,
  track: Track,
): number {
  const full = context.calculateTrackDurationWithPause(track);
  if (context.mode !== 'session' || context.activeTrackId !== track.id) {
    return full;
  }
  if (context.isTrackPlayed(track.id)) {
    return full;
  }
  const pos = context.currentTrackPosition;
  if (pos === undefined || pos <= 0) {
    return full;
  }
  return Math.max(0, full - Math.min(pos, full));
}

/**
 * В сессии сдвигает нулевую точку накопления к началу трека в wall time:
 * trackStart = now − pos, trackEnd = trackStart + full.
 */
function shiftAccumulatedForSessionCurrentTrackStart(
  context: DividerCalculationContext,
  track: Track,
  accumulatedDuration: number,
): number {
  if (
    context.mode !== 'session' ||
    context.isTrackPlayed(track.id) ||
    context.activeTrackId !== track.id
  ) {
    return accumulatedDuration;
  }
  const pos = context.currentTrackPosition;
  if (pos === undefined || pos <= 0) {
    return accumulatedDuration;
  }
  const full = context.calculateTrackDurationWithPause(track);
  return accumulatedDuration - Math.min(pos, full);
}

/**
 * Вычисляет накопленную длительность от startIndex до endIndex (включительно)
 */
export function calculateAccumulatedDuration(
  tracks: Track[],
  startIndex: number,
  endIndex: number,
  context: DividerCalculationContext,
): number {
  const { mode, isTrackDisabled, isTrackPlayed } = context;

  let accumulatedDuration = 0;

  for (let i = startIndex; i <= endIndex && i < tracks.length; i++) {
    const track = tracks[i];

    // Пропускаем отключённые треки
    if (isTrackDisabled(track.id)) {
      continue;
    }

    // Пропускаем проигранные треки в режиме сессии
    if (mode === 'session' && isTrackPlayed(track.id)) {
      continue;
    }

    const trackDuration = getSessionOrFullTrackDurationSeconds(context, track);
    accumulatedDuration += trackDuration;
  }

  return accumulatedDuration;
}

/**
 * Результат расчета отсечек
 */
export interface DividerMarkers {
  markers: Map<string, number | null>; // trackId -> timestamp или null
  startPosition: StartPosition;
  nextEvenTime: number | null;
  /** time — для отрисовки в session: при плане внутри трека — граница сегмента (trackEnd), как у интервальных отсечек; иначе plannedEndTime */
  plannedEndMarker: {
    trackId: string | null;
    time: number | null;
  } | null;
}

/**
 * Вычисляет позиции отсечек
 */
export function calculateDividerMarkers(
  context: DividerCalculationContext & {
    showHourDividers: boolean;
    plannedEndTime?: number | null;
  },
): DividerMarkers {
  const { tracks, hourDividerInterval, showHourDividers, plannedEndTime } = context;

  const markers = new Map<string, number | null>();
  let accumulatedDuration = 0;
  let nextEvenTime: number | null = null;
  let plannedEndMarker: { trackId: string | null; time: number | null } | null = null;

  if (!showHourDividers || hourDividerInterval <= 0 || tracks.length === 0) {
    return {
      markers,
      startPosition: {
        startFromIndex: 0,
        currentTimeOffset: 0,
        currentRealTime: null,
      },
      nextEvenTime: null,
      plannedEndMarker: null,
    };
  }

  const startPosition = calculateStartPosition(context);
  const { startFromIndex, currentRealTime } = startPosition;

  // Вычисляем следующее ровное время для режима сессии
  if (context.mode === 'session' && currentRealTime !== null) {
    nextEvenTime = calculateNextEvenTime(currentRealTime, hourDividerInterval);
  }

  // В режиме подготовки используем логику с учетом пауз между треками
  if (context.mode === 'preparation') {
    // Начинаем с начала списка
    for (let i = 0; i < tracks.length; i++) {
      const track = tracks[i];

      // Пропускаем отключённые треки
      if (context.isTrackDisabled(track.id)) {
        continue;
      }

      // В режиме подготовки учитываем паузы между треками (как в режиме сессии)
      accumulatedDuration += context.calculateTrackDurationWithPause(track);

      // Используем ту же логику, что и в плейлисте
      const intervals = Math.floor(accumulatedDuration / hourDividerInterval);
      if (intervals > markers.size) {
        markers.set(track.id, null);
      }
    }
  } else {
    // В режиме сессии: now — текущий момент; для активного трека
    // start в прошлом на currentTrackPosition, конец = start + full.
    let previousTrack: Track | null = null;

    for (let i = startFromIndex; i < tracks.length; i++) {
      const track = tracks[i];

      // Пропускаем отключённые треки
      if (context.isTrackDisabled(track.id)) {
        continue;
      }

      // Пропускаем проигранные треки (они уже учтены в currentRealTime)
      if (context.isTrackPlayed(track.id)) {
        continue;
      }

      const fullTrackDuration = context.calculateTrackDurationWithPause(track);
      accumulatedDuration = shiftAccumulatedForSessionCurrentTrackStart(
        context,
        track,
        accumulatedDuration,
      );

      // Проверяем, попадает ли отсечка внутри этого трека
      // Для этого проверяем ДО того, как добавим длительность трека
      if (currentRealTime !== null) {
        // Время начала трека (в реальном времени)
        const trackStartRealTime = currentRealTime + accumulatedDuration * 1000;
        // Время окончания трека (в реальном времени)
        const trackEndRealTime = trackStartRealTime + fullTrackDuration * 1000;

        // Проверяем обычные отсечки (ровное время)
        if (nextEvenTime !== null) {
          // nextEvenTime попадает внутрь интервала трека: визуально отсечка после трека, в map кладётся
          // wall-clock на конец трека (trackEndRealTime), а не «ровный» nextEvenTime — метка в UI
          // совпадает с границей трека на таймлайне, как в formatSessionDividerLabel.
          if (nextEvenTime >= trackStartRealTime && nextEvenTime <= trackEndRealTime) {
            markers.set(track.id, trackEndRealTime);
            // Вычисляем следующее ровное время
            nextEvenTime += hourDividerInterval * 1000;
          }
        }

        // Проверяем красную отсечку (плановое время окончания)
        // Для красной отсечки используем округление вверх: если время попадает внутри трека,
        // показываем отсечку после предыдущего трека
        if (
          plannedEndTime !== null &&
          plannedEndTime !== undefined &&
          plannedEndMarker === null &&
          context.mode === 'session'
        ) {
          const position = findPlannedEndPosition(
            plannedEndTime,
            trackStartRealTime,
            trackEndRealTime,
            previousTrack,
          );
          if (position !== null) {
            plannedEndMarker = position;
          }
        }
      }

      // Сохраняем текущий трек как предыдущий для следующей итерации
      previousTrack = track;

      // Отрезок на таймлайне имеет длину full (смещение start уже в accumulated)
      accumulatedDuration += fullTrackDuration;
    }
  }

  return {
    markers,
    startPosition,
    nextEvenTime,
    plannedEndMarker,
  };
}

function padTimePart(value: number): string {
  return Math.max(0, Math.floor(value)).toString().padStart(2, '0');
}

/**
 * Форматирует время из timestamp в формат hh:mm:ss (локальные часы)
 */
export function formatTimeFromTimestamp(timestamp: number): string {
  const date = new Date(timestamp);
  return `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}:${padTimePart(date.getSeconds())}`;
}

/**
 * Форматирует длительность в секундах в формат hh:mm:ss
 */
export function formatTimeFromDuration(durationSeconds: number): string {
  const total = Math.max(0, Math.floor(durationSeconds));
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const seconds = total % 60;
  return `${padTimePart(hours)}:${padTimePart(minutes)}:${padTimePart(seconds)}`;
}

/**
 * Простая функция для расчета отсечек в плейлисте (без учета пауз, отключенных треков и т.д.)
 * Возвращает массив индексов треков, после которых нужно показать отсечку
 */
export function calculateSimpleDividerMarkers(
  tracks: Track[],
  hourDividerInterval: number,
): number[] {
  const markers: number[] = [];
  let accumulatedDuration = 0;

  tracks.forEach((track, index) => {
    accumulatedDuration += track.duration || 0;
    const intervals = Math.floor(accumulatedDuration / hourDividerInterval);

    // Если перешли через новый интервал, добавляем маркер после этого трека
    if (intervals > markers.length) {
      markers.push(index);
    }
  });

  return markers;
}

/**
 * Простая функция для форматирования метки отсечки в плейлисте
 * Показывает время с начала плейлиста
 */
export function formatSimpleDividerLabel(tracks: Track[], index: number): string {
  const accumulatedDuration = tracks
    .slice(0, index + 1)
    .reduce((sum, track) => sum + (track.duration || 0), 0);

  return formatTimeFromDuration(accumulatedDuration);
}

/**
 * Не больше одной отсечки на строку списка. Приоритет: план — конец очереди — интервал.
 * Используется плеером и плейлистом, чтобы визуальная иерархия совпадала.
 */
export function getPriorityHourDividerKind(
  hasPlannedEndDivider: boolean,
  hasQueueEndDivider: boolean,
  showIntervalDivider: boolean,
): 'planned-end' | 'queue-end' | 'interval' | null {
  if (hasPlannedEndDivider) {
    return 'planned-end';
  }
  if (hasQueueEndDivider) {
    return 'queue-end';
  }
  if (showIntervalDivider) {
    return 'interval';
  }
  return null;
}

/**
 * Позиция отсечки, привязанной к треку в списке отображения (flatIndex строки трека)
 */
export function calculateTrackAnchorDividerPosition<T extends { id: string }>(
  anchor: { trackId: string | null } | null,
  displayItems: Array<{ item: T }>,
  isPlayerTrack: (item: T) => boolean,
): number | null {
  if (anchor === null) {
    return null;
  }

  if (anchor.trackId === null) {
    return -1;
  }

  const trackIdToDisplayIndex = new Map<string, number>();
  displayItems.forEach((di, idx) => {
    if (isPlayerTrack(di.item)) {
      trackIdToDisplayIndex.set(di.item.id, idx);
    }
  });

  const trackDisplayIndex = trackIdToDisplayIndex.get(anchor.trackId);
  return trackDisplayIndex !== undefined ? trackDisplayIndex : null;
}

/**
 * Вычисляет позицию красной отсечки планового времени окончания
 * Использует данные из calculateDividerMarkers
 */
export function calculatePlannedEndDividerPosition<T extends { id: string }>(
  dividerMarkers: DividerMarkers,
  displayItems: Array<{ item: T }>,
  isPlayerTrack: (item: T) => boolean,
): number | null {
  return calculateTrackAnchorDividerPosition(
    dividerMarkers.plannedEndMarker,
    displayItems,
    isPlayerTrack,
  );
}

/** Фактический конец текущей очереди / раскладки (не плановое окончание) */
export interface QueueEndMarker {
  trackId: string;
  sessionEndTimestamp: number | null;
  preparationDurationSeconds: number | null;
}

/**
 * Последний учитываемый трек и время конца очереди: в сессии — wall-clock, в подготовке — накопленная длительность.
 */
export function calculateQueueEndMarker(context: DividerCalculationContext): QueueEndMarker | null {
  const { tracks, mode } = context;
  if (tracks.length === 0) {
    return null;
  }

  if (mode === 'preparation') {
    let lastTrackId: string | null = null;
    let totalSeconds = 0;
    for (let i = 0; i < tracks.length; i++) {
      const track = tracks[i];
      if (context.isTrackDisabled(track.id)) {
        continue;
      }
      totalSeconds += context.calculateTrackDurationWithPause(track);
      lastTrackId = track.id;
    }
    if (lastTrackId === null) {
      return null;
    }
    return {
      trackId: lastTrackId,
      sessionEndTimestamp: null,
      preparationDurationSeconds: totalSeconds,
    };
  }

  const startPosition = calculateStartPosition(context);
  const { startFromIndex, currentRealTime } = startPosition;
  if (currentRealTime === null) {
    return null;
  }

  let accumulatedDuration = 0;
  let lastTrackId: string | null = null;

  for (let i = startFromIndex; i < tracks.length; i++) {
    const track = tracks[i];
    if (context.isTrackDisabled(track.id)) {
      continue;
    }
    if (context.isTrackPlayed(track.id)) {
      continue;
    }
    accumulatedDuration += getSessionOrFullTrackDurationSeconds(context, track);
    lastTrackId = track.id;
  }

  if (lastTrackId === null) {
    return null;
  }

  return {
    trackId: lastTrackId,
    sessionEndTimestamp: currentRealTime + accumulatedDuration * 1000,
    preparationDurationSeconds: null,
  };
}

export function calculateQueueEndDividerPosition<T extends { id: string }>(
  queueEndMarker: QueueEndMarker | null,
  displayItems: Array<{ item: T }>,
  isPlayerTrack: (item: T) => boolean,
): number | null {
  if (queueEndMarker === null) {
    return null;
  }
  return calculateTrackAnchorDividerPosition(
    { trackId: queueEndMarker.trackId },
    displayItems,
    isPlayerTrack,
  );
}

/**
 * Находит позицию планового времени окончания относительно трека
 * @param plannedEndTime - Плановое время окончания (timestamp)
 * @param trackStartRealTime - Время начала трека (timestamp)
 * @param trackEndRealTime - Время окончания трека (timestamp)
 * @param previousTrack - Предыдущий трек или null для первого трека
 * @returns Якорь (trackId) и время подписи в поле time (при плане внутри трека — trackEndRealTime, как у ровных отсечек), или null если искать в следующем треке
 */
function findPlannedEndPosition(
  plannedEndTime: number,
  trackStartRealTime: number,
  trackEndRealTime: number,
  previousTrack: Track | null,
): { trackId: string | null; time: number | null } | null {
  // Проверяем, попадает ли плановое время окончания до начала первого трека
  if (previousTrack === null && plannedEndTime < trackStartRealTime) {
    // Плановое время попадает до начала первого трека - отсечка вверху
    return {
      trackId: null,
      time: plannedEndTime,
    };
  }

  // Проверяем, попадает ли плановое время окончания внутри или после трека
  if (plannedEndTime >= trackStartRealTime && plannedEndTime <= trackEndRealTime) {
    // План внутри сегмента трека на таймлайне — подпись по границе сегмента (дрейф/смещение как у интервальных маркеров)
    return {
      trackId: previousTrack?.id ?? null,
      time: trackEndRealTime,
    };
  }

  // Если plannedEndTime > trackEndRealTime, продолжаем поиск в следующих треках
  return null;
}

/**
 * Вычисляет плановое время окончания плейлиста
 * Использует ту же логику, что и calculateDividerMarkers
 */
export function calculateProjectedEndTime(context: DividerCalculationContext): number | null {
  const { mode } = context;

  if (mode !== 'session') {
    return null;
  }

  const startPosition = calculateStartPosition(context);
  const { startFromIndex, currentRealTime } = startPosition;

  if (currentRealTime === null) {
    return null;
  }

  // Считаем накопленную длительность от текущего трека до конца
  const remainingDuration = calculateAccumulatedDuration(
    context.tracks,
    startFromIndex,
    context.tracks.length - 1,
    context,
  );

  // Вычисляем время окончания: текущее время + оставшаяся длительность
  return currentRealTime + remainingDuration * 1000;
}

/**
 * Вычисляет plannedEndMarker независимо от showHourDividers
 * Используется для красной отсечки, которая должна показываться всегда при наличии plannedEndTime
 */
export function calculatePlannedEndMarker(
  context: DividerCalculationContext,
  plannedEndTime: number | null,
): { trackId: string | null; time: number | null } | null {
  const { mode, tracks } = context;

  if (mode !== 'session' || plannedEndTime === null || plannedEndTime === undefined) {
    return null;
  }

  const startPosition = calculateStartPosition(context);
  const { startFromIndex, currentRealTime } = startPosition;

  if (currentRealTime === null) {
    return null;
  }

  let accumulatedDuration = 0;
  let previousTrack: Track | null = null;

  for (let i = startFromIndex; i < tracks.length; i++) {
    const track = tracks[i];

    // Пропускаем отключённые треки
    if (context.isTrackDisabled(track.id)) {
      continue;
    }

    // Пропускаем проигранные треки
    if (context.isTrackPlayed(track.id)) {
      continue;
    }

    const fullTrackDuration = context.calculateTrackDurationWithPause(track);
    accumulatedDuration = shiftAccumulatedForSessionCurrentTrackStart(
      context,
      track,
      accumulatedDuration,
    );

    // Время начала трека (в реальном времени)
    const trackStartRealTime = currentRealTime + accumulatedDuration * 1000;
    // Время окончания трека (в реальном времени)
    const trackEndRealTime = trackStartRealTime + fullTrackDuration * 1000;

    // Проверяем позицию планового времени окончания
    const position = findPlannedEndPosition(
      plannedEndTime,
      trackStartRealTime,
      trackEndRealTime,
      previousTrack,
    );
    if (position !== null) {
      return position;
    }
    previousTrack = track;
    accumulatedDuration += fullTrackDuration;
  }

  // Если не нашли позицию, возвращаем null (отсечка будет показана в конце)
  return null;
}

import { Track } from '../../core/types/track';

/**
 * Format duration in seconds to "H:MM:SS" format
 */
export function formatDuration(seconds: number): string {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);

  if (hours > 0) {
    return `${hours}:${minutes.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  }

  return `${minutes}:${secs.toString().padStart(2, '0')}`;
}

/**
 * Format duration in seconds to "M:SS" format (for track display)
 */
export function formatTrackDuration(seconds: number): string {
  const minutes = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60);
  return `${minutes}:${secs.toString().padStart(2, '0')}`;
}

/**
 * Calculate total duration of tracks
 */
export function calculateTotalDuration(tracks: Track[]): number {
  return tracks.reduce((sum, track) => sum + (track.duration || 0), 0);
}

/**
 * Format duration for player timeline (M:SS, zero-safe)
 */
export function formatPlayerTime(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds <= 0) {
    return '0:00';
  }

  const totalSeconds = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(totalSeconds / 60);
  const secs = totalSeconds % 60;

  return `${minutes}:${secs.toString().padStart(2, '0')}`;
}

/**
 * Stack + index navigation for the file browser (Back = history, Up = parent is handled separately with push).
 * When the user navigates to a new path from the current point, forward history is trimmed (browser-like).
 */

/** Canonical form for nav stack + comparisons: trim, `/` separators, Windows drive root as `X:/`. */
export function normalizeFileBrowserPath(path: string): string {
  const trimmed = path.trim().replace(/\\/g, '/');
  const driveRoot = /^([A-Za-z]):\/?$/.exec(trimmed);
  if (driveRoot) {
    return `${driveRoot[1]}:/`;
  }
  return trimmed;
}

export type FileBrowserNavState = {
  readonly entries: readonly string[];
  readonly index: number;
};

export function createFileBrowserNavState(initialPath: string): FileBrowserNavState {
  return { entries: [normalizeFileBrowserPath(initialPath)], index: 0 };
}

export function pushFileBrowserPath(
  state: FileBrowserNavState,
  nextPath: string,
): FileBrowserNavState {
  const next = normalizeFileBrowserPath(nextPath);
  const current = normalizeFileBrowserPath(state.entries[state.index] ?? '');
  if (current === next) {
    return state;
  }
  const entries = [...state.entries.slice(0, state.index + 1), next];
  return { entries, index: entries.length - 1 };
}

export function goBackInFileBrowserHistory(state: FileBrowserNavState): FileBrowserNavState {
  if (state.index <= 0) {
    return state;
  }
  return { ...state, index: state.index - 1 };
}

const FILE_NOT_FOUND_MESSAGE_PATTERNS = [
  'enoent',
  'no such file',
  'file not found',
  'файл не найден',
] as const;

/** True when Node/Electron IPC or adapter reports a missing file. */
export function isFileNotFoundError(error: unknown): boolean {
  if (!error) {
    return false;
  }

  const code = (error as NodeJS.ErrnoException).code;
  if (code === 'ENOENT') {
    return true;
  }

  if (!(error instanceof Error)) {
    return false;
  }

  const message = error.message.toLowerCase();
  return FILE_NOT_FOUND_MESSAGE_PATTERNS.some((pattern) => message.includes(pattern));
}

export function formatMissingTrackMessage(trackName: string, trackPath?: string): string {
  if (trackPath) {
    return `Файл не найден: ${trackPath}`;
  }
  return `Файл не найден: ${trackName}`;
}

export function formatGainDb(gainDb: number): string {
  const rounded = gainDb.toFixed(1);
  return gainDb > 0 ? `+${rounded}` : rounded;
}

