import type { Zone } from '../../core/types/layout';

function formatSizePercent(size: number): string {
  return size.toFixed(2);
}

export function getLayoutStructureSignature(zone: Zone): string {
  if (zone.type === 'workspace') {
    return `workspace:${zone.workspaceType}`;
  }

  return `${zone.direction}(${zone.zones.map(getLayoutStructureSignature).join(',')})`;
}

export function getLayoutStructureDirtySignature(zone: Zone): string {
  if (zone.type === 'workspace') {
    return `workspace:${zone.workspaceType}:${zone.workspaceId}`;
  }

  return `${zone.direction}(${zone.zones.map(getLayoutStructureDirtySignature).join(',')})`;
}

export function getLayoutZoneSignature(zone: Zone): string {
  if (zone.type === 'workspace') {
    return `workspace:${zone.workspaceType}:${zone.workspaceId}`;
  }

  const sizesPart = zone.sizes.map(formatSizePercent).join(',');
  return `${zone.direction}[${sizesPart}](${zone.zones.map(getLayoutZoneSignature).join(',')})`;
}

import { MAX_LAYOUT_DEPTH, MAX_ZONES_PER_CONTAINER } from '@core/constants/layoutConstraints';

import { Zone, ContainerZone, ZoneId, SplitDirection } from '../../core/types/layout';

import { getMinSizePercentsForContainer } from './layoutWorkspaceMins';

/**
 * Рекурсивный поиск зоны по ID
 * @param root - корневая зона для поиска
 * @param targetId - ID искомой зоны
 * @returns найденная зона или null
 */
export function findZoneById(root: Zone, targetId: ZoneId): Zone | null {
  if (root.id === targetId) {
    return root;
  }

  if (root.type === 'container') {
    for (const child of root.zones) {
      const found = findZoneById(child, targetId);
      if (found) {
        return found;
      }
    }
  }

  return null;
}

/**
 * Рекурсивный поиск родительского контейнера для зоны
 * @param root - корневая зона для поиска
 * @param targetId - ID целевой зоны
 * @param parent - текущий родительский контейнер (для рекурсии)
 * @returns родительский контейнер или null
 */
export function findParentZone(
  root: Zone,
  targetId: ZoneId,
  parent: ContainerZone | null = null,
): ContainerZone | null {
  if (root.id === targetId) {
    return parent;
  }

  if (root.type === 'container') {
    for (const child of root.zones) {
      const found = findParentZone(child, targetId, root);
      if (found !== null) {
        return found;
      }
    }
  }

  return null;
}

/**
 * Подсчет общего количества зон в дереве
 * @param root - корневая зона
 * @returns общее количество зон
 */
export function countZones(root: Zone): number {
  if (root.type === 'workspace') {
    return 1;
  }

  return 1 + root.zones.reduce((sum, zone) => sum + countZones(zone), 0);
}

/**
 * @deprecated Global 10px floor — use `getMinSizePercentsForContainer` from
 * `layoutWorkspaceMins` for per-zone mins. Retained for SplitContainer until
 * subtask 3 migrates divider clamp; not used for layout validation.
 */
export function calculateMinSizePercent(containerSize: number): number {
  if (containerSize <= 0) {
    return 0;
  }
  return (10 / containerSize) * 100;
}

/**
 * Immutable replace of a tree node by ID (works for workspace, container, or split substitution).
 */
export function updateZoneInTree(root: Zone, zoneId: ZoneId, updated: Zone): Zone {
  if (root.id === zoneId) {
    return updated;
  }

  if (root.type === 'container') {
    return {
      ...root,
      zones: root.zones.map((child) => updateZoneInTree(child, zoneId, updated)),
    };
  }

  return root;
}

/** @see updateZoneInTree — call-site alias when substituting one node (e.g. workspace → split container). */
export const replaceZoneInTree = updateZoneInTree;

/** @see updateZoneInTree — call-site alias when the replacement is a known container. */
export function updateContainerInTree(
  root: Zone,
  containerId: ZoneId,
  updated: ContainerZone,
): Zone {
  return updateZoneInTree(root, containerId, updated);
}

/**
 * Проверка глубины вложенности
 * @param root - корневая зона
 * @param currentDepth - текущая глубина (для рекурсии)
 * @returns максимальная глубина
 */
export function getMaxDepth(root: Zone, currentDepth: number = 0): number {
  if (root.type === 'workspace') {
    return currentDepth;
  }

  let maxDepth = currentDepth;
  for (const child of root.zones) {
    const childDepth = getMaxDepth(child, currentDepth + 1);
    maxDepth = Math.max(maxDepth, childDepth);
  }

  return maxDepth;
}

/**
 * Валидация layout
 * @param root - корневая зона для валидации
 * @param containerWidth - ширина контейнера в пикселях
 * @param containerHeight - высота контейнера в пикселях
 * @returns true если layout валиден
 */
export function validateLayout(
  root: Zone,
  containerWidth: number,
  containerHeight: number,
): boolean {
  const maxDepth = getMaxDepth(root);
  if (maxDepth > MAX_LAYOUT_DEPTH) {
    return false;
  }

  // Рекурсивная валидация контейнеров
  function validateZone(zone: Zone, _parentDirection?: SplitDirection): boolean {
    if (zone.type === 'workspace') {
      // Workspace зона должна иметь валидный размер
      if (zone.size < 0 || zone.size > 100) {
        return false;
      }
      return true;
    }

    // Контейнер должен иметь хотя бы 2 зоны
    if (zone.zones.length < 2) {
      return false;
    }

    if (zone.zones.length > MAX_ZONES_PER_CONTAINER) {
      return false;
    }

    // Размеры должны суммироваться до 100% (с небольшой погрешностью)
    const totalSize = zone.sizes.reduce((sum, size) => sum + size, 0);
    if (Math.abs(totalSize - 100) > 0.01) {
      return false;
    }

    // Количество размеров должно совпадать с количеством зон
    if (zone.sizes.length !== zone.zones.length) {
      return false;
    }

    const minPercents = getMinSizePercentsForContainer(zone, containerWidth, containerHeight);

    for (let index = 0; index < zone.sizes.length; index += 1) {
      if (zone.sizes[index] < minPercents[index]) {
        return false;
      }
    }

    // Рекурсивная валидация дочерних зон
    for (const child of zone.zones) {
      if (!validateZone(child, zone.direction)) {
        return false;
      }
    }

    return true;
  }

  return validateZone(root);
}

/**
 * Удаление пустых контейнеров (если в контейнере только 1 элемент)
 * @param root - корневая зона для обработки
 * @returns очищенная зона
 */
export function cleanupContainers(root: Zone): Zone {
  if (root.type === 'workspace') {
    return root;
  }

  // Если контейнер содержит только 1 зону, заменить контейнер на его содержимое
  if (root.zones.length === 1) {
    const child = cleanupContainers(root.zones[0]);
    return child;
  }

  // Рекурсивно очистить дочерние зоны
  const cleanedZones = root.zones.map((zone) => cleanupContainers(zone));

  // Если после очистки осталась только 1 зона, вернуть её
  if (cleanedZones.length === 1) {
    return cleanedZones[0];
  }

  // Вернуть контейнер с очищенными зонами
  return {
    ...root,
    zones: cleanedZones,
  };
}

/** Syncs workspace zone `size` fields with parent container `sizes` array. */
export function syncContainerChildSizes(container: ContainerZone): ContainerZone {
  return {
    ...container,
    zones: container.zones.map((zone, index) => {
      if (zone.type === 'workspace') {
        return { ...zone, size: container.sizes[index] };
      }
      return syncContainerChildSizes(zone);
    }),
  };
}

export interface LayoutViewportSize {
  width: number;
  height: number;
}

let getLayoutViewport: (() => LayoutViewportSize | null) | null = null;

/**
 * Registers a getter that measures the current layout host viewport (pixels).
 * Wired from the renderer window-min hook so pure layout operations (add-adjacent
 * feasibility) can read the live viewport without direct DOM access.
 */
export function registerLayoutViewportGetter(getter: () => LayoutViewportSize | null): void {
  getLayoutViewport = getter;
}

export function getCurrentLayoutViewport(): LayoutViewportSize | null {
  return getLayoutViewport?.() ?? null;
}

import { workspaceRegistry } from '@core/registry';
import type { ContainerZone, Layout, SplitDirection, Zone } from '@core/types/layout';

import { logger } from './logger';

export interface WorkspaceMinSize {
  minWidth: number;
  minHeight: number;
}

/**
 * Conservative fallback used when a workspace type is not registered
 * or does not declare explicit mins.
 */
export const DEFAULT_WORKSPACE_MIN_SIZE: WorkspaceMinSize = {
  minWidth: 200,
  minHeight: 150,
};

export interface WindowChromeInsets {
  top: number;
  bottom: number;
  left: number;
  right: number;
}

/**
 * Normalizes legacy/alias workspace types before registry lookup or zone
 * creation. `aimp` zones are treated as `player` (spec A7). Single source of
 * truth reused by layout operations so the alias mapping never diverges.
 */
export function normalizeWorkspaceType(workspaceType: string): string {
  return workspaceType === 'aimp' ? 'player' : workspaceType;
}

/**
 * Resolves the minimum content size (in pixels) for a workspace type via the
 * registry. `aimp` normalizes to `player`. Unknown types fall back to a
 * conservative default and emit a dev warning.
 */
export function getWorkspaceMinSize(workspaceType: string): WorkspaceMinSize {
  const normalizedType = normalizeWorkspaceType(workspaceType);
  const module = workspaceRegistry.getModuleByType(normalizedType);

  if (!module) {
    logger.warn(
      `[layoutWorkspaceMins] No registered module for workspace type "${workspaceType}". ` +
        `Falling back to default mins ${DEFAULT_WORKSPACE_MIN_SIZE.minWidth}x${DEFAULT_WORKSPACE_MIN_SIZE.minHeight}.`,
    );
    return { ...DEFAULT_WORKSPACE_MIN_SIZE };
  }

  return { minWidth: module.minWidth, minHeight: module.minHeight };
}

export interface WorkspaceTypeWithMins extends WorkspaceMinSize {
  type: string;
}

/**
 * Returns all registered workspace types with their declared mins.
 * Intended for documentation and tests.
 */
export function getAllRegisteredWorkspaceTypesWithMins(): WorkspaceTypeWithMins[] {
  return workspaceRegistry.getAllModulesByType().map((module) => ({
    type: module.type,
    minWidth: module.minWidth,
    minHeight: module.minHeight,
  }));
}

function getMinAlongSplitAxis(size: WorkspaceMinSize, direction: SplitDirection): number {
  return direction === 'horizontal' ? size.minWidth : size.minHeight;
}

function getMinAlongCrossAxis(size: WorkspaceMinSize, direction: SplitDirection): number {
  return direction === 'horizontal' ? size.minHeight : size.minWidth;
}

function getChildMinPixelsAlongSplitAxis(child: Zone, direction: SplitDirection): number {
  const childSize = computeMinLayoutSize(child);
  return getMinAlongSplitAxis(childSize, direction);
}

/**
 * Minimum layout viewport size at which the tree can be arranged so every
 * workspace leaf receives at least its declared `minWidth` × `minHeight`.
 *
 * Min-content model (dividers are adjustable): along a container's split axis
 * the minimum is the **sum** of child mins; along the cross axis it is the
 * **max** of child mins. Size fractions do not affect this minimum.
 */
export function computeMinLayoutSize(rootZone: Zone): WorkspaceMinSize {
  if (rootZone.type === 'workspace') {
    return getWorkspaceMinSize(rootZone.workspaceType);
  }

  if (rootZone.zones.length === 0) {
    return { minWidth: 0, minHeight: 0 };
  }

  const childSizes = rootZone.zones.map((child) => computeMinLayoutSize(child));

  const splitAxisMins = childSizes.map((childSize) =>
    getMinAlongSplitAxis(childSize, rootZone.direction),
  );

  const crossAxisMins = childSizes.map((childSize) =>
    getMinAlongCrossAxis(childSize, rootZone.direction),
  );

  const splitAxisTotal = splitAxisMins.reduce((sum, value) => sum + value, 0);
  const crossAxisMax = Math.max(...crossAxisMins, 0);

  if (rootZone.direction === 'horizontal') {
    return {
      minWidth: splitAxisTotal,
      minHeight: crossAxisMax,
    };
  }

  return {
    minWidth: crossAxisMax,
    minHeight: splitAxisTotal,
  };
}

/**
 * Per-sibling minimum percentages along a container's split axis, parallel to
 * `zones`. Uses current container pixel width/height for percent conversion.
 */
export function getMinSizePercentsForContainer(
  containerZone: ContainerZone,
  containerPixelWidth: number,
  containerPixelHeight: number,
): number[] {
  const splitAxisSize =
    containerZone.direction === 'horizontal' ? containerPixelWidth : containerPixelHeight;

  if (splitAxisSize <= 0) {
    return containerZone.zones.map(() => 0);
  }

  return containerZone.zones.map((child) => {
    const minPixels = getChildMinPixelsAlongSplitAxis(child, containerZone.direction);
    return (minPixels / splitAxisSize) * 100;
  });
}

function roundPx(value: number): number {
  return Math.round(value * 100) / 100;
}

/**
 * Human-readable breakdown of `computeMinLayoutSize`, exposing the recursion for
 * both axes (width and height). Returned `lines` are indented per depth so the
 * console output mirrors the layout tree; `size` matches `computeMinLayoutSize`.
 */
export function explainMinLayoutSize(
  rootZone: Zone,
  depth = 0,
): { size: WorkspaceMinSize; lines: string[] } {
  const indent = '  '.repeat(depth);

  if (rootZone.type === 'workspace') {
    const size = getWorkspaceMinSize(rootZone.workspaceType);
    return {
      size,
      lines: [
        `${indent}• workspace "${rootZone.workspaceType}" → minWidth=${size.minWidth}px, minHeight=${size.minHeight}px`,
      ],
    };
  }

  if (rootZone.zones.length === 0) {
    return {
      size: { minWidth: 0, minHeight: 0 },
      lines: [`${indent}• container (пустой) → minWidth=0px, minHeight=0px`],
    };
  }

  const isHorizontal = rootZone.direction === 'horizontal';
  const axisLabel = isHorizontal ? 'горизонтальный (делит ширину)' : 'вертикальный (делит высоту)';
  const lines: string[] = [`${indent}▸ container ${axisLabel}, зон: ${rootZone.zones.length}`];

  const childResults = rootZone.zones.map((child) => explainMinLayoutSize(child, depth + 1));
  const childAxisLabel = isHorizontal ? 'minWidth' : 'minHeight';

  const splitAxisMins = childResults.map((childResult, index) => {
    const childMin = getMinAlongSplitAxis(childResult.size, rootZone.direction);

    lines.push(...childResult.lines);
    lines.push(
      `${indent}  ↳ зона[${index}] ${childAxisLabel}=${roundPx(childMin)}px (вклад в ось split)`,
    );

    return childMin;
  });

  const crossAxisMins = childResults.map((childResult) =>
    getMinAlongCrossAxis(childResult.size, rootZone.direction),
  );

  const splitAxisTotal = splitAxisMins.reduce((sum, value) => sum + value, 0);
  const crossAxisMax = Math.max(...crossAxisMins, 0);

  const size: WorkspaceMinSize = isHorizontal
    ? { minWidth: splitAxisTotal, minHeight: crossAxisMax }
    : { minWidth: crossAxisMax, minHeight: splitAxisTotal };

  const splitSumExpr = splitAxisMins.map((value) => `${roundPx(value)}px`).join(' + ');
  const crossMaxExpr = crossAxisMins.map((value) => `${roundPx(value)}px`).join(', ');

  if (isHorizontal) {
    lines.push(
      `${indent}∑ ширина = сумма минимумов = ${splitSumExpr} = ${roundPx(
        splitAxisTotal,
      )}px; высота = max(${crossMaxExpr}) = ${roundPx(crossAxisMax)}px`,
    );
  } else {
    lines.push(
      `${indent}∑ высота = сумма минимумов = ${splitSumExpr} = ${roundPx(
        splitAxisTotal,
      )}px; ширина = max(${crossMaxExpr}) = ${roundPx(crossAxisMax)}px`,
    );
  }

  return { size, lines };
}

/**
 * Minimum browser window size = layout viewport mins plus chrome insets.
 */
export function computeMinWindowSize(layout: Layout, chrome: WindowChromeInsets): WorkspaceMinSize {
  const layoutMins = computeMinLayoutSize(layout.rootZone);

  return {
    minWidth: chrome.left + chrome.right + layoutMins.minWidth,
    minHeight: chrome.top + chrome.bottom + layoutMins.minHeight,
  };
}

