} from '@core/types/project';

/**
 * Интерфейс для PlayerItem без path (для API)
 */
export interface PlayerItemForApi {
  id: string;
  type: 'track' | 'group';
  name: string;
  duration?: number;
  items?: PlayerItemForApi[];
  displayOrder: number;
  level: number;
}

/**
 * Имя трека для API/превью вечеринки с учётом настроек отображения (графемы Unicode).
 */
export function normalizePartyTrackDisplaySettings(
  settings: PartyTrackDisplaySettings,
): PartyTrackDisplaySettings {
  const mode = settings.stripLeadingCharsMode === 'untilDelimiter' ? 'untilDelimiter' : 'count';
  const delimiterRaw = settings.stripLeadingCharsDelimiter;
  const delimiter =
    typeof delimiterRaw === 'string' && delimiterRaw.length > 0
      ? delimiterRaw.slice(0, 1)
      : DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS.stripLeadingCharsDelimiter;
  const count =
    Number.isFinite(settings.stripLeadingCharsCount) && settings.stripLeadingCharsCount > 0
      ? Math.max(0, Math.floor(settings.stripLeadingCharsCount))
      : 0;

  return {
    stripLeadingCharsEnabled: Boolean(settings.stripLeadingCharsEnabled),
    stripLeadingCharsMode: mode,
    stripLeadingCharsCount: count,
    stripLeadingCharsDelimiter: delimiter,
  };
}

export function applyPartyTrackDisplayToTrackName(
  name: string,
  settings: PartyTrackDisplaySettings = DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
): string {
  const normalized = normalizePartyTrackDisplaySettings(settings);
  if (!normalized.stripLeadingCharsEnabled) {
    return name;
  }

  if (normalized.stripLeadingCharsMode === 'untilDelimiter') {
    const delimiter = normalized.stripLeadingCharsDelimiter;
    const index = name.indexOf(delimiter);
    if (index === -1) {
      return name;
    }
    const rest = name.slice(index + delimiter.length);
    return rest.length > 0 ? rest : name;
  }

  if (normalized.stripLeadingCharsCount <= 0) {
    return name;
  }
  const chars = [...name];
  const n = Math.min(normalized.stripLeadingCharsCount, chars.length);
  const rest = chars.slice(n).join('');
  return rest.length > 0 ? rest : name;
}

export function applyPartyTrackDisplayToComponentPlaylist(
  items: ComponentPlayerItem[],
  settings: PartyTrackDisplaySettings = DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
): ComponentPlayerItem[] {
  return items.map((item) => {
    if (item.type === 'group') {
      const nested = item.items ?? [];
      return {
        ...item,
        items: applyPartyTrackDisplayToComponentPlaylist(nested, settings),
      };
    }
    return {
      ...item,
      name: applyPartyTrackDisplayToTrackName(item.name, settings),
    };
  });
}

/**
 * Преобразует ProjectItem из приложения в формат для библиотеки компонентов
 */
export function convertToComponentPlayerItem(
  item: ProjectItem,
  displayOrder: number = 0,
  level: number = 0,
): ComponentPlayerItem {
  if (isProjectGroup(item)) {
    return {
      id: item.id,
      type: 'group',
      name: item.name || 'Группа',
      items: item.items.map((childItem, index) =>
        convertToComponentPlayerItem(childItem, index, level + 1),
      ),
      displayOrder,
      level,
    };
  } else {
    return {
      id: item.id,
      type: 'track',
      name: item.name,
      duration: item.duration,
      displayOrder,
      level,
    };
  }
}

/**
 * Преобразует массив ProjectItem в формат для библиотеки компонентов
 */
export function convertToComponentPlayerItems(items: ProjectItem[]): ComponentPlayerItem[] {
  return items.map((item, index) => convertToComponentPlayerItem(item, index, 0));
}

/**
 * Вычисляет общую длительность плейлиста
 */
export function calculateTotalDuration(items: ProjectItem[]): number {
  let total = 0;
  for (const item of items) {
    if (isProjectTrack(item)) {
      total += item.duration || 0;
    } else if (isProjectGroup(item)) {
      total += calculateTotalDuration(item.items);
    }
  }
  return total;
}

/**
 * Подсчитывает общее количество треков
 */
export function countTotalTracks(items: ProjectItem[]): number {
  let count = 0;
  for (const item of items) {
    if (isProjectTrack(item)) {
      count++;
    } else if (isProjectGroup(item)) {
      count += countTotalTracks(item.items);
    }
  }
  return count;
}

/** Collects track ids from a component playlist tree (preview / playback helpers). */
export function collectComponentPlaylistTrackIds(items: ComponentPlayerItem[]): string[] {
  const ids: string[] = [];
  for (const item of items) {
    if (item.type === 'track') {
      ids.push(item.id);
      continue;
    }
    if (item.type === 'group' && item.items) {
      ids.push(...collectComponentPlaylistTrackIds(item.items));
    }
  }
  return ids;
}

/**
 * Преобразует ProjectItem из приложения в формат для API (без path)
 */
export function convertToApiPlayerItem(
  item: ProjectItem,
  displayOrder: number = 0,
  level: number = 0,
  trackDisplay?: PartyTrackDisplaySettings,
): PlayerItemForApi {
  if (isProjectGroup(item)) {
    return {
      id: item.id,
      type: 'group',
      name: item.name || 'Группа',
      items: item.items.map((childItem, index) =>
        convertToApiPlayerItem(childItem, index, level + 1, trackDisplay),
      ),
      displayOrder,
      level,
    };
  } else {
    const rawName = item.name;
    const name =
      trackDisplay !== undefined
        ? applyPartyTrackDisplayToTrackName(rawName, trackDisplay)
        : rawName;
    return {
      id: item.id,
      type: 'track',
      name,
      duration: item.duration,
      displayOrder,
      level,
      // path намеренно не включается
    };
  }
}

/**
 * Преобразует массив ProjectItem в формат для API (без path)
 */
export function convertToApiPlayerItems(
  items: ProjectItem[],
  trackDisplay?: PartyTrackDisplaySettings,
): PlayerItemForApi[] {
  return items.map((item, index) => convertToApiPlayerItem(item, index, 0, trackDisplay));
}

/**
 * Вычисляет метаданные плейлиста для API
 */
export function calculatePlaylistMetadata(items: ProjectItem[]): {
  totalTracks: number;
  totalDuration: number;
} {
  return {
    totalTracks: countTotalTracks(items),
    totalDuration: calculateTotalDuration(items),
  };
}

/**
 * Преобразует плейлист в формат для API с вычислением метаданных
 */
export function convertPlaylistForApi(
  items: ProjectItem[],
  trackDisplay?: PartyTrackDisplaySettings,
): {
  items: PlayerItemForApi[];
  totalTracks: number;
  totalDuration: number;
} {
  const apiItems = convertToApiPlayerItems(items, trackDisplay);
  const metadata = calculatePlaylistMetadata(items);

  return {
    items: apiItems,
    totalTracks: metadata.totalTracks,
    totalDuration: metadata.totalDuration,
  };
}

import { ProjectGroup, ProjectItem, isProjectGroup, isProjectTrack } from '@core/types/project';
import { Track } from '@core/types/track';

export interface DisplayItem {
  item: ProjectItem;
  level: number;
  displayIndex: number;
  flatIndex: number;
  parentGroupId: string | null;
}

function flattenItemsRecursive(
  items: ProjectItem[],
  level: number,
  trackIndex: number,
  flatIndex: number,
  parentGroupId: string | null,
): { result: DisplayItem[]; nextTrackIndex: number; nextFlatIndex: number } {
  const result: DisplayItem[] = [];
  let currentTrackIndex = trackIndex;
  let currentFlatIndex = flatIndex;

  for (const item of items) {
    const isItemGroup = isProjectGroup(item);
    const itemDisplayIndex = isItemGroup ? -1 : currentTrackIndex++;

    result.push({
      item,
      level,
      displayIndex: itemDisplayIndex,
      flatIndex: currentFlatIndex++,
      parentGroupId,
    });

    if (isItemGroup) {
      const nested = flattenItemsRecursive(
        item.items,
        level + 1,
        currentTrackIndex,
        currentFlatIndex,
        item.id,
      );
      result.push(...nested.result);
      currentTrackIndex = nested.nextTrackIndex;
      currentFlatIndex = nested.nextFlatIndex;
    }
  }

  return { result, nextTrackIndex: currentTrackIndex, nextFlatIndex: currentFlatIndex };
}

export function flattenItemsForDisplay(items: ProjectItem[]): DisplayItem[] {
  const { result } = flattenItemsRecursive(items, 0, 0, 0, null);
  return result;
}

function getAllTracksFromGroup(group: ProjectGroup): Track[] {
  const tracks: Track[] = [];
  for (const item of group.items) {
    if (isProjectTrack(item)) {
      tracks.push(item);
    } else if (isProjectGroup(item)) {
      tracks.push(...getAllTracksFromGroup(item));
    }
  }
  return tracks;
}

export function getGroupItemCount(group: ProjectGroup): number {
  let count = 0;
  for (const item of group.items) {
    count++;
    if (isProjectGroup(item)) {
      count += getGroupItemCount(item);
    }
  }
  return count;
}

export function getGroupTotalDuration(group: ProjectGroup): number {
  const tracks = getAllTracksFromGroup(group);
  return tracks.reduce((sum, track) => sum + (track.duration || 0), 0);
}

export function getTracksFromDisplayItems(displayItems: DisplayItem[]): Track[] {
  const tracks: Track[] = [];
  for (const displayItem of displayItems) {
    if (isProjectTrack(displayItem.item)) {
      tracks.push(displayItem.item);
    }
  }
  return tracks;
}

export function getGroupWithNestedIds(groupId: string, displayItems: DisplayItem[]): string[] {
  const ids: string[] = [];

  const groupIndex = displayItems.findIndex((di) => di.item.id === groupId);
  if (groupIndex === -1) {
    return ids;
  }

  const groupDisplayItem = displayItems[groupIndex];
  if (!isProjectGroup(groupDisplayItem.item)) {
    return [groupId];
  }

  ids.push(groupId);

  const groupLevel = groupDisplayItem.level;
  for (let i = groupIndex + 1; i < displayItems.length; i++) {
    const di = displayItems[i];
    if (di.level <= groupLevel) {
      break;
    }
    ids.push(di.item.id);
  }

  return ids;
}

export function expandSelectionWithGroupContents(
  selectedIds: Set<string>,
  displayItems: DisplayItem[],
): Set<string> {
  const expandedIds = new Set<string>();

  for (const di of displayItems) {
    if (selectedIds.has(di.item.id)) {
      expandedIds.add(di.item.id);

      if (isProjectGroup(di.item)) {
        const nestedIds = getGroupWithNestedIds(di.item.id, displayItems);
        nestedIds.forEach((nestedId) => expandedIds.add(nestedId));
      }
    } else if (di.parentGroupId && selectedIds.has(di.parentGroupId)) {
      expandedIds.add(di.item.id);
    } else {
      let parentId = di.parentGroupId;
      while (parentId) {
        if (selectedIds.has(parentId)) {
          expandedIds.add(di.item.id);
          break;
        }
        const parentDi = displayItems.find((d) => d.item.id === parentId);
        parentId = parentDi?.parentGroupId ?? null;
      }
    }
  }

  return expandedIds;
}

import {
  DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS,
  DEFAULT_PROJECT_SETTINGS,
  DEFAULT_SESSION_STATE,
  PartyTrackDisplaySettings,
  ProjectFile,
  ProjectGroupSettings,
  ProjectSessionState,
  ProjectSettings,
  ProjectTrackSettings,
  SavedProjectGroup,
  SavedProjectItem,
  SavedProjectTrack,
} from '@core/types/project';
import { LOUDNESS_ALGORITHM_VERSION, type TrackLoudnessStatus } from '@core/types/track';

/**
 * Результат валидации проекта
 */
export interface ValidationResult {
  isValid: boolean;
  errors: string[];
  warnings: string[];
  data: ProjectFile | null;
}

/**
 * Проверяет, является ли значение объектом
 */
function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Проверяет, является ли значение массивом
 */
function isArray(value: unknown): value is unknown[] {
  return Array.isArray(value);
}

/**
 * Проверяет, является ли значение строкой
 */
function isString(value: unknown): value is string {
  return typeof value === 'string';
}

/**
 * Проверяет, является ли значение числом
 */
function isNumber(value: unknown): value is number {
  return typeof value === 'number' && !isNaN(value);
}

function isBoolean(value: unknown): value is boolean {
  return typeof value === 'boolean';
}

function validatePartyCustomizationSettings(
  raw: unknown,
  warnings: string[],
): Record<string, unknown> | undefined {
  if (raw === undefined || raw === null) {
    return undefined;
  }
  if (!isObject(raw) || isArray(raw)) {
    warnings.push('Invalid partyCustomizationSettings, omitting');
    return undefined;
  }
  try {
    return JSON.parse(JSON.stringify(raw)) as Record<string, unknown>;
  } catch {
    warnings.push('Invalid partyCustomizationSettings, omitting');
    return undefined;
  }
}

function validatePartyTrackDisplay(raw: unknown, warnings: string[]): PartyTrackDisplaySettings {
  if (!isObject(raw)) {
    warnings.push('Invalid partyTrackDisplay, using defaults');
    return { ...DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS };
  }
  const enabled = isBoolean(raw.stripLeadingCharsEnabled) ? raw.stripLeadingCharsEnabled : false;
  let count = 0;
  if (isNumber(raw.stripLeadingCharsCount) && isFinite(raw.stripLeadingCharsCount)) {
    count = Math.max(0, Math.floor(raw.stripLeadingCharsCount));
  } else if (raw.stripLeadingCharsCount !== undefined) {
    warnings.push('Invalid stripLeadingCharsCount in partyTrackDisplay, using 0');
  }
  let mode: PartyTrackDisplaySettings['stripLeadingCharsMode'] = 'count';
  if (raw.stripLeadingCharsMode === 'untilDelimiter') {
    mode = 'untilDelimiter';
  } else if (raw.stripLeadingCharsMode !== undefined && raw.stripLeadingCharsMode !== 'count') {
    warnings.push('Invalid stripLeadingCharsMode in partyTrackDisplay, using count');
  }
  let delimiter = DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS.stripLeadingCharsDelimiter;
  if (typeof raw.stripLeadingCharsDelimiter === 'string') {
    delimiter =
      raw.stripLeadingCharsDelimiter.length > 0
        ? raw.stripLeadingCharsDelimiter.slice(0, 1)
        : DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS.stripLeadingCharsDelimiter;
  } else if (raw.stripLeadingCharsDelimiter !== undefined) {
    warnings.push('Invalid stripLeadingCharsDelimiter in partyTrackDisplay, using space');
  }
  return {
    stripLeadingCharsEnabled: enabled,
    stripLeadingCharsMode: mode,
    stripLeadingCharsCount: count,
    stripLeadingCharsDelimiter: delimiter,
  };
}

/**
 * Валидирует ActionAfterTrack
 */
function isValidActionAfterTrack(value: unknown): boolean {
  return value === 'next' || value === 'pauseAndNext' || value === 'pause';
}

const VALID_LOUDNESS_STATUSES: TrackLoudnessStatus[] = ['ok', 'pending', 'error'];

function validateTrackLoudness(
  loudness: unknown,
  trackId: string,
  errors: string[],
  warnings: string[],
): boolean {
  if (loudness === undefined) {
    return true;
  }

  if (!isObject(loudness)) {
    errors.push(`Track ${trackId} has invalid loudness`);
    return false;
  }

  if (
    !isString(loudness.status) ||
    !VALID_LOUDNESS_STATUSES.includes(loudness.status as TrackLoudnessStatus)
  ) {
    errors.push(`Track ${trackId} has invalid loudness status`);
    return false;
  }

  const numericFields = [
    'integratedLufs',
    'lraLowLufs',
    'lraLu',
    'truePeakDb',
    'trackGainDb',
    'manualGainDb',
    'manualCompressionStrength',
    'fileMtime',
  ] as const;
  for (const field of numericFields) {
    if (loudness[field] !== undefined && !isNumber(loudness[field])) {
      errors.push(`Track ${trackId} loudness.${field} must be a number`);
      return false;
    }
  }

  if (loudness.errorMessage !== undefined && !isString(loudness.errorMessage)) {
    errors.push(`Track ${trackId} loudness.errorMessage must be a string`);
    return false;
  }

  if (
    loudness.algorithmVersion !== undefined &&
    loudness.algorithmVersion !== LOUDNESS_ALGORITHM_VERSION
  ) {
    warnings.push(
      `Track ${trackId} loudness.algorithmVersion mismatch; loudness will be rescanned on load`,
    );
  }

  return true;
}

/**
 * Валидирует SavedProjectTrack
 */
function validateSavedTrack(
  item: unknown,
  errors: string[],
  warnings: string[],
): item is SavedProjectTrack {
  if (!isObject(item)) {
    errors.push('Track item is not an object');
    return false;
  }

  if (item.type !== 'track') {
    errors.push(`Expected track type, got: ${item.type}`);
    return false;
  }

  if (!isString(item.id) || item.id.length === 0) {
    errors.push('Track missing valid id');
    return false;
  }

  if (!isString(item.path) || item.path.length === 0) {
    errors.push(`Track ${item.id} missing valid path`);
    return false;
  }

  if (!isString(item.name)) {
    errors.push(`Track ${item.id} missing valid name`);
    return false;
  }

  if (item.duration !== undefined && !isNumber(item.duration)) {
    errors.push(`Track ${item.id} has invalid duration`);
    return false;
  }

  if (!validateTrackLoudness(item.loudness, item.id, errors, warnings)) {
    return false;
  }

  return true;
}

/**
 * Валидирует SavedProjectGroup
 */
function validateSavedGroup(item: unknown, errors: string[]): item is SavedProjectGroup {
  if (!isObject(item)) {
    errors.push('Group item is not an object');
    return false;
  }

  if (item.type !== 'group') {
    errors.push(`Expected group type, got: ${item.type}`);
    return false;
  }

  if (!isString(item.id) || item.id.length === 0) {
    errors.push('Group missing valid id');
    return false;
  }

  if (!isString(item.name)) {
    errors.push(`Group ${item.id} missing valid name`);
    return false;
  }

  if (!isArray(item.items)) {
    errors.push(`Group ${item.id} missing items array`);
    return false;
  }

  for (const childId of item.items) {
    if (!isString(childId)) {
      errors.push(`Group ${item.id} has invalid child id`);
      return false;
    }
  }

  return true;
}

/**
 * Валидирует SavedProjectItem
 */
function validateSavedItem(
  item: unknown,
  errors: string[],
  warnings: string[],
): item is SavedProjectItem {
  if (!isObject(item)) {
    errors.push('Item is not an object');
    return false;
  }

  if (item.type === 'track') {
    return validateSavedTrack(item, errors, warnings);
  } else if (item.type === 'group') {
    return validateSavedGroup(item, errors);
  } else {
    errors.push(`Unknown item type: ${item.type}`);
    return false;
  }
}

/**
 * Валидирует ProjectSettings с graceful degradation
 */
function validateSettings(settings: unknown, warnings: string[]): ProjectSettings {
  const result = { ...DEFAULT_PROJECT_SETTINGS };

  if (!isObject(settings)) {
    warnings.push('Settings is not an object, using defaults');
    return result;
  }

  if (isNumber(settings.defaultPauseBetweenTracks)) {
    result.defaultPauseBetweenTracks = settings.defaultPauseBetweenTracks;
  } else if (settings.defaultPauseBetweenTracks !== undefined) {
    warnings.push('Invalid defaultPauseBetweenTracks, using default');
  }

  if (isValidActionAfterTrack(settings.defaultActionAfterTrack)) {
    result.defaultActionAfterTrack =
      settings.defaultActionAfterTrack as ProjectSettings['defaultActionAfterTrack'];
  } else if (settings.defaultActionAfterTrack !== undefined) {
    warnings.push('Invalid defaultActionAfterTrack, using default');
  }

  if (settings.plannedEndTime === null || isNumber(settings.plannedEndTime)) {
    result.plannedEndTime = settings.plannedEndTime as number | null;
  } else if (settings.plannedEndTime !== undefined) {
    warnings.push('Invalid plannedEndTime, using default');
  }

  if (typeof settings.portableMode === 'boolean') {
    result.portableMode = settings.portableMode;
  } else if (settings.portableMode !== undefined) {
    warnings.push('Invalid portableMode value, using default');
  }

  return result;
}

/**
 * Валидирует ProjectSessionState с graceful degradation
 */
function validateSessionState(sessionState: unknown, warnings: string[]): ProjectSessionState {
  const result = { ...DEFAULT_SESSION_STATE };

  if (!isObject(sessionState)) {
    return result;
  }

  if (sessionState.mode === 'preparation' || sessionState.mode === 'session') {
    result.mode = sessionState.mode;
  } else if (sessionState.mode !== undefined) {
    warnings.push('Invalid session mode, using default');
  }

  if (isArray(sessionState.playedTrackIds)) {
    result.playedTrackIds = sessionState.playedTrackIds.filter(isString);
  }

  if (isArray(sessionState.disabledTrackIds)) {
    result.disabledTrackIds = sessionState.disabledTrackIds.filter(isString);
  }

  if (isArray(sessionState.disabledGroupIds)) {
    result.disabledGroupIds = sessionState.disabledGroupIds.filter(isString);
  }

  if (sessionState.currentTrackId === null || isString(sessionState.currentTrackId)) {
    result.currentTrackId = sessionState.currentTrackId;
  }

  if (sessionState.sessionStartTime === null || isNumber(sessionState.sessionStartTime)) {
    result.sessionStartTime = sessionState.sessionStartTime;
  }

  return result;
}

/**
 * Валидирует trackSettings
 */
function validateTrackSettings(
  trackSettings: unknown,
  warnings: string[],
): Record<string, ProjectTrackSettings> {
  const result: Record<string, ProjectTrackSettings> = {};

  if (!isObject(trackSettings)) {
    if (trackSettings !== undefined) {
      warnings.push('Invalid trackSettings, using empty');
    }
    return result;
  }

  for (const [key, value] of Object.entries(trackSettings)) {
    if (!isObject(value)) {
      warnings.push(`Invalid track settings for ${key}, skipping`);
      continue;
    }

    const settings: ProjectTrackSettings = {};

    if (value.pauseBetweenTracks === null || isNumber(value.pauseBetweenTracks)) {
      settings.pauseBetweenTracks = value.pauseBetweenTracks as number | null;
    }

    if (value.actionAfterTrack === null || isValidActionAfterTrack(value.actionAfterTrack)) {
      settings.actionAfterTrack =
        value.actionAfterTrack as ProjectTrackSettings['actionAfterTrack'];
    }

    result[key] = settings;
  }

  return result;
}

/**
 * Валидирует groupSettings
 */
function validateGroupSettings(
  groupSettings: unknown,
  warnings: string[],
): Record<string, ProjectGroupSettings> {
  const result: Record<string, ProjectGroupSettings> = {};

  if (!isObject(groupSettings)) {
    if (groupSettings !== undefined) {
      warnings.push('Invalid groupSettings, using empty');
    }
    return result;
  }

  for (const [key, value] of Object.entries(groupSettings)) {
    if (!isObject(value)) {
      warnings.push(`Invalid group settings for ${key}, skipping`);
      continue;
    }

    const settings: ProjectGroupSettings = {};

    if (value.pauseBetweenTracks === null || isNumber(value.pauseBetweenTracks)) {
      settings.pauseBetweenTracks = value.pauseBetweenTracks as number | null;
    }

    if (value.actionAfterTrack === null || isValidActionAfterTrack(value.actionAfterTrack)) {
      settings.actionAfterTrack =
        value.actionAfterTrack as ProjectGroupSettings['actionAfterTrack'];
    }

    result[key] = settings;
  }

  return result;
}

/**
 * Валидирует файл проекта .cherry
 * Возвращает результат валидации с graceful degradation
 */
export function validateProjectFile(data: unknown): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Проверяем базовую структуру
  if (!isObject(data)) {
    return {
      isValid: false,
      errors: ['Project file is not a valid object'],
      warnings: [],
      data: null,
    };
  }

  // Проверяем версию
  if (data.version !== '2.0') {
    if (data.version === undefined) {
      errors.push('Missing version field');
    } else {
      errors.push(`Unsupported version: ${data.version}`);
    }
  }

  // Проверяем name
  let name = 'Untitled';
  if (isString(data.name)) {
    name = data.name;
  } else {
    warnings.push('Missing or invalid name, using "Untitled"');
  }

  // Проверяем items
  const items: SavedProjectItem[] = [];
  if (!isArray(data.items)) {
    errors.push('Missing or invalid items array');
  } else {
    for (let i = 0; i < data.items.length; i++) {
      const item = data.items[i];
      if (validateSavedItem(item, errors, warnings)) {
        items.push(item);
      } else {
        warnings.push(`Skipping invalid item at index ${i}`);
      }
    }
  }

  // Проверяем rootItems
  let rootItems: string[] = [];
  if (!isArray(data.rootItems)) {
    errors.push('Missing or invalid rootItems array');
    // Fallback: use all top-level item IDs
    rootItems = items.map((item) => item.id);
    warnings.push('Using all items as root items');
  } else {
    rootItems = data.rootItems.filter(isString);
    if (rootItems.length !== data.rootItems.length) {
      warnings.push('Some rootItems were invalid and filtered out');
    }
  }

  // Валидируем settings с graceful degradation
  const settings = validateSettings(data.settings, warnings);

  // Валидируем trackSettings
  const trackSettings = validateTrackSettings(data.trackSettings, warnings);

  // Валидируем groupSettings
  const groupSettings = validateGroupSettings(data.groupSettings, warnings);

  // Валидируем sessionState
  const sessionState = validateSessionState(data.sessionState, warnings);

  const partyTrackDisplay =
    data.partyTrackDisplay !== undefined
      ? validatePartyTrackDisplay(data.partyTrackDisplay, warnings)
      : { ...DEFAULT_PARTY_TRACK_DISPLAY_SETTINGS };

  let partyThemeId: string | undefined;
  if (data.partyThemeId !== undefined) {
    if (isString(data.partyThemeId)) {
      partyThemeId = data.partyThemeId;
    } else {
      warnings.push('Invalid partyThemeId, omitting');
    }
  }

  const partyCustomizationSettings =
    data.partyCustomizationSettings !== undefined
      ? validatePartyCustomizationSettings(data.partyCustomizationSettings, warnings)
      : undefined;

  // Если есть критические ошибки, возвращаем null
  if (errors.length > 0) {
    return {
      isValid: false,
      errors,
      warnings,
      data: null,
    };
  }

  // Собираем валидный ProjectFile
  const projectFile: ProjectFile = {
    version: '2.0',
    name,
    items,
    rootItems,
    settings,
    trackSettings,
    groupSettings,
    sessionState,
    partyTrackDisplay,
    ...(partyThemeId !== undefined ? { partyThemeId } : {}),
    ...(partyCustomizationSettings !== undefined ? { partyCustomizationSettings } : {}),
  };

  return {
    isValid: true,
    errors: [],
    warnings,
    data: projectFile,
  };
}

/**
 * Проверяет целостность ссылок в проекте
 * (все rootItems и group.items ссылаются на существующие элементы)
 */
export function validateProjectIntegrity(projectFile: ProjectFile): string[] {
  const warnings: string[] = [];
  const itemIds = new Set(projectFile.items.map((item) => item.id));

  // Проверяем rootItems
  for (const rootId of projectFile.rootItems) {
    if (!itemIds.has(rootId)) {
      warnings.push(`Root item ${rootId} not found in items`);
    }
  }

  // Проверяем ссылки в группах
  for (const item of projectFile.items) {
    if (item.type === 'group') {
      for (const childId of item.items) {
        if (!itemIds.has(childId)) {
          warnings.push(`Group ${item.id} references non-existent item ${childId}`);
        }
      }
    }
  }

  return warnings;
}

import { DEFAULT_FILEBROWSER_WORKSPACE_ID } from '@core/constants/workspace';
import type { Layout } from '@core/types/layout';
import type { WorkspaceId } from '@core/types/workspace';

import { collectWorkspaceZones } from './layoutWorkspaceOperations';

export interface FileBrowserFocusRequestInput {
  path: string;
  targetWorkspaceId?: WorkspaceId;
}

/**
 * Resolves which fileBrowser panel should handle a focus request.
 * Order: explicit target (if zone exists) → default workspace id → first fileBrowser zone.
 */
export function resolveFileBrowserFocusTarget(
  layout: Layout,
  request: FileBrowserFocusRequestInput,
): WorkspaceId | null {
  const fileBrowserZones = collectWorkspaceZones(layout.rootZone).filter(
    (zone) => zone.workspaceType === 'fileBrowser',
  );

  if (fileBrowserZones.length === 0) {
    return null;
  }

  if (request.targetWorkspaceId) {
    const explicitMatch = fileBrowserZones.find(
      (zone) => zone.workspaceId === request.targetWorkspaceId,
    );
    if (explicitMatch) {
      return explicitMatch.workspaceId;
    }
  }

  const defaultZone = fileBrowserZones.find(
    (zone) => zone.workspaceId === DEFAULT_FILEBROWSER_WORKSPACE_ID,
  );
  if (defaultZone) {
    return defaultZone.workspaceId;
  }

  return fileBrowserZones[0].workspaceId;
}

import { usePlayerAudioStore, useProjectStore, useUIStore } from '@shared/stores';

export const DEMO_PLAY_FAILURE_MESSAGE =
  'Не удалось начать воспроизведение. Проверьте настройки аудио.';

export interface TogglePlayPauseParams {
  hasTrack: boolean;
  isPlaying: boolean;
  blocked?: boolean;
  play: () => Promise<void>;
  pause: () => void;
  onPlayFailure?: () => void;
}

export async function togglePlayPause(params: TogglePlayPauseParams): Promise<void> {
  if (params.blocked || !params.hasTrack) {
    return;
  }

  if (params.isPlaying) {
    params.pause();
    return;
  }

  try {
    await params.play();
  } catch {
    params.onPlayFailure?.();
  }
}

export function notifyDemoPlayFailureIfNeeded(existingError: string | null | undefined): void {
  if (existingError) {
    return;
  }
  useUIStore.getState().addNotification({
    type: 'error',
    message: DEMO_PLAY_FAILURE_MESSAGE,
  });
}

export function toggleSessionPlayPause(): void {
  const mode = useProjectStore.getState().sessionState.mode;
  if (mode !== 'session') {
    return;
  }

  const { currentTrack, status, play, pause } = usePlayerAudioStore.getState();
  void togglePlayPause({
    hasTrack: currentTrack !== null,
    isPlaying: status === 'playing',
    play,
    pause,
  });
}

/**
 * Утилиты для работы с JWT токенами
 */

export interface TokenPayload {
  organizerId: string;
  name: string;
  exp: number;
  iat: number;
  jti: string;
}

/**
 * Constant-time string equality for sensitive values (e.g. bearer token cache keys).
 */
export function constantTimeStringEqual(a: string, b: string): boolean {
  const lenA = a.length;
  const lenB = b.length;
  const maxLen = Math.max(lenA, lenB);

  let mismatch = lenA ^ lenB;
  for (let i = 0; i < maxLen; i += 1) {
    const charA = i < lenA ? a.charCodeAt(i) : 0;
    const charB = i < lenB ? b.charCodeAt(i) : 0;
    mismatch |= charA ^ charB;
  }

  return mismatch === 0;
}

/**
 * Декодирует JWT токен и возвращает payload
 */
export function decodeToken(token: string): TokenPayload | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) {
      return null;
    }

    const payload = parts[1];
    const decoded = JSON.parse(atob(payload.replace(/-/g, '+').replace(/_/g, '/')));
    return decoded as TokenPayload;
  } catch (error) {
    console.error('[TokenUtils] Failed to decode token:', error);
    return null;
  }
}

/**
 * Проверяет, истек ли токен
 */
export function isTokenExpired(token: string): boolean {
  if (token.startsWith('demo.cherryplaylist.')) {
    return false;
  }
  const payload = decodeToken(token);
  if (!payload || !payload.exp) {
    return true;
  }

  // exp в секундах, конвертируем в миллисекунды
  const expirationTime = payload.exp * 1000;
  const now = Date.now();

  // Добавляем запас в 1 минуту для учета задержек сети
  return now >= expirationTime - 60000;
}

/**
 * Проверяет, истекает ли токен в ближайшие дни
 */
export function isTokenExpiringSoon(token: string, daysThreshold: number = 7): boolean {
  const payload = decodeToken(token);
  if (!payload || !payload.exp) {
    return true;
  }

  const expirationTime = payload.exp * 1000;
  const now = Date.now();
  const thresholdTime = daysThreshold * 24 * 60 * 60 * 1000; // дни в миллисекундах

  return expirationTime - now <= thresholdTime;
}

/**
 * Получает количество дней до истечения токена
 */
export function getDaysUntilExpiration(token: string): number | null {
  const payload = decodeToken(token);
  if (!payload || !payload.exp) {
    return null;
  }

  const expirationTime = payload.exp * 1000;
  const now = Date.now();
  const diff = expirationTime - now;

  if (diff <= 0) {
    return 0;
  }

  return Math.ceil(diff / (24 * 60 * 60 * 1000));
}

import { v4 as uuidv4 } from 'uuid';

import { Track } from '../../core/types/track';

export type TrackDraft = Omit<Track, 'id'>;

export function extractName(path: string): string {
  const segments = path.split(/[/\\]/);
  const fallback = 'Unknown';
  return segments[segments.length - 1] || fallback;
}

export function createTrackDraft(path: string): TrackDraft {
  return {
    path,
    name: extractName(path),
    duration: undefined,
  };
}

export function createTrackDrafts(paths: string[]): TrackDraft[] {
  return paths.map(createTrackDraft);
}

/**
 * Создает трек с автоматически сгенерированным ID
 * Использует uuidv4() для генерации уникального идентификатора
 */
export function createTrackWithId(track: TrackDraft): Track {
  return {
    ...track,
    id: uuidv4(),
  };
}

const SAFE_EXTERNAL_PROTOCOLS = new Set(['http:', 'https:', 'mailto:', 'tg:']);

export function sanitizeExternalUrl(rawUrl: string | null | undefined): string | null {
  if (typeof rawUrl !== 'string') {
    return null;
  }

  const trimmed = rawUrl.trim();
  if (!trimmed) {
    return null;
  }

  try {
    const parsed = new URL(trimmed);
    if (!SAFE_EXTERNAL_PROTOCOLS.has(parsed.protocol)) {
      return null;
    }

    return parsed.toString();
  } catch {
    return null;
  }
}

import { registerWorkspaceType, unregisterWorkspaceType } from '@core/constants/workspace';
import { WorkspaceZone } from '@core/types/layout';

import { ensureProjectStore, removeProjectStore } from '../stores/projectStoreFactory';
import { useSettingsStore } from '../stores/settingsStore';
import { useUIStore } from '../stores/uiStore';

const COLLECTION_NAME_PREFIX = 'Подборка ';
const COLLECTION_NAME_PATTERN = /^(?:Подборка|Коллекция) (\d+)$/;

function getNextCollectionNumber(collectionNames: string[]): number {
  let maxNumber = 0;
  let parsedAny = false;

  for (const name of collectionNames) {
    const match = name.match(COLLECTION_NAME_PATTERN);
    if (match) {
      parsedAny = true;
      maxNumber = Math.max(maxNumber, Number.parseInt(match[1], 10));
    }
  }

  if (parsedAny) {
    return maxNumber + 1;
  }

  return collectionNames.length + 1;
}

export function setupCollectionZoneForPreset(zone: WorkspaceZone, name: string): void {
  const { workspaceId, workspaceType, id: zoneId } = zone;

  ensureProjectStore({
    workspaceId,
    initialName: name,
    persist: true,
    supportsGroups: false,
    maxItems: null,
  });

  registerWorkspaceType(workspaceId, workspaceType);
  const uiStore = useUIStore.getState();
  uiStore.addWorkspace({ id: workspaceId, type: workspaceType, name, zoneId });
  uiStore.setWorkspaceZoneId(workspaceId, zoneId);
}

export function prepareWorkspaceInstance(zone: WorkspaceZone): void {
  const { workspaceId, workspaceType, id: zoneId } = zone;

  if (workspaceType === 'collection') {
    const uiStore = useUIStore.getState();
    const collectionNames = uiStore.workspaces
      .filter((workspace) => workspace.type === 'collection')
      .map((workspace) => workspace.name);
    const name = `${COLLECTION_NAME_PREFIX}${getNextCollectionNumber(collectionNames)}`;

    ensureProjectStore({
      workspaceId,
      initialName: name,
      persist: true,
      supportsGroups: false,
      maxItems: null,
    });

    registerWorkspaceType(workspaceId, workspaceType);
    uiStore.addWorkspace({ id: workspaceId, type: workspaceType, name, zoneId });
    uiStore.setWorkspaceZoneId(workspaceId, zoneId);
    return;
  }

  if (workspaceType === 'fileBrowser') {
    registerWorkspaceType(workspaceId, workspaceType);
    return;
  }

  if (workspaceType.startsWith('test')) {
    registerWorkspaceType(workspaceId, workspaceType);
  }
}

export function cleanupWorkspaceInstance(zone: WorkspaceZone): void {
  if (zone.workspaceType === 'collection') {
    const uiStore = useUIStore.getState();
    uiStore.removeWorkspace(zone.workspaceId);
    removeProjectStore(zone.workspaceId);
    unregisterWorkspaceType(zone.workspaceId);
    return;
  }

  if (zone.workspaceType === 'fileBrowser') {
    useSettingsStore.getState().removeFileBrowserPathForWorkspace(zone.workspaceId);
    unregisterWorkspaceType(zone.workspaceId);
    return;
  }

  if (zone.workspaceType.startsWith('test')) {
    unregisterWorkspaceType(zone.workspaceId);
  }
}

