import {
  Button,
  getPopularTimeZones,
  getDefaultTimeZone,
  IconButton,
} from '@cherryplay/components';
import React, { useEffect, useRef, useState } from 'react';

import {
  MAX_SHORT_DESCRIPTION_LENGTH,
  MAX_DANCE_TAGS,
  MAX_DANCE_TAG_LENGTH,
  MAX_EXTERNAL_LINK_URL_LENGTH,
  MAX_EXTERNAL_LINK_TEXT_LENGTH,
  PREDEFINED_DANCE_TAGS,
} from '@shared/services/partyService';

import { PartyEditorAccordion } from './PartyEditorAccordion';

import './PartyEditor.css';

interface DanceTagsFieldProps {
  tags: string[];
  onChange: (tags: string[]) => void;
  predefinedOptions: string[];
  maxTags: number;
  maxTagLength: number;
  readOnly?: boolean;
}

const DanceTagsField: React.FC<DanceTagsFieldProps> = ({
  tags,
  onChange,
  predefinedOptions,
  maxTags,
  maxTagLength,
  readOnly = false,
}) => {
  const [customInput, setCustomInput] = useState('');
  const [showCustomInput, setShowCustomInput] = useState(false);
  const customBlockRef = useRef<HTMLDivElement>(null);
  const collapseTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (collapseTimeoutRef.current) clearTimeout(collapseTimeoutRef.current);
    },
    [],
  );

  const addTag = (tag: string) => {
    const trimmed = tag.trim().slice(0, maxTagLength);
    if (!trimmed || tags.includes(trimmed) || tags.length >= maxTags) return;
    onChange([...tags, trimmed]);
  };

  const removeTag = (index: number) => {
    onChange(tags.filter((_, i) => i !== index));
  };

  const handleCustomKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addTag(customInput);
      setCustomInput('');
      if (collapseTimeoutRef.current) {
        clearTimeout(collapseTimeoutRef.current);
        collapseTimeoutRef.current = null;
      }
      setShowCustomInput(false);
    }
  };

  return (
    <div className="party-editor-section">
      <label className="party-editor-label">Танцевальные теги (макс. {maxTags})</label>
      <div className="party-editor-tags-predefined">
        {predefinedOptions.map((option) => (
          <Button
            key={option}
            type="button"
            variant="ghost"
            size="sm"
            className={`party-editor-tag-button ${tags.includes(option) ? 'party-editor-tag-button--selected' : ''}`}
            onClick={() => {
              if (tags.includes(option)) {
                removeTag(tags.indexOf(option));
              } else if (tags.length < maxTags) {
                addTag(option);
              }
            }}
            disabled={readOnly || (!tags.includes(option) && tags.length >= maxTags)}
          >
            {option}
          </Button>
        ))}
        {!readOnly && !showCustomInput ? (
          <Button
            type="button"
            variant="ghost"
            size="sm"
            className="party-editor-tag-button"
            onClick={() => {
              if (collapseTimeoutRef.current) {
                clearTimeout(collapseTimeoutRef.current);
                collapseTimeoutRef.current = null;
              }
              setShowCustomInput(true);
            }}
            disabled={tags.length >= maxTags}
            aria-label="Ввести другой танец"
          >
            Другой танец
          </Button>
        ) : !readOnly ? (
          <div
            ref={customBlockRef}
            className="party-editor-tags-custom party-editor-tags-custom--inline"
          >
            <input
              type="text"
              className="party-editor-input party-editor-tag-input"
              value={customInput}
              onChange={(e) => setCustomInput(e.target.value.slice(0, maxTagLength))}
              onKeyDown={handleCustomKeyDown}
              onBlur={(e) => {
                if (e.relatedTarget && customBlockRef.current?.contains(e.relatedTarget as Node))
                  return;
                collapseTimeoutRef.current = setTimeout(() => setShowCustomInput(false), 150);
              }}
              placeholder="Другой танец (Enter или запятая)"
              maxLength={maxTagLength}
              disabled={tags.length >= maxTags}
              aria-label="Поле для ввода другого танца"
            />
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="party-editor-tag-add"
              onClick={() => {
                addTag(customInput);
                setCustomInput('');
                if (collapseTimeoutRef.current) {
                  clearTimeout(collapseTimeoutRef.current);
                  collapseTimeoutRef.current = null;
                }
                setShowCustomInput(false);
              }}
              disabled={tags.length >= maxTags || !customInput.trim()}
            >
              Добавить
            </Button>
          </div>
        ) : null}
      </div>
      {tags.length > 0 && (
        <div className="party-editor-tags-list">
          {tags.map((tag, index) => (
            <span key={`${tag}-${index}`} className="party-editor-tag-chip">
              {tag}
              {!readOnly && (
                <IconButton
                  type="button"
                  variant="ghost"
                  size="sm"
                  className="party-editor-tag-remove"
                  onClick={() => removeTag(index)}
                  aria-label={`Удалить тег ${tag}`}
                  icon="×"
                />
              )}
            </span>
          ))}
        </div>
      )}
    </div>
  );
};

export interface PartyCardFieldsSectionProps {
  eventDateTime: string;
  eventEndDateTime: string;
  city: string;
  timeZone: string;
  shortDescription: string;
  externalLinkUrl: string;
  externalLinkText: string;
  danceTags: string[];
  readOnly?: boolean;
  defaultExpanded?: boolean;
  onEventDateTimeChange: (dateTime: string) => void;
  onEventEndDateTimeChange?: (dateTime: string) => void;
  onCityChange?: (city: string) => void;
  onShortDescriptionChange?: (value: string) => void;
  onExternalLinkUrlChange?: (value: string) => void;
  onExternalLinkTextChange?: (value: string) => void;
  onDanceTagsChange?: (tags: string[]) => void;
  onTimeZoneChange?: (timeZone: string) => void;
}

export const PartyCardFieldsSection: React.FC<PartyCardFieldsSectionProps> = ({
  eventDateTime,
  eventEndDateTime,
  city,
  timeZone,
  shortDescription,
  externalLinkUrl,
  externalLinkText,
  danceTags,
  readOnly = false,
  defaultExpanded = false,
  onEventDateTimeChange,
  onEventEndDateTimeChange,
  onCityChange,
  onShortDescriptionChange,
  onExternalLinkUrlChange,
  onExternalLinkTextChange,
  onDanceTagsChange,
  onTimeZoneChange,
}) => {
  return (
    <PartyEditorAccordion title="Карточка в каталоге" defaultExpanded={defaultExpanded}>
      <div className="party-editor-fields-group">
        <h4 className="party-editor-fields-group__title">Дата и время</h4>
        <div className="party-editor-fields-group__fields">
          {onTimeZoneChange && (
            <div className="party-editor-section">
              <label className="party-editor-label">
                Таймзона
                <select
                  className="party-editor-input"
                  value={timeZone || getDefaultTimeZone()}
                  onChange={(e) => onTimeZoneChange(e.target.value)}
                  disabled={readOnly}
                >
                  {getPopularTimeZones().map((tz) => (
                    <option key={tz.value} value={tz.value}>
                      {tz.label}
                    </option>
                  ))}
                </select>
              </label>
            </div>
          )}
          <div className="party-editor-section">
            <label className="party-editor-label">
              Дата и время мероприятия
              <input
                type="datetime-local"
                className="party-editor-input"
                value={eventDateTime}
                onChange={(e) => onEventDateTimeChange(e.target.value)}
                readOnly={readOnly}
                disabled={readOnly}
              />
            </label>
          </div>
          {onEventEndDateTimeChange && (
            <div className="party-editor-section">
              <label className="party-editor-label">
                Время окончания
                <input
                  type="datetime-local"
                  className="party-editor-input"
                  value={eventEndDateTime}
                  onChange={(e) => onEventEndDateTimeChange(e.target.value)}
                  readOnly={readOnly}
                  disabled={readOnly}
                />
              </label>
            </div>
          )}
        </div>
      </div>

      {onCityChange && (
        <div className="party-editor-fields-group">
          <h4 className="party-editor-fields-group__title">Место</h4>
          <div className="party-editor-fields-group__fields">
            <div className="party-editor-section">
              <label className="party-editor-label">
                Город
                <input
                  type="text"
                  className="party-editor-input"
                  value={city}
                  onChange={(e) => onCityChange(e.target.value)}
                  placeholder="Город"
                  readOnly={readOnly}
                  disabled={readOnly}
                />
              </label>
            </div>
          </div>
        </div>
      )}

      {onShortDescriptionChange && (
        <div className="party-editor-fields-group">
          <h4 className="party-editor-fields-group__title">Описание</h4>
          <div className="party-editor-fields-group__fields">
            <div className="party-editor-section">
              <label className="party-editor-label">
                Краткое описание
                <textarea
                  className="party-editor-input"
                  value={shortDescription}
                  onChange={(e) =>
                    onShortDescriptionChange(e.target.value.slice(0, MAX_SHORT_DESCRIPTION_LENGTH))
                  }
                  placeholder="Краткое описание до 200 символов"
                  rows={2}
                  maxLength={MAX_SHORT_DESCRIPTION_LENGTH}
                  readOnly={readOnly}
                  disabled={readOnly}
                />
                <span className="party-editor-char-count">
                  {shortDescription.length}/{MAX_SHORT_DESCRIPTION_LENGTH}
                </span>
              </label>
            </div>
          </div>
        </div>
      )}

      {(onExternalLinkUrlChange && onExternalLinkTextChange) || onDanceTagsChange ? (
        <div className="party-editor-fields-group">
          <h4 className="party-editor-fields-group__title">Ссылки и теги</h4>
          <div className="party-editor-fields-group__fields">
            {onExternalLinkUrlChange && onExternalLinkTextChange && (
              <div className="party-editor-section">
                <label className="party-editor-label">
                  Внешняя ссылка (URL)
                  <input
                    type="url"
                    className="party-editor-input"
                    value={externalLinkUrl}
                    onChange={(e) =>
                      onExternalLinkUrlChange(e.target.value.slice(0, MAX_EXTERNAL_LINK_URL_LENGTH))
                    }
                    placeholder="https://..."
                    maxLength={MAX_EXTERNAL_LINK_URL_LENGTH}
                    readOnly={readOnly}
                    disabled={readOnly}
                  />
                </label>
                <label className="party-editor-label">
                  Текст ссылки (подпись)
                  <input
                    type="text"
                    className="party-editor-input"
                    value={externalLinkText}
                    onChange={(e) =>
                      onExternalLinkTextChange(
                        e.target.value.slice(0, MAX_EXTERNAL_LINK_TEXT_LENGTH),
                      )
                    }
                    placeholder="Например: Сайт мероприятия"
                    maxLength={MAX_EXTERNAL_LINK_TEXT_LENGTH}
                    readOnly={readOnly}
                    disabled={readOnly}
                  />
                </label>
              </div>
            )}
            {onDanceTagsChange && (
              <DanceTagsField
                tags={danceTags}
                onChange={onDanceTagsChange}
                predefinedOptions={[...PREDEFINED_DANCE_TAGS]}
                maxTags={MAX_DANCE_TAGS}
                maxTagLength={MAX_DANCE_TAG_LENGTH}
                readOnly={readOnly}
              />
            )}
          </div>
        </div>
      ) : null}
    </PartyEditorAccordion>
  );
};

import React from 'react';

import { useProjectStore } from '@shared/stores/projectStore';

import type { PartyEditorPhase } from '../partyEditorPhase';
import type { PartySettingsSection } from '../partySettingsUiStore';

import { PartyCardFieldsSection } from './PartyCardFieldsSection';
import { PartyDesignSection } from './PartyDesignSection';
import type {
  PartyEditorConnectionState,
  PartyEditorDesignState,
  PartyEditorFieldHandlers,
  PartyEditorFieldValues,
} from './partyEditorRuntimeTypes';
import { PartyInfoSection } from './PartyInfoSection';

import './PartyEditor.css';

export type PartyEditorSectionMode = Exclude<PartySettingsSection, 'danger'> | 'all';

interface PartyEditorProps {
  phase: PartyEditorPhase;
  section: PartyEditorSectionMode;
  fields: PartyEditorFieldValues;
  handlers: PartyEditorFieldHandlers;
  design: PartyEditorDesignState;
  connection: PartyEditorConnectionState;
  isBlocked?: boolean;
  aboutActions?: React.ReactNode;
  defaultExpanded?: boolean;
  designPreviewHint?: React.ReactNode;
  showCopyUrl?: boolean;
  copyUrlDisabled?: boolean;
  copyUrlTitle?: string;
  onCopyUrl?: () => void;
}

export const PartyEditor: React.FC<PartyEditorProps> = ({
  phase,
  section,
  fields,
  handlers,
  design,
  connection,
  isBlocked = false,
  aboutActions,
  defaultExpanded = false,
  designPreviewHint,
  showCopyUrl = false,
  copyUrlDisabled = false,
  copyUrlTitle,
  onCopyUrl,
}) => {
  const projectName = useProjectStore((state) => state.name);
  const {
    partyName,
    partyTitle,
    partySubtitle,
    eventDateTime,
    eventEndDateTime,
    city,
    timeZone,
    shortDescription,
    externalLinkUrl,
    externalLinkText,
    danceTags,
  } = fields;

  const {
    onPartyNameChange,
    onPartyTitleChange,
    onPartySubtitleChange,
    onEventDateTimeChange,
    onEventEndDateTimeChange,
    onCityChange,
    onShortDescriptionChange,
    onExternalLinkUrlChange,
    onExternalLinkTextChange,
    onDanceTagsChange,
    onTimeZoneChange,
  } = handlers;

  const {
    themeId,
    customizationSettings,
    lockedThemes,
    hasThemeAccess,
    networkEnabled: designNetworkEnabled,
    isThemeAccessLoading,
    visibleThemeIds,
    themeAccessErrorMessage,
    onThemeIdChange,
    onCustomizationSettingsChange,
  } = design;

  const { linkedParty, serverError, isCheckingParty, onRetry } = connection;

  const isReadOnly = phase === 'completed';
  const showAllSections = section === 'all';
  const showAbout = section === 'about' || showAllSections;
  const showDesign = section === 'design' || showAllSections;
  const accessibleStyleIds = new Set(
    (visibleThemeIds ?? [])
      .filter((id) => !lockedThemes.some((locked) => locked.themeId === id))
      .map((id) => id),
  );
  const selectedLockedTheme = lockedThemes.find((item) => item.themeId === themeId) ?? null;

  return (
    <div className={`party-editor${isReadOnly ? ' party-editor--read-only' : ''}`}>
      {showAbout ? (
        <>
          <PartyInfoSection
            partyName={partyName}
            partyTitle={partyTitle}
            partySubtitle={partySubtitle}
            projectName={projectName}
            readOnly={isReadOnly}
            defaultExpanded={defaultExpanded}
            partyUrl={linkedParty?.url}
            showCopyUrl={showCopyUrl}
            copyUrlDisabled={copyUrlDisabled}
            copyUrlTitle={copyUrlTitle}
            onCopyUrl={onCopyUrl}
            onPartyNameChange={onPartyNameChange}
            onPartyTitleChange={onPartyTitleChange}
            onPartySubtitleChange={onPartySubtitleChange}
          />

          <PartyCardFieldsSection
            eventDateTime={eventDateTime}
            eventEndDateTime={eventEndDateTime}
            city={city}
            timeZone={timeZone}
            shortDescription={shortDescription}
            externalLinkUrl={externalLinkUrl}
            externalLinkText={externalLinkText}
            danceTags={danceTags}
            readOnly={isReadOnly}
            defaultExpanded={defaultExpanded}
            onEventDateTimeChange={onEventDateTimeChange}
            onEventEndDateTimeChange={onEventEndDateTimeChange}
            onCityChange={onCityChange}
            onShortDescriptionChange={onShortDescriptionChange}
            onExternalLinkUrlChange={onExternalLinkUrlChange}
            onExternalLinkTextChange={onExternalLinkTextChange}
            onDanceTagsChange={onDanceTagsChange}
            onTimeZoneChange={onTimeZoneChange}
          />
        </>
      ) : null}

      {showDesign ? (
        <>
          {designPreviewHint}
          <PartyDesignSection
            themeId={themeId}
            customizationSettings={customizationSettings}
            onThemeIdChange={onThemeIdChange}
            onCustomizationSettingsChange={onCustomizationSettingsChange}
            readOnly={isReadOnly}
            lockedThemes={lockedThemes}
            visibleThemeIds={visibleThemeIds}
            hasThemeAccess={hasThemeAccess}
            networkEnabled={designNetworkEnabled}
            isThemeAccessLoading={isThemeAccessLoading}
            themeAccessErrorMessage={themeAccessErrorMessage}
            defaultExpanded={defaultExpanded}
            showNoAccessibleThemesHint={
              !isThemeAccessLoading && visibleThemeIds != null && accessibleStyleIds.size === 0
            }
            selectedLockedTheme={selectedLockedTheme}
          />
        </>
      ) : null}

      {showAbout ? (
        <>
          {aboutActions}

          {!isBlocked && isCheckingParty ? (
            <div className="party-editor-checking" aria-busy="true" aria-live="polite">
              <div className="party-editor-checking-message">
                Идёт проверка соединения с сервером...
              </div>
            </div>
          ) : null}

          {!isBlocked && serverError && !linkedParty && !isCheckingParty ? (
            <div className="party-editor-error">
              <div className="party-editor-error-header">
                <strong className="party-editor-error-title">Ошибка подключения</strong>
              </div>
              <div className="party-editor-error-message">
                <p>{serverError}</p>
                <p className="party-editor-error-hint">Убедитесь, что сервер запущен и доступен.</p>
              </div>
              {onRetry ? (
                <div className="party-editor-error-actions">
                  <button
                    className="action-button party-editor-error-retry-button"
                    onClick={onRetry}
                    type="button"
                    disabled={isCheckingParty}
                  >
                    Переподключиться
                  </button>
                </div>
              ) : null}
            </div>
          ) : null}
        </>
      ) : null}
    </div>
  );
};

import { Button } from '@cherryplay/components';
import React from 'react';

import type { PartyEditorPhase } from '../partyEditorPhase';

import './PartyEditor.css';

export interface PartyEditorActionsProps {
  phase: PartyEditorPhase;
  isAuthenticated: boolean;
  isCreating: boolean;
  isSaving?: boolean;
  networkDisabled?: boolean;
  createBlockedByTheme?: boolean;
  createBlockedByThemeTitle?: string;
  showSave?: boolean;
  showMakeReady?: boolean;
  isMakeReadyLoading?: boolean;
  secondaryExtra?: React.ReactNode;
  onCreateParty?: () => void;
  onOpenLinkParty?: () => void;
  onSaveMetadata?: () => void;
  onMakeReady?: () => void;
}

export function getPartyEditorActionVisibility(
  phase: PartyEditorPhase,
  options: {
    isAuthenticated: boolean;
    hasOnOpenLinkParty: boolean;
  },
): { showCreate: boolean; showLinkParty: boolean; showSave: boolean; showMakeReady: boolean } {
  const showCreate = phase === 'draft-unlinked';
  const showLinkParty =
    phase === 'draft-unlinked' && options.hasOnOpenLinkParty && options.isAuthenticated;
  const showSave = phase === 'draft-linked' || phase === 'ready';
  const showMakeReady = phase === 'draft-linked';

  return { showCreate, showLinkParty, showSave, showMakeReady };
}

export function shouldShowPartyLifecycleControls(
  phase: PartyEditorPhase,
  linkedParty: { id: string; shortCode: string } | null | undefined,
): boolean {
  return (
    (phase === 'draft-linked' || phase === 'ready' || phase === 'completed') && linkedParty != null
  );
}

export function shouldShowPartyCatalogVisibilityControl(phase: PartyEditorPhase): boolean {
  return phase === 'draft-unlinked' || phase === 'ready' || phase === 'completed';
}

export const PartyEditorActions: React.FC<PartyEditorActionsProps> = ({
  phase,
  isAuthenticated,
  isCreating,
  isSaving = false,
  networkDisabled = false,
  createBlockedByTheme = false,
  createBlockedByThemeTitle = 'Выберите тему, доступную в вашем тарифе',
  showSave = false,
  showMakeReady = false,
  isMakeReadyLoading = false,
  secondaryExtra,
  onCreateParty,
  onOpenLinkParty,
  onSaveMetadata,
  onMakeReady,
}) => {
  if (phase === 'completed' && !secondaryExtra) {
    return null;
  }

  const { showCreate, showLinkParty } = getPartyEditorActionVisibility(
    phase === 'completed' ? 'ready' : phase,
    {
      isAuthenticated,
      hasOnOpenLinkParty: Boolean(onOpenLinkParty),
    },
  );

  const effectiveShowCreate = phase !== 'completed' && showCreate;
  const effectiveShowLink = phase !== 'completed' && showLinkParty;
  const effectiveShowSave = phase !== 'completed' && showSave;
  const effectiveShowMakeReady = phase !== 'completed' && showMakeReady;

  const actionDisabled = isCreating || isSaving || isMakeReadyLoading || networkDisabled;

  const networkDisabledTitle = 'Включите «Онлайн» в настройках';

  const hasPrimaryCluster =
    effectiveShowCreate || effectiveShowLink || effectiveShowSave || effectiveShowMakeReady;
  const hasSecondary = Boolean(secondaryExtra);

  if (!hasPrimaryCluster && !hasSecondary) {
    return null;
  }

  return (
    <div className="party-editor-actions" aria-busy={isCreating || isSaving} aria-live="polite">
      {effectiveShowCreate && onCreateParty && (
        <Button
          className="party-editor-actions__action"
          onClick={onCreateParty}
          disabled={!isAuthenticated || actionDisabled || createBlockedByTheme}
          loading={isCreating}
          loadingLabel="Создание..."
          type="button"
          title={
            networkDisabled
              ? networkDisabledTitle
              : !isAuthenticated
                ? 'Требуется авторизация'
                : createBlockedByTheme
                  ? createBlockedByThemeTitle
                  : 'Создать запись вечеринки на сервере'
          }
          variant="primary"
          size="sm"
        >
          Создать
        </Button>
      )}
      {effectiveShowLink && onOpenLinkParty && (
        <Button
          className="party-editor-actions__action"
          onClick={onOpenLinkParty}
          disabled={actionDisabled}
          type="button"
          title={
            networkDisabled
              ? networkDisabledTitle
              : 'Привязать существующую вечеринку на сервере к этому проекту (не создаёт новую и не запускает трансляцию)'
          }
          variant="secondary"
          size="sm"
        >
          Привязать
        </Button>
      )}
      {effectiveShowSave && onSaveMetadata && (
        <Button
          className="party-editor-actions__action"
          type="button"
          onClick={() => void onSaveMetadata()}
          disabled={actionDisabled}
          loading={isSaving}
          loadingLabel="Обновление..."
          variant="primary"
          size="sm"
          title={
            networkDisabled
              ? networkDisabledTitle
              : 'Обновить название, описание и другие поля на сервере (без обновления плейлиста)'
          }
        >
          Обновить
        </Button>
      )}
      {effectiveShowMakeReady && onMakeReady && (
        <Button
          className="party-editor-actions__action"
          type="button"
          onClick={() => void onMakeReady()}
          disabled={actionDisabled}
          loading={isMakeReadyLoading}
          variant="secondary"
          size="sm"
          title={
            networkDisabled
              ? networkDisabledTitle
              : 'Снять черновик и перевести в «Ждёт начала». Это не публикация в каталоге.'
          }
        >
          Сделать доступной
        </Button>
      )}
      {hasSecondary ? <div className="party-editor-actions__trailing">{secondaryExtra}</div> : null}
    </div>
  );
};

