import { AuthForm, AUTH_FORM_TITLE_ID } from '@cherryplay/components';
import React from 'react';

import { BROWSER_LOGIN_PANEL_TITLE_ID, BrowserLoginPanel } from '@app/components/BrowserLoginPanel';
import { OnlineUnavailablePanel, Spinner } from '@shared/components';
import { getAppMode, isDemoLiveMode } from '@shared/platform';
import { authService } from '@shared/services/authService';

import type { PartyEditorBlockedReason } from '../partyEditorPhase';

import './PartyEditorShell.css';

export interface PartyEditorBlockedOverlayProps {
  reason: PartyEditorBlockedReason;
  clientRequiredVersion?: string | null;
  isReconnecting?: boolean;
  lastManualCheckFailed?: boolean;
  onManualReconnect?: () => void;
  onResetAndCreateNew?: () => void;
}

export const PartyEditorBlockedOverlay: React.FC<PartyEditorBlockedOverlayProps> = ({
  reason,
  clientRequiredVersion,
  isReconnecting = false,
  lastManualCheckFailed = false,
  onManualReconnect,
  onResetAndCreateNew,
}) => {
  const isLiveDemo = isDemoLiveMode() && getAppMode() === 'demo';
  const authLabelledBy =
    reason === 'auth'
      ? isLiveDemo
        ? AUTH_FORM_TITLE_ID
        : BROWSER_LOGIN_PANEL_TITLE_ID
      : undefined;

  return (
    <div
      className="party-editor-shell-blocked-overlay"
      role={reason === 'checking' ? 'presentation' : 'dialog'}
      aria-modal={reason === 'checking' ? undefined : true}
      aria-label={reason === 'checking' ? 'Идёт загрузка состояния вечеринки' : undefined}
      aria-labelledby={authLabelledBy}
    >
      <div className="party-editor-shell-blocked-overlay-content">
        {reason === 'auth' &&
          (isLiveDemo ? (
            <AuthForm
              title="Требуется авторизация"
              titleId={AUTH_FORM_TITLE_ID}
              description="Для работы с вечеринками необходимо войти в аккаунт"
              compact={false}
              authService={authService}
              oauthEnabled={false}
            />
          ) : (
            <BrowserLoginPanel
              title="Требуется авторизация"
              description="Для работы с вечеринками необходимо войти в аккаунт"
            />
          ))}

        {reason === 'outdated' && (
          <OnlineUnavailablePanel reason="outdated" requiredVersion={clientRequiredVersion} />
        )}

        {reason === 'checking' && (
          <div
            className="party-editor-shell-blocked-spinner"
            role="status"
            aria-live="polite"
            aria-label="Идёт загрузка состояния вечеринки"
          >
            <Spinner size="large" />
          </div>
        )}

        {reason === 'unreachable' && (
          <OnlineUnavailablePanel
            reason="connection"
            isReconnecting={isReconnecting}
            lastCheckFailed={lastManualCheckFailed}
            onRetry={onManualReconnect ? () => void onManualReconnect() : undefined}
          />
        )}

        {reason === 'party-not-found' && (
          <div className="party-editor-shell-party-not-found">
            <h3 className="party-editor-shell-party-not-found-title">
              Подключённая вечеринка удалена
            </h3>
            <p className="party-editor-shell-party-not-found-text">
              На сервере эта вечеринка больше недоступна. Можно отключиться и выбрать другую.
            </p>
            <button
              type="button"
              className="action-button party-editor-shell-party-not-found-button"
              title="Отвязывает проект от вечеринки на сервере"
              onClick={() => void onResetAndCreateNew?.()}
            >
              Отключить от вечеринки
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';

import type { ProjectSessionMode } from '@core/types/project';

import {
  PARTY_EDITOR_PHASE_BADGE_LABELS,
  PARTY_EDITOR_PHASE_HEADERS,
  type PartyEditorBlockedReason,
  type PartyEditorPhase,
  resolvePartyLifecycleServerBadgeLabel,
} from '../partyEditorPhase';

import {
  PartyEditorBlockedOverlay,
  type PartyEditorBlockedOverlayProps,
} from './PartyEditorBlockedOverlay';
import './PartyEditorShell.css';

export interface PartyEditorShellProps {
  phase: PartyEditorPhase | null;
  isBlocked: boolean;
  blockedReason: PartyEditorBlockedReason | null;
  blockedOverlayProps?: Omit<PartyEditorBlockedOverlayProps, 'reason'>;
  headerActions?: React.ReactNode;
  hidePhaseBadge?: boolean;
  sessionMode?: ProjectSessionMode;
  connectivityBanner?: React.ReactNode;
  children: React.ReactNode;
}

export const PartyEditorShell: React.FC<PartyEditorShellProps> = ({
  phase,
  isBlocked,
  blockedReason,
  blockedOverlayProps,
  headerActions,
  hidePhaseBadge = false,
  sessionMode,
  connectivityBanner,
  children,
}) => {
  const headerTitle = phase
    ? PARTY_EDITOR_PHASE_HEADERS[phase]
    : PARTY_EDITOR_PHASE_HEADERS['draft-unlinked'];
  const badgeLifecycle = phase ? PARTY_EDITOR_PHASE_BADGE_LABELS[phase] : undefined;
  const badgeLabel = badgeLifecycle
    ? resolvePartyLifecycleServerBadgeLabel(badgeLifecycle, sessionMode)
    : null;

  return (
    <div className="party-editor-shell">
      <header className="party-editor-shell-header">
        <div className="party-editor-shell-header-main">
          <h2 className="party-editor-shell-title">{headerTitle}</h2>
          {badgeLabel && badgeLifecycle && !hidePhaseBadge && (
            <span
              className={`party-editor-shell-phase-badge party-editor-shell-phase-badge--${badgeLifecycle}`}
            >
              {badgeLabel}
            </span>
          )}
        </div>
        {headerActions && <div className="party-editor-shell-header-actions">{headerActions}</div>}
      </header>

      {connectivityBanner}

      <div className="party-editor-shell-body">{children}</div>

      {isBlocked && blockedReason && (
        <PartyEditorBlockedOverlay reason={blockedReason} {...blockedOverlayProps} />
      )}
    </div>
  );
};

