import type { ProjectSessionMode } from '@core/types/project';
import type { PartyLifecycleState } from '@shared/services/partyService';

import { resolvePartyLifecycleServerBadgeLabel } from '../partyEditorPhase';

import './PartyLifecycleControls.css';

export type PartyLifecycleControlSlot = 'all' | 'accent' | 'secondary';

export interface PartyLifecycleControlsProps {
  partyLifecycleState: PartyLifecycleState;
  isTransitioning?: boolean;
  pendingTransition?: PartyLifecycleState | null;
  disabled?: boolean;
  onTransition: (targetState: PartyLifecycleState) => void;
  layout?: 'default' | 'header';
  sessionMode?: ProjectSessionMode;
  slot?: PartyLifecycleControlSlot;
  hideUnarchive?: boolean;
}

function isLoadingForTarget(
  target: PartyLifecycleState,
  isTransitioning: boolean,
  pendingTransition?: PartyLifecycleState | null,
): boolean {
  return isTransitioning && pendingTransition === target;
}

export const PartyLifecycleControls: React.FC<PartyLifecycleControlsProps> = ({
  partyLifecycleState,
  isTransitioning = false,
  pendingTransition = null,
  disabled = false,
  onTransition,
  layout = 'default',
  sessionMode,
  slot = 'all',
  hideUnarchive = false,
}) => {
  const isDisabled = disabled || isTransitioning;
  const isHeader = layout === 'header';
  const showAccentPublish =
    partyLifecycleState === 'draft' && (slot === 'all' || slot === 'accent');
  const showSecondaryReady =
    partyLifecycleState === 'ready' && (slot === 'all' || slot === 'secondary');
  const showSecondaryUnarchive =
    !hideUnarchive &&
    partyLifecycleState === 'completed' &&
    (slot === 'all' || slot === 'secondary');

  if (!showAccentPublish && !showSecondaryReady && !showSecondaryUnarchive) {
    return null;
  }

  const transitionButtons = (
    <>
      {showAccentPublish && (
        <Button
          type="button"
          className="party-lifecycle-action"
          disabled={isDisabled}
          loading={isLoadingForTarget('ready', isTransitioning, pendingTransition)}
          onClick={() => onTransition('ready')}
          title="Снять черновик и перевести в «Ждёт начала». Это не публикация в каталоге."
          variant="primary"
          size="sm"
        >
          Сделать доступной
        </Button>
      )}

      {showSecondaryReady && (
        <Button
          type="button"
          className="party-lifecycle-action party-lifecycle-action--complete"
          disabled={isDisabled}
          loading={isLoadingForTarget('completed', isTransitioning, pendingTransition)}
          onClick={() => onTransition('completed')}
          title="Перевести вечеринку в архив"
          variant="secondary"
          size="sm"
        >
          В архив
        </Button>
      )}

      {showSecondaryUnarchive && (
        <Button
          type="button"
          className="party-lifecycle-action"
          disabled={isDisabled}
          loading={isLoadingForTarget('ready', isTransitioning, pendingTransition)}
          onClick={() => onTransition('ready')}
          title="Вернуть вечеринку из архива в статус «Ждёт начала»"
          variant="primary"
          size="sm"
        >
          Вернуть из архива
        </Button>
      )}
    </>
  );

  if (isHeader) {
    return (
      <div
        className="party-lifecycle-actions party-lifecycle-actions--header"
        role="group"
        aria-label="Состояние вечеринки"
      >
        {transitionButtons}
      </div>
    );
  }

  return (
    <section className="party-lifecycle" aria-label="Состояние вечеринки">
      <div className="party-lifecycle-header">
        <span className="party-lifecycle-header-label">Статус вечеринки</span>
        <span className={`party-lifecycle-badge party-lifecycle-badge--${partyLifecycleState}`}>
          {resolvePartyLifecycleServerBadgeLabel(partyLifecycleState, sessionMode)}
        </span>
      </div>
      <p className="party-lifecycle-hint">
        Статус на сайте. Каталог («В каталоге» / «По ссылке») настраивается отдельно.
      </p>

      <div className="party-lifecycle-actions">{transitionButtons}</div>
    </section>
  );
};

import { type PartyThemeId, type PlaybackState } from '@cherryplay/components';
import { Button, Disclosure } from '@cherryplay/components';
import React, { useMemo } from 'react';

import type { PartyLifecycleState } from '@shared/services/partyService';

import {
  resetPreviewScenario,
  setPreviewConnectionBreak,
  setPreviewCustomizationSettings,
  setPreviewLifecycleOverride,
  setPreviewMockLive,
  setPreviewTheme,
  setPreviewTrackNumber,
  type PreviewConnectionScenario,
} from '../partyPreviewScenarioActions';
import { usePartyPreviewScenarioStore } from '../partyPreviewScenarioStore';

import { PartyDesignSettingsBlock } from './PartyDesignSettingsBlock';

import '../PartyWorkspaceDemoPanel.css';

export type PartyPreviewScenarioControlsVariant = 'toolbar' | 'panel';

export type PartyPreviewScenarioControlsSection = 'quick' | 'expanded' | 'all';

export interface PartyPreviewDesignOption {
  id: PartyThemeId;
  name: string;
  isAvailable: boolean;
}

export interface PartyPreviewScenarioPlaybackContext {
  isSynchronized: boolean;
  previewLifecycleState: PartyLifecycleState | null;
  effectivePlaybackState: PlaybackState | null;
}

interface PartyPreviewScenarioControlsProps {
  variant: PartyPreviewScenarioControlsVariant;
  section?: PartyPreviewScenarioControlsSection;
  previewTrackIds: readonly string[];
  playbackContext: PartyPreviewScenarioPlaybackContext;
  previewThemeId: PartyThemeId;
  previewCustomizationSettings: Record<string, unknown>;
  previewDesignOptions: PartyPreviewDesignOption[];
}

const LIFECYCLE_PRESETS: { label: string; lifecycle: PartyLifecycleState }[] = [
  { label: 'Черновик (legacy)', lifecycle: 'draft' },
  { label: 'Ждёт начала', lifecycle: 'ready' },
  { label: 'В архиве', lifecycle: 'completed' },
];

const CONNECTION_SCENARIOS: { label: string; scenario: PreviewConnectionScenario }[] = [
  { label: 'Подключение…', scenario: 'connecting' },
  { label: 'Нет связи с сервером', scenario: 'server_unreachable' },
  { label: 'Переподключение…', scenario: 'reconnecting' },
  { label: 'Организатор не в сети', scenario: 'organizer_offline' },
];

function shouldShowSection(
  section: PartyPreviewScenarioControlsSection,
  target: 'quick' | 'expanded',
): boolean {
  if (section === 'all') {
    return true;
  }
  return section === target;
}

export const PartyPreviewScenarioControls: React.FC<PartyPreviewScenarioControlsProps> = ({
  variant,
  section = 'all',
  previewTrackIds,
  playbackContext,
  previewThemeId,
  previewCustomizationSettings,
  previewDesignOptions,
}) => {
  const { isSynchronized, previewLifecycleState, effectivePlaybackState } = playbackContext;

  const lifecycleOverride = usePartyPreviewScenarioStore((state) => state.lifecycleOverride);
  const mockLiveEnabled = usePartyPreviewScenarioStore((state) => state.mockLiveEnabled);
  const currentTrackNumber = usePartyPreviewScenarioStore((state) => state.currentTrackNumber);

  const hasPreviewTracks = previewTrackIds.length > 0;
  const activeLifecycle = isSynchronized ? previewLifecycleState : lifecycleOverride;
  const activeMockLive = isSynchronized
    ? effectivePlaybackState?.status === 'playing'
    : mockLiveEnabled;

  const displayTrackNumber = useMemo(() => {
    if (isSynchronized) {
      if (!hasPreviewTracks || !effectivePlaybackState?.currentTrackId) {
        return 1;
      }
      const index = previewTrackIds.indexOf(effectivePlaybackState.currentTrackId);
      return index >= 0 ? index + 1 : 1;
    }
    if (!hasPreviewTracks) {
      return 1;
    }
    return Math.min(Math.max(currentTrackNumber ?? 1, 1), previewTrackIds.length);
  }, [
    isSynchronized,
    hasPreviewTracks,
    previewTrackIds,
    effectivePlaybackState,
    currentTrackNumber,
  ]);

  const handlePreviewTrackChange = (nextValue: number | null) => {
    if (!hasPreviewTracks) {
      return;
    }
    if (nextValue == null) {
      setPreviewTrackNumber(1);
      return;
    }
    const bounded = Math.min(Math.max(nextValue, 1), previewTrackIds.length);
    setPreviewTrackNumber(bounded);
  };

  const buttonClassName = (isActive = false, modifier?: string) => {
    const base = 'party-workspace-demo-panel-button';
    const classes = [base];
    if (modifier) {
      classes.push(`${base}--${modifier}`);
    }
    if (isActive) {
      classes.push('party-workspace-demo-panel-button--active');
      classes.push('party-preview-scenario-controls-button--active');
    }
    return classes.join(' ');
  };

  const lifecycleBlock = (
    <div
      className={`party-preview-scenario-controls-group${
        variant === 'toolbar' ? ' party-preview-scenario-controls-group--inline' : ''
      }`}
    >
      {variant === 'panel' && (
        <span className="party-workspace-demo-panel-group-label">Режим превью</span>
      )}
      <div className="party-workspace-demo-panel-buttons">
        {LIFECYCLE_PRESETS.map(({ label, lifecycle }) => (
          <Button
            key={lifecycle}
            type="button"
            className={buttonClassName(activeLifecycle === lifecycle)}
            onClick={() => setPreviewLifecycleOverride(lifecycle)}
            variant="secondary"
            size="sm"
            aria-pressed={activeLifecycle === lifecycle}
          >
            {label}
          </Button>
        ))}
        <Button
          type="button"
          className={buttonClassName(Boolean(activeMockLive), 'live')}
          onClick={setPreviewMockLive}
          variant="secondary"
          size="sm"
          aria-pressed={Boolean(activeMockLive)}
        >
          Эфир (live)
        </Button>
      </div>
    </div>
  );

  const trackBlock = (
    <div className="party-workspace-demo-panel-track-row">
      <span className="party-workspace-demo-panel-track-label">Трек в эфире:</span>
      <Button
        type="button"
        className="party-workspace-demo-panel-button party-workspace-demo-panel-stepper"
        onClick={() => handlePreviewTrackChange(displayTrackNumber - 1)}
        disabled={!hasPreviewTracks || isSynchronized}
        variant="secondary"
        size="sm"
        aria-label="Предыдущий трек"
      >
        -
      </Button>
      <input
        type="number"
        min={1}
        max={Math.max(1, previewTrackIds.length)}
        value={displayTrackNumber}
        className="party-workspace-demo-panel-track-input"
        onChange={(event) => handlePreviewTrackChange(Number(event.target.value))}
        disabled={!hasPreviewTracks || isSynchronized}
        aria-label="Номер трека в эфире"
      />
      <Button
        type="button"
        className="party-workspace-demo-panel-button party-workspace-demo-panel-stepper"
        onClick={() => handlePreviewTrackChange(displayTrackNumber + 1)}
        disabled={!hasPreviewTracks || isSynchronized}
        variant="secondary"
        size="sm"
        aria-label="Следующий трек"
      >
        +
      </Button>
      <span className="party-workspace-demo-panel-track-total">/ {previewTrackIds.length}</span>
    </div>
  );

  const connectionBlock =
    variant === 'panel' ? (
      <Disclosure
        title="Разрыв соединения"
        className="party-workspace-demo-panel-accordion party-preview-scenario-controls-connection-accordion"
      >
        <div className="party-workspace-demo-panel-accordion-content">
          <div className="party-workspace-demo-panel-buttons">
            {CONNECTION_SCENARIOS.map(({ label, scenario }) => (
              <Button
                key={scenario}
                type="button"
                className="party-workspace-demo-panel-button party-workspace-demo-panel-button--blocked"
                onClick={() => setPreviewConnectionBreak(scenario)}
                variant="secondary"
                size="sm"
              >
                {label}
              </Button>
            ))}
          </div>
        </div>
      </Disclosure>
    ) : (
      <div className="party-preview-scenario-controls-group">
        <span className="party-workspace-demo-panel-group-label">Разрыв соединения</span>
        <div className="party-workspace-demo-panel-buttons">
          {CONNECTION_SCENARIOS.map(({ label, scenario }) => (
            <Button
              key={scenario}
              type="button"
              className="party-workspace-demo-panel-button party-workspace-demo-panel-button--blocked"
              onClick={() => setPreviewConnectionBreak(scenario)}
              variant="secondary"
              size="sm"
            >
              {label}
            </Button>
          ))}
        </div>
      </div>
    );

  const designBlock =
    previewDesignOptions.length > 0 ? (
      <PartyDesignSettingsBlock
        key={`preview-design-${previewThemeId}`}
        themeId={previewThemeId}
        customizationSettings={previewCustomizationSettings}
        onThemeIdChange={setPreviewTheme}
        onCustomizationSettingsChange={setPreviewCustomizationSettings}
        visibleThemeIds={previewDesignOptions
          .filter((item) => item.isAvailable)
          .map((item) => item.id)}
        lockedThemes={previewDesignOptions
          .filter((item) => !item.isAvailable)
          .map((item) => ({
            themeId: item.id,
            packageCode: 'preview-unavailable',
            packageName: 'Недоступно',
          }))}
        allowLockedSelection
        showApplyButton
        applyButtonLabel="Изменить дизайн"
        applyButtonClassName="party-workspace-demo-panel-button"
      />
    ) : null;

  const resetBlock = (
    <div className="party-workspace-demo-panel-group">
      <Button
        type="button"
        className="party-workspace-demo-panel-button party-workspace-demo-panel-button--reset"
        onClick={resetPreviewScenario}
        variant="secondary"
        size="sm"
      >
        Снова как на сайте
      </Button>
    </div>
  );

  const showQuick = shouldShowSection(section, 'quick');
  const showExpanded = shouldShowSection(section, 'expanded');

  if (variant === 'toolbar' && section === 'quick') {
    return (
      <div className="party-preview-scenario-controls party-preview-scenario-controls--toolbar-quick">
        {lifecycleBlock}
        {hasPreviewTracks && trackBlock}
      </div>
    );
  }

  if (variant === 'toolbar' && section === 'expanded') {
    return (
      <div className="party-preview-scenario-controls party-preview-scenario-controls--toolbar-expanded">
        {connectionBlock}
        {designBlock}
        {resetBlock}
      </div>
    );
  }

  return (
    <div className={`party-preview-scenario-controls party-preview-scenario-controls--${variant}`}>
      {showQuick && (
        <>
          {lifecycleBlock}
          {hasPreviewTracks && trackBlock}
        </>
      )}
      {showExpanded && (
        <>
          {connectionBlock}
          {designBlock}
          {resetBlock}
        </>
      )}
    </div>
  );
};

import React from 'react';

import type { PartyWorkspaceRuntimeValue } from '../partyWorkspaceRuntimeContext';
import { usePartySettingsFormState } from '../usePartySettingsFormState';

import { PartyCatalogVisibilityControl } from './PartyCatalogVisibilityControl';
import { PartyConnectivityBanner } from './PartyConnectivityBanner';
import { PartyEditor } from './PartyEditor';
import { PartyEditorActions } from './PartyEditorActions';
import { PartyEditorDangerZone } from './PartyEditorDangerZone';
import { PartyTrackDisplaySection } from './PartyTrackDisplaySection';

export interface PartySettingsContentProps {
  runtime: PartyWorkspaceRuntimeValue;
  onOpenLinkParty: () => void;
}

export const PartySettingsContent: React.FC<PartySettingsContentProps> = ({
  runtime,
  onOpenLinkParty,
}) => {
  const form = usePartySettingsFormState(runtime);

  const connectivityBanner = !form.isNetworkEnabledForEditor ? (
    <PartyConnectivityBanner
      kind="offline"
      offlineHint="Включите «Онлайн» в настройках приложения (шестерёнка), а не здесь. Локальное редактирование полей вечеринки доступно."
    />
  ) : runtime.serverUnreachable ? (
    <PartyConnectivityBanner
      kind="unreachable"
      isReconnecting={runtime.isReconnecting}
      lastManualCheckFailed={runtime.lastManualCheckFailed}
      onManualReconnect={runtime.handleManualReconnect}
    />
  ) : null;

  const archiveZone = form.archiveAvailability.showDangerSection ? (
    <PartyEditorDangerZone
      availability={form.archiveAvailability}
      disabled={form.isCreating || form.isSavingMetadata || form.networkActionsDisabled}
      isTransitioning={
        form.isTransitioningLifecycle && form.pendingLifecycleTransition === 'completed'
      }
      onArchive={() => void form.handleLifecycleTransition('completed')}
    />
  ) : null;

  const catalogBlock =
    form.editorPhase && form.actionVisibility && form.showCatalog ? (
      <PartyCatalogVisibilityControl
        isListedInCatalog={form.isListedInCatalog}
        disabled={form.networkActionsDisabled || form.editorPhase === 'completed'}
        isUpdating={form.isTogglingCatalogVisibility}
        networkOffline={!form.isNetworkEnabledForEditor}
        onChange={(listed) => void form.handleCatalogVisibilityChange(listed)}
      />
    ) : null;

  const primaryActions =
    form.editorPhase && form.actionVisibility ? (
      <PartyEditorActions
        phase={form.editorPhase}
        isAuthenticated={form.isAuth}
        isCreating={form.isCreating}
        isSaving={form.isSavingMetadata}
        networkDisabled={form.networkActionsDisabled}
        createBlockedByTheme={form.createBlockedByTheme}
        createBlockedByThemeTitle={form.createBlockedByThemeTitle}
        showSave={form.actionVisibility.showSave}
        showMakeReady={form.actionVisibility.showMakeReady}
        isMakeReadyLoading={
          form.isTransitioningLifecycle && form.pendingLifecycleTransition === 'ready'
        }
        secondaryExtra={archiveZone}
        onCreateParty={form.handleCreateParty}
        onOpenLinkParty={onOpenLinkParty}
        onSaveMetadata={form.handleSaveMetadata}
        onMakeReady={() => void form.handleLifecycleTransition('ready')}
      />
    ) : archiveZone ? (
      <div className="party-editor-actions">
        <div className="party-editor-actions__trailing">{archiveZone}</div>
      </div>
    ) : null;

  const footerActions =
    catalogBlock || primaryActions ? (
      <div className="party-editor-about-actions">
        {catalogBlock}
        {primaryActions}
      </div>
    ) : null;

  const aboutActions =
    form.showTrackDisplay || footerActions ? (
      <>
        {form.showTrackDisplay ? (
          <PartyTrackDisplaySection
            value={form.partyTrackDisplay}
            onChange={form.setPartyTrackDisplaySettings}
            defaultExpanded={true}
          />
        ) : null}
        {footerActions}
      </>
    ) : null;

  const designPreviewHint = form.editorPhase ? (
    <p className="party-settings-design-hint">
      Оформление удобнее править в превью гостей — кнопка «Дизайн» слева от превью.
    </p>
  ) : null;

  return (
    <div className="party-settings-content">
      {connectivityBanner}
      <div className="party-settings-content__body">
        {form.editorPhase ? (
          <PartyEditor
            phase={form.editorPhase}
            section="all"
            fields={form.editorFields}
            handlers={form.editorHandlers}
            design={form.editorDesign}
            connection={form.editorConnection}
            isBlocked={form.isBlocked}
            aboutActions={aboutActions}
            defaultExpanded={true}
            designPreviewHint={designPreviewHint}
            showCopyUrl={form.showCopyUrl}
            copyUrlDisabled={
              form.networkActionsDisabled || form.isCreating || form.isSavingMetadata
            }
            copyUrlTitle={
              form.networkActionsDisabled
                ? 'Включите «Онлайн» в настройках'
                : 'Скопировать URL вечеринки'
            }
            onCopyUrl={form.handleCopyUrl}
          />
        ) : null}
      </div>
    </div>
  );
};

