export function applyDemoBlockedOverride(
  baseResult: PartyEditorPhaseResult,
  input: ResolvePartyEditorPhaseInput,
  demoBlockedOverride: PartyEditorBlockedReason | null,
): PartyEditorPhaseResult {
  if (demoBlockedOverride == null) {
    return baseResult;
  }

  const unblocked = resolvePartyEditorPhase({
    ...input,
    isAuth: true,
    isClientOutdated: false,
    isCheckingParty: false,
  });

  return {
    phase: unblocked.phase,
    blockedReason: demoBlockedOverride,
    isBlocked: true,
    effectiveLifecycle: unblocked.effectiveLifecycle,
  };
}

export function shouldPreserveShellContentWhenBlocked(
  demoBlockedOverride: PartyEditorBlockedReason | null,
): boolean {
  return demoBlockedOverride != null;
}

export function resolvePartyEditorPhase(
  input: ResolvePartyEditorPhaseInput,
): PartyEditorPhaseResult {
  if (!input.isAuth) {
    return { phase: null, blockedReason: 'auth', isBlocked: true, effectiveLifecycle: null };
  }
  if (input.isClientOutdated) {
    return { phase: null, blockedReason: 'outdated', isBlocked: true, effectiveLifecycle: null };
  }
  if (input.isCheckingParty) {
    return { phase: null, blockedReason: 'checking', isBlocked: true, effectiveLifecycle: null };
  }

  const linked = input.linkedParty != null;
  if (!linked) {
    return {
      phase: 'draft-unlinked',
      blockedReason: null,
      isBlocked: false,
      effectiveLifecycle: null,
    };
  }

  const lifecycle = input.partyLifecycleState ?? 'draft';

  let result: PartyEditorPhaseResult;
  if (lifecycle === 'completed') {
    result = {
      phase: 'completed',
      blockedReason: null,
      isBlocked: false,
      effectiveLifecycle: lifecycle,
    };
  } else if (lifecycle === 'ready') {
    result = {
      phase: 'ready',
      blockedReason: null,
      isBlocked: false,
      effectiveLifecycle: lifecycle,
    };
  } else {
    result = {
      phase: 'draft-linked',
      blockedReason: null,
      isBlocked: false,
      effectiveLifecycle: lifecycle,
    };
  }

  return applyPartyNotFoundBlocking(result, input);
}

function applyPartyNotFoundBlocking(
  result: PartyEditorPhaseResult,
  input: ResolvePartyEditorPhaseInput,
): PartyEditorPhaseResult {
  if (
    result.isBlocked ||
    input.linkedParty == null ||
    input.serverError !== ERROR_PARTY_NOT_FOUND
  ) {
    return result;
  }

  return {
    ...result,
    isBlocked: true,
    blockedReason: 'party-not-found',
  };
}

export function shouldShowPartyTrackDisplaySection(phase: PartyEditorPhase | null): boolean {
  return phase != null && phase !== 'completed';
}

import {
  InvalidPartyLifecycleTransitionError,
  ThemeNotEntitledError,
  partyService,
} from '@shared/services/partyService';
import {
  useAimpStore,
  useAuthStore,
  usePlayerAudioStore,
  useProjectStore,
  useSettingsStore,
  useUIStore,
} from '@shared/stores';
import { getOnlineNetworkPolicy } from '@shared/streaming';
import { isSessionExpiredError } from '@shared/utils/authErrorHandler';
import { sanitizeExternalUrl } from '@shared/utils';

import { markPartyPublishFullySynced } from './partyPublishSync';
import { loadPartyThemeAccess } from './partyThemeAccessLoad';
import { buildPlaylistForApi, buildUpdatePartyDto } from './partyWorkspaceApiBuilders';
import { usePartyWorkspaceStore } from './partyWorkspaceStore';
import { buildThemeNotEntitledMessage, isThemeNotEntitledError } from './partyWorkspaceUtils';
import { resolveHeaderPartyPublishDisabledReason } from './resolveHeaderPartyPublishDisabledReason';
import {
  PARTY_ARCHIVE_CONFIRM_MESSAGE,
  resolvePartyArchiveAvailability,
} from './resolvePartyArchiveAvailability';

function getPartyStore() {
  return usePartyWorkspaceStore.getState();
}

function isNetworkEnabledNow(): boolean {
  return getOnlineNetworkPolicy({
    enableStreaming: useSettingsStore.getState().enableStreaming,
  }).networkEnabled;
}

function buildPlaylistParamsFromStores() {
  const project = useProjectStore.getState();
  return {
    streamingSource: useSettingsStore.getState().streamingSource,
    aimpPlaylistSnapshot: useAimpStore.getState().bridgeState.playlistSnapshot,
    items: project.items,
    partyTrackDisplay: project.meta.partyTrackDisplay,
  };
}

async function handleThemeNotEntitled(error: ThemeNotEntitledError): Promise<void> {
  const store = getPartyStore();
  const message = buildThemeNotEntitledMessage(error, store.themeAccess);
  const safeContactUrl = sanitizeExternalUrl(store.themeAccess?.contactUrl);
  useUIStore.getState().addNotification({
    type: 'error',
    message,
    duration: 7000,
  });
  store.setThemeEntitlementModal({
    message,
    safeContactUrl,
  });
}

export async function refreshPartyThemeAccess(forceRefresh = false): Promise<void> {
  await loadPartyThemeAccess(forceRefresh);
}

export async function publishPartyToSite(): Promise<void> {
  const store = getPartyStore();
  const ui = useUIStore.getState();
  const networkEnabled = isNetworkEnabledNow();
  const isAuth = useAuthStore.getState().isAuthenticated();
  const linkedParty = useProjectStore.getState().meta.linkedParty;

  const disabledReason = resolveHeaderPartyPublishDisabledReason({
    isAuthenticated: isAuth,
    networkEnabled,
    hasLinkedParty: Boolean(linkedParty),
    partyLifecycleState: store.partyLifecycleState,
  });
  if (disabledReason) {
    if (!isAuth) {
      ui.openModal('account');
    }
    ui.addNotification({
      type: 'warning',
      message: disabledReason,
    });
    return;
  }

  if (!linkedParty) {
    return;
  }

  store.setIsPublishing(true);
  store.setServerError(null);
  try {
    const playlistForApi = buildPlaylistForApi(buildPlaylistParamsFromStores());
    await partyService.updatePartyPlaylist(linkedParty.id, playlistForApi);
    await partyService.updateParty(linkedParty.id, buildUpdatePartyDto(store));
    await refreshPartyThemeAccess(true);
    markPartyPublishFullySynced();
    ui.addNotification({
      type: 'success',
      message: 'Плейлист и настройки обновлены на сайте',
    });
  } catch (error) {
    console.error('Failed to publish playlist:', error);
    if (isSessionExpiredError(error)) {
      return;
    }
    if (isThemeNotEntitledError(error)) {
      await handleThemeNotEntitled(error);
      return;
    }
    ui.addNotification({
      type: 'error',
      message: error instanceof Error ? error.message : 'Ошибка публикации',
    });
  } finally {
    store.setIsPublishing(false);
  }
}

export async function publishPartyFromHeader(): Promise<void> {
  await publishPartyToSite();
}

export async function unarchivePartyFromHeader(): Promise<void> {
  const store = getPartyStore();
  const ui = useUIStore.getState();
  const networkEnabled = isNetworkEnabledNow();
  const isAuth = useAuthStore.getState().isAuthenticated();
  const linkedParty = useProjectStore.getState().meta.linkedParty;

  if (!networkEnabled) {
    ui.addNotification({
      type: 'warning',
      message: 'Вернуть из архива нельзя: включите «Онлайн» в настройках',
    });
    return;
  }
  if (!isAuth) {
    ui.addNotification({
      type: 'warning',
      message: 'Для смены статуса необходимо войти в аккаунт',
    });
    ui.openModal('account');
    return;
  }
  if (!linkedParty) {
    ui.addNotification({
      type: 'warning',
      message: 'Нет привязанной вечеринки',
    });
    return;
  }
  if (!window.confirm('Вернуть вечеринку из архива в статус «Ждёт начала»?')) {
    return;
  }

  store.setPendingLifecycleTransition('ready');
  store.setIsTransitioningLifecycle(true);
  try {
    const party = await partyService.transitionPartyLifecycle(linkedParty.id, 'ready');
    store.setPartyLifecycleState(party.partyLifecycleState);
  } catch (error) {
    console.error('Failed to unarchive party from header:', error);
    if (isSessionExpiredError(error)) {
      return;
    }
    if (error instanceof InvalidPartyLifecycleTransitionError) {
      ui.addNotification({
        type: 'error',
        message: error.message,
      });
      return;
    }
    ui.addNotification({
      type: 'error',
      message: error instanceof Error ? error.message : 'Не удалось вернуть вечеринку из архива',
    });
  } finally {
    store.setIsTransitioningLifecycle(false);
    store.setPendingLifecycleTransition(null);
  }
}

export async function archivePartyFromHeader(): Promise<void> {
  const store = getPartyStore();
  const ui = useUIStore.getState();
  const networkEnabled = isNetworkEnabledNow();
  const isAuth = useAuthStore.getState().isAuthenticated();
  const linkedParty = useProjectStore.getState().meta.linkedParty;

  if (!networkEnabled) {
    ui.addNotification({
      type: 'warning',
      message: 'Отправить в архив нельзя: включите «Онлайн» в настройках',
    });
    return;
  }
  if (!isAuth) {
    ui.addNotification({
      type: 'warning',
      message: 'Для смены статуса необходимо войти в аккаунт',
    });
    ui.openModal('account');
    return;
  }
  if (!linkedParty) {
    ui.addNotification({
      type: 'warning',
      message: 'Нет привязанной вечеринки',
    });
    return;
  }
  if (store.isTransitioningLifecycle) {
    ui.addNotification({
      type: 'warning',
      message: 'Смена статуса уже выполняется',
    });
    return;
  }

  const sessionMode = useProjectStore.getState().sessionState.mode;
  const playbackStatus = usePlayerAudioStore.getState().status;
  const streamingSource = useSettingsStore.getState().streamingSource;
  const aimpBridge = useAimpStore.getState().bridgeState;
  const availability = resolvePartyArchiveAvailability({
    partyLifecycleState: store.partyLifecycleState,
    sessionMode,
    playbackStatus: sessionMode === 'session' ? playbackStatus : null,
    aimpLiveStreamStarted: aimpBridge.liveStreamStarted,
    aimpPlaybackStatus: aimpBridge.playbackSnapshot?.status ?? null,
    streamingSource,
  });

  if (availability.isBlockedByLive) {
    window.alert(availability.blockedExplanation ?? 'Сейчас нельзя отправить вечеринку в архив');
    return;
  }
  if (!availability.canArchive || store.partyLifecycleState !== 'ready') {
    ui.addNotification({
      type: 'warning',
      message: 'Сейчас нельзя отправить вечеринку в архив',
    });
    return;
  }
  if (!window.confirm(PARTY_ARCHIVE_CONFIRM_MESSAGE)) {
    return;
  }

  store.setPendingLifecycleTransition('completed');
  store.setIsTransitioningLifecycle(true);
  try {
    const party = await partyService.transitionPartyLifecycle(linkedParty.id, 'completed');
    store.setPartyLifecycleState(party.partyLifecycleState);
  } catch (error) {
    console.error('Failed to archive party from header:', error);
    if (isSessionExpiredError(error)) {
      return;
    }
    if (error instanceof InvalidPartyLifecycleTransitionError) {
      ui.addNotification({
        type: 'error',
        message: error.message,
      });
      return;
    }
    ui.addNotification({
      type: 'error',
      message: error instanceof Error ? error.message : 'Не удалось отправить вечеринку в архив',
    });
  } finally {
    store.setIsTransitioningLifecycle(false);
    store.setPendingLifecycleTransition(null);
  }
}

export const PARTY_HEADER_GUIDE_TARGET_ATTR = 'data-party-header-guide-target';
export const PARTY_HEADER_GUIDE_TARGET_START = 'start-playback';
export const PARTY_HEADER_GUIDE_TARGET_RESUME = 'resume-playback';
export const PARTY_HEADER_GUIDE_TARGET_STOP = 'stop-playback';
export const PARTY_HEADER_GUIDE_HIGHLIGHT_CLASS = 'party-header-guide-highlight';
export const PARTY_HEADER_GUIDE_HIGHLIGHT_MS = 5000;
export const PARTY_GO_TO_PLAY_GUIDE_PANEL_WIDTH = 280;

export type PartyHeaderGuideTargetKind =
  | typeof PARTY_HEADER_GUIDE_TARGET_START
  | typeof PARTY_HEADER_GUIDE_TARGET_RESUME
  | typeof PARTY_HEADER_GUIDE_TARGET_STOP;

export function resolvePartyHeaderGuideTargetKind(input: {
  primaryStatus: string;
  streamingSource: string;
}): PartyHeaderGuideTargetKind {
  if (input.primaryStatus === 'Идёт') {
    return PARTY_HEADER_GUIDE_TARGET_STOP;
  }
  if (input.streamingSource === 'aimp') {
    return PARTY_HEADER_GUIDE_TARGET_START;
  }
  if (input.primaryStatus === 'Пауза' || input.primaryStatus === 'Конец') {
    return PARTY_HEADER_GUIDE_TARGET_RESUME;
  }
  return PARTY_HEADER_GUIDE_TARGET_START;
}

export function resolvePartyHeaderGuideStartLabel(streamingSource: string): string {
  return streamingSource === 'aimp' ? 'Включить онлайн' : 'Начать проигрывание';
}

export function resolvePartyHeaderGuideStopLabel(streamingSource: string): string {
  return streamingSource === 'aimp' ? 'Выключить онлайн' : 'Остановить проигрывание';
}

export function findPartyHeaderGuideTarget(kind: PartyHeaderGuideTargetKind): HTMLElement | null {
  return document.querySelector<HTMLElement>(`[${PARTY_HEADER_GUIDE_TARGET_ATTR}="${kind}"]`);
}

let highlightTimeoutId: number | null = null;
let highlightedElement: HTMLElement | null = null;

export function clearPartyHeaderGuideHighlight(): void {
  if (highlightTimeoutId != null) {
    window.clearTimeout(highlightTimeoutId);
    highlightTimeoutId = null;
  }
  if (highlightedElement) {
    highlightedElement.classList.remove(PARTY_HEADER_GUIDE_HIGHLIGHT_CLASS);
    highlightedElement = null;
  }
}

export function runPartyHeaderGuideHighlight(target: HTMLElement): void {
  clearPartyHeaderGuideHighlight();
  target.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'smooth' });
  highlightedElement = target;
  target.classList.add(PARTY_HEADER_GUIDE_HIGHLIGHT_CLASS);
  highlightTimeoutId = window.setTimeout(() => {
    clearPartyHeaderGuideHighlight();
  }, PARTY_HEADER_GUIDE_HIGHLIGHT_MS);
}

export function waitForPartyHeaderGuideTarget(
  kind: PartyHeaderGuideTargetKind,
  options?: { attempts?: number; intervalMs?: number; signal?: AbortSignal },
): Promise<HTMLElement | null> {
  const attempts = options?.attempts ?? 20;
  const intervalMs = options?.intervalMs ?? 50;
  const signal = options?.signal;

  return new Promise((resolve) => {
    if (signal?.aborted) {
      resolve(null);
      return;
    }

    let remaining = attempts;
    let timeoutId: number | null = null;

    const finish = (value: HTMLElement | null) => {
      if (timeoutId != null) {
        window.clearTimeout(timeoutId);
        timeoutId = null;
      }
      signal?.removeEventListener('abort', onAbort);
      resolve(value);
    };

    const onAbort = () => {
      finish(null);
    };

    signal?.addEventListener('abort', onAbort, { once: true });

    const tryFind = () => {
      if (signal?.aborted) {
        finish(null);
        return;
      }
      const found = findPartyHeaderGuideTarget(kind);
      if (found) {
        finish(found);
        return;
      }
      remaining -= 1;
      if (remaining <= 0) {
        finish(null);
        return;
      }
      timeoutId = window.setTimeout(tryFind, intervalMs);
    };

    tryFind();
  });
}

import type { ProjectSessionMode } from '@core/types/project';
