}

export interface PartyWorkspaceState {
  partyName: string;
  partyTitle: string;
  partySubtitle: string;
  themeId: PartyThemeId;
  customizationSettings: Record<string, unknown>;
  eventDateTime: string;
  eventEndDateTime: string;
  hasInitialEventEndDateTime: boolean;
  eventEndDateTimeTouched: boolean;
  description: string;
  place: string;
  city: string;
  schedule: string;
  timeZone: string;
  shortDescription: string;
  externalLinkUrl: string;
  externalLinkText: string;
  danceTags: string[];
  isListedInCatalog: boolean;
  isTogglingCatalogVisibility: boolean;
  isCreating: boolean;
  isPublishing: boolean;
  isSavingMetadata: boolean;
  partyLifecycleState: PartyLifecycleState | null;
  isTransitioningLifecycle: boolean;
  pendingLifecycleTransition: PartyLifecycleState | null;
  isCheckingParty: boolean;
  serverError: string | null;
  partyVerified: boolean;
  serverUnreachable: boolean;
  isReconnecting: boolean;
  lastManualCheckFailed: boolean;
  themeAccess: ThemeAccessDto | null;
  isThemeAccessLoading: boolean;
  themeAccessErrorMessage: string | null;
  themeEntitlementModal: ThemeEntitlementModalState | null;
  lastSyncedPublishParts: PartyPublishSyncParts | null;

  setPartyName: (value: string) => void;
  setPartyTitle: (value: string) => void;
  setPartySubtitle: (value: string) => void;
  setThemeId: (value: PartyThemeId) => void;
  setCustomizationSettings: (value: Record<string, unknown>) => void;
  setEventDateTime: (value: string) => void;
  setEventEndDateTime: (value: string) => void;
  setHasInitialEventEndDateTime: (value: boolean) => void;
  setEventEndDateTimeTouched: (value: boolean) => void;
  setDescription: (value: string) => void;
  setPlace: (value: string) => void;
  setCity: (value: string) => void;
  setSchedule: (value: string) => void;
  setTimeZone: (value: string) => void;
  setShortDescription: (value: string) => void;
  setExternalLinkUrl: (value: string) => void;
  setExternalLinkText: (value: string) => void;
  setDanceTags: (value: string[]) => void;
  setIsListedInCatalog: (value: boolean) => void;
  setIsTogglingCatalogVisibility: (value: boolean) => void;
  setIsCreating: (value: boolean) => void;
  setIsPublishing: (value: boolean) => void;
  setIsSavingMetadata: (value: boolean) => void;
  setPartyLifecycleState: (value: PartyLifecycleState | null) => void;
  setIsTransitioningLifecycle: (value: boolean) => void;
  setPendingLifecycleTransition: (value: PartyLifecycleState | null) => void;
  setIsCheckingParty: (value: boolean) => void;
  setServerError: (value: string | null) => void;
  setPartyVerified: (value: boolean) => void;
  setServerUnreachable: (value: boolean) => void;
  setIsReconnecting: (value: boolean) => void;
  setLastManualCheckFailed: (value: boolean) => void;
  setThemeAccess: (value: ThemeAccessDto | null) => void;
  setIsThemeAccessLoading: (value: boolean) => void;
  setThemeAccessErrorMessage: (value: string | null) => void;
  setThemeEntitlementModal: (value: ThemeEntitlementModalState | null) => void;
  setLastSyncedPublishParts: (value: PartyPublishSyncParts | null) => void;
  resetPartyWorkspaceState: () => void;
  resetPartyLinkState: () => void;
}

const defaultCustomizationSettings = getDefaultCustomizationSettings(
  DEFAULT_PARTY_THEME_ID,
) as Record<string, unknown>;

const initialPartyWorkspaceState = {
  partyName: '',
  partyTitle: '',
  partySubtitle: '',
  themeId: DEFAULT_PARTY_THEME_ID,
  customizationSettings: defaultCustomizationSettings,
  eventDateTime: '',
  eventEndDateTime: '',
  hasInitialEventEndDateTime: false,
  eventEndDateTimeTouched: false,
  description: '',
  place: '',
  city: '',
  schedule: '',
  timeZone: '',
  shortDescription: '',
  externalLinkUrl: '',
  externalLinkText: '',
  danceTags: [] as string[],
  isListedInCatalog: false,
  isTogglingCatalogVisibility: false,
  isCreating: false,
  isPublishing: false,
  isSavingMetadata: false,
  partyLifecycleState: null as PartyLifecycleState | null,
  isTransitioningLifecycle: false,
  pendingLifecycleTransition: null as PartyLifecycleState | null,
  isCheckingParty: false,
  serverError: null as string | null,
  partyVerified: false,
  serverUnreachable: false,
  isReconnecting: false,
  lastManualCheckFailed: false,
  themeAccess: null as ThemeAccessDto | null,
  isThemeAccessLoading: false,
  themeAccessErrorMessage: null as string | null,
  themeEntitlementModal: null as ThemeEntitlementModalState | null,
  lastSyncedPublishParts: null as PartyPublishSyncParts | null,
};

export const usePartyWorkspaceStore = createWithEqualityFn<PartyWorkspaceState>((set) => ({
  ...initialPartyWorkspaceState,

  setPartyName: (partyName) => set({ partyName }),
  setPartyTitle: (partyTitle) => set({ partyTitle }),
  setPartySubtitle: (partySubtitle) => set({ partySubtitle }),
  setThemeId: (themeId) => set({ themeId }),
  setCustomizationSettings: (customizationSettings) => set({ customizationSettings }),
  setEventDateTime: (eventDateTime) => set({ eventDateTime }),
  setEventEndDateTime: (eventEndDateTime) => set({ eventEndDateTime }),
  setHasInitialEventEndDateTime: (hasInitialEventEndDateTime) =>
    set({ hasInitialEventEndDateTime }),
  setEventEndDateTimeTouched: (eventEndDateTimeTouched) => set({ eventEndDateTimeTouched }),
  setDescription: (description) => set({ description }),
  setPlace: (place) => set({ place }),
  setCity: (city) => set({ city }),
  setSchedule: (schedule) => set({ schedule }),
  setTimeZone: (timeZone) => set({ timeZone }),
  setShortDescription: (shortDescription) => set({ shortDescription }),
  setExternalLinkUrl: (externalLinkUrl) => set({ externalLinkUrl }),
  setExternalLinkText: (externalLinkText) => set({ externalLinkText }),
  setDanceTags: (danceTags) => set({ danceTags }),
  setIsListedInCatalog: (isListedInCatalog) => set({ isListedInCatalog }),
  setIsTogglingCatalogVisibility: (isTogglingCatalogVisibility) =>
    set({ isTogglingCatalogVisibility }),
  setIsCreating: (isCreating) => set({ isCreating }),
  setIsPublishing: (isPublishing) => set({ isPublishing }),
  setIsSavingMetadata: (isSavingMetadata) => set({ isSavingMetadata }),
  setPartyLifecycleState: (partyLifecycleState) => set({ partyLifecycleState }),
  setIsTransitioningLifecycle: (isTransitioningLifecycle) => set({ isTransitioningLifecycle }),
  setPendingLifecycleTransition: (pendingLifecycleTransition) =>
    set({ pendingLifecycleTransition }),
  setIsCheckingParty: (isCheckingParty) => set({ isCheckingParty }),
  setServerError: (serverError) => set({ serverError }),
  setPartyVerified: (partyVerified) => set({ partyVerified }),
  setServerUnreachable: (serverUnreachable) => set({ serverUnreachable }),
  setIsReconnecting: (isReconnecting) => set({ isReconnecting }),
  setLastManualCheckFailed: (lastManualCheckFailed) => set({ lastManualCheckFailed }),
  setThemeAccess: (themeAccess) => set({ themeAccess }),
  setIsThemeAccessLoading: (isThemeAccessLoading) => set({ isThemeAccessLoading }),
  setThemeAccessErrorMessage: (themeAccessErrorMessage) => set({ themeAccessErrorMessage }),
  setThemeEntitlementModal: (themeEntitlementModal) => set({ themeEntitlementModal }),
  setLastSyncedPublishParts: (lastSyncedPublishParts) => set({ lastSyncedPublishParts }),
  resetPartyWorkspaceState: () =>
    set((state) => ({
      ...initialPartyWorkspaceState,
      customizationSettings: { ...defaultCustomizationSettings },
      danceTags: [],
      themeAccess: state.themeAccess,
      isThemeAccessLoading: state.isThemeAccessLoading,
      themeAccessErrorMessage: state.themeAccessErrorMessage,
    })),
  resetPartyLinkState: () =>
    set({
      serverError: null,
      partyVerified: false,
      partyLifecycleState: null,
      isListedInCatalog: false,
      serverUnreachable: false,
      isReconnecting: false,
      isCheckingParty: false,
      lastManualCheckFailed: false,
      lastSyncedPublishParts: null,
    }),
}));

export function resetPartyWorkspaceState(): void {
  usePartyWorkspaceStore.getState().resetPartyWorkspaceState();
}

export function resetPartyLinkState(): void {
  usePartyWorkspaceStore.getState().resetPartyLinkState();
}

import {
  getDefaultCustomizationSettings,
  normalizeBasicThemePaletteSettings,
  type PartyThemeId,
} from '@cherryplay/components';

import {
  ThemeAccessDto,
  LockedThemeDto,
  ThemeNotEntitledError,
} from '@shared/services/partyService';

export const RECONNECT_INTERVAL_MS = 60_000;
export const THEME_ACCESS_POLL_INTERVAL_MS = 5 * 60_000;
export { ERROR_PARTY_NOT_FOUND, ERROR_CONNECTION } from './partyWorkspaceConstants';
export const THEME_PICKER_UNAVAILABLE_MESSAGE = 'Выбор недоступен — нет связи с сервером';
export const THEME_PICKER_ONLINE_OFF_MESSAGE = 'Включите «Онлайн» в настройках';

export function resolveThemeAccessAfterFetchFailure(previousThemeAccess: ThemeAccessDto | null): {
  themeAccess: ThemeAccessDto | null;
  themeAccessErrorMessage: string | null;
} {
  if (previousThemeAccess) {
    return {
      themeAccess: previousThemeAccess,
      themeAccessErrorMessage: null,
    };
  }
  return {
    themeAccess: null,
    themeAccessErrorMessage: THEME_PICKER_UNAVAILABLE_MESSAGE,
  };
}

export function resolveThemePickerHintMessage(input: {
  networkEnabled: boolean;
  hasThemeAccess: boolean;
  isThemeAccessLoading: boolean;
  themeAccessErrorMessage: string | null;
}): string | null {
  const themePickerUnavailable = !input.hasThemeAccess && !input.isThemeAccessLoading;
  if (!input.networkEnabled) {
    return themePickerUnavailable ? THEME_PICKER_ONLINE_OFF_MESSAGE : null;
  }
  return (
    input.themeAccessErrorMessage ??
    (themePickerUnavailable ? THEME_PICKER_UNAVAILABLE_MESSAGE : null)
  );
}

export function resolveCreateBlockedByTheme(input: {
  themeAccess: ThemeAccessDto | null;
  isCurrentThemeLocked: boolean;
}): { blocked: boolean; title: string | undefined } {
  const blocked = Boolean(input.themeAccess) && input.isCurrentThemeLocked;
  return {
    blocked,
    title: blocked ? 'Выберите тему, доступную в вашем тарифе' : undefined,
  };
}

export function resolveDisplayPartyName(
  partyName: string | null | undefined,
  projectName: string | null | undefined,
  fallback = 'Вечеринка',
): string {
  const trimmedParty = partyName?.trim() ?? '';
  if (trimmedParty.length > 0) {
    return trimmedParty;
  }
  const trimmedProject = projectName?.trim() ?? '';
  if (trimmedProject.length > 0) {
    return trimmedProject;
  }
  return fallback;
}

export const REVOKED_THEME_PACKAGE_CODE = 'revoked-current-theme';
export const REVOKED_THEME_PACKAGE_NAME = 'Не доступна в пакетах';

const UNAVAILABLE_PACKAGE_LABELS = new Set([
  REVOKED_THEME_PACKAGE_NAME,
  'Недоступно',
  'недоступно',
]);

export function isUnavailableThemePackageLabel(packageName: string | null | undefined): boolean {
  if (!packageName) {
    return false;
  }
  const trimmed = packageName.trim();
  return UNAVAILABLE_PACKAGE_LABELS.has(trimmed);
}

export function buildThemeLockInfoMessage(packageName: string): string {
  if (isUnavailableThemePackageLabel(packageName)) {
    return 'Тема не доступна в ваших пакетах';
  }
  return `Доступно в пакете ${packageName}`;
}

export function buildThemeLockAriaLabel(themeName: string, packageName: string): string {
  if (isUnavailableThemePackageLabel(packageName)) {
    return `${themeName}. Тема не доступна в ваших пакетах.`;
  }
  return `${themeName}. Требуется пакет ${packageName}.`;
}

export function isThemeGranted(themeId: string, access: ThemeAccessDto | null): boolean {
  if (!access) {
    return false;
  }
  return access.grantedThemeIds.some((id) => id === themeId);
}

export function isThemeNotEntitledError(error: unknown): error is ThemeNotEntitledError {
  return error instanceof ThemeNotEntitledError;
}

export function resolveLockedThemeByPackageCode(
  access: ThemeAccessDto | null,
  packageCode: string,
): LockedThemeDto | null {
  if (!access) {
    return null;
  }
  return access.visibleLockedThemes.find((item) => item.packageCode === packageCode) ?? null;
}

export function buildThemeNotEntitledMessage(
  error: ThemeNotEntitledError,
  access: ThemeAccessDto | null,
): string {
  const firstRequiredPackage = error.requiredPackageCodes[0] ?? null;
  const lockedThemeInfo = firstRequiredPackage
    ? resolveLockedThemeByPackageCode(access, firstRequiredPackage)
    : null;

  const resolvedPackageName = lockedThemeInfo?.packageName ?? null;
  if (resolvedPackageName) {
    if (!isUnavailableThemePackageLabel(resolvedPackageName)) {
      return `Тема доступна в пакете "${resolvedPackageName}".`;
    }
    return 'Тема не доступна в ваших пакетах';
  }

  if (firstRequiredPackage === REVOKED_THEME_PACKAGE_CODE) {
    return 'Тема не доступна в ваших пакетах';
  }

  return 'Тема не доступна в ваших пакетах';
}

export function resolveLoadedCustomizationSettings(
  resolvedThemeId: PartyThemeId,
  customizationSettings: Record<string, unknown> | undefined,
): Record<string, unknown> {
  const defaults = getDefaultCustomizationSettings(resolvedThemeId);
  const hasMeaningful =
    customizationSettings &&
    typeof customizationSettings === 'object' &&
    !Array.isArray(customizationSettings) &&
    Object.keys(customizationSettings).length > 0;

  if (!hasMeaningful) {
    return defaults as Record<string, unknown>;
  }

  const raw = customizationSettings as Record<string, unknown>;
  if (resolvedThemeId === 'basic') {
    return normalizeBasicThemePaletteSettings({
      ...defaults,
      ...raw,
    }) as Record<string, unknown>;
  }

  return { ...defaults, ...raw } as Record<string, unknown>;
}

export function normalizeCustomizationSettings(
  settings: Record<string, unknown> | undefined,
): Record<string, unknown> | undefined {
  if (!settings) {
    return undefined;
  }

  const normalized = Object.entries(settings).reduce(
    (acc, [key, value]) => {
      if (value === null || value === undefined) {
        return acc;
      }

      const valueType = typeof value;
      if (valueType === 'string') {
        acc[key] = value as string;
      } else if (valueType === 'number' && !isNaN(value as number) && isFinite(value as number)) {
        acc[key] = value as number;
      } else if (key === 'basicUserSavedPalettes' && Array.isArray(value)) {
        acc[key] = value;
      } else if (valueType === 'object' && !Array.isArray(value)) {
        acc[key] = value as Record<string, unknown>;
      }
      return acc;
    },
    {} as Record<string, unknown>,
  );

  return Object.keys(normalized).length > 0 ? normalized : undefined;
}

import { resetPreviewScenario } from './partyPreviewScenarioActions';
import { clearPartyProgramEnded } from './partyProgramEndedStore';
import { resetPartySettingsUiState } from './partySettingsUiStore';
import {
  clearPartyWorkspaceLinkedPartyCheck,
  partyWorkspaceOneShotGuards,
  partyWorkspaceReconnectRefs,
} from './partyWorkspaceReconnectRefs';
import { resetPartyWorkspaceState } from './partyWorkspaceStore';

export function resetPartyWorkspaceForFreshProject(): void {
  resetPartyWorkspaceState();
  resetPartySettingsUiState();
  clearPartyProgramEnded();
  resetPreviewScenario();
  partyWorkspaceOneShotGuards.loadedPartyMetadataId = null;
  clearPartyWorkspaceLinkedPartyCheck();
  partyWorkspaceReconnectRefs.linkedParty = null;
  partyWorkspaceReconnectRefs.cancelled = true;
  if (partyWorkspaceReconnectRefs.intervalId !== null) {
    clearInterval(partyWorkspaceReconnectRefs.intervalId);
    partyWorkspaceReconnectRefs.intervalId = null;
  }
}

import type { PartyLifecycleState } from '@shared/services/partyService';

export function resolveHeaderPartyPublishDisabledReason(input: {
  isAuthenticated: boolean;
  networkEnabled: boolean;
  hasLinkedParty: boolean;
  partyLifecycleState: PartyLifecycleState | null;
}): string | null {
  if (!input.networkEnabled) {
    return 'Включите «Онлайн» в настройках';
  }
  if (!input.isAuthenticated) {
    return 'Для обновления необходимо войти в аккаунт';
  }
  if (!input.hasLinkedParty) {
    return 'Сначала создайте или привяжите вечеринку';
  }
  if (input.partyLifecycleState === 'completed') {
    return 'Сначала верните вечеринку из архива';
  }
  if (input.partyLifecycleState !== 'ready' && input.partyLifecycleState !== 'draft') {
    return 'Нечего отправлять на сайт';
  }
  return null;
}

import type { AimpPlaybackStatus } from '@shared/contracts/aimp';
import type { StorePlaybackStatus } from '@shared/contracts/storePlaybackStatus';
import type { PartyLifecycleState } from '@shared/services/partyService';

export type PartyArchiveAvailabilityMode = 'active' | 'quiet' | 'blockedByLive' | 'hidden';

export interface PartyArchiveAvailabilityInput {
  partyLifecycleState: PartyLifecycleState | null | undefined;
  sessionMode: string;
  playbackStatus?: StorePlaybackStatus | null;
  aimpLiveStreamStarted?: boolean;
  aimpPlaybackStatus?: AimpPlaybackStatus | null;
  streamingSource?: string;
}

export interface PartyArchiveAvailability {
  mode: PartyArchiveAvailabilityMode;
  showDangerSection: boolean;
  canArchive: boolean;
  isQuiet: boolean;
  isBlockedByLive: boolean;
  blockedExplanation: string | null;
}

export const PARTY_ARCHIVE_CONFIRM_MESSAGE =
  'Отправить вечеринку в архив? Гости перестанут видеть её как активную. Можно будет вернуть из архива с пульта.';

export const PARTY_ARCHIVE_LIVE_BLOCKED_EXPLANATION =
  'Сначала остановите проигрывание или выключите онлайн — нельзя отправить в архив во время эфира';

export function resolvePartyArchiveAvailability(
  input: PartyArchiveAvailabilityInput,
): PartyArchiveAvailability {
  if (input.partyLifecycleState !== 'ready') {
    return {
      mode: 'hidden',
      showDangerSection: false,
      canArchive: false,
      isQuiet: false,
      isBlockedByLive: false,
      blockedExplanation: null,
    };
  }

  const isAimpLive = input.streamingSource === 'aimp' && input.aimpLiveStreamStarted === true;
  const isAimpStopped = isAimpLive && input.aimpPlaybackStatus === 'stopped';
  const isAimpPaused = isAimpLive && input.aimpPlaybackStatus === 'paused';
  const isAimpPlaying = isAimpLive && !isAimpPaused && !isAimpStopped;
  const isCherryPlayPlaying =
    input.streamingSource !== 'aimp' &&
    input.sessionMode === 'session' &&
    input.playbackStatus === 'playing';
  const isCherryPlayPaused =
    input.streamingSource !== 'aimp' &&
    input.sessionMode === 'session' &&
    input.playbackStatus === 'paused';

  if (isAimpPlaying || isCherryPlayPlaying) {
    return {
      mode: 'blockedByLive',
      showDangerSection: true,
      canArchive: false,
      isQuiet: false,
      isBlockedByLive: true,
      blockedExplanation: PARTY_ARCHIVE_LIVE_BLOCKED_EXPLANATION,
    };
  }

  if (isAimpPaused || isCherryPlayPaused) {
    return {
      mode: 'quiet',
      showDangerSection: true,
      canArchive: true,
      isQuiet: true,
      isBlockedByLive: false,
      blockedExplanation: null,
    };
  }

  return {
    mode: 'active',
    showDangerSection: true,
    canArchive: true,
    isQuiet: false,
    isBlockedByLive: false,
    blockedExplanation: null,
  };
}

