import { useEffect, useRef } from 'react';

import { useProjectStore } from '@shared/stores';
import {
  syncDemoWithMainPlayer,
  syncMainWithDemoPlayer,
} from '@shared/stores/playbackDeviceConflictSync';
import { usePlayerAudioStore } from '@shared/stores/playerAudioStore';
import { useSettingsStore } from '@shared/stores/settingsStore';
import { logger } from '@shared/utils';

/**
 * Silently restores the player to the last session track on mount.
 * Runs once: if the component remounts (layout change), the ref guard
 * prevents re-loading a track that is already loaded.
 *
 * Waits for projectStore hydration to complete before attempting recovery,
 * because electronStorage (IndexedDB via localforage) is async and items
 * may still be empty at first render.
 */
export function useSessionRecovery(): void {
  const hasRestoredRef = useRef(false);

  useEffect(() => {
    const runRecovery = () => {
      // Two-layer guard against double-loading:
      // 1. hasRestoredRef prevents double-fire within a single mount cycle (React Strict Mode
      //    unmounts+remounts in development, firing the effect twice).
      // 2. The store-level check below prevents re-loading when the component remounts due to
      //    a layout change while the track is already loaded. Do NOT remove the store check
      //    thinking the ref alone is sufficient — the ref resets on every real remount.
      if (hasRestoredRef.current) return;
      hasRestoredRef.current = true;

      const projectState = useProjectStore.getState();
      const { mode, currentTrackId } = projectState.sessionState;

      if (mode !== 'session') return;

      const { playerAudioDeviceId, demoPlayerAudioDeviceId } = useSettingsStore.getState();
      syncMainWithDemoPlayer(playerAudioDeviceId);
      syncDemoWithMainPlayer(demoPlayerAudioDeviceId);

      if (!currentTrackId) return;

      // Already loaded — user navigated away and back (remount guard, see comment above)
      if (usePlayerAudioStore.getState().currentTrack?.id === currentTrackId) return;

      const allTracks = projectState.getAllTracksInOrder();
      const track = allTracks.find((t) => t.id === currentTrackId);
      if (!track) return;

      // void: intentional floating promise — error is captured in playerAudioStore.error
      // and surfaced via the UI (red play button); no caller needs to await this.
      void usePlayerAudioStore
        .getState()
        .loadTrack(track)
        .catch((error) => {
          logger.error('Session recovery: failed to load track', error);
        });
    };

    // Check if already hydrated (component may mount after hydration completes)
    if (useProjectStore.persist.hasHydrated()) {
      runRecovery();
      return;
    }

    // Wait for hydration to complete before reading items from the store
    const unsub = useProjectStore.persist.onFinishHydration(() => {
      runRecovery();
      unsub();
    });
    return () => unsub();
  }, []); // empty deps — run once on mount
}

import { DividerCalculationContext, formatTimeFromDuration } from '@shared/utils/dividerUtils';

/**
 * Форматирует метку отсечки для режима preparation
 * @param trackId - ID трека
 * @param context - Контекст расчета отсечек
 * @returns Отформатированная метка времени
 */
export function formatPreparationDividerLabel(
  trackId: string,
  context: DividerCalculationContext,
): string {
  const { tracks, hourDividerInterval } = context;

  // Находим индекс трека
  const trackIndex = tracks.findIndex((t) => t.id === trackId);
  if (trackIndex === -1 || hourDividerInterval <= 0) {
    return '';
  }

  // Режим подготовки: учитываем паузы между треками
  // Считаем накопленную длительность от начала, пропуская отключенные треки
  let accumulatedDuration = 0;
  for (let i = 0; i <= trackIndex && i < tracks.length; i++) {
    const track = tracks[i];
    // Пропускаем отключённые треки
    if (context.isTrackDisabled(track.id)) {
      continue;
    }
    // Учитываем паузы между треками (как в режиме сессии)
    accumulatedDuration += context.calculateTrackDurationWithPause(track);
  }
  return formatTimeFromDuration(accumulatedDuration);
}

import {
  DividerCalculationContext,
  DividerMarkers,
  calculateAccumulatedDuration,
  calculateNextEvenTime,
  formatTimeFromTimestamp,
} from '@shared/utils/dividerUtils';

/**
 * Форматирует метку отсечки для режима session
 * @param trackId - ID трека
 * @param context - Контекст расчета отсечек
 * @param dividerMarkers - Результат расчета отсечек
 * @returns Отформатированная метка времени
 */
export function formatSessionDividerLabel(
  trackId: string,
  context: DividerCalculationContext,
  dividerMarkers: DividerMarkers,
): string {
  const { tracks, hourDividerInterval } = context;

  // Находим индекс трека
  const trackIndex = tracks.findIndex((t) => t.id === trackId);
  if (trackIndex === -1 || hourDividerInterval <= 0) {
    return '';
  }

  // Получаем время отсечки из markers
  const dividerTime = dividerMarkers.markers.get(trackId);

  if (dividerTime !== null && dividerTime !== undefined && dividerTime > 0) {
    // Используем уже вычисленное время из markers
    return formatTimeFromTimestamp(dividerTime);
  }

  // Если время не найдено в markers, вычисляем его
  // Это может произойти, если отсечка была вычислена, но время не было сохранено
  const { startPosition } = dividerMarkers;
  const { startFromIndex, currentRealTime } = startPosition;

  if (currentRealTime === null) {
    return '';
  }

  // Считаем накопленную длительность до этого трека
  // Используем функцию calculateAccumulatedDuration напрямую
  const accumulatedDuration = calculateAccumulatedDuration(
    tracks,
    startFromIndex,
    trackIndex,
    context,
  );

  // Вычисляем будущее реальное время
  const futureRealTime = currentRealTime + accumulatedDuration * 1000;

  // Вычисляем следующее ровное время
  const nextEvenTime = calculateNextEvenTime(currentRealTime, hourDividerInterval);

  // Находим, какое ровное время соответствует этой отсечке
  let currentEvenTime = nextEvenTime;
  while (futureRealTime >= currentEvenTime) {
    currentEvenTime += hourDividerInterval * 1000;
  }

  // Возвращаем предыдущее ровное время (то, которое мы достигли или прошли)
  const prevEvenTime = currentEvenTime - hourDividerInterval * 1000;
  return formatTimeFromTimestamp(prevEvenTime);
}

import { FileSource } from '../hooks/usePlayerFileProcessing';

/**
 * Создает массив источников файлов из массивов файлов и директорий
 * @param files - Массив путей к файлам
 * @param directories - Массив путей к директориям
 * @returns Массив источников файлов
 */
export function createFileSources(files: string[], directories: string[]): FileSource[] {
  const sources: FileSource[] = [];
  if (files.length > 0) {
    sources.push({ type: 'files', paths: files });
  }
  if (directories.length > 0) {
    sources.push({ type: 'directories', paths: directories });
  }
  return sources;
}

import { ProjectItem, isProjectGroup, isProjectTrack, ActionAfterTrack } from '@core/types/project';
import { Track } from '@core/types/track';

/**
 * Результат проверки состояния элемента
 */
export interface ItemState {
  isPlayed: boolean;
  isDisabled: boolean;
}

/**
 * Проверяет состояние элемента (трека или группы)
 * @param item - Элемент для проверки
 * @param isTrackPlayed - Функция проверки проигранности трека
 * @param isGroupDisabled - Функция проверки отключенности группы
 * @param isTrackOrGroupDisabled - Функция проверки отключенности трека или его родительских групп
 * @param getAllTracksInOrder - Функция получения всех треков из группы
 * @returns Состояние элемента
 */
export function getItemState(
  item: ProjectItem,
  isTrackPlayed: (id: string) => boolean,
  isGroupDisabled: (id: string) => boolean,
  isTrackOrGroupDisabled: (id: string) => boolean,
  getAllTracksInOrder: (items: ProjectItem[]) => Track[],
): ItemState {
  if (isProjectGroup(item)) {
    // Для группы проверяем состояние всех треков внутри
    const groupTracks = getAllTracksInOrder([item]);
    const isPlayed = groupTracks.length > 0 && groupTracks.every((t) => isTrackPlayed(t.id));
    const isDisabled = isGroupDisabled(item.id);
    return { isPlayed, isDisabled };
  } else if (isProjectTrack(item)) {
    // Для трека проверяем его состояние и состояние родительских групп
    const isPlayed = isTrackPlayed(item.id);
    const isDisabled = isTrackOrGroupDisabled(item.id);
    return { isPlayed, isDisabled };
  }
  // Fallback для неизвестных типов
  return { isPlayed: false, isDisabled: false };
}

/**
 * Проверяет, заблокирован ли элемент (нельзя удалять/перемещать в режиме сессии)
 * @param item - Элемент для проверки
 * @param isPreparationMode - Режим подготовки
 * @param activePlayerTrackId - ID текущего активного трека
 * @param itemState - Состояние элемента
 * @param getAllTracksInOrder - Функция получения всех треков из группы
 * @param isTrackPlayed - Функция проверки проигранности трека
 * @returns true, если элемент заблокирован
 */
export function isItemLocked(
  item: ProjectItem,
  isPreparationMode: boolean,
  activePlayerTrackId: string | null | undefined,
  itemState: ItemState,
  getAllTracksInOrder: (items: ProjectItem[]) => Track[],
  isTrackPlayed: (id: string) => boolean,
): boolean {
  if (isPreparationMode) {
    return false;
  }

  const track = isProjectTrack(item) ? item : null;
  const isCurrentTrack = track?.id === activePlayerTrackId;

  // Элемент заблокирован, если он проигран или является текущим треком
  if (itemState.isPlayed || isCurrentTrack) {
    return true;
  }

  // Для группы проверяем, содержит ли она проигранные или текущий трек
  if (isProjectGroup(item)) {
    const groupTracks = getAllTracksInOrder([item]);
    return groupTracks.some((t) => isTrackPlayed(t.id) || t.id === activePlayerTrackId);
  }

  return false;
}

/**
 * Вычисляет длительность группы с учетом пауз между треками
 * @param group - Группа для вычисления
 * @param getAllTracksInOrder - Функция получения всех треков из группы
 * @param getEffectiveTrackSettings - Функция получения эффективных настроек трека
 * @returns Длительность группы в секундах или undefined, если нет треков с длительностью
 */
export function calculateGroupDurationWithPauses(
  group: ProjectItem,
  getAllTracksInOrder: (items: ProjectItem[]) => Track[],
  getEffectiveTrackSettings: (trackId: string) => {
    actionAfterTrack: ActionAfterTrack;
    pauseBetweenTracks: number;
  },
): number | undefined {
  if (!isProjectGroup(group)) {
    return undefined;
  }

  const groupTracks = getAllTracksInOrder([group]);
  let total = 0;

  for (let i = 0; i < groupTracks.length; i++) {
    const groupTrack = groupTracks[i];
    total += groupTrack.duration || 0;
    // Получаем эффективные настройки для трека (учитывает иерархию: трек -> группа -> глобальные)
    const settings = getEffectiveTrackSettings(groupTrack.id);
    // Если действие "pauseAndNext", добавляем время паузы
    if (settings.actionAfterTrack === 'pauseAndNext') {
      // Добавляем паузу после каждого трека с настройкой pauseAndNext
      // (включая последний трек в группе)
      total += settings.pauseBetweenTracks || 0;
    }
  }

  // Если есть хотя бы один трек с длительностью, возвращаем результат
  const hasAnyDuration = groupTracks.some((t) => t.duration && t.duration > 0);
  return hasAnyDuration ? total : undefined;
}

import { ProjectItem, isProjectGroup, isProjectTrack } from '@core/types/project';
import { Track } from '@core/types/track';

/**
 * Проверяет, отключен ли трек или его родительские группы
 */
export function isTrackOrGroupDisabled(
  itemId: string,
  isTrackDisabled: (id: string) => boolean,
  isGroupDisabled: (id: string) => boolean,
  getItemPath: (id: string) => string[],
  findItemById: (id: string) => ProjectItem | null,
): boolean {
  // Проверяем, отключен ли сам трек
  if (isTrackDisabled(itemId)) {
    return true;
  }

  // Проверяем родительские группы
  const path = getItemPath(itemId);
  // Путь содержит: [rootGroupId, innerGroupId, ..., itemId]
  // Проверяем все элементы пути кроме последнего (самого элемента)
  if (path.length > 1) {
    for (let i = path.length - 2; i >= 0; i--) {
      const groupId = path[i];
      // Убеждаемся, что это действительно группа, а не трек
      const item = findItemById(groupId);
      if (item && isProjectGroup(item) && isGroupDisabled(groupId)) {
        return true;
      }
    }
  }

  return false;
}

/**
 * Проверяет, является ли трек активным (не проигран и не отключен)
 */
export function isTrackActive(
  trackId: string,
  isTrackPlayed: (id: string) => boolean,
  isTrackOrGroupDisabled: (id: string) => boolean,
): boolean {
  return !isTrackPlayed(trackId) && !isTrackOrGroupDisabled(trackId);
}

/**
 * Помечает пропущенные отключённые треки как проигранные
 */
export function markSkippedDisabledTracks(
  fromIndex: number,
  toIndex: number,
  allTracks: Track[],
  isTrackOrGroupDisabled: (id: string) => boolean,
  isTrackPlayed: (id: string) => boolean,
  markTrackAsPlayed: (id: string) => void,
): void {
  for (let i = fromIndex + 1; i < toIndex; i++) {
    const track = allTracks[i];
    if (track && isTrackOrGroupDisabled(track.id) && !isTrackPlayed(track.id)) {
      markTrackAsPlayed(track.id);
    }
  }
}

/**
 * Проверяет, можно ли удалить выбранные элементы
 * (не должно быть проигранных или текущего в режиме сессии)
 */
export function canRemoveSelectedItems(
  selectedItemIds: Set<string>,
  isPreparationMode: boolean,
  activePlayerTrackId: string | null | undefined,
  findItemById: (id: string) => ProjectItem | null,
  isTrackPlayed: (id: string) => boolean,
  getAllTracksInOrder: (items: ProjectItem[]) => Track[],
): boolean {
  if (isPreparationMode) {
    return true;
  }

  return Array.from(selectedItemIds).every((itemId) => {
    const item = findItemById(itemId);
    if (!item) {
      return true;
    }

    // Для треков проверяем проигранность и текущий статус
    if (isProjectTrack(item)) {
      const trackIsPlayed = isTrackPlayed(itemId);
      const isCurrentTrack = itemId === activePlayerTrackId;
      return !trackIsPlayed && !isCurrentTrack;
    }

    // Для групп проверяем, что внутри нет проигранных или текущего трека
    if (isProjectGroup(item)) {
      const groupTracks = getAllTracksInOrder([item]);
      return groupTracks.every((track) => {
        const trackIsPlayed = isTrackPlayed(track.id);
        const isCurrentTrack = track.id === activePlayerTrackId;
        return !trackIsPlayed && !isCurrentTrack;
      });
    }

    return true;
  });
}

/**
 * Проверяет, являются ли выбранные элементы соседними
 */
export function areItemsConsecutive(
  itemIds: string[],
  items: ProjectItem[],
  getItemPath: (id: string) => string[],
  findItemById: (id: string) => ProjectItem | null,
): boolean {
  if (itemIds.length < 2) return false;

  // Получаем пути для всех элементов
  const itemPaths = itemIds.map((id) => ({
    id,
    path: getItemPath(id) || [],
  }));

  // Проверяем, что все элементы находятся в одном контейнере (корневой список или одна группа)
  const firstPath = itemPaths[0].path;
  const parentId = firstPath.length > 1 ? firstPath[firstPath.length - 2] : null;

  // Проверяем, что все элементы имеют одного родителя
  for (let i = 1; i < itemPaths.length; i++) {
    const currentPath = itemPaths[i].path;
    const currentParentId = currentPath.length > 1 ? currentPath[currentPath.length - 2] : null;
    if (currentParentId !== parentId) {
      return false;
    }
  }

  // Находим родительский контейнер
  let parentContainer: ProjectItem[];
  if (parentId === null) {
    // Элементы в корневом списке
    parentContainer = items;
  } else {
    // Элементы внутри группы - находим группу
    const parentGroup = findItemById(parentId);
    if (!parentGroup || !isProjectGroup(parentGroup)) {
      return false;
    }
    parentContainer = parentGroup.items;
  }

  // Находим индексы элементов в родительском контейнере
  const itemIndices: number[] = [];
  for (const itemId of itemIds) {
    const index = parentContainer.findIndex((item) => item.id === itemId);
    if (index === -1) {
      return false;
    }
    itemIndices.push(index);
  }

  // Проверяем, что элементы соседние
  const sortedIndices = [...itemIndices].sort((a, b) => a - b);
  for (let i = 1; i < sortedIndices.length; i++) {
    if (sortedIndices[i] !== sortedIndices[i - 1] + 1) {
      return false;
    }
  }

  return true;
}

