  });

  it('prefers Конец over Пауза when both paused and programEnded', () => {
    const withEnd = resolveHeaderPartyStatus({
      ...readySession,
      playbackStatus: 'paused',
      programEnded: true,
    });
    const pausedOnly = resolveHeaderPartyStatus({
      ...readySession,
      playbackStatus: 'paused',
      programEnded: false,
