  Integrated loudness:
    I:         -18.5 LUFS

  True peak:
    TPK:  -3.2  -1.1 dBFS
`;

describe('parseEbur128Summary', () => {
  test('parses integrated LUFS and true peak from Summary fixture', () => {
    const result = parseEbur128Summary(EBUR128_SUMMARY_FIXTURE);

    expect(result).toEqual({
      integratedLufs: -17.7,
      lraLowLufs: -23.1,
      lraLu: 8.1,
      truePeakDb: -0.4,
    });
  });

  test('parses dBTP true peak label', () => {
    const result = parseEbur128Summary(EBUR128_DBTP_FIXTURE);

    expect(result).toEqual({
      integratedLufs: -23,
      lraLu: 0,
      truePeakDb: -2.3,
    });
  });

  test('prefers dBTP over dBFS when both peak labels are present', () => {
    const stderr = `
Summary:

  Integrated loudness:
    I:         -18.0 LUFS

  True peak:
    Peak:       -0.4 dBFS
    Peak:       -2.3 dBTP
`;

    const result = parseEbur128Summary(stderr);

    expect(result).toEqual({
      integratedLufs: -18,
      truePeakDb: -2.3,
    });
  });

  test('uses max channel TPK for multichannel output', () => {
    const result = parseEbur128Summary(EBUR128_MULTICHANNEL_TPK_FIXTURE);

    expect(result).toEqual({
      integratedLufs: -18.5,
      truePeakDb: -1.1,
    });
  });

  test('falls back to last streaming I: value when Summary integrated block is missing', () => {
    const stderr = `
[Parsed_ebur128_0 @ 0xabc] t: 1.0 M:-20.0 S:-20.0 I: -22.5 LUFS LRA: 1.0 LU
[Parsed_ebur128_0 @ 0xabc] t: 2.0 M:-19.0 S:-19.0 I: -21.0 LUFS LRA: 1.0 LU
True peak:
  Peak:       -4.0 dBFS
`;

    const result = parseEbur128Summary(stderr);

    expect(result).toEqual({
      integratedLufs: -21,
      truePeakDb: -4,
    });
  });

  test('returns null for empty stderr', () => {
    expect(parseEbur128Summary('')).toBeNull();
  });

  test('returns null when integrated loudness is out of sane range', () => {
    const stderr = `
Summary:
  Integrated loudness:
    I:         -120.0 LUFS
  True peak:
    Peak:       -1.0 dBFS
`;

    expect(parseEbur128Summary(stderr)).toBeNull();
  });

  test('returns null when true peak is out of sane range', () => {
    const stderr = `
Summary:
  Integrated loudness:
    I:         -18.0 LUFS
  True peak:
    Peak:       25.0 dBFS
`;

    expect(parseEbur128Summary(stderr)).toBeNull();
  });
});

describe('computeTrackGainDb', () => {
  test('applies target LUFS offset when headroom allows', () => {
    expect(computeTrackGainDb(-23, -6, DEFAULT_TARGET_LUFS, HEADROOM_DB_TP)).toBe(5);
  });

  test('caps gain to respect −1 dBTP headroom', () => {
    expect(computeTrackGainDb(-23, -2, DEFAULT_TARGET_LUFS, HEADROOM_DB_TP)).toBe(1);
  });

  test('reduces gain when true peak already exceeds headroom', () => {
    expect(computeTrackGainDb(-20, 0.5, DEFAULT_TARGET_LUFS, HEADROOM_DB_TP)).toBe(-1.5);
  });

  test('uses smaller of LUFS offset and headroom cap', () => {
    expect(computeTrackGainDb(-20, -5, DEFAULT_TARGET_LUFS, HEADROOM_DB_TP)).toBe(2);
  });

  test('respects custom target LUFS', () => {
    expect(computeTrackGainDb(-16, -6, -14, HEADROOM_DB_TP)).toBe(2);
  });
});

import { renderHook } from '@testing-library/react';

import { useDemoPlayerFloatingVisibility } from '../../src/app/hooks/useDemoPlayerFloatingVisibility';
import type { Track } from '../../src/core/types/track';
import type { PlayerStatus } from '../../src/shared/stores/demoPlayerStore';

const track: Track = {
  id: 'track-1',
  name: 'Demo',
  path: 'D:/demo.flac',
  duration: 120,
};

type VisibilityParams = {
  hasDemoPlayerWorkspace: boolean;
  demoPlayerFloatingOpen: boolean;
  currentTrack: Track | null;
  demoPlayerStatus: PlayerStatus;
  setDemoPlayerFloatingOpen: jest.Mock;
};

const createParams = (overrides: Partial<VisibilityParams> = {}): VisibilityParams => ({
  hasDemoPlayerWorkspace: false,
  demoPlayerFloatingOpen: false,
  currentTrack: null,
  demoPlayerStatus: 'idle',
  setDemoPlayerFloatingOpen: jest.fn(),
  ...overrides,
});

describe('useDemoPlayerFloatingVisibility', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('auto-opens floating panel when a demo session becomes active', () => {
    const setDemoPlayerFloatingOpen = jest.fn();
    const { rerender } = renderHook(
      (props: VisibilityParams) => useDemoPlayerFloatingVisibility(props),
      {
        initialProps: createParams({ setDemoPlayerFloatingOpen }),
      },
    );

    rerender(
      createParams({
        setDemoPlayerFloatingOpen,
        currentTrack: track,
        demoPlayerStatus: 'paused',
      }),
    );

    expect(setDemoPlayerFloatingOpen).toHaveBeenCalledWith(true);
  });

  it('forces floating panel closed when demo-player workspace is present', () => {
    const setDemoPlayerFloatingOpen = jest.fn();

    renderHook(() =>
      useDemoPlayerFloatingVisibility(
        createParams({
          hasDemoPlayerWorkspace: true,
          demoPlayerFloatingOpen: true,
          currentTrack: track,
          setDemoPlayerFloatingOpen,
        }),
      ),
    );

    expect(setDemoPlayerFloatingOpen).toHaveBeenCalledWith(false);
  });

  it('suppresses auto-open after manual close for the same session and track', () => {
    const setDemoPlayerFloatingOpen = jest.fn();
    const { rerender } = renderHook(
      (props: VisibilityParams) => useDemoPlayerFloatingVisibility(props),
      {
        initialProps: createParams({
          setDemoPlayerFloatingOpen,
          currentTrack: track,
          demoPlayerStatus: 'paused',
          demoPlayerFloatingOpen: true,
        }),
      },
    );

    setDemoPlayerFloatingOpen.mockClear();

    rerender(
      createParams({
        setDemoPlayerFloatingOpen,
        currentTrack: track,
        demoPlayerStatus: 'paused',
        demoPlayerFloatingOpen: false,
      }),
    );

    expect(setDemoPlayerFloatingOpen).not.toHaveBeenCalledWith(true);
  });

  it('closes floating panel when demo session ends', () => {
    const setDemoPlayerFloatingOpen = jest.fn();
    const { rerender } = renderHook(
      (props: VisibilityParams) => useDemoPlayerFloatingVisibility(props),
      {
        initialProps: createParams({
          setDemoPlayerFloatingOpen,
          currentTrack: track,
          demoPlayerStatus: 'paused',
          demoPlayerFloatingOpen: true,
        }),
      },
    );

    setDemoPlayerFloatingOpen.mockClear();

    rerender(
      createParams({
        setDemoPlayerFloatingOpen,
        currentTrack: null,
        demoPlayerStatus: 'idle',
        demoPlayerFloatingOpen: true,
      }),
    );

    expect(setDemoPlayerFloatingOpen).toHaveBeenCalledWith(false);
  });

  it('reports isFloatingVisible only when open and no demo-player workspace', () => {
    const openParams = createParams({
      currentTrack: track,
      demoPlayerStatus: 'paused',
      demoPlayerFloatingOpen: true,
    });

    const { result: openResult } = renderHook(() => useDemoPlayerFloatingVisibility(openParams));
    expect(openResult.current.isFloatingVisible).toBe(true);

    const { result: workspaceResult } = renderHook(() =>
      useDemoPlayerFloatingVisibility({
        ...openParams,
        hasDemoPlayerWorkspace: true,
      }),
    );
    expect(workspaceResult.current.isFloatingVisible).toBe(false);
  });
});

