    bindPlaybackEngineToStore(engine, {
      onStatusChanged: jest.fn(),
      onPositionChanged: jest.fn(),
      onDurationChanged: jest.fn(),
      onEnded: jest.fn(),
      onError: (message) => {
        onError(message);
