import { useBrowserLogin } from '@shared/hooks/useBrowserLogin';

describe('useBrowserLogin', () => {
  beforeEach(() => {
    startBrowserLoginMock.mockReset();
    invokeMock.mockReset();
    beginBrowserLoginFlow.mockClear();
    completeBrowserLoginFlow.mockClear();
    failBrowserLoginFlow.mockClear();
    resetBrowserLoginFlow.mockClear();
    subscribeBrowserLoginFlow.mockClear();
    isPlatformInitializedMock.mockReturnValue(true);
    getAppModeMock.mockReturnValue('electron');
    getBrowserLoginFlowState.mockReturnValue({ status: 'idle', error: null });
    isAuthenticatedMock.mockReturnValue(false);
    startBrowserLoginMock.mockResolvedValue(undefined);
    invokeMock.mockResolvedValue({ success: true });
  });

  it('startLogin: cancel IPC → begin → startBrowserLogin', async () => {
    getBrowserLoginFlowState.mockReturnValue({ status: 'waiting', error: null });
    const { result } = renderHook(() => useBrowserLogin());

    await act(async () => {
      await result.current.startLogin();
    });

    expect(invokeMock).toHaveBeenCalledWith('auth:cancelCallback');
    expect(beginBrowserLoginFlow).toHaveBeenCalled();
    expect(startBrowserLoginMock).toHaveBeenCalledTimes(1);
  });

  it('openBrowser failure → failBrowserLoginFlow', async () => {
    startBrowserLoginMock.mockRejectedValueOnce(new Error('Failed to open browser'));
    const { result } = renderHook(() => useBrowserLogin());

    await act(async () => {
      await result.current.startLogin();
    });

    expect(failBrowserLoginFlow).toHaveBeenCalledWith('Failed to open browser');
  });

  it('authenticated while waiting → complete', async () => {
    getBrowserLoginFlowState.mockReturnValue({ status: 'waiting', error: null });
    isAuthenticatedMock.mockReturnValue(true);

    renderHook(() => useBrowserLogin());

    await waitFor(() => {
      expect(completeBrowserLoginFlow).toHaveBeenCalled();
    });
  });

  it('retryLogin resets and starts again', async () => {
    const { result } = renderHook(() => useBrowserLogin());

    await act(async () => {
      result.current.retryLogin();
    });

    expect(resetBrowserLoginFlow).toHaveBeenCalled();
    await waitFor(() => {
      expect(startBrowserLoginMock).toHaveBeenCalled();
    });
  });

  it('cancelWaiting invokes auth:cancelCallback and resets', () => {
    const { result } = renderHook(() => useBrowserLogin());

    act(() => {
      result.current.cancelWaiting();
    });

    expect(invokeMock).toHaveBeenCalledWith('auth:cancelCallback');
    expect(resetBrowserLoginFlow).toHaveBeenCalled();
  });

  it('cancel IPC no-op when platform not ready', async () => {
    isPlatformInitializedMock.mockReturnValue(false);
    const { result } = renderHook(() => useBrowserLogin());

    await act(async () => {
      await result.current.startLogin();
    });

    expect(invokeMock).not.toHaveBeenCalled();
    expect(startBrowserLoginMock).toHaveBeenCalledTimes(1);
  });

  it('cancel IPC no-op when not electron', async () => {
    getAppModeMock.mockReturnValue('demo');
    const { result } = renderHook(() => useBrowserLogin());

    await act(async () => {
      await result.current.startLogin();
    });

    expect(invokeMock).not.toHaveBeenCalled();
    expect(startBrowserLoginMock).toHaveBeenCalledTimes(1);
  });
});

import { act, renderHook } from '@testing-library/react';

import { usePlaybackTimeline } from '../../../src/shared/hooks/usePlaybackTimeline';

describe('usePlaybackTimeline', () => {
  it('uses engine position when not scrubbing', () => {
    const seek = jest.fn();
    const { result } = renderHook(() =>
      usePlaybackTimeline({
        position: 42,
        duration: 200,
        disabled: false,
        seek,
      }),
    );

    expect(result.current.displayPosition).toBe(42);
    expect(result.current.resolvedDuration).toBe(200);
  });

  it('keeps local scrub value while scrubbing', () => {
    const seek = jest.fn();
    const { result } = renderHook(() =>
      usePlaybackTimeline({
        position: 10,
        duration: 100,
        disabled: false,
        seek,
      }),
    );

    act(() => {
      result.current.beginScrub();
    });

    act(() => {
      result.current.handleInput({
        target: { value: '55' },
      } as React.ChangeEvent<HTMLInputElement>);
    });

    expect(result.current.displayPosition).toBe(55);
    expect(seek).toHaveBeenCalledWith(55);
  });

  it('ends scrubbing on change and calls onSeekCommitted', () => {
    const seek = jest.fn();
    const onSeekCommitted = jest.fn();
    const { result } = renderHook(() =>
      usePlaybackTimeline({
        position: 10,
        duration: 100,
        disabled: false,
        seek,
        onSeekCommitted,
      }),
    );

    act(() => {
      result.current.beginScrub();
      result.current.handleChange({
        target: { value: '70' },
      } as React.ChangeEvent<HTMLInputElement>);
    });

    expect(seek).toHaveBeenCalledWith(70);
    expect(onSeekCommitted).toHaveBeenCalledWith(70);
    expect(result.current.displayPosition).toBe(10);
  });
});

import { isDemoFixturesMode, isDemoLiveMode } from '../../../src/shared/platform/demoLiveMode';

describe('demoLiveMode helpers', () => {
  const originalDemoLive = process.env.VITE_DEMO_LIVE;
  const originalAppMode = process.env.VITE_APP_MODE;

  afterEach(() => {
    if (originalDemoLive === undefined) {
      delete process.env.VITE_DEMO_LIVE;
    } else {
      process.env.VITE_DEMO_LIVE = originalDemoLive;
    }
    if (originalAppMode === undefined) {
      delete process.env.VITE_APP_MODE;
    } else {
      process.env.VITE_APP_MODE = originalAppMode;
    }
  });

  test('isDemoLiveMode is true only when VITE_DEMO_LIVE is 1', () => {
    process.env.VITE_DEMO_LIVE = '1';
    expect(isDemoLiveMode()).toBe(true);
    process.env.VITE_DEMO_LIVE = '0';
    expect(isDemoLiveMode()).toBe(false);
    delete process.env.VITE_DEMO_LIVE;
    expect(isDemoLiveMode()).toBe(false);
  });

  test('isDemoFixturesMode requires demo app mode without live flag', () => {
    process.env.VITE_APP_MODE = 'demo';
    delete process.env.VITE_DEMO_LIVE;
    expect(isDemoFixturesMode()).toBe(true);

    process.env.VITE_DEMO_LIVE = '1';
    expect(isDemoFixturesMode()).toBe(false);

    delete process.env.VITE_APP_MODE;
    delete process.env.VITE_DEMO_LIVE;
    expect(isDemoFixturesMode()).toBe(false);
  });

  test('isDemoFixturesMode accepts explicit appMode for gating', () => {
    delete process.env.VITE_APP_MODE;
    delete process.env.VITE_DEMO_LIVE;
    expect(isDemoFixturesMode('demo')).toBe(true);
    expect(isDemoFixturesMode('electron')).toBe(false);

    process.env.VITE_DEMO_LIVE = '1';
    expect(isDemoFixturesMode('demo')).toBe(false);
  });
});

